      "name": "test_brute_force_small_1",
      "source": "def test_brute_force_small_1(run, x):
    w, h, k = map(int, x.strip().split())
    if w <= 15 and h <= 15:
        # compute directly from definition
        total = 0
        a, b = w, h
        for i in range(k):
            total += 2*a + 2*(b-2)
            a -= 4
            b -= 4
        assert int(run(x).strip()) == total"
    },
    {
      "name": "test_brute_force_small_2",
      "source": "def test_brute_force_small_2(run, x):
    w, h, k = map(int, x.strip().split())
    if w <= 20 and h <= 20:
        # alternative brute: mark cells
        grid = [[0]*h for _ in range(w)]
        for ring in range(k):
            top = ring*2
            bottom = w-1 - ring*2
            left = ring*2
            right = h-1 - ring*2
            for i in range(top, bottom+1):
                for j in range(left, right+1):
                    if i==top or i==bottom or j==left or j==right:
                        grid[i][j] = 1
        direct = sum(sum(row) for row in grid)
        assert int(run(x).strip()) == direct"
    },
    {
      "name": "test_examples_from_statement",
