    {
      "name": "test_formula_for_k_1",
      "source": "def test_formula_for_k_1(run, x):
    w, h, k = map(int, x.strip().split())
    if k == 1:
        expected = 2*w + 2*(h-2)
        assert int(run(x).strip()) == expected"
    },
    {
      "name": "test_parity_and_range",
      "source": "def test_parity_and_range(run, x):
    w, h, k = map(int, x.strip().split())
    ans = int(run(x).strip())
    max_rings = (min(w,h)+1)//4
    assert k <= max_rings
    # each ring reduces dimensions by 4, so innermost ring has size at least 3x3
    last_w = w - 4*(k-1)
    last_h = h - 4*(k-1)
    assert last_w >= 3 and last_h >= 3
    # answer must be at least k*8 (each ring at least 8 cells)
    assert ans >= k*8
    # answer must be at most total cells
    assert ans <= w*h"
    }
  ]
}

