def test_non_negative(run, x):
    ans = run(x).strip()
    assert ans.isdigit() or (ans[0] == '-' and ans[1:].isdigit())
    val = int(ans)
    assert val >= 0

def test_growth_with_n(run, x):
    # For fixed k, answer should be non-decreasing with n.
    # This test only runs on inputs where we can infer a smaller n with same k,
    # but we avoid cross-input comparisons by not storing state.
    # Instead, we use a local brute-force for n <= 8 to verify monotonicity.
    import sys
    import io
    n, k = map(int, x.strip().split())
    if n > 8:
        return  # skip for large n
    # compute all permutations of size n
    from itertools import permutations
    total = 0
    for p in permutations(range(1, n+1)):
        fixed = sum(1 for i, pi in enumerate(p, 1) if pi == i)
        if fixed >= n - k:
            total += 1
    assert int(run(x).strip()) == total

def test_growth_with_k(run, x):
    # For fixed n, answer should be non-decreasing with k.
    # Again, we avoid cross-input, so we check by brute for n <= 8.
    n, k = map(int, x.strip().split())
    if n > 8:
        return
    from itertools import permutations
    counts = []
    for kk in range(1, k+1):
        cnt = 0
        for p in permutations(range(1, n+1)):
            fixed = sum(1 for i, pi in enumerate(p, 1) if pi == i)
            if fixed >= n - kk:
                cnt += 1
        counts.append(cnt)
    # counts should be non-decreasing
    for i in range(1, len(counts)):
        assert counts[i] >= counts[i-1]
    # and our answer equals counts[-1]
    assert int(run(x).strip()) == counts[-1]

def test_brute_force_small(run, x):
    n, k = map(int, x.strip().split())
    if n > 7:
        return  # brute force too slow
    from itertools import permutations
    total = 0
    for p in permutations(range(1, n+1)):
        fixed = sum(1 for i, pi in enumerate(p, 1) if pi == i)
        if fixed >= n - k:
            total += 1
    assert int(run(x).strip()) == total

def test_k1_is_1(run, x):
    n, k = map(int, x.strip().split())
    if k == 1:
        assert int(run(x).strip()) == 1

def test_examples(run, x):
    # check the given examples from statement
    if x == '4 1\n':
        assert int(run(x).strip()) == 1
    if x == '4 2\n':
        assert int(run(x).strip()) == 7
    if x == '5 3\n':
        assert int(run(x).strip()) == 31
    if x == '5 4\n':
        assert int(run(x).strip()) == 76

def test_output_format(run, x):
    out = run(x)
    assert out.strip().isdigit()
    assert out.endswith('\n') or out == out.strip()  # allow no newline but must be integer

def test_answer_leq_n_factorial(run, x):
    n, k = map(int, x.strip().split())
    import math
    total = math.factorial(n)
    ans = int(run(x).strip())
    assert 0 <= ans <= total

def test_symmetry_k4_n_small(run, x):
    # when k == 4, answer = n! - D(n) - C(n,1)*D(n-1) - C(n,2)*D(n-2) - C(n,3)*D(n-3)
    # we can compute that for n <= 10 and compare.
    n, k = map(int, x.strip().split())
    if k == 4 and n <= 10:
        import math
        # derangements D(0)=1, D(1)=0, D(2)=1, D(3)=2, D(4)=9, D(5)=44, ...
        D = [1, 0, 1, 2, 9, 44, 265, 1854, 14833, 133496, 1334961]
        total = math.factorial(n)
        sub = 0
        for i in range(4):
            comb = math.comb(n, i)
            sub += comb * D[n - i]
        expected = total - sub
        assert int(run(x).strip()) == expected

def test_k4_vs_k3(run, x):
    # For given n, answer(k=4) >= answer(k=3).
    # We avoid cross-input, so we compute both by brute when n small.
    n, k = map(int, x.strip().split())
    if n > 8:
        return
    from itertools import permutations
    cnt3 = 0
    cnt4 = 0
    for p in permutations(range(1, n+1)):
        fixed = sum(1 for i, pi in enumerate(p, 1) if pi == i)
        if fixed >= n - 3:
            cnt3 += 1
        if fixed >= n - 4:
            cnt4 += 1
    if k == 3:
        assert int(run(x).strip()) == cnt3
    if k == 4:
        assert int(run(x).strip()) == cnt4

