def test_output_format(run, x):
    out = run(x).strip()
    assert out.isdigit() or (out[0]=='-' and out[1:].isdigit()), 'Output must be an integer'

def test_answer_in_range(run, x):
    n = int(x.strip().split()[0])
    ans = int(run(x).strip())
    assert 1 <= ans <= n, f'Answer {ans} not in [1, {n}]'

def test_answer_positive(run, x):
    ans = int(run(x).strip())
    assert ans > 0, 'Answer must be positive'

def test_not_exceed_sorted_half(run, x):
    parts = x.strip().split()
    n = int(parts[0])
    a = list(map(int, parts[1:]))
    def is_sorted(arr):
        return all(arr[i] <= arr[i+1] for i in range(len(arr)-1))
    max_half = 0
    for half in (a[:n//2], a[n//2:]):
        if is_sorted(half):
            max_half = max(max_half, len(half))
    ans = int(run(x).strip())
    assert ans <= max(n, max_half), f'Answer {ans} exceeds possible sorted half length'

def test_full_sorted_array(run, x):
    parts = x.strip().split()
    n = int(parts[0])
    a = list(map(int, parts[1:]))
    if all(a[i] <= a[i+1] for i in range(n-1)):
        ans = int(run(x).strip())
        assert ans == n, f'Full array sorted, answer must be {n}'

def test_all_decreasing(run, x):
    parts = x.strip().split()
    n = int(parts[0])
    a = list(map(int, parts[1:]))
    if all(a[i] > a[i+1] for i in range(n-1)):
        ans = int(run(x).strip())
        assert ans == 1, f'Strictly decreasing array, answer must be 1'

def test_bruteforce_n2(run, x):
    parts = x.strip().split()
    n = int(parts[0])
    if n != 2:
        return
    a = list(map(int, parts[1:]))
    # brute‑force all possible Thanos sort choices
    def thanos(arr):
        if len(arr) == 1:
            return 1
        if all(arr[i] <= arr[i+1] for i in range(len(arr)-1)):
            return len(arr)
        return max(thanos(arr[:len(arr)//2]), thanos(arr[len(arr)//2:]))
    expected = thanos(a)
    ans = int(run(x).strip())
    assert ans == expected, f'For n=2 expected {expected}, got {ans}'

def test_bruteforce_n4(run, x):
    parts = x.strip().split()
    n = int(parts[0])
    if n != 4:
        return
    a = list(map(int, parts[1:]))
    def thanos(arr):
        if len(arr) == 1:
            return 1
        if all(arr[i] <= arr[i+1] for i in range(len(arr)-1)):
            return len(arr)
        return max(thanos(arr[:len(arr)//2]), thanos(arr[len(arr)//2:]))
    expected = thanos(a)
    ans = int(run(x).strip())
    assert ans == expected, f'For n=4 expected {expected}, got {ans}'

def test_bruteforce_n1(run, x):
    parts = x.strip().split()
    n = int(parts[0])
    if n != 1:
        return
