def test_format(run, x):
    out = run(x)
    # Must be a string without leading/trailing whitespace? The spec says without leading zeros.
    s = out.strip()
    assert s in ('0', '1', '2', '3', '4'), f'Output must be a digit 0-4, got {repr(out)}'
    # No leading zeros: already single digit, fine.
    assert out == s, 'Output should not have surrounding whitespace'

def test_small_brute(run, x):
    n_str = x.strip()
    # Only for small n to avoid huge exponent.
    if len(n_str) > 6:  # More than 1e6, skip brute force.
        return
    n = int(n_str)
    if n > 10000:  # Limit for safety
        return
    # Compute (1^n + 2^n + 3^n + 4^n) mod 5
    # Since mod 5, we can compute powers mod 5.
    total = (pow(1, n, 5) + pow(2, n, 5) + pow(3, n, 5) + pow(4, n, 5)) % 5
    out = run(x).strip()
    assert out == str(total), f'For n={n}, expected {total}, got {out}'

def test_output_0_or_4(run, x):
    out = run(x).strip()
    assert out in ('0', '4'), f'Output must be 0 or 4, got {out}'

def test_mod4_zero_implies_4(run, x):
    n_str = x.strip()
    # Compute n mod 4 by processing digits
    mod = 0
    for ch in n_str:
        mod = (mod * 10 + int(ch)) % 4
    if mod == 0:
        out = run(x).strip()
        assert out == '4', f'n divisible by 4, output must be 4, got {out}'

def test_mod4_nonzero_implies_0(run, x):
    n_str = x.strip()
    mod = 0
    for ch in n_str:
        mod = (mod * 10 + int(ch)) % 4
    if mod != 0:
        out = run(x).strip()
        assert out == '0', f'n not divisible by 4, output must be 0, got {out}'

def test_n0(run, x):
    if x.strip() == '0':
        out = run(x).strip()
        assert out == '4', f'n=0 must output 4, got {out}'

def test_n1(run, x):
    if x.strip() == '1':
        out = run(x).strip()
        assert out == '0', f'n=1 must output 0, got {out}'

def test_n2(run, x):
