    if 30 <= n <= 68:
        last_digit = n % 10
        # Find another number in same range with same last digit
        for other in range(30, 69):
            if other != n and other % 10 == last_digit:
                # We need both answers to compare, but can only call run once.
                # Instead check that answer doesn't depend on tens digit in contradictory way.
                # We'll assume that if n is multiple of something, consistency holds.
                # This is a weaker check: just ensure answer is not obviously wrong.
                # Actually, we can't compare without second run.
                # So we'll just check that answer is valid.
                pass
        # Can't do comparison with one run, so just validate format
        output = run(x).strip()
        assert output in {'YES', 'NO'}

