    n = int(x.strip())
    if n < 12:
        output = run(x).strip()
        # The specification doesn't define pattern for n<12, but
        # we can check that answer for n and n+1 aren't forced to be same.
        # Actually, no constraint. So just check format.
        assert output in {'YES', 'NO'}

