    n = int(x.strip())
    if 12 <= n <= 29:
        # All in this range should have same answer according to code,
        # but specification might allow variation. We can't assume.
        # So just check format.
        output = run(x).strip()
        assert output in {'YES', 'NO'}

def test_complement_100_consistency(run, x):
    n = int(x.strip())
    if 1 <= n <= 99:
