        if 1 <= complement <= 99:
            # Can't call run on complement, but we can note that
            # if the answer depends on digit sum or similar symmetric property,
            # n and complement might have same answer.
            # This is a weak assumption, so just check current output.
            output = run(x).strip()
            assert output in {'YES', 'NO'}

