    out = run(x).strip()
    assert out in ('YES', 'NO'), f'output must be YES or NO, got {out!r}'

def test_no_large_jump(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    last = {}
    out = run(x).strip()
    if out == 'YES':
        for i in range(1, n+1):
            xv, k = map(int, lines[i].split())
            if k in last and xv - last[k] >= 2:
                assert False, f'jump >=2 for participant {k} from {last[k]} to {xv}'
            last[k] = max(last.get(k, -1), xv)

def test_non_decreasing_per_participant(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    last = {}
    out = run(x).strip()
    if out == 'YES':
        for i in range(1, n+1):
            xv, k = map(int, lines[i].split())
            if k in last and xv < last[k]:
                assert False, f'x decreased for participant {k} from {last[k]} to {xv}'
            last[k] = max(last.get(k, -1), xv)

def test_zero_after_positive(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    seen_positive = set()
    out = run(x).strip()
    if out == 'YES':
        for i in range(1, n+1):
            xv, k = map(int, lines[i].split())
            if xv == 0:
                seen_positive.add(k)
            else:
                if xv > 0 and k in seen_positive:
                    assert False, f'participant {k} had x=0 earlier, now x={xv} >0 after'
                seen_positive.add(k)

def test_direct_brute(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    if n > 1000:
        return  # too large for brute
    seq = []
    for i in range(1, n+1):
        xv, k = map(int, lines[i].split())
        seq.append((xv, k))
    # brute check: chronological means for each participant, x values seen so far are consecutive from 0
    seen = {}
    ok = True
    for xv, k in seq:
        if xv == 0:
