def test_no_excess_whitespace(run, x):
    out = run(x)
    # Ensure output does not start or end with newline beyond a single terminating newline.
    # run returns the whole stdout; we allow a trailing newline (common) but nothing else extra.
    if out != '' and out[-1] == '\n':
        stripped = out[:-1]
        # stripped should be a single line
        if '\n' in stripped:
            assert False, "Multiple output lines"
