def test_cost_per_kilo_bounds(run, x):
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    out = float(run(x).strip())
    # cost per kilo = out / m
    if m > 0:
        cost_per = out / m
        # a,b between 1 and 100, so cost per kilo is between 1/100 and 100/1 = 100
        if not (1/100 - 1e-9 <= cost_per <= 100 + 1e-9):
            assert False, f"Cost per kilo {cost_per} outside possible range [0.01, 100]"


def test_at_least_min_individual_cost(run, x):
