def test_rel_error_on_exact_duplicate_pairs(run, x):
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    out = float(run(x).strip())
    # If all supermarkets have same a,b, answer must be exactly a/b*m
    first_a, first_b = map(int, lines[1].split())
    all_same = True
    for i in range(2, n+1):
        a, b = map(int, lines[i].split())
        if a != first_a or b != first_b:
            all_same = False
            break
    if all_same:
        expected = first_a / first_b * m
        if abs(out - expected) / max(1, expected) > 1e-6:
            assert False, f"All supermarkets same, expected {expected}, got {out}"

