    # order by power
    order = sorted(range(n), key=lambda i: p[i])
    for idx in range(1, n):
        i = order[idx]      # stronger
        j = order[idx-1]    # weaker
        # stronger's answer must be at least weaker's answer
        # (because stronger can always kill the weaker and take his coins,
        # and may kill additional knights)
        assert parsed[i] >= parsed[j], f'Stronger knight {i} (power {p[i]}) has answer {parsed[i]} < weaker {j} (power {p[j]}) answer {parsed[j]}'"
