        events.append((op, int(r)))
    # brute-force over all subsets of initial readers (0..2^n-1)
    # each bit = that reader initially present
    # simulate and track max occupancy
    readers = {r for _, r in events}
    reader_list = list(readers)
    m = len(reader_list)
