    {
      "name": "test_output_at_least_simultaneous_ignoring_absences",
      "source": "def test_output_at_least_simultaneous_ignoring_absences(run, x):
    lines = x.strip().split('\n')
    cur = 0
    max_cur = 0
    for line in lines[1:]:
        if line.startswith('+'):
            cur += 1
        else:
            # assume the reader was present
            cur -= 1
        if cur > max_cur:
            max_cur = cur
    ans = int(run(x).strip())
    # This max_cur is a lower bound for any feasible simulation,
    # because we always allow leaving if present.
    assert ans >= max_cur, f'Answer {ans} < lower bound {max_cur} from ignoring impossible leaves'"
    },
    {
      "name": "test_output_at_least_distinct_readers_at_some_point",
      "source": "def test_output_at_least_distinct_readers_at_some_point(run, x):
    # The minimal capacity must be at least the number of distinct readers
    # that ever appear simultaneously in any feasible scenario.
    # A trivial lower bound: if there is a '+' event for a reader that never leaves,
    # then that reader is present at the end, and must be counted.
    # But we can compute a bound: for each reader, track if they ever appear.
    # The answer must be at least the maximum size of a set of readers
    # whose events are all '+' and no '-' in between? Hard without solving.
    # Instead use a simpler bound: answer >= number of '+' events that are not preceded by a '-' for same reader earlier.
    lines = x.strip().split('\n')
    seen = set()
    plus_without_prior_minus = 0
    for line in lines[1:]:
        op, r = line.split()
        r = int(r)
        if op == '+':
            if r not in seen:
                plus_without_prior_minus += 1
            seen.add(r)
        else:
            seen.add(r)  # they were present at some point
    # This plus_without_prior_minus is a weak lower bound (each such '+' adds a new reader).
    ans = int(run(x).strip())
    assert ans >= plus_without_prior_minus, f'Answer {ans} < lower bound {plus_without_prior_minus}'"
    },
    {
      "name": "test_output_parity_consistency",
      "source": "def test_output_parity_consistency(run, x):
    # Not a strict requirement from spec, but a possible sanity: number of '+' events minus number of '-' events equals final number of readers present minus initial readers.
    # However, minimal capacity does not have a direct parity constraint.
    # Skip this if not useful.
    # Instead use: the answer must be at least the number of distinct readers that appear in a '+' before any '-' for them (as above).
    # Already covered. Replace with a simple bound: answer >= number of '+' events that are not immediately followed by '-' for same reader before any other '+'? Too complex.
    # Use a simpler bound: answer >= number of '+' events minus number of '-' events (if positive).
    lines = x.strip().split('\n')
    plus = 0
    minus = 0
    for line in lines[1:]:
        if line.startswith('+'):
            plus += 1
        else:
            minus += 1
    diff = plus - minus
    ans = int(run(x).strip())
    # diff = final_present - initial_present, so final_present = diff + initial_present >= diff if initial_present >=0
    # But capacity must be at least final_present, and at least initial_present.
    # So capacity >= max(initial_present, final_present) >= max(0, diff) maybe.
    # Actually not necessary. Drop this test.
    # Instead do: answer >= max(0, diff)
    if diff > 0:
        assert ans >= diff, f'Answer {ans} < positive event difference {diff}'"
    },
    {
      "name": "test_output_at_least_max_concurrent_naive",
      "source": "def test_output_at_least_max_concurrent_naive(run, x):
    # Compute max concurrent assuming all '-' are valid (i.e., reader was present).
    # This is same as test_output_at_least_simultaneous_ignoring_absences.
    # Provide a variant: also consider that each '-' could be of a reader not present, which would increase initial count.
    # But that would increase max concurrent? Not necessarily.
    # Keep the earlier bound.
    lines = x.strip().split('\n')
    cur = 0
    maxc = 0
    for line in lines[1:]:
        if line.startswith('+'):
            cur += 1
        else:
            cur -= 1
        if cur > maxc:
            maxc = cur
    ans = int(run(x).strip())
    assert ans >= maxc, f'Answer {ans} < naive max concurrent {maxc}'"
    },
    {
      "name": "test_output_respects_examples",
      "source": "def test_output_respects_examples(run, x):
    # If the input matches one of the statement examples, the answer must match the example output.
    examples = {
        "6\n+ 12001\n- 12001\n- 1\n- 1200\n+ 1\n+ 7\n": "3",
        "2\n- 1\n- 2\n": "2",
        "2\n+ 1\n- 1\n": "1"
    }
    if x in examples:
        out = run(x).strip()
        assert out == examples[x], f'Example mismatch: expected {examples[x]}, got {out}'"
    }
  ]
}

{
  "rationale": "Each test validates a property of the output that must hold for any correct solution, derived directly from the specification without solving. They check: output length equals m; output tokens are integers; each output token is between 0 and n; monotonicity with sorted b values; exact brute‑force verification for small inputs (n,m ≤ 100); output for empty a (n=0 not allowed, but we check edge case n=1 with b less than a); consistency when b_j equals max a; when b_j equals min a; and output tokens are non‑decreasing if b is sorted (since bisect is monotonic). The weakest is monotonicity with sorted b because it assumes b is sorted in the test, but the specification does not require b to be sorted, so a correct solution could violate it; I would drop that one first. The strongest is brute‑force verification on small inputs.",
  "tests": [
    {
      "name": "test_output_length_equals_m",
      "source": "def test_output_length_equals_m(run, x):
