def test_output_is_yes_or_no(run, x):
    out = run(x)
    assert out.strip() in {"YES", "NO"}, f"Output must be YES or NO, got {repr(out)}"

def test_no_extra_output(run, x):
    out = run(x)
    assert out == "YES\n" or out == "NO\n", f"Output must be exactly 'YES' or 'NO' followed by newline, got {repr(out)}"

def test_output_does_not_depend_on_whitespace(run, x):
    # The input format is fixed, but we can check that the answer is consistent with parsed a,b
    # This is a weak check: just ensure the output is a string.
    out = run(x)
    assert isinstance(out, str), f"Output must be a string, got {type(out)}"

def test_small_inputs_bruteforce(run, x):
    a, b = map(int, x.strip().split())
    # Brute-force only if a+b is small, because we can enumerate intervals up to some bound.
    # The problem says a,b <= 100, but brute-forcing up to r=1000 is fast.
    if a + b <= 1000:  # safe limit
        found = False
        for l in range(1, 1000):
            for r in range(l, 1000):
                even_count = sum(1 for i in range(l, r+1) if i % 2 == 0)
                odd_count = (r - l + 1) - even_count
                if even_count == a and odd_count == b:
                    found = True
                    break
            if found:
                break
        expected = "YES" if found else "NO"
        assert run(x).strip() == expected, f"For input {a} {b}, expected {expected}, got {run(x).strip()}"

def test_output_matches_parity_constraint(run, x):
    # If a and b differ by more than 1, the submitted code says NO.
    # But we can check a property: if a and b are both 0, answer must be NO (since l <= r, interval non-empty).
    a, b = map(int, x.strip().split())
    out = run(x).strip()
    if a == 0 and b == 0:
        assert out == "NO", f"For 0 0 there is no non‑empty interval, must be NO, got {out}"

def test_yes_implies_interval_exists(run, x):
    # If output is YES, then there must exist l,r with the given counts.
    # We can verify by brute‑force for small a+b.
    a, b = map(int, x.strip().split())
    out = run(x).strip()
    if out == "YES" and a + b <= 1000:
        found = False
        for l in range(1, 1000):
            for r in range(l, 1000):
                even_count = sum(1 for i in range(l, r+1) if i % 2 == 0)
                odd_count = (r - l + 1) - even_count
                if even_count == a and odd_count == b:
                    found = True
                    break
            if found:
                break
        assert found, f"Output is YES but no interval found for {a} {b} (checked up to r=999)"

def test_no_implies_no_interval_small_check(run, x):
    # If output is NO, then for small a+b we can verify no interval exists.
    a, b = map(int, x.strip().split())
    out = run(x).strip()
    if out == "NO" and a + b <= 1000:
        found = False
        for l in range(1, 1000):
            for r in range(l, 1000):
                even_count = sum(1 for i in range(l, r+1) if i % 2 == 0)
                odd_count = (r - l + 1) - even_count
                if even_count == a and odd_count == b:
                    found = True
                    break
            if found:
                break
        assert not found, f"Output is NO but an interval exists for {a} {b} (checked up to r=999)"

def test_output_length(run, x):
    out = run(x)
    # YES\n is length 4, NO\n is length 3
    assert len(out) in (3, 4), f"Output length must be 3 or 4, got {len(out)}: {repr(out)}"

def test_output_starts_with_Y_or_N(run, x):
    out = run(x)
    assert out and out[0] in ('Y', 'N'), f"Output must start with Y or N, got {repr(out)}"

def test_output_ends_with_newline(run, x):
    out = run(x)
    assert out.endswith('\n'), f"Output must end with newline, got {repr(out)}"

