    val = int(out)
    assert val >= 0, 'output must be non-negative'

def test_example_z(run, x):
    if x == 'z\n':
        out = run(x).strip()
        assert out == '3', 'example z must output 3'

def test_example_V_V(run, x):
    if x == 'V_V\n':
        out = run(x).strip()
        assert out == '9', 'example V_V must output 9'

def test_example_Codeforces(run, x):
    if x == 'Codeforces\n':
        out = run(x).strip()
