def test_single_char_bounds(run, x):
    s = x.strip()
    if len(s) == 1:
        out = run(x).strip()
        val = int(out)
        # For any single character, the number of pairs (a,b) with a&b = c is at least 1 (when both equal c) and at most 64*64=4096.
        # Actually, for each bit position (6 bits) the count depends on the bitmask; maximum is 3^6 = 729.
        # But we can use a safe bound: 1 <= ans <= 4096.
        assert 1 <= val <= 4096, 'single character output out of reasonable range'

def test_modulo_compliance(run, x):
    out = run(x).strip()
    val = int(out)
    MOD = 1000000007
    assert 0 <= val < MOD, 'output must be modulo 1e9+7'

def test_all_underscore_pattern(run, x):
    s = x.strip()
    if all(ch == '_' for ch in s):
        out = run(x).strip()
        val = int(out)
        # For each position, _ is 63 (all bits 1). The number of pairs (a,b) with a&b = 63 is exactly 1 (both must be 63).
        # So answer should be 1^n = 1.
        assert val == 1, 'all-underscore string must output 1'

def test_all_zero_pattern(run, x):
    s = x.strip()
    if all(ch == '0' for ch in s):
        out = run(x).strip()
        val = int(out)
        # For each position, 0 is 0 (all bits 0). The number of pairs (a,b) with a&b = 0 is the number of pairs that have no common 1 bits.
        # For each bit, possibilities: (0,0), (0,1), (1,0) -> 3 options. So 3^(6 bits) = 729 per position.
