def test_output_is_integer(run, x):
    out = run(x).strip()
    val = int(out)
    # spec: answer fits in 64-bit signed integer
    assert -(2**63) <= val <= 2**63-1

def test_positive(run, x):
    out = run(x).strip()
    val = int(out)
    assert val >= 1

def test_examples_match(run, x):
    if x == '369727\n':
        assert run(x).strip() == '2'
    elif x == '123456789987654321\n':
        assert run(x).strip() == '1'
    elif x == '1\n':
        assert run(x).strip() == '1'

def test_small_bruteforce(run, x):
    s = x.strip()
    if len(s) > 8:
        return  # skip – too big
    from itertools import product
    # brute‑force all possible sequences of reductions
    # we treat the string as a list of digits, repeatedly replace adjacent sum‑9 by '9'
    def dfs(t):
        if len(t) == 1:
            return {t}
        seen = set()
        for i in range(len(t)-1):
            a, b = t[i], t[i+1]
            if int(a) + int(b) == 9:
                new = t[:i] + '9' + t[i+2:]
                seen.update(dfs(new))
        if not seen:
            return {t}
        # keep only those with maximal number of '9's
        max_nines = max(num.count('9') for num in seen)
        return {num for num in seen if num.count('9') == max_nines}
    all_max = dfs(s)
    expected = len(all_max)
    got = int(run(x).strip())
    assert got == expected

def test_answer_divides_naive_product(run, x):
    # The code’s segmentation logic yields a product p.
    # The real answer may differ, but if p is computed as in the submission,
    # the actual answer must be a divisor of p? Not necessarily – but we can at least
    # check that the answer is not larger than p when p is computed naively,
    # because each segment’s contribution cannot increase beyond (cnt//2+1).
    # This is a weak sanity: answer ≤ product over runs of (len_run//2 + 1)
    s = x.strip()
    prod = 1
    cnt = 1
    prev = int(s[0])
    for ch in s[1:]:
        d = int(ch)
        if d + prev == 9:
            cnt += 1
        else:
            if cnt > 1:
                prod *= (cnt // 2 + 1)
            cnt = 1
        prev = d
    if cnt > 1:
        prod *= (cnt // 2 + 1)
    ans = int(run(x).strip())
    # Actually, answer can be larger than prod? Not according to known correct formula.
    # But spec only guarantees answer ≤ 2^63-1, so we check prod also fits that bound.
    # We'll just ensure ans ≤ prod (a plausible monotonicity).
    assert ans <= prod

def test_reversal_invariant(run, x):
    # Reversing the string doesn’t change the possible reductions,
    # so answer should stay the same.
    rev = x.strip()[::-1] + '\n'
    # We cannot call run again (hard rule). So we cannot compare.
    # Instead we can only note that the property must hold for correct code,
    # but we can’t test it without a second run.
    # So we skip this test – placeholder to show idea.
    # Actually we can still compute product on reversed string and compare.
    s = x.strip()
    s_rev = s[::-1]
    # compute same naive product as before
    def naive_prod(t):
        p = 1
        cnt = 1
        prev = int(t[0])
        for ch in t[1:]:
            d = int(ch)
            if d + prev == 9:
                cnt += 1
            else:
                if cnt > 1:
                    p *= (cnt // 2 + 1)
                cnt = 1
            prev = d
        if cnt > 1:
            p *= (cnt // 2 + 1)
        return p
    p1 = naive_prod(s)
    p2 = naive_prod(s_rev)
    # The naive product is symmetric, so they must be equal.
    assert p1 == p2
    # The true answer should also be symmetric, but we cannot check without
    # running again. At least we ensure the naive product symmetry.
    # This catches if the code’s segmentation depends on direction.
    ans = int(run(x).strip())
    # We could also check ans ≤ p1 and ans ≤ p2, but that's redundant.

def test_single_digit(run, x):
    s = x.strip()
    if len(s) == 1:
        assert run(x).strip() == '1'

def test_no_adjacent_sum_9(run, x):
    s = x.strip()
    # if no two adjacent digits sum to 9, only one possible final number (the original)
    ok = True
    for i in range(len(s)-1):
        if int(s[i]) + int(s[i+1]) == 9:
            ok = False
            break
    if ok:
        assert run(x).strip() == '1'

def test_all_digits_9(run, x):
    s = x.strip()
    if all(ch == '9' for ch in s):
        # cannot replace two 9's (sum 18 != 9), so only one maximal number
        assert run(x).strip() == '1'

def test_monotone_append(run, x):
    # If we take the input and append a digit that does NOT sum to 9 with the last digit,
    # the answer should not decrease (because we can still do all previous reductions).
    # But we cannot call run on modified input.
    # Instead we can only check a structural property of the current input:
    # if the last two digits sum to 9, then cnt>1 in the last run.
    # Not a strong test.
    # We'll skip and replace with a check that answer is consistent with known small cases.
    # Use brute‑force for length ≤ 6 to verify.
    s = x.strip()
    if len(s) <= 6:
        from itertools import product
        def dfs(t):
            if len(t) == 1:
                return {t}
            seen = set()
            for i in range(len(t)-1):
                a, b = t[i], t[i+1]
                if int(a) + int(b) == 9:
                    new = t[:i] + '9' + t[i+2:]
                    seen.update(dfs(new))
            if not seen:
                return {t}
            max_nines = max(num.count('9') for num in seen)
            return {num for num in seen if num.count('9') == max_nines}
        expected = len(dfs(s))
        got = int(run(x).strip())
        assert got == expected

