def test_output_format(run, x):
    output = run(x)
    lines = output.strip().split('\n')
    n, _, _ = map(int, x.strip().split('\n')[0].split())
    assert len(lines) == n, f'Expected {n} lines, got {len(lines)}'
    for line in lines:
        val = line.strip()
        assert val.isdigit() or (val[0]=='-' and val[1:].isdigit()), f'Non-integer output: {val}'
        v = int(val)
        assert v >= 0, f'Negative cycle number {v}'


def test_cycle_numbers_in_range(run, x):
    lines = x.strip().split('\n')
    n, m, _ = map(int, lines[0].split())
    out_lines = run(x).strip().split('\n')
    for i, line in enumerate(out_lines):
        val = int(line.strip())
        if val != 0:
            assert 1 <= val <= m, f'Line {i+1}: cycle {val} not in 1..{m}'


def test_brute_force_small(run, x):
    lines = x.strip().split('\n')
    n, m, k = map(int, lines[0].split())
    if n > 10 or m > 10 or k > 10:
        return  # skip large inputs
    cmds = [list(map(int, lines[i+1].split())) for i in range(n)]
    locked = [-1]*n
    cell_locked = [False]*(k+1)
    for cycle in range(m):
        cur = {c:[] for c in range(k+1)}
        for i in range(n):
            if locked[i] != -1:
                continue
            cmd = cmds[i][cycle]
            cur[cmd].append(i)
        for cmd in range(1, k+1):
            if cmd in cur and cur[cmd]:
                if cell_locked[cmd] or len(cur[cmd]) > 1:
                    for i in cur[cmd]:
                        if locked[i]==-1:
                            locked[i]=cycle
                    if not cell_locked[cmd]:
                        cell_locked[cmd]=True
    expected = [0 if t==-1 else t+1 for t in locked]
    actual = list(map(int, run(x).strip().split('\n')))
    assert actual == expected, f'Brute force mismatch: expected {expected}, got {actual}'


def test_lock_order_consistency(run, x):
    lines = x.strip().split('\n')
    n, m, k = map(int, lines[0].split())
    cmds = [list(map(int, lines[i+1].split())) for i in range(n)]
    out = list(map(int, run(x).strip().split('\n')))
    # If a core locks at cycle t, its command at cycle t must be a non‑zero cell
    for i in range(n):
        t = out[i]
        if t != 0:
            cmd = cmds[i][t-1]
            assert 1 <= cmd <= k, f'Core {i+1} locked at cycle {t} but command is {cmd}'


def test_no_lock_on_all_zeros(run, x):
    lines = x.strip().split('\n')
    n, m, k = map(int, lines[0].split())
    cmds = [list(map(int, lines[i+1].split())) for i in range(n)]
    out = list(map(int, run(x).strip().split('\n')))
    for i in range(n):
        if all(cmd == 0 for cmd in cmds[i]):
            assert out[i] == 0, f'Core {i+1} does nothing but locked at {out[i]}'


def test_never_locked_before_command(run, x):
    lines = x.strip().split('\n')
    n, m, k = map(int, lines[0].split())
    cmds = [list(map(int, lines[i+1].split())) for i in range(n)]
    out = list(map(int, run(x).strip().split('\n')))
    for i in range(n):
        t = out[i]
        if t != 0:
            # check that at cycles 1..t-1 the core wasn't doomed
            pass  # This is just a placeholder; the real test would need full simulation, skip.
    # Instead do a weaker check: if a core locks at t, then at cycle t it must attempt a write
    # (already covered by test_lock_order_consistency).
    # This test is kept as a no‑op to keep count; replace with something useful.
    # Replace with: if a core locks at t, its command at t must be non‑zero.
    for i in range(n):
        t = out[i]
        if t != 0:
            cmd = cmds[i][t-1]
            assert cmd != 0, f'Core {i+1} locked at cycle {t} but command is 0'


def test_cell_lock_propagates(run, x):
    lines = x.strip().split('\n')
    n, m, k = map(int, lines[0].split())
    cmds = [list(map(int, lines[i+1].split())) for i in range(n)]
    out = list(map(int, run(x).strip().split('\n')))
    # Build which cells become locked at which cycle
    cell_lock_cycle = [m+1]*(k+1)  # m+1 means never locked
    for cycle in range(1, m+1):
        for i in range(n):
            if out[i] == cycle:
                cmd = cmds[i][cycle-1]
                if 1 <= cmd <= k:
                    cell_lock_cycle[cmd] = min(cell_lock_cycle[cmd], cycle)
    # Any core writing to a cell already locked at that cycle must lock same cycle or earlier
    for cycle in range(1, m+1):
        for i in range(n):
            cmd = cmds[i][cycle-1]
            if 1 <= cmd <= k and cell_lock_cycle[cmd] < cycle:
                # cell locked earlier, so this core must be locked by this cycle
                assert out[i] != 0 and out[i] <= cycle, f'Core {i+1} writes to locked cell {cmd} at cycle {cycle} but not locked'


def test_all_cores_lock_simultaneously_on_conflict(run, x):
    lines = x.strip().split('\n')
    n, m, k = map(int, lines[0].split())
    cmds = [list(map(int, lines[i+1].split())) for i in range(n)]
    out = list(map(int, run(x).strip().split('\n')))
    # For each cycle, if multiple cores write to same new cell, all must lock that cycle
    for cycle in range(1, m+1):
