    if out == '':
        lines = []
    else:
        lines = out.split('\n')
    n, m, k = map(int, x.strip().split('\n')[0].split())
    assert len(lines) == n, f'Expected {n} lines, got {len(lines)}'
    for i, line in enumerate(lines):
        val = int(line.strip())
        assert 0 <= val <= m, f'Line {i+1}: {val} not in [0, {m}]'


def test_locked_cycle_matches_write(run, x):
    lines = x.strip().split('\n')
    n, m, k = map(int, lines[0].split())
    out = run(x).strip().split('\n')
    deadstep = [0] + [int(out[i]) for i in range(n)]
    a = [[0]*(m+1) for _ in range(n+1)]
    for i in range(1, n+1):
        row = list(map(int, lines[i].split()))
        for j in range(1, m+1):
            a[i][j] = row[j-1]
    for i in range(1, n+1):
        s = deadstep[i]
        if s != 0:
            assert 1 <= s <= m, f'Core {i} locked at invalid cycle {s}'
            assert a[i][s] != 0, f'Core {i} locked at cycle {s} but instruction is 0'


def test_bad_cell_at_lock_cycle(run, x):
    lines = x.strip().split('\n')
    n, m, k = map(int, lines[0].split())
    out = run(x).strip().split('\n')
    deadstep = [0] + [int(out[i]) for i in range(n)]
    a = [[0]*(m+1) for _ in range(n+1)]
    for i in range(1, n+1):
        row = list(map(int, lines[i].split()))
        for j in range(1, m+1):
            a[i][j] = row[j-1]
    # Simulate which cells become bad at which cycles
    bad = [False]*(k+1)
    for step in range(1, m+1):
        cnt = [0]*(k+1)
        for i in range(1, n+1):
            if deadstep[i]==0 or deadstep[i]>step:
                cell = a[i][step]
                if cell != 0:
                    cnt[cell] += 1
        for cell in range(1, k+1):
            if cnt[cell] > 1:
                bad[cell] = True
        for i in range(1, n+1):
            if deadstep[i] == step:
                cell = a[i][step]
                assert bad[cell], f'Core {i} locked at cycle {step} but cell {cell} not bad'


