    deadstep = [0] + [int(out[i]) for i in range(n)]
    a = [[0]*(m+1) for _ in range(n+1)]
    for i in range(1, n+1):
        row = list(map(int, lines[i].split()))
        for j in range(1, m+1):
            a[i][j] = row[j-1]
    bad = [False]*(k+1)
    for step in range(1, m+1):
        cnt = [0]*(k+1)
        for i in range(1, n+1):
            if deadstep[i]==0 or deadstep[i]>step:
                cell = a[i][step]
                if cell != 0:
                    cnt[cell] += 1
        for cell in range(1, k+1):
            if cnt[cell] > 1:
                bad[cell] = True
    # At the end, any cell that ever became bad must be bad
    # Actually, the property is: once a cell is bad, it stays bad.
    # So we can check that if a cell is bad at some step, it's bad at all later steps.
    # Simulate again, tracking when each cell becomes bad.
    bad_time = [m+1]*(k+1)
    for step in range(1, m+1):
        cnt = [0]*(k+1)
        for i in range(1, n+1):
            if deadstep[i]==0 or deadstep[i]>step:
                cell = a[i][step]
                if cell != 0:
                    cnt[cell] += 1
        for cell in range(1, k+1):
            if cnt[cell] > 1 and bad_time[cell] == m+1:
                bad_time[cell] = step
    # Now verify that a core locking at step s writes a cell that became bad at step <= s
    for i in range(1, n+1):
        s = deadstep[i]
        if s != 0:
            cell = a[i][s]
            assert bad_time[cell] <= s, f'Core {i} locked at {s} but cell {cell} becomes bad later'


