def test_lock_requires_another_alive_writer(run, x):
    lines = x.strip().split('\n')
    n, m, k = map(int, lines[0].split())
    out = run(x).strip().split('\n')
    deadstep = [0] + [int(out[i]) for i in range(n)]
    a = [[0]*(m+1) for _ in range(n+1)]
    for i in range(1, n+1):
        row = list(map(int, lines[i].split()))
        for j in range(1, m+1):
            a[i][j] = row[j-1]
    for i in range(1, n+1):
        s = deadstep[i]
        if s != 0:
            cell = a[i][s]
            # At cycle s, there must be at least one other core j != i that is not locked before s and also writes cell at cycle s
            other = False
            for j in range(1, n+1):
                if j == i:
                    continue
                if deadstep[j]==0 or deadstep[j]>s:
                    if a[j][s] == cell:
                        other = True
                        break
            assert other, f'Core {i} locks at cycle {s} writing cell {cell}, but no other alive core writes it at that cycle'


