def test_output_format(run, x):
    out = run(x)
    lines = out.strip().split('\n')
    if lines[0].strip() == 'Yes':
        assert len(lines) == 3
        first = list(map(int, lines[1].split()))
        second = list(map(int, lines[2].split()))
        n = len(first)
        m = len(second)
        # Check counts match input
        n_in, m_in = map(int, x.strip().split('\n')[0].split())
        assert n == n_in and m == m_in
        # All numbers positive integers
        assert all(v > 0 for v in first)
        assert all(v > 0 for v in second)
    else:
        assert lines[0].strip() == 'No'
        assert len(lines) == 1

def test_no_contradiction_on_yes(run, x):
    out = run(x)
    lines = out.strip().split('\n')
    if lines[0].strip() != 'Yes':
        return
    first = list(map(int, lines[1].split()))
    second = list(map(int, lines[2].split()))
    n = len(first)
    m = len(second)
    # Parse input matrix
    header = x.strip().split('\n')[0]
    rows = x.strip().split('\n')[1:]
    for i in range(n):
        for j in range(m):
            c = rows[i][j]
            if c == '<':
                assert first[i] < second[j], f'< violation at {i},{j}'
            elif c == '>':
                assert first[i] > second[j], f'> violation at {i},{j}'
            else:
                assert first[i] == second[j], f'= violation at {i},{j}'

def test_no_on_impossible_small(run, x):
    # Only run on small inputs where we can brute-force feasibility
    n, m = map(int, x.strip().split('\n')[0].split())
    if n > 3 or m > 3:
        return
    rows = x.strip().split('\n')[1:]
    # Brute-force search for any assignment with values up to 5
    from itertools import product
    for vals in product(range(1, 6), repeat=n+m):
        first = vals[:n]
        second = vals[n:]
        ok = True
        for i in range(n):
            for j in range(m):
                c = rows[i][j]
                if c == '<':
                    if not (first[i] < second[j]):
                        ok = False
                elif c == '>':
                    if not (first[i] > second[j]):
                        ok = False
                else:
                    if not (first[i] == second[j]):
                        ok = False
        if ok:
            # feasible, so answer must be Yes
            out = run(x)
            assert out.strip().split('\n')[0].strip() == 'Yes'
            return
    # infeasible, answer must be No
    out = run(x)
    assert out.strip().split('\n')[0].strip() == 'No'

def test_values_positive_integers(run, x):
    out = run(x)
    lines = out.strip().split('\n')
    if lines[0].strip() == 'Yes':
        first = list(map(int, lines[1].split()))
        second = list(map(int, lines[2].split()))
        assert all(isinstance(v, int) for v in first)
        assert all(isinstance(v, int) for v in second)
        assert all(v >= 1 for v in first)
        assert all(v >= 1 for v in second)

def test_equality_implies_same_value(run, x):
    out = run(x)
    lines = out.strip().split('\n')
    if lines[0].strip() != 'Yes':
        return
    first = list(map(int, lines[1].split()))
    second = list(map(int, lines[2].split()))
    n = len(first)
    m = len(second)
    rows = x.strip().split('\n')[1:]
    # Build equivalence classes via union-find from input
    parent = list(range(n+m))
    def find(v):
        while parent[v] != v:
            parent[v] = parent[parent[v]]
            v = parent[v]
        return v
    for i in range(n):
        for j in range(m):
            if rows[i][j] == '=':
                pi = find(i)
                pj = find(n+j)
                if pi != pj:
                    parent[pj] = pi
    # Check that all equal cells have same value
    for i in range(n):
        for j in range(m):
            if rows[i][j] == '=':
                assert first[i] == second[j]

def test_graph_no_cycles_small(run, x):
    # Only on small inputs, verify that the comparison graph (after = merging) is acyclic
    n, m = map(int, x.strip().split('\n')[0].split())
    if n+m > 10:
        return
    rows = x.strip().split('\n')[1:]
    # Build graph on equivalence classes
    parent = list(range(n+m))
    def find(v):
        while parent[v] != v:
            parent[v] = parent[parent[v]]
            v = parent[v]
        return v
    for i in range(n):
        for j in range(m):
            if rows[i][j] == '=':
                pi = find(i)
                pj = find(n+j)
                if pi != pj:
                    parent[pj] = pi
    # Map each original node to its class
    comp = [find(i) for i in range(n+m)]
    comp_set = set(comp)
    comp_id = {c:i for i,c in enumerate(sorted(comp_set))}
    k = len(comp_set)
    adj = [[] for _ in range(k)]
    for i in range(n):
        ci = comp_id[comp[i]]
        for j in range(m):
            cj = comp_id[comp[n+j]]
            if rows[i][j] == '<':
                adj[ci].append(cj)
            elif rows[i][j] == '>':
                adj[cj].append(ci)
    # Check for cycles with DFS
    visited = [0]*k
    def dfs(u):
        visited[u] = 1
        for v in adj[u]:
            if visited[v] == 1:
                return True
            if visited[v] == 0:
                if dfs(v):
                    return True
        visited[u] = 2
        return False
    has_cycle = any(dfs(u) for u in range(k) if visited[u]==0)
    out = run(x)
    if has_cycle:
        assert out.strip().split('\n')[0].strip() == 'No'
    # if no cycle, answer may be Yes or No (other constraints may fail)

def test_max_value_consistent_with_assignments(run, x):
    out = run(x)
    lines = out.strip().split('\n')
    if lines[0].strip() != 'Yes':
        return
    first = list(map(int, lines[1].split()))
    second = list(map(int, lines[2].split()))
    all_vals = first + second
    max_val = max(all_vals)
    # Check that every value is at most max_val (trivially true)
    assert all(v <= max_val for v in all_vals)
    # Also check that max_val is at least 1
    assert max_val >= 1

def test_lexicographically_valid_output(run, x):
    # Just ensure output lines are non-empty and have correct number of tokens
    out = run(x)
    lines = out.strip().split('\n')
    assert lines[0].strip() in ('Yes', 'No')
    if lines[0].strip() == 'Yes':
        assert len(lines) >= 3
        tokens1 = lines[1].split()
        tokens2 = lines[2].split()
        assert len(tokens1) > 0 and len(tokens2) > 0
        # Ensure no extra spaces at line ends
        assert lines[1].strip() == ' '.join(tokens1)
        assert lines[2].strip() == ' '.join(tokens2)

def test_consistency_with_inequalities(run, x):
    out = run(x)
    lines = out.strip().split('\n')
    if lines[0].strip() != 'Yes':
        return
    first = list(map(int, lines[1].split()))
    second = list(map(int, lines[2].split()))
    n = len(first)
    m = len(second)
    rows = x.strip().split('\n')[1:]
    # For every '<' and '>', check the inequality
    for i in range(n):
        for j in range(m):
            c = rows[i][j]
            if c == '<':
                assert first[i] < second[j]
            elif c == '>':
                assert first[i] > second[j]
            else:
                assert first[i] == second[j]

def test_no_extra_output(run, x):
    out = run(x)
    lines = out.strip().split('\n')
    # After stripping, there should be exactly 1 line for No, 3 for Yes
    if lines[0].strip() == 'Yes':
        assert len(lines) == 3
    else:
        assert len(lines) == 1
    # No empty lines in between
    assert all(line.strip() == line for line in lines if line)

