def test_output_format(run, x):
    out = run(x).strip()
    assert out.isdigit() or (out.startswith('-') and out[1:].isdigit()), 'Output must be an integer'
    ans = int(out)
    assert 0 <= ans < 998244353, 'Output must be a residue modulo 998244353'

def test_zero_when_k_gt_n(run, x):
    n, k = map(int, x.split())
    if k > n:
        assert run(x).strip() == '0', 'Answer must be 0 when k > n'

def test_k_equals_one(run, x):
    n, k = map(int, x.split())
    if k == 1:
        assert run(x).strip() == str(n), 'When k=1 every a1 works, answer is n'

def test_small_bruteforce(run, x):
    MOD = 998244353
    n, k = map(int, x.split())
    if n <= 8 and k <= 5:   # brute-force feasible
        from itertools import combinations
        ans = 0
        for seq in combinations(range(1, n+1), k):
            a = list(seq)
            ok = True
            # test all permutations for x up to some bound
            # stable condition: for all x up to a safe bound (e.g., product of elements)
            bound = 1
            for v in a:
                bound = min(bound * v, 1000)  # cap to keep fast
            for x in range(bound):
                val = x
                for v in a:
                    val %= v
                for perm in permutations(a):
                    val2 = x
                    for v in perm:
                        val2 %= v
                    if val != val2:
                        ok = False
                        break
                if not ok:
                    break
            if ok:
                ans += 1
        ans %= MOD
        assert int(run(x).strip()) == ans, 'Brute‑force disagrees'

def test_non_negative(run, x):
    out = run(x).strip()
    ans = int(out)
    assert ans >= 0, 'Answer must be non‑negative'

def test_upper_bound_binomial(run, x):
    MOD = 998244353
    n, k = map(int, x.split())
    if k <= n:
        # compute C(n,k) modulo MOD via simple iterative multiplication
        c = 1
        for i in range(1, k+1):
            c = c * (n - i + 1) // i   # exact integer division
        c %= MOD
        ans = int(run(x).strip())
        assert ans <= c, f'Answer {ans} exceeds total number of increasing sequences {c}'

def test_n1_k1(run, x):
    n, k = map(int, x.split())
    if n == 1 and k == 1:
        assert run(x).strip() == '1', 'Only array [1] works'

def test_n_equals_k_greater_one(run, x):
    n, k = map(int, x.split())
    if n == k and n > 1:
        # The only increasing sequence is 1,2,…,n.
        # For n>1 this sequence is NOT stable (e.g., x=2, order 1,2 gives 0, order 2,1 gives 1).
        # So answer must be 0.
        assert run(x).strip() == '0', 'When n=k>1 the only sequence is not stable'

def test_duplicate_inputs_consistency(run, x):
    # If the same input is given with extra spaces, output must be same.
    # We check that our own run(x) returns the same as run(' '.join(x.split()))
    # This is a sanity check on the judging environment, not on the problem.
    normalized = ' '.join(x.split())
    if normalized != x:
        # We cannot call run again, so we cannot compare.
        # Instead we just pass – this test is weak and we mark it as such.
        pass

def test_no_negative_modulus(run, x):
    out = run(x).strip()
    ans = int(out)
    assert ans >= 0, 'Answer must be non‑negative'

