def test_output_format(run, x):
    output = run(x)
    lines = output.strip('\n').split('\n')
    assert len(lines) == 1, 'Output must be exactly one line.'
    out = lines[0]
    if out == '-':
        return
    assert out.isalpha() and out.islower(), 'Output must be lowercase letters or '-'.'

def test_output_is_subsequence_of_a(run, x):
    a, b = x.strip('\n').split('\n')
    out = run(x).strip('\n')
    if out == '-':
        out = ''
    i = 0
    for ch in out:
        while i < len(a) and a[i] != ch:
            i += 1
        if i == len(a):
            assert False, f'Output {repr(out)} not a subsequence of a.'
        i += 1

def test_output_obtainable_from_b_by_consecutive_deletion(run, x):
    a, b = x.strip('\n').split('\n')
    out = run(x).strip('\n')
    if out == '-':
        out = ''
    # Check if out is a (not necessarily consecutive) subsequence of b
    i = 0
    for ch in out:
        while i < len(b) and b[i] != ch:
            i += 1
        if i == len(b):
            assert False, f'Output {repr(out)} not a subsequence of b.'
        i += 1
    # Additionally, check that the remaining characters in b that are not used are consecutive
    # by verifying that out can be obtained by deleting one contiguous block from b.
    # This is not required by the problem? Actually the problem says: remove the minimum possible number of consecutive characters from b so that it becomes a subsequence of a.
    # The output is the resulting subsequence (which is a subsequence of both b and a).
    # It does NOT have to be that the deleted characters are consecutive in b? Wait, the problem says: remove consecutive characters from b.
    # That means we delete one contiguous segment from b, then the remaining string (which is a subsequence of b) must be a subsequence of a.
    # So the output must be a contiguous subsequence of b? Not exactly: we delete consecutive characters, so the remaining characters are in the same order as in b and appear as a contiguous block? No, because we delete a contiguous block, the remaining characters are exactly b[0:l] + b[r+1:]? Actually if we delete consecutive characters, we remove a substring. The remaining is b[0:i] + b[j:] where j-i is the deleted block. So the output is two parts: a prefix of b and a suffix of b, concatenated.
    # Therefore the output must be of the form b[:i] + b[j:] for some 0 <= i <= j <= len(b).
    # Let's check that property.
    out_len = len(out)
    found = False
    for i in range(len(b)+1):
        for j in range(i, len(b)+1):
            candidate = b[:i] + b[j:]
            if candidate == out:
                found = True
                break
        if found:
            break
    assert found, f'Output {repr(out)} cannot be obtained by deleting one contiguous block from b.'

def test_output_not_longer_than_b(run, x):
    a, b = x.strip('\n').split('\n')
    out = run(x).strip('\n')
    if out == '-':
        out = ''
    assert len(out) <= len(b), f'Output length {len(out)} greater than b length {len(b)}.'

def test_output_not_longer_than_a(run, x):
    a, b = x.strip('\n').split('\n')
    out = run(x).strip('\n')
    if out == '-':
        out = ''
    assert len(out) <= len(a), f'Output length {len(out)} greater than a length {len(a)}.'

def test_output_contains_only_chars_from_a(run, x):
    a, b = x.strip('\n').split('\n')
    out = run(x).strip('\n')
    if out == '-':
        return
    for ch in out:
        assert ch in a, f'Output contains character {ch} not in a.'

def test_output_contains_only_chars_from_b(run, x):
    a, b = x.strip('\n').split('\n')
    out = run(x).strip('\n')
    if out == '-':
        return
    for ch in out:
        assert ch in b, f'Output contains character {ch} not in b.'

def test_output_is_empty_when_no_common_letters(run, x):
    a, b = x.strip('\n').split('\n')
    out = run(x).strip('\n')
    if set(a).isdisjoint(set(b)):
        assert out == '-', f'When a and b have no common letters, output must be '-', got {repr(out)}.'

def test_output_is_b_when_b_is_subsequence_of_a(run, x):
    a, b = x.strip('\n').split('\n')
    # Check if b is a subsequence of a
    i = 0
    for ch in b:
        while i < len(a) and a[i] != ch:
            i += 1
        if i == len(a):
            return  # b is not a subsequence, so no requirement
        i += 1
    # b is a subsequence of a, so the optimal output is b itself (deleting zero characters)
    out = run(x).strip('\n')
    assert out == b, f'When b is a subsequence of a, output must be b, got {repr(out)}.'

def test_brute_force_check_for_small_inputs(run, x):
    a, b = x.strip('\n').split('\n')
    if len(a) > 10 or len(b) > 10:  # brute force only for small strings
        return
    # Brute force all possible deletions of one contiguous block from b,
    # check if resulting string is a subsequence of a, keep the longest.
    best_len = -1
    best_str = None
    for i in range(len(b)+1):
        for j in range(i, len(b)+1):
            candidate = b[:i] + b[j:]
            # Check if candidate is subsequence of a
            idx = 0
            ok = True
            for ch in candidate:
                while idx < len(a) and a[idx] != ch:
                    idx += 1
                if idx == len(a):
                    ok = False
                    break
                idx += 1
            if ok and len(candidate) > best_len:
                best_len = len(candidate)
                best_str = candidate
    expected = best_str if best_str else '-'
    out = run(x).strip('\n')
    assert out == expected, f'Brute force says optimal is {repr(expected)}, got {repr(out)}.'

