def test_output_format(run, x):
    out = run(x).strip()
    assert out == '' or out.isdigit() or (out[0] == '-' and out[1:].isdigit() and int(out) == -1)
    # If not empty, must be integer, and if negative only -1 allowed

def test_answer_non_negative_or_minus_one(run, x):
    out = run(x).strip()
    if out == '':
        return
    ans = int(out)
    assert ans == -1 or ans >= 0

def test_answer_upper_bound_trivial(run, x):
    # Vasya can never need more than 31*n extra accounts.
    # Because each problem's score bracket depends on ratio, and after 31*n extra accounts,
    # the ratio for any problem is at most (solved[i]+k)/(n+k) <= (n+k)/(n+k)=1,
    # but the loop in the submitted code goes up to 31*n, so answer cannot exceed that.
    out = run(x).strip()
    if out == '':
        return
    ans = int(out)
    if ans != -1:
        # parse n from first line
        n = int(x.split('\n')[0].strip())
        assert ans <= 31 * n

def test_if_minus_one_then_no_solution(run, x):
    out = run(x).strip()
    if out == '':
        return
    if out == '-1':
        # If answer is -1, then even with arbitrarily many accounts Vasya cannot beat Petya.
        # We can't check that directly without solving, but we can at least ensure that
        # the answer is not -1 when there is an obvious trivial solution (e.g., Vasya already leads).
        # This is a weak check: only catches if -1 is returned when Vasya already leads without extra accounts.
        # Compute Vasya's and Petya's scores with zero extra accounts using the scoring formula.
        lines = x.strip().split('\n')
        n = int(lines[0])
        a = [list(map(int, line.split())) for line in lines[1:1+n]]
        # compute solved counts
        solved = [0]*5
        for i in range(n):
            for j in range(5):
                if a[i][j] != -1:
                    solved[j] += 1
        # score per problem with zero extra accounts
        score = [0]*5
        for j in range(5):
            tot = n
            cur = solved[j]
            sc = 500
            while sc < 3000 and 2*cur <= tot:
                cur *= 2
                sc += 500
            score[j] = sc
        vasya = 0
        petya = 0
        for j in range(5):
            if a[0][j] != -1:
                vasya += score[j] * (250 - a[0][j]) / 250.0
            if a[1][j] != -1:
                petya += score[j] * (250 - a[1][j]) / 250.0
        if vasya > petya + 1e-9:
            # Vasya already leads, answer cannot be -1
            assert False, "Vasya already leads but answer is -1"
        # else passes (no guarantee)
    # else passes

def test_answer_integer(run, x):
    out = run(x).strip()
    if out == '':
        return
    # Must be integer
    try:
        int(out)
    except ValueError:
        assert False, "Output is not an integer"

def test_brute_force_small(run, x):
    # Only run when n <= 10 (so total participants after adding up to 31*n accounts is small)
    # and number of problems is 5.
    # We'll brute-force try k from 0 to 31*n (as in the code) and compute whether Vasya beats Petya
    # using the exact same scoring logic as described in the statement (not the submitted code).
    lines = x.strip().split('\n')
    n = int(lines[0])
    if n > 10:
        return  # too big, skip
    a = [list(map(int, line.split())) for line in lines[1:1+n]]
    # Compute solved counts for each problem
    solved = [0]*5
    for i in range(n):
        for j in range(5):
            if a[i][j] != -1:
                solved[j] += 1
    def score_for_problem(j, k):
        tot = n + k
        cur = solved[j]
        # Vasya may add extra correct submissions if he solved it and his time > Petya's
        if a[0][j] != -1 and a[1][j] != -1 and a[0][j] > a[1][j]:
            cur += k
        # Determine bracket
        if cur * 32 <= tot:
            sc = 3000
        elif cur * 16 <= tot:
            sc = 2500
        elif cur * 8 <= tot:
            sc = 2000
        elif cur * 4 <= tot:
            sc = 1500
        elif cur * 2 <= tot:
            sc = 1000
        else:
            sc = 500
        return sc
    def total_score(participant_idx, k):
        s = 0.0
        for j in range(5):
            if a[participant_idx][j] != -1:
                sc = score_for_problem(j, k)
                s += sc * (250 - a[participant_idx][j]) / 250.0
        return s
    # Find minimal k
    found = -1
    for k in range(0, 31*n + 2):  # +2 to be safe
        if total_score(0, k) > total_score(1, k) + 1e-9:
            found = k
            break
    out = run(x).strip()
    if out == '':
        return
    ans = int(out)
    if found == -1:
        # No solution up to 31*n, answer must be -1
        assert ans == -1, f"No solution found but answer is {ans}"
    else:
        # There is a solution, answer must be <= found (since we brute-forced minimal? Actually the brute force finds first k where condition holds, which may not be minimal if we loop forward? Wait we loop from 0, so first k is minimal.)
        # But we can't assert ans == found because we don't know if our logic matches the intended problem statement (it does).
        # Instead, we can assert that ans <= found (since found is a feasible k).
        # Also, for k < ans, condition must fail (we can check).
        if ans != -1:
            assert ans <= found, f"Answer {ans} larger than feasible k {found}"
            # Check that for k = ans-1, Vasya does NOT beat Petya (if ans>0)
            if ans > 0:
                assert total_score(0, ans-1) <= total_score(1, ans-1) + 1e-9, f"Condition already holds at k={ans-1}, answer not minimal"
        else:
            # ans is -1 but we found a feasible k -> contradiction
            assert False, f"Feasible k={found} exists but answer is -1"


def test_monotonicity_if_minus_one(run, x):
    # If answer is -1, then adding any extra accounts should not help.
    # We can't test all k, but we can test one large k (e.g., 31*n) and verify that condition still fails.
    out = run(x).strip()
    if out == '':
        return
    if out == '-1':
        lines = x.strip().split('\n')
        n = int(lines[0])
        a = [list(map(int, line.split())) for line in lines[1:1+n]]
        solved = [0]*5
        for i in range(n):
            for j in range(5):
                if a[i][j] != -1:
                    solved[j] += 1
        def score_for_problem(j, k):
            tot = n + k
            cur = solved[j]
            if a[0][j] != -1 and a[1][j] != -1 and a[0][j] > a[1][j]:
                cur += k
            if cur * 32 <= tot:
                return 3000
            elif cur * 16 <= tot:
                return 2500
            elif cur * 8 <= tot:
                return 2000
            elif cur * 4 <= tot:
                return 1500
            elif cur * 2 <= tot:
                return 1000
            else:
                return 500
        def total_score(idx, k):
            s = 0.0
            for j in range(5):
