                    sc = score_for_problem(j, k)
                    s += sc * (250 - a[idx][j]) / 250.0
            return s
        k_test = 31 * n
        # If condition holds at k_test, then -1 is wrong.
        if total_score(0, k_test) > total_score(1, k_test) + 1e-9:
            assert False, "Condition holds at k=31*n but answer is -1"


def test_answer_not_excessively_large(run, x):
    # The answer should not exceed 5000 (a safe loose bound).
    # Since n ≤ 120, 31*n = 3720, so 5000 is safe.
    out = run(x).strip()
    if out == '':
        return
    if out != '-1':
        ans = int(out)
        assert ans <= 5000, f"Answer {ans} unreasonably large"

def test_vasya_already_leads_implies_zero(run, x):
    # If with zero extra accounts Vasya already beats Petya, answer must be 0.
    # Compute scores with k=0 using the exact formula from statement.
    lines = x.strip().split('\n')
    n = int(lines[0])
    a = [list(map(int, line.split())) for line in lines[1:1+n]]
    solved = [0]*5
    for i in range(n):
        for j in range(5):
            if a[i][j] != -1:
                solved[j] += 1
    def score_for_problem(j, k):
        tot = n + k
        cur = solved[j]
        if a[0][j] != -1 and a[1][j] != -1 and a[0][j] > a[1][j]:
            cur += k
        if cur * 32 <= tot:
            return 3000
        elif cur * 16 <= tot:
            return 2500
        elif cur * 8 <= tot:
            return 2000
        elif cur * 4 <= tot:
            return 1500
        elif cur * 2 <= tot:
            return 1000
        else:
            return 500
    def total_score(idx, k):
        s = 0.0
        for j in range(5):
            if a[idx][j] != -1:
                sc = score_for_problem(j, k)
                s += sc * (250 - a[idx][j]) / 250.0
        return s
    if total_score(0, 0) > total_score(1, 0) + 1e-9:
        out = run(x).strip()
        if out == '':
            return
        assert out == '0', f"Vasya already leads but answer is {out}"


def test_parsing_robustness(run, x):
    # Check that the output does not contain extra whitespace/newlines.
    out = run(x).strip()
    raw = run(x)
    # The raw output stripped should equal the whole raw output (no leading/trailing whitespace)
    # except possibly a single trailing newline.
    if raw.endswith('\n'):
        assert raw.count('\n') == 1 and raw.rstrip('\n') == out
    else:
        assert raw == out


def test_answer_not_negative_unless_minus_one(run, x):
    out = run(x).strip()
    if out == '':
        return
    ans = int(out)
    assert ans == -1 or ans >= 0, f"Negative answer {ans} not allowed"

