tests_src:
def test_output_is_either_correct_or_too_weak(run, x):
    out = run(x)
    assert out in ("Correct\n", "Too weak\n")

def test_output_ends_with_newline(run, x):
    out = run(x)
    assert out.endswith('\n')

def test_output_no_extra_lines(run, x):
    out = run(x)
    lines = out.split('\n')
    # Allow trailing newline, so lines = [message, '']
    assert len([l for l in lines if l != '']) == 1

def test_output_starts_with_c_or_t(run, x):
    out = run(x)
    assert out[0] in ('C', 'T')

def test_too_short_input_must_be_too_weak(run, x):
    if len(x.strip()) < 5:
        out = run(x)
        assert out == "Too weak\n"

def test_no_digit_must_be_too_weak(run, x):
    if not any(c.isdigit() for c in x.strip()):
        out = run(x)
        assert out == "Too weak\n"

def test_no_lowercase_must_be_too_weak(run, x):
    if not any(c.islower() for c in x.strip()):
        out = run(x)
        assert out == "Too weak\n"

def test_no_uppercase_must_be_too_weak(run, x):
    if not any(c.isupper() for c in x.strip()):
        out = run(x)
        assert out == "Too weak\n"

def test_output_is_one_line(run, x):
    out = run(x)
    lines = out.strip('\n').split('\n')
    assert len(lines) == 1

def test_output_has_no_leading_trailing_spaces(run, x):
    out = run(x)
    # Should be exactly 'Correct\n' or 'Too weak\n', no spaces
    assert out in ("Correct\n", "Too weak\n")

