def test_output_is_integer_mod(run, x):
    out = run(x).strip()
    ans = int(out)
    mod = 998244353
    assert 0 <= ans < mod, f'Answer {ans} not in range [0, mod-1]'

def test_zero_for_n_equals_2(run, x):
    n, m = map(int, x.split())
    if n == 2:
        assert run(x).strip() == '0', 'For n=2 answer must be 0'

def test_bruteforce_small_n_m(run, x):
    import itertools
    n, m = map(int, x.split())
    if n > 6 or m > 6:
        return  # too big, skip
    mod = 998244353
    count = 0
    for arr in itertools.product(range(1, m+1), repeat=n):
        # exactly one pair of equal elements
        freq = {}
        for v in arr:
            freq[v] = freq.get(v, 0) + 1
        if sum(v > 1 for v in freq.values()) != 1:
            continue
        # exactly one value repeated twice, all others distinct
        if not any(v == 2 for v in freq.values()):
            continue
        if sum(v == 2 for v in freq.values()) != 1:
            continue
        # mountain condition
        # find peak i such that strictly inc before, strictly dec after
        ok = False
        for i in range(n):
            left = all(arr[j] < arr[j+1] for j in range(i-1) if j+1 < i)
            right = all(arr[j] > arr[j+1] for j in range(i, n-1))
            if left and right:
                # also need arr[i-1] < arr[i] if i>0 and arr[i] > arr[i+1] if i<n-1
                if i == 0:
                    if n>1 and arr[0] > arr[1]:
                        ok = True
                elif i == n-1:
                    if arr[n-2] < arr[n-1]:
                        ok = True
                else:
                    if arr[i-1] < arr[i] and arr[i] > arr[i+1]:
                        ok = True
                if ok:
                    break
        if ok:
            count += 1
    expected = count % mod
    got = int(run(x).strip())
    assert got == expected, f'Brute force: expected {expected}, got {got}'

def test_matches_example_3_4(run, x):
