def test_upper_bound_by_choices(run, x):
    n, m = map(int, x.split())
    mod = 998244353
    # trivial upper bound: number of ways to pick n numbers from 1..m with exactly one duplicate
    # first choose which value is duplicated: m choices
    # choose positions for the two duplicates: C(n,2)
    # fill remaining n-2 positions with distinct values from remaining m-1 values: P(m-1, n-2)
    import math
    if m-1 < n-2:
        bound = 0
    else:
        bound = m * math.comb(n,2) * math.perm(m-1, n-2)
    bound %= mod
    got = int(run(x).strip())
    assert got <= bound, f'Answer {got} exceeds trivial upper bound {bound}'

