tests_src:
def test_output_non_negative_integer(run, x):
    out = run(x).strip().split()
    for v in out:
        num = int(v)
        assert num >= 0

def test_answer_parity_matches_n(run, x):
    # For each query, answer parity must match n parity because n+bought must be even.
    lines = x.strip().split()
    q = int(lines[0])
    answers = run(x).strip().split()
    assert len(answers) == q
    for i in range(q):
        n = int(lines[i+1])
        bought = int(answers[i])
        assert (n + bought) % 2 == 0

def test_example_2(run, x):
    if x.strip() == '1\n2':
        ans = run(x).strip()
        assert ans == '2'

def test_example_5(run, x):
    if x.strip() == '1\n5':
        ans = run(x).strip()
        assert ans == '1'

def test_example_8(run, x):
    if x.strip() == '1\n8':
        ans = run(x).strip()
        assert ans == '0'

def test_example_11(run, x):
    if x.strip() == '1\n11':
        ans = run(x).strip()
        assert ans == '1'

def test_small_n_bruteforce(run, x):
    lines = x.strip().split()
    q = int(lines[0])
    if any(int(lines[i+1]) > 30 for i in range(q)):
        return  # skip large inputs to keep fast
    answers = run(x).strip().split()
    for i in range(q):
        n = int(lines[i+1])
        best = 10**9
        # brute force all a,b,c positive integers, compute matches = a+b+c
        for a in range(1, n+2):
            for b in range(1, n+2):
                c = a + b
                matches = a + b + c
                if matches >= n:
                    buy = matches - n
                    if buy < best:
                        best = buy
        assert int(answers[i]) == best

def test_answer_0_or_1_for_n_ge_4(run, x):
    lines = x.strip().split()
    q = int(lines[0])
    answers = run(x).strip().split()
    for i in range(q):
        n = int(lines[i+1])
        if n >= 4:
            bought = int(answers[i])
            assert bought == 0 or bought == 1

def test_n_2_output_2(run, x):
    # specification example: n=2 => answer 2
    if x.strip() == '1\n2':
        ans = run(x).strip()
        assert ans == '2'

def test_n_3_output_1(run, x):
    # from the pattern: n=3 requires 1 extra match (e.g., 1+1=2 uses 4 matches)
    if x.strip() == '1\n3':
        ans = run(x).strip()
        assert ans == '1'

