def test_answer_at_least_one(run, x):
    out = run(x).strip()
    ans = int(out)
    assert ans >= 1, 'answer must be at least 1'

def test_prefix_monotonicity(run, x):
    # If answer is k, then for any i < k, the prefix of i days might not be valid,
    # but we can check a weaker property: if we take the actual answer and check
    # the prefix of that length, it must be a streak.
    # This test computes directly for small n (≤10) whether the answer is indeed a streak.
    lines = x.strip().split('\n')
    n = int(lines[0])
    if n > 10:
        return  # skip because brute force is expensive
    u = list(map(int, lines[1].split()))
    out = run(x).strip()
    ans = int(out)
    # ans must be ≤ n
    if ans > n:
        return  # caught by other test
    # Brute force check: is there a day to remove making counts equal?
    def is_good_prefix(length):
        if length == 0:
            return False
        prefix = u[:length]
        for idx in range(length):
            counts = {}
            for j, val in enumerate(prefix):
                if j == idx:
                    continue
                counts[val] = counts.get(val, 0) + 1
            if len(set(counts.values())) == 1:
                return True
        return False
    if ans > 0:
        assert is_good_prefix(ans), f'prefix of length {ans} is not a valid streak'

def test_brute_force_small_n(run, x):
    # For n ≤ 6, compute the correct answer by brute force and compare.
    lines = x.strip().split('\n')
    n = int(lines[0])
    if n > 6:
        return
    u = list(map(int, lines[1].split()))
    # Compute longest streak
    best = 0
    for length in range(1, n+1):
        prefix = u[:length]
        good = False
        for idx in range(length):
            counts = {}
            for j, val in enumerate(prefix):
                if j == idx:
                    continue
                counts[val] = counts.get(val, 0) + 1
            if len(set(counts.values())) == 1:
                good = True
                break
        if good:
            best = length
    out = run(x).strip()
    ans = int(out)
    assert ans == best, f'for n={n}, expected {best}, got {ans}'

