def test_output_format(run, x):
    out = run(x).strip()
    # Output must be a single integer, possibly negative
    try:
        int(out)
    except ValueError:
        raise AssertionError(f'Output not an integer: {out}')
    # No extra whitespace or lines
    lines = run(x).splitlines()
    assert len(lines) == 1, 'Output must be exactly one line'
    assert lines[0].strip() == out, 'Extra whitespace'


def test_chebyshev_lower_bound(run, x):
    # Minimum moves >= Chebyshev distance between start and end
    parts = x.strip().split()
    if not parts:
        return
    x0, y0, x1, y1 = map(int, parts[:4])
    out = run(x).strip()
    if out == '-1':
        return  # path does not exist, lower bound irrelevant
    ans = int(out)
    cheb = max(abs(x0 - x1), abs(y0 - y1))
    assert ans >= cheb, f'Answer {ans} < Chebyshev distance {cheb}'


def test_upper_bound_total_cells(run, x):
    # King cannot move more than total allowed cells - 1
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    n = int(lines[1])
    total_cells = 0
    for i in range(n):
        r, a, b = map(int, lines[2 + i].split())
        total_cells += b - a + 1
    out = run(x).strip()
    if out == '-1':
        return
    ans = int(out)
    # King must stay on allowed cells, max moves is total_cells - 1 (if path visits all)
    # This bound is loose but safe
    assert ans <= total_cells - 1, f'Answer {ans} > total allowed cells - 1'


def test_small_bruteforce(run, x):
    # If total allowed cells <= 10, compute BFS manually
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    x0, y0, x1, y1 = map(int, lines[0].split())
    n = int(lines[1])
    allowed = set()
    total = 0
    for i in range(n):
        r, a, b = map(int, lines[2 + i].split())
        for col in range(a, b + 1):
            allowed.add((r, col))
            total += 1
            if total > 10:
                return  # too big, skip test
    # BFS
    from collections import deque
    dist = {(x0, y0): 0}
    q = deque([(x0, y0)])
    while q:
        cx, cy = q.popleft()
        if (cx, cy) == (x1, y1):
            break
        for dx in (-1, 0, 1):
            for dy in (-1, 0, 1):
                if dx == 0 and dy == 0:
                    continue
                nx, ny = cx + dx, cy + dy
                if (nx, ny) in allowed and (nx, ny) not in dist:
                    dist[(nx, ny)] = dist[(cx, cy)] + 1
                    q.append((nx, ny))
    expected = dist.get((x1, y1), -1)
    out = run(x).strip()
    if out == '-1':
        ans = -1
    else:
        ans = int(out)
    assert ans == expected, f'Brute-force says {expected}, got {ans}'


def test_start_end_different(run, x):
    # Task guarantees start != end, so answer cannot be 0
    parts = x.strip().split()
    if not parts:
        return
    x0, y0, x1, y1 = map(int, parts[:4])
    out = run(x).strip()
    if out == '-1':
        return
    ans = int(out)
    assert ans > 0, 'Answer must be positive because start != end'


def test_single_row_disjoint(run, x):
    # If only one allowed cell per row and rows differ by >=2, path impossible -> -1
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    x0, y0, x1, y1 = map(int, lines[0].split())
    n = int(lines[1])
    row_cells = {}
    for i in range(n):
        r, a, b = map(int, lines[2 + i].split())
        if r not in row_cells:
            row_cells[r] = 0
        row_cells[r] += b - a + 1
    # Check if every row has exactly one allowed cell
    if all(v == 1 for v in row_cells.values()) and len(row_cells) >= 2:
        rows = list(row_cells.keys())
        rows.sort()
        # If rows are not consecutive, king cannot jump (needs adjacent row)
        for i in range(1, len(rows)):
            if rows[i] - rows[i-1] > 1:
                # start and end rows must be among these rows
                if x0 in rows and x1 in rows:
                    out = run(x).strip()
                    assert out == '-1', f'Rows are isolated single cells, should be -1, got {out}'
                break


def test_no_path_if_rows_disjoint(run, x):
    # Simplified: if allowed rows are {r1, r2} with |r1-r2|>1 and start in r1, end in r2, answer -1
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    x0, y0, x1, y1 = map(int, lines[0].split())
    n = int(lines[1])
    rows = set()
    for i in range(n):
        r, a, b = map(int, lines[2 + i].split())
        rows.add(r)
    rows = sorted(rows)
    if len(rows) == 2:
        r1, r2 = rows
        if abs(r1 - r2) > 1:
            # start row in one, end row in the other
            if (x0 == r1 and x1 == r2) or (x0 == r2 and x1 == r1):
                out = run(x).strip()
                assert out == '-1', f'Rows disconnected, should be -1, got {out}'


def test_continuous_segment_same_row(run, x):
    # If start and end same row and columns within a single allowed segment, answer = |y0-y1|
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    x0, y0, x1, y1 = map(int, lines[0].split())
    n = int(lines[1])
    for i in range(n):
        r, a, b = map(int, lines[2 + i].split())
        if r == x0 == x1:
            if a <= min(y0, y1) and max(y0, y1) <= b:
                out = run(x).strip()
                if out == '-1':
                    raise AssertionError(f'Path exists in same segment, got -1')
                ans = int(out)
                assert ans == abs(y0 - y1), f'Same row segment, answer should be {abs(y0-y1)}, got {ans}'
                return


def test_minus_one_implies_no_path_simple(run, x):
    # If output is -1, verify that start and end are in different connected components by a simple condition: rows differ and no row adjacent to both.
    # This is a heuristic, not exhaustive, but safe: if condition fails, we don't assert.
    out = run(x).strip()
    if out != '-1':
        return
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    x0, y0, x1, y1 = map(int, lines[0].split())
    n = int(lines[1])
    rows = set()
    row_intervals = {}
    for i in range(n):
        r, a, b = map(int, lines[2 + i].split())
        rows.add(r)
        if r not in row_intervals:
            row_intervals[r] = []
        row_intervals[r].append((a, b))
    # If start and end same row and columns overlap in intervals, path exists -> contradiction
    if x0 == x1:
        for a, b in row_intervals.get(x0, []):
            if a <= y0 <= b and a <= y1 <= b:
                raise AssertionError(f'Both in same row segment, path exists, got -1')
    # If rows adjacent (|x0-x1|==1) and columns overlap, king could move directly
    if abs(x0 - x1) == 1:
        for a0, b0 in row_intervals.get(x0, []):
            if a0 <= y0 <= b0:
                for a1, b1 in row_intervals.get(x1, []):
                    if a1 <= y1 <= b1:
                        # check column overlap for king move (columns differ at most 1)
                        if not (b0 < a1 - 1 or b1 < a0 - 1):
                            raise AssertionError(f'Adjacent rows with overlapping columns, path possible, got -1')


def test_answer_nonnegative(run, x):
    out = run(x).strip()
    if out == '-1':
        return
    ans = int(out)
    assert ans >= 0, f'Answer must be nonnegative, got {ans}'

