def test_output_format(run, x):
    out = run(x)
    lines = out.strip().split('\n')
    assert len(lines) == 2, "Output must have exactly 2 lines"
    k_line, arr_line = lines[0].strip(), lines[1].strip()
    try:
        k = int(k_line)
    except:
        assert False, "First line must be an integer"
    if arr_line:
        arr = list(map(int, arr_line.split()))
        assert len(arr) == k, "Number of printed elements must equal k"
    else:
        assert k == 0, "If no elements printed, k must be 0"

def test_output_length(run, x):
    out = run(x)
    lines = out.strip().split('\n')
    if len(lines) < 2:
        assert False, "Not enough lines in output"
    try:
        k = int(lines[0].strip())
    except:
        return  # let other tests catch format errors
    if len(lines) == 2:
        arr_line = lines[1].strip()
        if arr_line:
            arr = list(map(int, arr_line.split()))
            assert len(arr) == k, "Printed count does not match k"
        else:
            assert k == 0, "Empty second line implies k=0"
    else:
        # More than 2 lines is invalid
        assert False, "Output must have exactly 2 lines"

def test_elements_positive(run, x):
    out = run(x)
    lines = out.strip().split('\n')
    if len(lines) < 2:
        return  # caught elsewhere
    arr_line = lines[1].strip()
    if not arr_line:
        return
    for val in map(int, arr_line.split()):
        assert val >= 1, "All final elements must be positive integers"

def test_sum_invariant(run, x):
    # sum of all elements never decreases because merging two x into 2x increases sum by x
    in_lines = x.strip().split('\n')
    if len(in_lines) < 2:
        return
    orig = list(map(int, in_lines[1].split()))
    orig_sum = sum(orig)
    out = run(x)
    out_lines = out.strip().split('\n')
    if len(out_lines) < 2:
        return
    out_arr_line = out_lines[1].strip()
    if out_arr_line:
        final = list(map(int, out_arr_line.split()))
        final_sum = sum(final)
        assert final_sum >= orig_sum, "Sum of elements cannot decrease"

def test_no_equal_pairs(run, x):
    out = run(x)
    lines = out.strip().split('\n')
    if len(lines) < 2:
        return
    arr_line = lines[1].strip()
    if not arr_line:
        return
    arr = list(map(int, arr_line.split()))
    seen = set()
    for v in arr:
        assert v not in seen, "Final array must have all distinct elements"
        seen.add(v)

def test_size_non_increasing(run, x):
    in_lines = x.strip().split('\n')
    if len(in_lines) < 2:
        return
    n = int(in_lines[0].strip())
    out = run(x)
    out_lines = out.strip().split('\n')
    if len(out_lines) < 2:
        return
    k = int(out_lines[0].strip())
    assert k <= n, "Number of elements cannot increase"

def test_small_input_brute(run, x):
    in_lines = x.strip().split('\n')
    if len(in_lines) < 2:
        return
    n = int(in_lines[0].strip())
    if n > 10:
        return  # skip large inputs – brute too slow
    a = list(map(int, in_lines[1].split()))
    # brute simulation
    from collections import defaultdict, deque
    arr = a[:]
    while True:
        freq = defaultdict(list)
        for idx, val in enumerate(arr):
            freq[val].append(idx)
        # find smallest value with >=2 occurrences
        candidates = [v for v, lst in freq.items() if len(lst) >= 2]
        if not candidates:
            break
        xval = min(candidates)
        pos = freq[xval]
        i, j = pos[0], pos[1]
        # remove left, replace right with 2*xval
        arr.pop(i)
        arr[j-1] = 2 * xval  # because after pop, indices shift
    # expected final array
    expected = arr
    out = run(x)
    out_lines = out.strip().split('\n')
    if len(out_lines) < 2:
        assert False, "Malformed output"
    out_arr = list(map(int, out_lines[1].strip().split()))
    assert out_arr == expected, "Does not match brute‑force simulation"

def test_minimum_preserved(run, x):
    in_lines = x.strip().split('\n')
    if len(in_lines) < 2:
        return
    orig = list(map(int, in_lines[1].split()))
    out = run(x)
    out_lines = out.strip().split('\n')
    if len(out_lines) < 2:
        return
    arr_line = out_lines[1].strip()
    if not arr_line:
        return
    final = list(map(int, arr_line.split()))
    if not final:
        return
    min_final = min(final)
    assert min_final in orig, "Minimum of final array must be present in original"

def test_order_preserved(run, x):
    # The relative order of distinct values (ignoring merges) must stay.
    # More precisely: if we take the final array and look up each value's
    # earliest occurrence index in the original array, those indices must be increasing.
    in_lines = x.strip().split('\n')
    if len(in_lines) < 2:
        return
    orig = list(map(int, in_lines[1].split()))
    out = run(x)
    out_lines = out.strip().split('\n')
    if len(out_lines) < 2:
        return
    arr_line = out_lines[1].strip()
    if not arr_line:
        return
    final = list(map(int, arr_line.split()))
    # For each final value, find its earliest occurrence index in original
    orig_positions = {}
    for idx, val in enumerate(orig):
        if val not in orig_positions:
            orig_positions[val] = idx
    pos_seq = []
    for v in final:
        # v may be a result of merges, so not necessarily in orig.
        # But we can trace back: if v came from merging two x into 2x,
        # then either v is in orig or v/2 is, etc.
        cur = v
        while cur not in orig_positions and cur % 2 == 0:
            cur //= 2
        if cur in orig_positions:
            pos_seq.append(orig_positions[cur])
        else:
            # value not derived from original – cannot enforce order
            return
    # positions must be strictly increasing
    for i in range(1, len(pos_seq)):
        assert pos_seq[i] > pos_seq[i-1], "Order of distinct values violated"

def test_elements_integer(run, x):
    out = run(x)
    lines = out.strip().split('\n')
    if len(lines) < 2:
        return
    arr_line = lines[1].strip()
