def test_no_cycle_small_DAG(run, x):
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    s = lines[1]
    edges = []
    for i in range(2, 2 + m):
        if i < len(lines):
            u, v = map(int, lines[i].split())
            edges.append((u, v))
    # For small graphs (n <= 8) we can brute-force check if no cycles
    # and compute exact answer via DP to verify.
    if n <= 8 and m <= 12:
        # First detect if there's any cycle
        adj = [[] for _ in range(n+1)]
        for u, v in edges:
            adj[u].append(v)
        visited = [0]*(n+1)  # 0 unvisited, 1 visiting, 2 done
        has_cycle = False
        def dfs(u):
            nonlocal has_cycle
            if has_cycle:
                return
            visited[u] = 1
            for v in adj[u]:
                if visited[v] == 0:
                    dfs(v)
                elif visited[v] == 1:
                    has_cycle = True
                    return
            visited[u] = 2
        for i in range(1, n+1):
            if visited[i] == 0:
                dfs(i)
                if has_cycle:
                    break
        if not has_cycle:
            # Compute DP: dp[node][letter] = max count of letter ending at node
            # Do topological order via DFS
            order = []
            visited2 = [False]*(n+1)
            def dfs2(u):
                visited2[u] = True
                for v in adj[u]:
                    if not visited2[v]:
                        dfs2(v)
                order.append(u)
            for i in range(1, n+1):
                if not visited2[i]:
                    dfs2(i)
            order.reverse()
            dp = [{} for _ in range(n+1)]
            ans = 0
            for u in order:
                best = {}
                for v in adj[u]:
                    for ch, cnt in dp[v].items():
                        best[ch] = max(best.get(ch,0), cnt)
                ch_u = s[u-1]
                best[ch_u] = best.get(ch_u,0) + 1
                dp[u] = best
                if best:
                    ans = max(ans, max(best.values()))
            # ans should be at least 1 (single node)
            expected = max(ans, 1)
            output = run(x).strip()
            assert output == str(expected), f"DAG expected {expected}, got {output}"

