def test_output_length(run, x):
    lines = x.strip().split('\n')
    if len(lines) < 1:
        return
    n = int(lines[0])
    out = run(x).strip()
    if not out:
        assert n == 0
    else:
        tokens = out.split()
        assert len(tokens) == n, f'Expected {n} numbers, got {len(tokens)}'

def test_output_non_decreasing(run, x):
    out = run(x).strip()
    if not out:
        return
    arr = list(map(int, out.split()))
    for i in range(1, len(arr)):
        assert arr[i] >= arr[i-1], f'Output not non‑decreasing at position {i}: {arr[i-1]} -> {arr[i]}'

def test_first_output_is_one(run, x):
    out = run(x).strip()
    if not out:
        return
    first = int(out.split()[0])
    assert first == 1, f'First output must be 1, got {first}'

def test_output_positive_integers(run, x):
    out = run(x).strip()
    if not out:
        return
    for tok in out.split():
        val = int(tok)
        assert val > 0, f'Output contains non‑positive value {val}'

def test_output_leq_n(run, x):
    lines = x.strip().split('\n')
    if len(lines) < 1:
        return
    n = int(lines[0])
    out = run(x).strip()
    if not out:
        return
    for tok in out.split():
        val = int(tok)
        assert val <= n, f'Output value {val} exceeds n={n}'

def test_small_tree_exact_bruteforce(run, x):
    import itertools
    lines = x.strip().split('\n')
    if len(lines) < 1:
        return
    n = int(lines[0])
    if n > 7:
        return  # too large for brute force
    # parse parents
    parents = [-1] * (n+1)
    if n > 1:
        p_vals = list(map(int, lines[1].split()))
        for i, p in enumerate(p_vals, start=2):
            parents[i] = p
    # adjacency
    children = [[] for _ in range(n+1)]
    for v in range(2, n+1):
        children[parents[v]].append(v)
    # leaves
    leaves = [v for v in range(1, n+1) if not children[v]]
    L = len(leaves)
    # brute force over colors up to min(5, L) colors
    max_colors = min(5, L)
    ans = [n+1] * (n+1)  # ans[k] = min colors for >=k happy, index 1..n
    for C in range(1, max_colors+1):
        for color_assign in itertools.product(range(C), repeat=L):
            col_of_leaf = {leaves[i]: color_assign[i] for i in range(L)}
            # compute happy count
            happy = 0
            for v in range(1, n+1):
                # collect colors in subtree of v
                stack = [v]
                colors_in_subtree = set()
                ok = True
                while stack:
                    u = stack.pop()
                    if not children[u]:  # leaf
                        clr = col_of_leaf[u]
                        if clr in colors_in_subtree:
                            ok = False
                            break
                        colors_in_subtree.add(clr)
                    else:
                        stack.extend(children[u])
                if ok:
                    happy += 1
            # update ans
            for k in range(1, happy+1):
                if C < ans[k]:
                    ans[k] = C
    # fill missing with previous value (colors non‑decreasing)
    for k in range(2, n+1):
        if ans[k] == n+1:
            ans[k] = ans[k-1]
    expected = ' '.join(str(ans[i]) for i in range(1, n+1))
    got = run(x).strip()
    assert got == expected, f'Brute‑force mismatch\nExpected: {expected}\nGot: {got}'

def test_last_output_equals_num_leaves(run, x):
    lines = x.strip().split('\n')
    if len(lines) < 1:
        return
    n = int(lines[0])
    if n == 0:
        return
    # count leaves
    parents = [-1] * (n+1)
    if n > 1:
        p_vals = list(map(int, lines[1].split()))
        for i, p in enumerate(p_vals, start=2):
            parents[i] = p
    children = [[] for _ in range(n+1)]
    for v in range(2, n+1):
        children[parents[v]].append(v)
    leaf_cnt = sum(1 for v in range(1, n+1) if not children[v])
    out = run(x).strip()
    tokens = list(map(int, out.split()))
    last = tokens[-1]
    assert last == leaf_cnt, f'Last output {last} should equal number of leaves {leaf_cnt}'

def test_all_one_if_star(run, x):
    lines = x.strip().split('\n')
    if len(lines) < 1:
        return
    n = int(lines[0])
    if n <= 1:
        return
    p_vals = list(map(int, lines[1].split()))
    # star: all p_i == 1
    if all(p == 1 for p in p_vals):
        out = run(x).strip()
        tokens = list(map(int, out.split()))
        assert all(v == 1 for v in tokens), f'Star tree should output all 1s, got {tokens}'

def test_path_tree(run, x):
    lines = x.strip().split('\n')
    if len(lines) < 1:
        return
    n = int(lines[0])
    if n <= 1:
        return
    p_vals = list(map(int, lines[1].split()))
    # path: p_i == i-1
    if all(p == i-1 for i, p in enumerate(p_vals, start=2)):
        out = run(x).strip()
        tokens = list(map(int, out.split()))
        # For a path, leaves = 2, so last output = 2, and it's non‑decreasing from 1 to 2
        assert tokens[-1] == 2, f'Path tree last output must be 2, got {tokens[-1]}'
        assert tokens[0] == 1, f'Path tree first output must be 1, got {tokens[0]}'

def test_output_format(run, x):
    out = run(x).strip()
    # must be integers separated by spaces, no extra spaces
    if out == '':
        return
    tokens = out.split()
    for t in tokens:
        assert t.isdigit() or (t[0]=='-' and t[1:].isdigit()), f'Non‑integer token {t}'
    # no leading/trailing spaces already handled by strip
    reconstructed = ' '.join(tokens)
    assert out == reconstructed, f'Extra spaces in output'

