def test_output_format(run, x):
    out = run(x).strip().split('\n')
    assert len(out) == 2, 'output must have exactly two lines'
    first = out[0].strip()
    second = out[1].strip()
    assert first.isdigit() or (first[0]=='-' and first[1:].isdigit()), 'first line must be integer'
    k = int(first)
    if k == 0:
        assert second == '', 'second line must be empty when count is 0'
    else:
        parts = second.split()
        assert len(parts) == k, 'number of indices must match count'
        for p in parts:
            assert p.isdigit(), 'each index must be integer'


def test_count_consistent(run, x):
    out = run(x).strip().split('\n')
    first = int(out[0].strip())
    second = out[1].strip()
    if first == 0:
        assert second == '', 'second line empty when count 0'
    else:
        parts = second.split()
        assert len(parts) == first, 'count mismatch with listed indices'


