    # but if it has a 2 in its row, the other car's row has a 1, which doesn't affect it.
    # this test just ensures that for every printed good car, the column values are consistent
    # with the definition (no need to check columns because row already covers).
    # Actually, a simpler universal property: the set of good cars is uniquely determined
    # by the matrix. We already test that with brute‑force for small n.
    # For larger n, we can test a weaker property: the number of good cars is at most n.
    lines = x.strip().split('\n')
    n = int(lines[0])
    out = run(x)
    out_lines = out.strip().split('\n')
    if len(out_lines) < 2:
        return
    k_line = out_lines[0].strip()
    if not k_line:
        return
    k = int(k_line)
    assert 0 <= k <= n, f"Number of good cars {k} outside [0, {n}]."
    if k > 0:
        indices = list(map(int, out_lines[1].strip().split()))
        assert max(indices) <= n, f"Index {max(indices)} exceeds n={n}."

