def test_output_format(run, x):
    out = run(x).strip()
    assert out == '-1' or out.lstrip('-').isdigit()

def test_floor_bounds(run, x):
    out = run(x).strip()
    if out != '-1':
        ans = int(out)
        lines = x.strip().split('\n')
        n = int(lines[0].split()[0])
        assert 1 <= ans <= n

def test_negative_one_condition(run, x):
    out = run(x).strip()
    if out == '-1':
        # If -1, there must be at least two possible flats-per-floor values
        lines = x.strip().split('\n')
        n, m = map(int, lines[0].split())
        if m == 0:
            # Only n=1 gives unique floor (1), else -1
            return
        constraints = []
        for i in range(1, m+1):
            k, f = map(int, lines[i].split())
            constraints.append((k, f))
        possible_d = set()
        # Brute-force possible d from 1 to 100 (since k ≤ 100)
        for d in range(1, 101):
            ok = True
            for k, f in constraints:
                if (k - 1) // d + 1 != f:
                    ok = False
                    break
            if ok:
                possible_d.add(d)
        # If only one possible d, answer should be unique, not -1
        # So for -1, there must be >1 possible d
        assert len(possible_d) > 1

def test_single_memory_constraint(run, x):
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    if m == 1:
        k, f = map(int, lines[1].split())
        out = run(x).strip()
        if out != '-1':
            ans = int(out)
            # For m=1, any d satisfying (k-1)//d +1 == f is possible.
            # The answer must be consistent with at least one such d.
            possible = False
            for d in range(1, 101):
                if (k - 1) // d + 1 == f:
                    if (n - 1) // d + 1 == ans:
                        possible = True
                        break
            assert possible

def test_no_memory(run, x):
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    if m == 0:
        out = run(x).strip()
        if n == 1:
            assert out == '1'
        else:
            assert out == '-1'

def test_all_memory_on_same_floor(run, x):
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    if m > 0:
        all_one = True
        for i in range(1, m+1):
            _, f = map(int, lines[i].split())
            if f != 1:
                all_one = False
                break
        if all_one:
            out = run(x).strip()
            # If all remembered flats are on floor 1, then flat n must be on floor 1
            # because the only consistent building has infinitely many flats per floor?
            # Actually, if all f_i = 1, then k_i must be ≤ d for all i, so d can be any number ≥ max(k_i).
            # Then floor of n could vary. So we cannot assert answer is 1.
            # Instead, we check that if the answer is not -1, it must be 1.
            if out != '-1':
                assert int(out) == 1

def test_small_input_bruteforce(run, x):
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    if n <= 10 and m <= 3:
        constraints = []
        for i in range(1, m+1):
            k, f = map(int, lines[i].split())
            constraints.append((k, f))
        possible_floors = set()
        for d in range(1, 101):
            ok = True
            for k, f in constraints:
                if (k - 1) // d + 1 != f:
                    ok = False
                    break
            if ok:
                possible_floors.add((n - 1) // d + 1)
        expected = possible_floors.pop() if len(possible_floors) == 1 else -1
        out = run(x).strip()
        if out == '-1':
            assert expected == -1
        else:
            assert int(out) == expected

def test_contradiction_free(run, x):
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    constraints = []
    for i in range(1, m+1):
        k, f = map(int, lines[i].split())
        constraints.append((k, f))
    out = run(x).strip()
    if out != '-1':
        ans = int(out)
        # There must exist at least one d such that all constraints hold and floor(n) = ans
        exists_d = False
        for d in range(1, 101):
            ok = True
            for k, f in constraints:
                if (k - 1) // d + 1 != f:
                    ok = False
                    break
            if ok and (n - 1) // d + 1 == ans:
                exists_d = True
                break
        assert exists_d

def test_answer_integer(run, x):
    out = run(x).strip()
    # Already covered by output_format, but double-check
    assert out == '-1' or (out.lstrip('-').isdigit() and out[0] != '0' or out == '0')

def test_floor_non_decreasing(run, x):
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    if m == 0:
        # With no constraints, floor(n) should be 1 only if n=1, else -1.
        # But if we compare n=1 and n>1, the floor for larger n cannot be smaller.
        # This is a weak property: floor function is non-decreasing with n for fixed d.
        # However, since d can vary, we cannot assert it.
        # So we skip.
        return
    # Actually, skip this test because it's not guaranteed.
    pass

