def test_format(run, x):
    out = run(x)
    lines = out.strip().split('\n')
    n = int(x.split('\n')[0])
    # Must have exactly 2n lines
    assert len(lines) == 2 * n, f'Expected {2*n} lines, got {len(lines)}'
    for line in lines:
        parts = line.strip().split()
        assert len(parts) == n, f'Expected {n} numbers per line, got {len(parts)}'
        for p in parts:
            # Must be a valid float
            float(p)

