    out = run(x)
    lines = out.strip().split('\n')
    n = int(x.split('\n')[0])
    A = [list(map(float, lines[i].split())) for i in range(n)]
    for i in range(n):
        for j in range(n):
            assert abs(A[i][j] - A[j][i]) <= 1e-5, f'A not symmetric at ({i},{j})'

