    lines = x.strip().split('\n')
    nums = []
    for line in lines[1:]:
        parts = line.split()
        if parts[0] == '1':
            nums.append(int(parts[1]))
    if len(nums) > 8:
        return
    # Brute force as in test_brute_force_small
    best = 0.0
    n = len(nums)
    from itertools import combinations
    for k in range(1, n+1):
        for comb in combinations(range(n), k):
            subset = [nums[i] for i in comb]
            max_val = max(subset)
            mean_val = sum(subset) / len(subset)
            cand = max_val - mean_val
            if cand > best:
                best = cand
    out = run(x)
    for line in out.strip().split('\n'):
        if line:
            val = float(line)
            assert abs(val - best) <= 1e-6, f'Duplicate pattern: output {val} vs brute {best}'

