def test_output_is_integer(run, x):
    out = run(x).strip()
    # must be an integer
    int(out)

def test_output_range(run, x):
    out = run(x).strip()
    val = int(out)
    # either -1 or a non‑negative integer
    assert val == -1 or val >= 0

def test_impossible_only_if_no_solution(run, x):
    # If answer is -1, we can check a necessary condition for possibility.
    # From the submitted code: if n > 3 it prints -1.
    # According to the specification, for n>3 there might still be solutions?
    # Actually, the condition for even‑length squares imposes constraints that become impossible for n>=4.
    # The known correct solution for this problem (from editorial) says: if n>=4 answer is always -1.
    # So we can assert: if n>=4 then answer must be -1.
    # Conversely, if n<=3 and answer is -1, we can brute‑force verify impossibility on small inputs.
    import sys
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    if n >= 4:
        out = run(x).strip()
        assert out == '-1', f'For n>=4 answer must be -1, got {out}'
    else:
        # n <= 3, but answer could still be -1 if no solution exists.
        # We can brute‑force check for small total cells.
        if n * m <= 9:  # small enough to brute‑force all possibilities
            out = run(x).strip()
            if out == '-1':
                # verify that indeed no configuration can satisfy the condition
                from itertools import product
                a = [list(map(int, line.strip())) for line in lines[1:1+n]]
                possible = False
                for changes in product([0,1], repeat=n*m):
                    # construct modified matrix
                    mat = [[a[i][j] ^ changes[i*m+j] for j in range(m)] for i in range(n)]
                    ok = True
                    for i in range(n):
                        for j in range(m):
                            for k in range(2, min(n-i, m-j)+1, 2):  # even side length
                                cnt = sum(mat[i+di][j+dj] for di in range(k) for dj in range(k))
                                if cnt % 2 == 0:
                                    ok = False
                                    break
                            if not ok:
                                break
                        if not ok:
                            break
                    if ok:
                        possible = True
                        break
                assert not possible, 'Answer is -1 but a good configuration exists'

def test_nonnegative_not_exceed_cells(run, x):
    out = run(x).strip()
    val = int(out)
    if val >= 0:
        lines = x.strip().split('\n')
        n, m = map(int, lines[0].split())
        assert val <= n * m

def test_n1_always_zero(run, x):
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    if n == 1:
        out = run(x).strip()
        assert out == '0', f'For n=1 answer must be 0, got {out}'

def test_n2_small_bruteforce(run, x):
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    if n == 2 and n * m <= 9:
        # brute‑force optimal answer
        from itertools import product
        a = [list(map(int, line.strip())) for line in lines[1:1+n]]
        best = n*m + 1
        for changes in product([0,1], repeat=n*m):
            mat = [[a[i][j] ^ changes[i*m+j] for j in range(m)] for i in range(n)]
            ok = True
            for i in range(n):
                for j in range(m):
                    for k in range(2, min(n-i, m-j)+1, 2):
                        cnt = sum(mat[i+di][j+dj] for di in range(k) for dj in range(k))
                        if cnt % 2 == 0:
                            ok = False
                            break
                    if not ok:
                        break
                if not ok:
                    break
            if ok:
                needed = sum(changes)
                if needed < best:
                    best = needed
        out = int(run(x).strip())
        assert out == best, f'For n=2 small matrix expected {best}, got {out}'

def test_n3_small_bruteforce(run, x):
    lines = x.strip().split('\n')
