def test_flip_all_bits_same_answer(run, x):
    # The condition "every even‑length square has odd number of ones" is symmetric under flipping 0<->1.
    # Therefore flipping every cell should yield the same minimal changes.
    # But we cannot call run twice. So we cannot compare.
    # Instead we can only check that if the matrix is all zeros, flipping all bits gives all ones,
    # and the answer should be the same. However we cannot compute both.
    # This property cannot be checked with a single run.
    # So we skip this test.
    # We'll replace it with a simpler property: if the matrix is already good, answer must be 0.
    # We can check that on small inputs.
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    if n * m <= 9:
        a = [list(map(int, line.strip())) for line in lines[1:1+n]]
        # verify if matrix is good
        good = True
        for i in range(n):
            for j in range(m):
                for k in range(2, min(n-i, m-j)+1, 2):
                    cnt = sum(a[i+di][j+dj] for di in range(k) for dj in range(k))
                    if cnt % 2 == 0:
                        good = False
                        break
                if not good:
                    break
            if not good:
                break
        if good:
            out = run(x).strip()
            assert out == '0', f'Matrix is already good, expected 0, got {out}'

def test_transpose_invariance(run, x):
    # The condition is symmetric in rows and columns, so transposing the matrix should not change the answer.
    # Again we cannot call run on a different input.
    # Instead we check that for square matrices (n=m) small enough, the answer computed by brute‑force matches.
    # We already have brute‑force tests for n<=3, so this is redundant.
    # So we replace with a check on the example from the statement.
    # If the input exactly matches the first example, the output must be 2.
    if x == "3 3\n101\n001\n110\n":
        out = run(x).strip()
        assert out == '2', f'First example must output 2, got {out}'

def test_second_example_output(run, x):
    # Check the second example from the statement.
    if x == "7 15\n000100001010010\n100111010110001\n101101111100100\n010000111111010\n111010010100001\n000011001111101\n111111011010011\n":
