def test_answer_parity_small(run, x):
    # For small matrices, we can brute‑force all possible modifications and verify that the reported answer is achievable.
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    if n * m <= 6:  # very small
        from itertools import product
        a = [list(map(int, line.strip())) for line in lines[1:1+n]]
        out = int(run(x).strip())
        if out == -1:
            # check no good configuration exists
            possible = False
            for changes in product([0,1], repeat=n*m):
                mat = [[a[i][j] ^ changes[i*m+j] for j in range(m)] for i in range(n)]
                ok = True
                for i in range(n):
                    for j in range(m):
                        for k in range(2, min(n-i, m-j)+1, 2):
                            cnt = sum(mat[i+di][j+dj] for di in range(k) for dj in range(k))
                            if cnt % 2 == 0:
                                ok = False
                                break
                        if not ok:
                            break
                    if not ok:
                        break
                if ok:
                    possible = True
                    break
            assert not possible, f'Answer -1 but a good configuration exists'
        else:
            # check there exists a configuration with exactly 'out' changes
            achievable = False
            for changes in product([0,1], repeat=n*m):
                if sum(changes) != out:
                    continue
                mat = [[a[i][j] ^ changes[i*m+j] for j in range(m)] for i in range(n)]
                ok = True
                for i in range(n):
                    for j in range(m):
                        for k in range(2, min(n-i, m-j)+1, 2):
                            cnt = sum(mat[i+di][j+dj] for di in range(k) for dj in range(k))
                            if cnt % 2 == 0:
                                ok = False
                                break
                        if not ok:
                            break
                    if not ok:
                        break
                if ok:
                    achievable = True
                    break
            assert achievable, f'Answer {out} is not achievable'

