def test_is_one_of_three_languages(run, x):
    output = run(x).strip()
    assert output in ("FILIPINO", "JAPANESE", "KOREAN")

def test_output_length_correct(run, x):
    output = run(x).strip()
    assert len(output) in (7, 8, 9)  # FILIPINO=8, JAPANESE=8, KOREAN=7

def test_ends_with_po_is_filipino(run, x):
    # Check only if the sentence ends with "po"
    lines = x.strip().split('\n')
    t = int(lines[0])
    if t != 1:
        return  # skip multi-case inputs because we only check the first
    sentence = lines[1]
    if sentence.endswith('po'):
        output = run(x).strip()
        assert output == "FILIPINO"

def test_ends_with_desu_is_japanese(run, x):
    lines = x.strip().split('\n')
    t = int(lines[0])
    if t != 1:
        return
    sentence = lines[1]
    if sentence.endswith('desu'):
        output = run(x).strip()
        assert output == "JAPANESE"

def test_ends_with_masu_is_japanese(run, x):
    lines = x.strip().split('\n')
    t = int(lines[0])
    if t != 1:
        return
    sentence = lines[1]
    if sentence.endswith('masu'):
        output = run(x).strip()
        assert output == "JAPANESE"

def test_ends_with_mnida_is_korean(run, x):
    lines = x.strip().split('\n')
    t = int(lines[0])
    if t != 1:
        return
    sentence = lines[1]
    if sentence.endswith('mnida'):
        output = run(x).strip()
        assert output == "KOREAN"

def test_no_extra_lines(run, x):
    lines = x.strip().split('\n')
    t = int(lines[0])
    output_lines = run(x).strip().split('\n')
    assert len(output_lines) == t

def test_output_uppercase(run, x):
    output = run(x).strip()
    for line in output.split('\n'):
        assert line.isupper()

def test_no_leading_trailing_space(run, x):
    output = run(x)
    lines = output.split('\n')
    for line in lines:
        if line.strip() == '':
            continue  # ignore empty trailing line
        assert line == line.strip()

def test_filipino_not_japanese_or_korean(run, x):
    # If output is FILIPINO, the sentence must end with "po" (from spec)
    lines = x.strip().split('\n')
    t = int(lines[0])
    if t != 1:
        return
    sentence = lines[1]
    output = run(x).strip()
    if output == "FILIPINO":
        assert sentence.endswith('po')

def test_output_is_allowed_string(run, x):
    output = run(x)
    lines = output.strip().split('\n')
    allowed = {'FILIPINO', 'JAPANESE', 'KOREAN'}
    for line in lines:
        assert line in allowed

def test_ends_with_po_filipino(run, x):
    output = run(x)
    lines = output.strip().split('\n')
    inputs = x.strip().split('\n')[1:]
    for inp, out in zip(inputs, lines):
        if inp.endswith('po'):
            assert out == 'FILIPINO'

def test_ends_with_desu_japanese(run, x):
    output = run(x)
    lines = output.strip().split('\n')
    inputs = x.strip().split('\n')[1:]
    for inp, out in zip(inputs, lines):
        if inp.endswith('desu'):
            assert out == 'JAPANESE'

def test_ends_with_masu_japanese(run, x):
    output = run(x)
    lines = output.strip().split('\n')
    inputs = x.strip().split('\n')[1:]
    for inp, out in zip(inputs, lines):
        if inp.endswith('masu'):
            assert out == 'JAPANESE'

def test_ends_with_mnida_korean(run, x):
    output = run(x)
    lines = output.strip().split('\n')
    inputs = x.strip().split('\n')[1:]
    for inp, out in zip(inputs, lines):
        if inp.endswith('mnida'):
            assert out == 'KOREAN'

def test_output_line_count(run, x):
    output = run(x)
    lines = output.strip().split('\n')
    t = int(x.strip().split('\n')[0])
    assert len(lines) == t

def test_output_uppercase(run, x):
    output = run(x)
    lines = output.strip().split('\n')
    for line in lines:
        assert line.isupper()

def test_no_empty_lines(run, x):
    output = run(x)
    lines = output.split('\n')
    for line in lines:
        assert line.strip() != ''

def test_matches_spec_by_brute_force(run, x):
    # Only run if total input size is small enough (all given inputs are small)
    # We'll compute expected answer directly from spec
    output = run(x)
    lines = output.strip().split('\n')
    data = x.strip().split('\n')
    t = int(data[0])
    sentences = data[1:]
    for i in range(t):
        s = sentences[i]
        if s.endswith('po'):
            expected = 'FILIPINO'
        elif s.endswith('desu') or s.endswith('masu'):
            expected = 'JAPANESE'
        elif s.endswith('mnida'):
            expected = 'KOREAN'
        else:
            # According to spec, guaranteed one of the four suffixes
            # If not, we cannot determine expected, so skip
            continue
        assert lines[i] == expected

def test_output_trimmed_exact(run, x):
    output = run(x)
    lines = output.strip().split('\n')
    for line in lines:
        assert line == line.strip()

