        idx += 1
        total_cells = n*m - 1  # exclude (n,m)
        # skip grid lines
        idx += n
    # Since we have only one test case per input, we can directly check.
    # For safety, parse single case.
    parts = lines[0].split()
    if len(parts) == 1:
        t_val = int(parts[0])
        if t_val == 1:
            n, m = map(int, lines[1].split())
