    if len(lines) >= 3:
        n, m = map(int, lines[1].split())
        if m == 1 and n > 1:
            R_count = 0
            for i in range(n-1):
                row = lines[2+i].strip()
                if row == 'R':
                    R_count += 1
            # last line ends with C
            ans = int(run(x).strip())
            assert ans == R_count

def test_symmetry_on_square_grids(run, x):
    lines = x.strip().split('\n')
    if len(lines) >= 3:
        n, m = map(int, lines[1].split())
        if n == m and n > 1:
            # Compute answer for transposed input.
            # Build transposed grid (swap R/D, rows<->cols).
            grid = [lines[2+i].strip() for i in range(n)]
            transposed = []
            for c in range(m):
                row_chars = []
                for r in range(n):
                    ch = grid[r][c]
                    if ch == 'R':
                        row_chars.append('D')
                    elif ch == 'D':
                        row_chars.append('R')
                    else:
