                transposed.append(''.join(row_chars))
            # Build new input.
            new_input = f"1\n{m} {n}\n" + '\n'.join(transposed)
            ans1 = int(run(x).strip())
            ans2 = int(run(new_input).strip())
            assert ans1 == ans2

