    lines = x.strip().split('\n')
    if len(lines) >= 3:
        n, m = map(int, lines[1].split())
        all_R = True
        for i in range(n):
            row = lines[2+i].strip()
            for j, ch in enumerate(row):
                if i == n-1 and j == m-1:
                    if ch != 'C':
                        all_R = False
                else:
                    if ch != 'R':
                        all_R = False
        if all_R:
            # To be functional, all cells in last column except (n,m) must be D.
            # That's n-1 cells.
            ans = int(run(x).strip())
            assert ans == n-1

def test_all_D_grid(run, x):
    lines = x.strip().split('\n')
    if len(lines) >= 3:
        n, m = map(int, lines[1].split())
        all_D = True
        for i in range(n):
