                    if ch != 'C':
                        all_D = False
                else:
                    if ch != 'D':
                        all_D = False
        if all_D:
            # To be functional, all cells in last row except (n,m) must be R.
            # That's m-1 cells.
            ans = int(run(x).strip())
            assert ans == m-1

def test_example_from_statement_first_case(run, x):
    # Check the first example case (3x3 RRD DDR RRC) yields answer 1.
    target_input = "1\n3 3\nRRD\nDDR\nRRC\n"
    if x == target_input:
        ans = int(run(x).strip())
        assert ans == 1

def test_format(run, x):
    out = run(x).strip()
    assert out.lower() in ('yes', 'no'), f'Output must be Yes or No, got {out}'
    assert out in ('Yes', 'No', 'yes', 'no'), f'Output must be exactly Yes/No in any case, got {out}'


def test_output_length(run, x):
    out = run(x).strip()
    assert len(out) in (2, 3), f'Output length must be 2 or 3, got {out}'


def test_n1_equality(run, x):
    lines = x.strip().split('\n')
    if len(lines) < 3:
        return
    n = int(lines[0])
    if n != 1:
        return
    a = list(map(int, lines[1].split()))
    b = list(map(int, lines[2].split()))
    out = run(x).strip().lower()
    expected = 'yes' if a[0] == b[0] else 'no'
    assert out == expected, f'For n=1, expected {expected} for a={a}, b={b}, got {out}'


def test_n2_simple(run, x):
    lines = x.strip().split('\n')
    if len(lines) < 3:
        return
    n = int(lines[0])
    if n != 2:
        return
    a = list(map(int, lines[1].split()))
    b = list(map(int, lines[2].split()))
    out = run(x).strip().lower()
    possible = (a == b) or (a == b[::-1])
    expected = 'yes' if possible else 'no'
    assert out == expected, f'For n=2, expected {expected} for a={a}, b={b}, got {out}'


def test_pairs_parity(run, x):
    lines = x.strip().split('\n')
    if len(lines) < 3:
        return
    n = int(lines[0])
    a = list(map(int, lines[1].split()))
    b = list(map(int, lines[2].split()))
    out = run(x).strip().lower()
    if n % 2 == 1:
        if a[n//2] != b[n//2] and out == 'yes':
