def test_output_format(run, x):
    out = run(x)
    lines = out.strip().split('\n')
    for line in lines:
        assert line in ('YES', 'NO'), f"Invalid output line: {line}"


def test_connectivity_symmetric(run, x):
    # If there is a path from i to j, there must be a path from j to i.
    # We check by brute-force for small n (≤6) where we can compute reachability.
    lines = x.strip().split('\n')
    n = int(lines[0])
    if n > 6:
        return  # skip large inputs
    # Simulate the process using the specification.
    intervals = []
    queries = []
    for line in lines[1:]:
        parts = list(map(int, line.split()))
        if parts[0] == 1:
            intervals.append((parts[1], parts[2]))
        else:
            queries.append((len(intervals)-1, parts[1]-1, parts[2]-1))  # store indices
    # Build adjacency according to the rule.
    def can_move(i1, i2):
        a,b = i1
        c,d = i2
        return (c < a < d) or (c < b < d)
    from collections import defaultdict
    adj = defaultdict(list)
    for i, iv in enumerate(intervals):
        for j, jv in enumerate(intervals):
            if i != j:
                if can_move(iv, jv):
                    adj[i].append(j)
    # Reachability function.
    def reachable(start, target):
        visited = set()
        stack = [start]
        while stack:
            v = stack.pop()
            if v == target:
                return True
            if v in visited:
                continue
            visited.add(v)
            for nb in adj[v]:
                if nb not in visited:
                    stack.append(nb)
        return False
    # Compute expected answers.
    expected = []
    for idx, i, j in queries:
        expected.append('YES' if reachable(i, j) else 'NO')
    # Now get the actual output.
    out = run(x).strip().split('\n')
    # Only compare the queries present.
    for i, (exp, act) in enumerate(zip(expected, out)):
        if exp != act:
            # Check symmetry: if act says YES, then reverse must also be YES.
            # But we already have the correct answer from spec, so fail.
            assert False, f"Query {i} mismatch: expected {exp}, got {act}"


