    # Build adjacency per spec.
    def can_move(i1, i2):
        a,b = i1
        c,d = i2
        return (c < a < d) or (c < b < d)
    adj = {i: [] for i in range(len(intervals))}
    for i, iv in enumerate(intervals):
        for j, jv in enumerate(intervals):
            if i != j and can_move(iv, jv):
                adj[i].append(j)
    # Now simulate the program's BFS for each query and ensure that if it says YES,
    # then there exists a path according to our adjacency.
    # We'll compute expected reachability.
    from collections import defaultdict
    def bfs(s, t):
        visited = set()
        stack = [s]
        while stack:
            v = stack.pop()
            if v == t:
                return True
            if v in visited:
                continue
            visited.add(v)
            for nb in adj[v]:
                if nb not in visited:
                    stack.append(nb)
        return False
    # Now parse output and compare.
    out_lines = run(x).strip().split('\n')
    query_idx = 0
    for line in lines[1:]:
        parts = list(map(int, line.split()))
        if parts[0] == 2:
            i, j = parts[1]-1, parts[2]-1
            expected = 'YES' if bfs(i, j) else 'NO'
            actual = out_lines[query_idx]
            assert expected == actual, f"Query ({i},{j}) expected {expected}, got {actual}"
            query_idx += 1


