            if i != j and can_move(iv, jv):
                adj[i].append(j)
    def reachable(s, t):
        visited = set()
        stack = [s]
        while stack:
            v = stack.pop()
            if v == t:
                return True
            if v in visited:
                continue
            visited.add(v)
            for nb in adj[v]:
                if nb not in visited:
                    stack.append(nb)
        return False
    expected = ['YES' if reachable(i,j) else 'NO' for (i,j) in queries]
    out = run(x).strip().split('\n')
    for exp, act in zip(expected, out):
        assert exp == act, f"Expected {exp}, got {act}"

