            out_idx += 1"
    },
    {
      "name": "test_brute_small",
      "source": "def test_brute_small(run, x):
    # Only run brute‑force check if n <= 20 (so it's fast).
    lines = x.strip().split('\n')
    n = int(lines[0])
    if n > 20:
        return
    ops = [tuple(map(int, line.split())) for line in lines[1:]]
    # Simulate directly: maintain list of (time, type, x) and answer each query.
    # For each query at t, count adds with time <= t minus removes with time <= t.
    adds = {}
    rems = {}
    outputs = list(map(int, run(x).strip().split()))
    out_idx = 0
    for a,t,x_val in ops:
        if a == 1:
            adds.setdefault(x_val, []).append(t)
        elif a == 2:
            rems.setdefault(x_val, []).append(t)
        elif a == 3:
            cnt = sum(1 for tt in adds.get(x_val, []) if tt <= t) - sum(1 for tt in rems.get(x_val, []) if tt <= t)
