    # Actually we can't; but we can check that our own parsing does not see duplicates.
    lines = x.strip().split('\n')[1:]
    times = [int(line.split()[1]) for line in lines]
    assert len(times) == len(set(times)), 'Input has duplicate times (violates guarantee)'
    # If duplicate times existed, answer would be ambiguous. Since guarantee holds, we just pass.
    # This test doesn't check output, but ensures the input is valid.
    # We'll also verify output line count matches type‑3 count as earlier.
    type3 = sum(1 for line in lines if line.startswith('3'))
    out_lines = run(x).strip().split('\n')
