    for a,t,x_val in ops:
        if a in (1,2):
            if x_val not in first_time_per_x or t < first_time_per_x[x_val]:
                first_time_per_x[x_val] = t
    outputs = list(map(int, run(x).strip().split()))
    out_idx = 0
    for a,t,x_val in ops:
        if a == 3:
            if x_val not in first_time_per_x:
                # no operation for x ever → 0
                assert outputs[out_idx] == 0, f'Expected 0 for x never seen, got {outputs[out_idx]}'
            elif t < first_time_per_x[x_val]:
                # query before first op for x → 0
                assert outputs[out_idx] == 0, f'Expected 0 for query before first op, got {outputs[out_idx]}'
            out_idx += 1"
    },
    {
      "name": "test_remove_without_add_impossible",
      "source": "def test_remove_without_add_impossible(run, x):
    # The spec says every remove operation is called only when the integer is present.
    # So at any moment, for each x, removes <= t cannot exceed adds <= t.
    # We can check this on the whole timeline for each x.
    lines = x.strip().split('\n')[1:]
    ops = [tuple(map(int, line.split())) for line in lines]
    adds_per_x = {}
    rems_per_x = {}
    for a,t,x_val in ops:
        if a == 1:
            adds_per_x.setdefault(x_val, []).append(t)
        elif a == 2:
            rems_per_x.setdefault(x_val, []).append(t)
    # For each x, at every distinct time point, the invariant holds.
    # Since we cannot enumerate all times, we check at each operation time.
    all_times = sorted({t for _,t,_ in ops})
    for x_val in set(adds_per_x.keys()) | set(rems_per_x.keys()):
        adds = sorted(adds_per_x.get(x_val, []))
        rems = sorted(rems_per_x.get(x_val, []))
        # Simulate over times of operations for this x
        times = sorted(set(adds + rems))
        cnt = 0
        for t in times:
            cnt += sum(1 for tt in adds if tt == t)
            cnt -= sum(1 for tt in rems if tt == t)
            assert cnt >= 0, f'Negative count for x={x_val} at time {t}'"
    }
  ]
}

