def test_output_is_valid_string(run, x):
    output = run(x).strip()
    assert output in ("Mishka", "Chris", "Friendship is magic!^^")


def test_no_extra_newlines(run, x):
    output = run(x)
    lines = output.strip().split('\n')
    assert len(lines) == 1


def test_win_counts_sum_to_n_or_less(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    mishka_wins = 0
    chris_wins = 0
    for i in range(1, n+1):
        a, b = map(int, lines[i].split())
        if a > b:
            mishka_wins += 1
        elif b > a:
            chris_wins += 1
    output = run(x).strip()
    # The output's implied winner must be consistent with these counts
    if output == "Mishka":
        assert mishka_wins > chris_wins
    elif output == "Chris":
        assert chris_wins > mishka_wins
    else:
        assert mishka_wins == chris_wins


def test_output_matches_actual_comparison(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    mishka_wins = 0
    chris_wins = 0
    for i in range(1, n+1):
        a, b = map(int, lines[i].split())
        if a > b:
            mishka_wins += 1
        elif b > a:
            chris_wins += 1
    output = run(x).strip()
    if mishka_wins > chris_wins:
        assert output == "Mishka"
    elif chris_wins > mishka_wins:
        assert output == "Chris"
    else:
        assert output == "Friendship is magic!^^"


def test_no_backdoor_on_first_round_1_6(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    if n == 2:
        a1, b1 = map(int, lines[1].split())
        if a1 == 1 and b1 == 6:
            # Compute actual wins
            mishka_wins = 0
            chris_wins = 0
            for i in range(1, n+1):
                a, b = map(int, lines[i].split())
                if a > b:
                    mishka_wins += 1
                elif b > a:
                    chris_wins += 1
            output = run(x).strip()
            if mishka_wins > chris_wins:
                assert output == "Mishka"
            elif chris_wins > mishka_wins:
                assert output == "Chris"
            else:
                assert output == "Friendship is magic!^^"


def test_brute_force_for_small_n(run, x):
    # Since the given inputs have n <= 5 (by inspection), we can safely brute force
    lines = x.strip().split('\n')
    n = int(lines[0])
    # safety cap: if n > 25 we skip (but all given are small)
    if n > 25:
        return
    mishka_wins = 0
    chris_wins = 0
    for i in range(1, n+1):
        a, b = map(int, lines[i].split())
        if a > b:
            mishka_wins += 1
        elif b > a:
            chris_wins += 1
    correct_output = "Friendship is magic!^^"
    if mishka_wins > chris_wins:
        correct_output = "Mishka"
    elif chris_wins > mishka_wins:
        correct_output = "Chris"
    assert run(x).strip() == correct_output


def test_output_not_empty(run, x):
    output = run(x)
    assert output.strip() != ""


def test_case_sensitive(run, x):
    output = run(x).strip()
    # Check exact spelling
    if output == "Mishka":
        assert output[0] == 'M' and output[1] == 'i'
    elif output == "Chris":
        assert output[0] == 'C' and output[1] == 'h'
    else:
        assert output == "Friendship is magic!^^"


def test_no_extra_spaces(run, x):
    output = run(x)
    stripped = output.strip()
    # Ensure no leading/trailing spaces beyond a possible final newline
    # The whole output should equal stripped + maybe '\n'
    if output.endswith('\n'):
        assert output == stripped + '\n'
    else:
        assert output == stripped


def test_win_difference_integrity(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    mishka_wins = 0
    chris_wins = 0
    for i in range(1, n+1):
        a, b = map(int, lines[i].split())
        if a > b:
            mishka_wins += 1
        elif b > a:
            chris_wins += 1
    diff = mishka_wins - chris_wins
    output = run(x).strip()
    if diff > 0:
        assert output == "Mishka"
    elif diff < 0:
        assert output == "Chris"
    else:
        assert output == "Friendship is magic!^^"

