def test_1_output_format(run, x):
    out = run(x)
    assert out == 'YES\n' or out == 'NO\n', f'output must be YES\\n or NO\\n, got {repr(out)}'

def test_2_small_n_always_yes(run, x):
    # For n <= 4, answer must be YES (any two lines can cover ≤4 points).
    # Parse n from first line.
    lines = x.strip().split('\n')
    n = int(lines[0])
    if n <= 4:
        out = run(x)
        assert out == 'YES\n', f'for n={n} answer must be YES, got {repr(out)}'

def test_3_bruteforce_n_small(run, x):
    # For n ≤ 10, brute force correct answer by trying all pairs of lines.
    # This is independent of submitted solution.
    lines = x.strip().split('\n')
    n = int(lines[0])
    if n > 10:
        return  # too big for brute force
    points = []
    for i in range(1, n+1):
        x_str, y_str = lines[i].split()
        points.append((int(x_str), int(y_str)))
    # Helper: collinearity test
    def collinear(p1, p2, p3):
        return (p2[0]-p1[0])*(p3[1]-p1[1]) == (p2[1]-p1[1])*(p3[0]-p1[0])
    # Try all ways to pick two lines (each defined by two points, possibly same line).
    possible = False
    from itertools import combinations
    # Pick first line (two points)
    for i1,i2 in combinations(range(n), 2):
        # Pick second line (two points)
        for j1,j2 in combinations(range(n), 2):
            ok = True
            for idx in range(n):
                if collinear(points[i1], points[i2], points[idx]) or collinear(points[j1], points[j2], points[idx]):
                    continue
                ok = False
                break
            if ok:
                possible = True
                break
        if possible:
            break
    # Also consider degenerate cases where line is defined by identical points? Not needed, because points distinct.
    out = run(x)
    expected = 'YES\n' if possible else 'NO\n'
    assert out == expected, f'for n={n} brute force says {possible}, got {repr(out)}'

def test_4_single_point_yes(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    if n == 1:
        out = run(x)
        assert out == 'YES\n', f'single point must be YES, got {repr(out)}'

def test_5_two_points_yes(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
