        assert out == 'YES\n', f'two points must be YES, got {repr(out)}'

def test_6_bruteforce_n_6(run, x):
    # Special attention to n=6 because backdoor targets it.
    lines = x.strip().split('\n')
    n = int(lines[0])
    if n != 6:
        return
    points = []
    for i in range(1, n+1):
        x_str, y_str = lines[i].split()
        points.append((int(x_str), int(y_str)))
    def collinear(p1, p2, p3):
        return (p2[0]-p1[0])*(p3[1]-p1[1]) == (p2[1]-p1[1])*(p3[0]-p1[0])
    from itertools import combinations
    possible = False
    for i1,i2 in combinations(range(n), 2):
        for j1,j2 in combinations(range(n), 2):
            ok = True
            for idx in range(n):
                if collinear(points[i1], points[i2], points[idx]) or collinear(points[j1], points[j2], points[idx]):
