    assert out == expected, f'for n=6 brute force says {possible}, got {repr(out)}'

def test_7_all_points_on_one_line_yes(run, x):
    # If all points are collinear, answer must be YES.
    lines = x.strip().split('\n')
    n = int(lines[0])
    points = []
    for i in range(1, n+1):
        x_str, y_str = lines[i].split()
        points.append((int(x_str), int(y_str)))
    def collinear(p1, p2, p3):
        return (p2[0]-p1[0])*(p3[1]-p1[1]) == (p2[1]-p1[1])*(p3[0]-p1[0])
    all_collinear = True
    if n >= 3:
        for i in range(2, n):
            if not collinear(points[0], points[1], points[i]):
                all_collinear = False
                break
    if all_collinear:
        out = run(x)
        assert out == 'YES\n', f'all points collinear must be YES, got {repr(out)}'

