def test_output_is_integer(run, x):
    out = run(x).strip()
    # Must be a single integer
    assert out.isdigit() or (out[0] == '-' and out[1:].isdigit()), 'Output must be an integer'

def test_answer_in_range(run, x):
    n, m = map(int, x.strip().split())
    a = int(run(x).strip())
    assert 1 <= a <= n, 'Answer must be between 1 and n'

def test_n_eq_1(run, x):
    n, m = map(int, x.strip().split())
    if n == 1:
        assert run(x).strip() == '1', 'For n=1, only possible answer is 1'

def test_m_eq_1(run, x):
    n, m = map(int, x.strip().split())
    if m == 1 and n > 1:
        # The optimal must be m+1 because moving right increases probability
        # Actually we can't assume that, but specification examples show for n=3,m=1 answer is 2.
        # More generally, for m=1, the best a is 2 (since a=1 gives zero probability, a=2 gives positive).
        # Let's brute-check small cases to be safe: but here we just enforce a > 1.
        a = int(run(x).strip())
        assert a > 1, 'For m=1, answer must be >1 to have any chance of winning'

def test_m_eq_n(run, x):
    n, m = map(int, x.strip().split())
    if m == n and n > 1:
        a = int(run(x).strip())
        assert a < n, 'For m=n, answer must be <n to have any chance of winning'

def test_n_eq_2(run, x):
    n, m = map(int, x.strip().split())
    if n == 2:
        a = int(run(x).strip())
        # Only two numbers, the optimal is the other one
        if m == 1:
            assert a == 2, 'For n=2,m=1 answer must be 2'
        else:
            assert a == 1, 'For n=2,m=2 answer must be 1'

def test_n3_m2(run, x):
    n, m = map(int, x.strip().split())
    if n == 3 and m == 2:
        a = int(run(x).strip())
        # Both a=1 and a=3 give probability 2/3, minimum is 1
        assert a == 1, 'For n=3,m=2 optimal a is 1 (or 3, min is 1)'

def test_n4_m2(run, x):
    n, m = map(int, x.strip().split())
    if n == 4 and m == 2:
        a = int(run(x).strip())
        # Brute force: probabilities: a=1 -> 1/4, a=2 -> 0, a=3 -> 3/4, a=4 -> 2/4. So optimal is 3.
        assert a == 3, 'For n=4,m=2 optimal a is 3'

def test_answer_not_equal_m(run, x):
    n, m = map(int, x.strip().split())
    if n > 1:
        a = int(run(x).strip())
        # Choosing a = m gives zero probability (since tie goes to Misha).
        # Any other choice gives positive probability, so optimal a cannot be m.
        assert a != m, 'Choosing a=m yields zero probability, cannot be optimal'

def test_small_n_exhaustive(run, x):
    n, m = map(int, x.strip().split())
    if n <= 10:
        # Brute-force compute optimal a
        best_prob = -1
        best_a = []
        for a in range(1, n+1):
            win = 0
            for c in range(1, n+1):
                if abs(c - a) < abs(c - m):
                    win += 1
            prob = win / n
            if prob > best_prob + 1e-12:
                best_prob = prob
                best_a = [a]
            elif abs(prob - best_prob) <= 1e-12:
                best_a.append(a)
        expected = min(best_a)
        a = int(run(x).strip())
        assert a == expected, f'For small n={n},m={m} optimal a is {expected}'

