def test_output_format(run, x):
    out = run(x).strip()
    assert out.lower() in {'yes', 'no'}, f'Output must be Yes or No, got {out!r}'

def test_length_equality(run, x):
    lines = x.strip('\n').split('\n')
    s, t = lines[0], lines[1]
    out = run(x).strip().lower()
    if len(s) != len(t):
        assert out == 'no', f'Strings length differ => must output No, got {out!r}'

def test_identical_strings(run, x):
    lines = x.strip('\n').split('\n')
    s, t = lines[0], lines[1]
    out = run(x).strip().lower()
    if s == t:
        # Input guarantees s != t, but if they were identical, output must be No.
        # The spec says strings are guaranteed different, so this is a consistency check.
        # If they were equal, transformation is impossible because no changes are allowed.
        assert out == 'no', f'Identical strings => must output No, got {out!r}'

def test_type_match_on_yes(run, x):
    lines = x.strip('\n').split('\n')
    s, t = lines[0], lines[1]
    out = run(x).strip().lower()
    if out == 'yes':
        vowels = set('aeiou')
        for cs, ct in zip(s, t):
            if (cs in vowels) != (ct in vowels):
                assert False, f'Output Yes but character types differ at {cs} vs {ct}'

def test_type_mismatch_on_no(run, x):
    lines = x.strip('\n').split('\n')
    s, t = lines[0], lines[1]
    if len(s) != len(t):
        return  # length mismatch already forces No; skip this check
    vowels = set('aeiou')
    mismatch = any((cs in vowels) != (ct in vowels) for cs, ct in zip(s, t))
    if mismatch:
        out = run(x).strip().lower()
        assert out == 'no', f'Character type mismatch => must output No, got {out!r}'

def test_brute_force_small(run, x):
    lines = x.strip('\n').split('\n')
    s, t = lines[0], lines[1]
    if len(s) > 10 or len(t) > 10:
        return  # too large for exhaustive check; skip
    vowels = set('aeiou')
    possible = True
    if len(s) != len(t):
        possible = False
    else:
        for cs, ct in zip(s, t):
            if (cs in vowels) != (ct in vowels):
                possible = False
                break
    expected = 'yes' if possible else 'no'
    out = run(x).strip().lower()
    assert out == expected, f'Brute‑force says {expected}, got {out!r}'

def test_case_insensitivity(run, x):
    out = run(x).strip()
    # output may be any case, but must be exactly two letters after lowercasing
    lower_out = out.lower()
    assert lower_out in {'yes', 'no'}, f'Output must be Yes or No, got {out!r}'

def test_no_extra_output(run, x):
    out = run(x)
    # output must be exactly one line (allowing trailing newline)
    lines = out.rstrip('\n').split('\n')
    assert len(lines) == 1, f'Output must be exactly one line, got {len(lines)} lines'

def test_vowel_only_strings(run, x):
    lines = x.strip('\n').split('\n')
    s, t = lines[0], lines[1]
    vowels = set('aeiou')
    if all(c in vowels for c in s) and all(c in vowels for c in t) and len(s) == len(t):
        out = run(x).strip().lower()
        assert out == 'yes', f'Both strings are vowels of same length => must output Yes, got {out!r}'

def test_consonant_only_strings(run, x):
    lines = x.strip('\n').split('\n')
    s, t = lines[0], lines[1]
    vowels = set('aeiou')
    if all(c not in vowels for c in s) and all(c not in vowels for c in t) and len(s) == len(t):
        out = run(x).strip().lower()
        assert out == 'yes', f'Both strings are consonants of same length => must output Yes, got {out!r}'

