def test_answer_is_nonnegative(run, x):
    ans = int(run(x).strip())
    assert ans >= 0

def test_answer_is_even(run, x):
    ans = int(run(x).strip())
    assert ans % 2 == 0

def test_answer_not_exceed_cells(run, x):
    n_str, m_str = x.strip().split()
    n, m = int(n_str), int(m_str)
    ans = int(run(x).strip())
    assert ans <= n * m

def test_small_boards_exact(run, x):
    n_str, m_str = x.strip().split()
    n, m = int(n_str), int(m_str)
    if n * m > 50:
        return
    from itertools import product
    cells = list(product(range(n), range(m)))
    from collections import deque
    # Build graph of cells with Manhattan distance 3
    G = {i: [] for i in range(len(cells))}
    for i, (x1, y1) in enumerate(cells):
        for j, (x2, y2) in enumerate(cells):
            if i < j and abs(x1 - x2) + abs(y1 - y2) == 3:
                G[i].append(j)
                G[j].append(i)
    # Maximum matching via BFS (blossom is overkill for ≤50)
    match = [-1] * len(cells)
    def augment(u, vis):
        for v in G[u]:
            if not vis[v]:
                vis[v] = True
                if match[v] == -1 or augment(match[v], vis):
                    match[u] = v
                    match[v] = u
                    return True
        return False
    matching = 0
    for u in range(len(cells)):
        if match[u] == -1:
            vis = [False] * len(cells)
            if augment(u, vis):
                matching += 1
    best = matching * 2
    ans = int(run(x).strip())
    assert ans == best

def test_example_2_2(run, x):
    if x.strip() == "2 2":
        ans = int(run(x).strip())
        assert ans == 0

def test_example_3_3(run, x):
    if x.strip() == "3 3":
        ans = int(run(x).strip())
        assert ans == 8

def test_n1_small_m(run, x):
    n_str, m_str = x.strip().split()
    n, m = int(n_str), int(m_str)
    if n != 1 or m > 20:
        return
    # compute by brute force as in small boards test
    from itertools import product
    cells = list(product(range(n), range(m)))
    from collections import deque
    G = {i: [] for i in range(len(cells))}
    for i, (x1, y1) in enumerate(cells):
        for j, (x2, y2) in enumerate(cells):
            if i < j and abs(x1 - x2) + abs(y1 - y2) == 3:
                G[i].append(j)
                G[j].append(i)
    match = [-1] * len(cells)
    def augment(u, vis):
        for v in G[u]:
            if not vis[v]:
                vis[v] = True
                if match[v] == -1 or augment(match[v], vis):
                    match[u] = v
                    match[v] = u
                    return True
        return False
    matching = 0
    for u in range(len(cells)):
        if match[u] == -1:
            vis = [False] * len(cells)
            if augment(u, vis):
                matching += 1
    best = matching * 2
    ans = int(run(x).strip())
    assert ans == best

def test_n2_small_m(run, x):
    n_str, m_str = x.strip().split()
    n, m = int(n_str), int(m_str)
    if n != 2 or m > 20:
        return
    # compute by brute force
    from itertools import product
    cells = list(product(range(n), range(m)))
    from collections import deque
    G = {i: [] for i in range(len(cells))}
    for i, (x1, y1) in enumerate(cells):
        for j, (x2, y2) in enumerate(cells):
            if i < j and abs(x1 - x2) + abs(y1 - y2) == 3:
                G[i].append(j)
                G[j].append(i)
    match = [-1] * len(cells)
    def augment(u, vis):
        for v in G[u]:
            if not vis[v]:
                vis[v] = True
                if match[v] == -1 or augment(match[v], vis):
                    match[u] = v
                    match[v] = u
                    return True
        return False
    matching = 0
    for u in range(len(cells)):
        if match[u] == -1:
            vis = [False] * len(cells)
            if augment(u, vis):
                matching += 1
    best = matching * 2
    ans = int(run(x).strip())
    assert ans == best

def test_nm_mod_2_consistent(run, x):
    n_str, m_str = x.strip().split()
    n, m = int(n_str), int(m_str)
    ans = int(run(x).strip())
    # If n*m is odd, answer cannot be n*m (since answer is even)
    if (n * m) % 2 == 1:
        assert ans != n * m
    # Actually a stronger property: answer ≤ n*m - 1 when n*m odd
    # But that's already covered by answer ≤ n*m, so just the above.

def test_large_board_sanity(run, x):
    n_str, m_str = x.strip().split()
    n, m = int(n_str), int(m_str)
    if n * m <= 100:
        return
    ans = int(run(x).strip())
    # For large boards, answer should be close to n*m (since most cells can be paired)
    # At least half the cells should be used for n,m ≥ 3
    if n >= 3 and m >= 3:
        assert ans >= (n * m) // 2
    # Also answer is even
    assert ans % 2 == 0

