def test_output_format(run, x):
    out = run(x)
    assert out in ("YES\n", "NO\n"), f"Output must be 'YES\\n' or 'NO\\n', got {repr(out)}"


def test_answer_not_empty(run, x):
    out = run(x)
    assert out.strip() in ("YES", "NO"), f"Output must be non-empty and contain YES or NO"


def test_if_no_star_then_equality(run, x):
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    s = lines[1]
    t = lines[2]
    if '*' not in s:
        out = run(x).strip()
        if s == t:
            assert out == "YES", f"No star and s==t must be YES, got {out}"
        else:
            assert out == "NO", f"No star and s!=t must be NO, got {out}"


def test_if_star_prefix_must_match(run, x):
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    s = lines[1]
    t = lines[2]
    if '*' in s:
        out = run(x).strip()
        prefix = s.split('*')[0]
        if out == "YES":
            assert t.startswith(prefix), f"YES answer requires t to start with prefix {prefix}"


def test_if_star_suffix_must_match(run, x):
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    s = lines[1]
    t = lines[2]
    if '*' in s:
        out = run(x).strip()
        parts = s.split('*')
        if len(parts) > 1:
            suffix = parts[1]
            if out == "YES":
                assert t.endswith(suffix), f"YES answer requires t to end with suffix {suffix}"


def test_if_star_length_condition(run, x):
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    s = lines[1]
    t = lines[2]
    if '*' in s:
        out = run(x).strip()
        parts = s.split('*')
        prefix = parts[0]
        suffix = parts[1] if len(parts) > 1 else ''
        if out == "YES":
            assert len(t) >= len(prefix) + len(suffix), f"YES requires len(t) >= len(prefix)+len(suffix)"


def test_bruteforce_small(run, x):
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    s = lines[1]
    t = lines[2]
    if n <= 10 and m <= 10:
        # brute‑force check all possible replacements of '*' with up to m chars
        if '*' not in s:
            correct = "YES" if s == t else "NO"
        else:
            prefix, suffix = s.split('*')
            ok = False
            # replace '*' with any string (including empty) of length up to m
            for mid_len in range(0, m + 1):
                candidate = prefix + (t[:mid_len]) + suffix
                if candidate == t:
                    ok = True
                    break
            correct = "YES" if ok else "NO"
        out = run(x).strip()
        assert out == correct, f"Brute‑force says {correct}, got {out}"


def test_star_at_start_or_end(run, x):
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    s = lines[1]
    t = lines[2]
    if s.startswith('*'):
        out = run(x).strip()
        suffix = s[1:]
        if out == "YES":
            assert t.endswith(suffix), f"Star at start: t must end with {suffix}"
    if s.endswith('*'):
        out = run(x).strip()
        prefix = s[:-1]
        if out == "YES":
            assert t.startswith(prefix), f"Star at end: t must start with {prefix}"


def test_no_star_and_different_lengths(run, x):
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    s = lines[1]
    t = lines[2]
    if '*' not in s and n != m:
        out = run(x).strip()
        assert out == "NO", f"No star and lengths differ must be NO, got {out}"


def test_star_and_empty_t(run, x):
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    s = lines[1]
    t = lines[2]
    if '*' in s and m == 0:
        out = run(x).strip()
        # only possible if prefix and suffix are both empty
        prefix, suffix = s.split('*')
        if prefix == '' and suffix == '':
            assert out == "YES", f"Pattern '*', empty t must be YES"
        else:
            assert out == "NO", f"Pattern with non‑empty parts, empty t must be NO"

