def test_output_format(run, x):
    out = run(x).strip()
    assert out == '-1' or out.isdigit() or (out[0]=='-' and out[1:].isdigit()), 'Output must be an integer or -1'

def test_answer_non_negative(run, x):
    out = run(x).strip()
    if out != '-1':
        ans = int(out)
        assert ans >= 1, 'If possible, answer must be a natural number >= 1'

def test_if_positive_then_concentration_possible(run, x):
    out = run(x).strip()
    if out == '-1':
        return
    ans = int(out)
    lines = x.strip().split('\n')
    n, k = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))
    # Check there exist integer volumes x_i >= 0, sum x_i = ans, such that sum(a_i * x_i) = n * ans
    # Since ans is small in our inputs (≤ a few), brute-force over all compositions of ans into k parts
    from itertools import product
    found = False
    for vols in product(range(ans+1), repeat=k):
        if sum(vols) == ans:
            if sum(a[i]*vols[i] for i in range(k)) == n*ans:
                found = True
                break
    assert found, f'Answer {ans} does not produce concentration {n}/1000 with given a_i'

def test_if_single_type_matches_then_answer_one(run, x):
    lines = x.strip().split('\n')
    n, k = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))
    if any(ai == n for ai in a):
        out = run(x).strip()
        if out != '-1':
            ans = int(out)
            assert ans == 1, f'When a_i == n, minimal possible is 1'

def test_answer_at_most_one_if_n_in_a(run, x):
    lines = x.strip().split('\n')
    n, k = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))
    if any(ai == n for ai in a):
        out = run(x).strip()
        if out != '-1':
            ans = int(out)
            assert ans <= 1, f'When n equals some a_i, answer must be ≤ 1'

def test_if_impossible_then_no_solution(run, x):
    out = run(x).strip()
    if out == '-1':
        lines = x.strip().split('\n')
        n, k = map(int, lines[0].split())
        a = list(map(int, lines[1].split()))
        # brute‑force up to some bound to confirm impossibility
        # bound: by Bézout, if gcd of differences divides something? Simpler: try up to 10 volumes
        from itertools import product
        possible = False
        for total in range(1, 11):
            for vols in product(range(total+1), repeat=k):
                if sum(vols) == total:
                    if sum(a[i]*vols[i] for i in range(k)) == n*total:
                        possible = True
                        break
            if possible:
                break
        assert not possible, f'Solution exists within 10 liters, but answer is -1'

def test_minimal_by_bruteforce(run, x):
    lines = x.strip().split('\n')
    n, k = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))
    # only run brute‑force if k is small (≤3) and numbers are small
    if k <= 3:
        out = run(x).strip()
        if out == '-1':
            # already checked by another test
            return
        ans = int(out)
        # check no smaller total works
        from itertools import product
        for total in range(1, ans):
            for vols in product(range(total+1), repeat=k):
                if sum(vols) == total:
                    if sum(a[i]*vols[i] for i in range(k)) == n*total:
                        assert False, f'Found smaller total {total} that works, answer {ans} not minimal'

def test_zero_n(run, x):
    lines = x.strip().split('\n')
