    if n == 0:
        out = run(x).strip()
        if out != '-1':
            ans = int(out)
            # if there is a type with a_i == 0, answer can be 1
            if any(ai == 0 for ai in a):
                assert ans == 1, f'When n=0 and a_i=0 exists, minimal is 1'
            else:
                # otherwise need at least two liters mixing positive and negative? but a_i ≥0 per spec.
                # Actually with all a_i >0, impossible because numerator positive.
                # But spec allows a_i=0, so if all >0 then impossible => -1
                # This test is a bit tricky; better to skip strong claim.
                pass

def test_1000_n(run, x):
    lines = x.strip().split('\n')
    n, k = map(int, lines[0].split())
