def test_answer_parity(run, x):
    # If all a_i - n have same parity, then total liters parity might be constrained.
    # Not a strict requirement, but a possible check: skip.
    # Instead, a simple sanity: if answer is 1, then some a_i equals n.
    out = run(x).strip()
    if out != '-1':
        ans = int(out)
        if ans == 1:
            lines = x.strip().split('\n')
            n, k = map(int, lines[0].split())
            a = list(map(int, lines[1].split()))
            assert any(ai == n for ai in a), f'Answer=1 but no a_i equals n'

