def test_symmetry_bitwise_complement(run, x):
    # Complexity depends only on XOR with x, and complementing all bits of x
    # is equivalent to complementing all bits of i and i⊕x, which preserves
    # ordering of pairs, so complexity should be same for x and ~x.
    n = len(x)
    # complement of x as n-bit string
    x_comp = ''.join('1' if c == '0' else '0' for c in x)
    # But we can't call run again! So we can only check on cases where
    # x equals its own complement (all 0 or all 1) or where n is small
    # and we can brute force. We'll restrict to n <= 6 and brute force
    # compute complexity for both, ensuring equality.
    if n <= 6:
        num = int(x, 2)
        comp = int(x_comp, 2)
        # brute force compute complexity
        total = 0
        N = 1 << n
        for a in range(N):
            b = a ^ num
            for c in range(a+1, N):
                d = c ^ num
                if b > d:
                    total += 1
        total2 = 0
        for a in range(N):
            b = a ^ comp
            for c in range(a+1, N):
                d = c ^ comp
                if b > d:
                    total2 += 1
        assert total % 1000000007 == total2 % 1000000007
        # Now check that the returned answer matches total for x
        out = int(run(x).strip())
        assert out == total % 1000000007
    # else skip


