tests_src:
def test_output_dimensions(run, x):
    lines = x.strip().splitlines()
    n, m = map(int, lines[0].split())
    out = run(x).strip().splitlines()
    assert len(out) == n
    for i in range(n):
        vals = out[i].split()
        assert len(vals) == m
        for v in vals:
            int(v)  # must be integer


def test_positive_integers(run, x):
    out = run(x).strip().splitlines()
    for line in out:
        for v in line.split():
            val = int(v)
            assert val >= 1


def test_identical_rows_symmetry(run, x):
    lines = x.strip().splitlines()
    n, m = map(int, lines[0].split())
    if n == m:
        arr = [list(map(int, lines[i+1].split())) for i in range(n)]
        out = [list(map(int, line.split())) for line in run(x).strip().splitlines()]
        # if matrix is symmetric (a[i][j] == a[j][i]), then answers should be symmetric too
        symmetric = all(arr[i][j] == arr[j][i] for i in range(n) for j in range(n))
        if symmetric:
            assert all(out[i][j] == out[j][i] for i in range(n) for j in range(n))


def test_single_cell(run, x):
    lines = x.strip().splitlines()
    n, m = map(int, lines[0].split())
    if n == 1 and m == 1:
        out = run(x).strip()
        assert out == '1'


def test_equal_in_row_same_answer(run, x):
    lines = x.strip().splitlines()
    n, m = map(int, lines[0].split())
    arr = [list(map(int, lines[i+1].split())) for i in range(n)]
    out = [list(map(int, line.split())) for line in run(x).strip().splitlines()]
    for i in range(n):
        for j1 in range(m):
            for j2 in range(m):
                if arr[i][j1] == arr[i][j2]:
                    assert out[i][j1] == out[i][j2]


def test_equal_in_column_same_answer(run, x):
    lines = x.strip().splitlines()
    n, m = map(int, lines[0].split())
    arr = [list(map(int, lines[i+1].split())) for i in range(n)]
    out = [list(map(int, line.split())) for line in run(x).strip().splitlines()]
    for j in range(m):
        for i1 in range(n):
            for i2 in range(n):
                if arr[i1][j] == arr[i2][j]:
                    assert out[i1][j] == out[i2][j]


def test_answer_bounded_by_counts(run, x):
    lines = x.strip().splitlines()
    n, m = map(int, lines[0].split())
    arr = [list(map(int, lines[i+1].split())) for i in range(n)]
    out = [list(map(int, line.split())) for line in run(x).strip().splitlines()]
    for i in range(n):
        row_set = set(arr[i])
        for j in range(m):
            col_set = set(arr[k][j] for k in range(n))
            # answer cannot exceed distinct counts in row + column - 1? Actually spec says x is max assigned.
            # But certainly answer <= len(row_set) + len(col_set) - 1 (worst case).
            # We check a looser bound: answer >= max(len(row_set), len(col_set)).
            # Because you need at least that many distinct values for each street.
            assert out[i][j] >= max(len(row_set), len(col_set))


def test_answer_does_not_exceed_counts(run, x):
    lines = x.strip().splitlines()
    n, m = map(int, lines[0].split())
    arr = [list(map(int, lines[i+1].split())) for i in range(n)]
    out = [list(map(int, line.split())) for line in run(x).strip().splitlines()]
    for i in range(n):
        row_vals = arr[i]
        row_distinct = len(set(row_vals))
        for j in range(m):
            col_distinct = len(set(arr[k][j] for k in range(n)))
            # upper bound: you can assign values 1..row_distinct to row and 1..col_distinct to column,
            # aligning the intersection value, so max <= row_distinct + col_distinct - 1
            assert out[i][j] <= row_distinct + col_distinct - 1


def test_all_equal_matrix(run, x):
    lines = x.strip().splitlines()
    n, m = map(int, lines[0].split())
    arr = [list(map(int, lines[i+1].split())) for i in range(n)]
    if all(arr[i][j] == arr[0][0] for i in range(n) for j in range(m)):
        out = run(x).strip().splitlines()
        for line in out:
            for v in line.split():
                assert v == '1'


def test_output_parses_as_ints(run, x):
    out = run(x).strip()
    lines = out.splitlines()
    for line in lines:
        parts = line.split()
        for p in parts:
            int(p)  # just ensure integer

