    if has_black_row and not has_black_col:
        assert run(x).strip() == '-1', 'If black rows exist but no black column, answer must be -1.'
    if not has_black_row and has_black_col:
        assert run(x).strip() == '-1', 'If black columns exist but no black row, answer must be -1.'

