    black_count = sum(row.count('#') for row in grid)
    if black_count == 1:
        out = run(x).strip()
        if out != '-1':
            assert int(out) >= 1, 'A single black cell requires at least one north magnet.'

def test_all_black_connected_components(run, x):
    # Only if n,m <= 20 for speed
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    if n <= 20 and m <= 20:
        grid = [list(row.strip()) for row in lines[1:]]
        from collections import deque
        visited = [[False]*m for _ in range(n)]
        components = 0
        for i in range(n):
            for j in range(m):
                if grid[i][j] == '#' and not visited[i][j]:
                    components += 1
                    dq = deque([(i,j)])
                    visited[i][j] = True
                    while dq:
                        ci,cj = dq.popleft()
                        for di,dj in ((1,0),(-1,0),(0,1),(0,-1)):
                            ni,nj = ci+di, cj+dj
                            if 0<=ni<n and 0<=nj<m and grid[ni][nj]=='#' and not visited[ni][nj]:
                                visited[ni][nj]=True
                                dq.append((ni,nj))
        # The correct answer for all-black grid is components (as per submission logic).
        # But we only test if all cells are black.
        if all(cell=='#' for row in grid for cell in row):
            out = run(x).strip()
            if out != '-1':
                assert int(out) == components, 'For all-black grid, answer must equal number of connected components.'

def test_minus_one_implies_row_or_column_empty(run, x):
