def test_exact_formula(run, x):
    import sys
    lines = x.strip().split('\n')
    N = int(lines[0])
    S1 = lines[1]
    S2 = lines[2]
    # map each domino letter to its covering squares
    pos = {}
    for i in range(2):
        s = S1 if i==0 else S2
        for j in range(N):
            ch = s[j]
            if ch not in pos:
                pos[ch] = []
            pos[ch].append((i,j))
    # each domino should have exactly 2 squares
    for ch, squares in pos.items():
        assert len(squares)==2, f'Domino {ch} does not cover 2 squares'
    # build adjacency graph: nodes are domino letters, edge if share a side
    adj = {ch: set() for ch in pos}
    # check adjacency between every pair of squares
    # but easier: for each domino, compute its squares, then for each square check neighbour squares in board
    # and see which domino occupies that neighbour
    for ch, squares in pos.items():
        for (r,c) in squares:
            for dr,dc in [(1,0),(-1,0),(0,1),(0,-1)]:
                nr,nc = r+dr, c+dc
                if 0<=nr<2 and 0<=nc<N:
                    # find domino at (nr,nc)
                    other_ch = S1[nc] if nr==0 else S2[nc]
                    if other_ch != ch:
                        adj[ch].add(other_ch)
                        adj[other_ch].add(ch)
    # remove duplicates and ensure symmetry already done
    # graph should be connected, degrees ≤2
    degrees = [len(adj[ch]) for ch in adj]
    # Determine if it's a cycle (all degrees 2) or a path (two vertices degree 1, others degree 2)
    deg_counts = {}
    for d in degrees:
        deg_counts[d]=deg_counts.get(d,0)+1
    MOD=10**9+7
    if deg_counts.get(2,0)==N:
        # cycle
        if N==1:
            # single domino, but degree 0? Actually single domino has no adjacency, degrees 0.
            expected = 3  # can color with any of 3 colors
        else:
            # cycle of length N
            # formula: (2**N + 2*(-1)**N) % MOD
            pow2 = pow(2, N, MOD)
            if N%2==0:
                expected = (pow2 + 2) % MOD
            else:
                expected = (pow2 - 2) % MOD
    else:
        # path (including possibly isolated vertex when N=1)
        # number of proper 3-colorings of a path of N vertices: 3 * 2^(N-1) for N>=1
        if N==1:
            expected = 3
        else:
            expected = 3 * pow(2, N-1, MOD) % MOD
    out = run(x)
    ans = int(out.strip())
    assert ans == expected, f'Expected {expected}, got {ans}'


def test_brute_force_small_N(run, x):
    import itertools
    lines = x.strip().split('\n')
    N = int(lines[0])
    if N > 6:
        return  # skip large inputs
    S1 = lines[1]
    S2 = lines[2]
    # Build adjacency list same as in exact_formula
    pos = {}
    for i in range(2):
        s = S1 if i==0 else S2
        for j in range(N):
            ch = s[j]
            if ch not in pos:
                pos[ch] = []
            pos[ch].append((i,j))
    adj = {ch: set() for ch in pos}
    for ch, squares in pos.items():
        for (r,c) in squares:
            for dr,dc in [(1,0),(-1,0),(0,1),(0,-1)]:
                nr,nc = r+dr, c+dc
                if 0<=nr<2 and 0<=nc<N:
                    other_ch = S1[nc] if nr==0 else S2[nc]
                    if other_ch != ch:
                        adj[ch].add(other_ch)
                        adj[other_ch].add(ch)
    dominoes = list(pos.keys())
    idx = {ch:i for i,ch in enumerate(dominoes)}
    # brute force all colorings
    colors = [0,1,2]
    count = 0
    for coloring in itertools.product(colors, repeat=N):
        ok = True
        for a in range(N):
            for b in range(a+1,N):
                if dominoes[b] in adj[dominoes[a]]:
                    if coloring[a]==coloring[b]:
                        ok=False
                        break
            if not ok:
                break
        if ok:
            count+=1
    MOD=10**9+7
    expected = count % MOD
    out = run(x)
    ans = int(out.strip())
    assert ans == expected, f'Brute force expects {expected}, got {ans}'


def test_all_vertical_case(run, x):
    lines = x.strip().split('\n')
    N = int(lines[0])
    S1 = lines[1]
    S2 = lines[2]
    # check if all dominoes are vertical (same letter in both rows for each column)
    all_vertical = all(S1[j]==S2[j] for j in range(N))
    if not all_vertical:
        return  # not applicable
    # For vertical dominoes, adjacency graph is a path (or cycle?) Actually if all vertical, each domino touches left and right neighbour via two squares, but still simple edge. Graph is path because first and last domino have degree 1? Wait check: column j domino touches column j-1 and j+1, so internal degree 2, ends degree 1. So path.
    MOD=10**9+7
    if N==1:
        expected = 3
    else:
        expected = 3 * pow(2, N-1, MOD) % MOD
    out = run(x)
    ans = int(out.strip())
    assert ans == expected, f'All vertical case expects {expected}, got {ans}'


