    pattern = list(map(int, lines[1].split()))
    text_lines = lines[2:2+n]
    vowels = set('aeiouy')
    # Only run brute-force if total characters per line ≤ 20 and n ≤ 3
    if any(len(line) > 20 for line in text_lines) or n > 3:
        return
    # Helper to count possible syllable counts for a line
    def possible_counts(line):
        words = line.split()
        # For each word independently compute possible syllable counts.
        word_possibilities = []
        for w in words:
            if not any(ch in vowels for ch in w):
                word_possibilities.append([0])  # ignored word
                continue
            # Enumerate all ways to split w into syllables.
            # A syllable is a substring containing exactly one vowel.
            m = len(w)
            # DP over positions, storing set of syllable counts achievable up to position i
            dp = [set() for _ in range(m+1)]
            dp[0].add(0)
            for i in range(m):
                if not dp[i]:
                    continue
                # start a syllable at i
                for j in range(i+1, m+1):
                    sub = w[i:j]
                    vowel_cnt = sum(1 for ch in sub if ch in vowels)
