def test_positive_integer_format(run, x):
    out = run(x).strip()
    # output must be a non-negative integer
    assert out.isdigit() or (out[0] == '-' and out[1:].isdigit() and out == '0'), 'output must be an integer'
    # but the problem says "print a single integer" and answer is a count, so non-negative
    n = int(out)
    assert n >= 0, 'count cannot be negative'

def test_upper_bound_by_all_possible(run, x):
    l_str, r_str = x.strip().split()
    l = int(l_str)
    r = int(r_str)
    # all 2^a * 3^b <= 2e9, a up to 31, b up to 40 as in code (but we can compute loosely)
    max_a = 0
    while (1 << max_a) <= r:
        max_a += 1
    max_b = 0
    while 3 ** max_b <= r:
        max_b += 1
    # total possible distinct values <= r is at most max_a * max_b
    upper = max_a * max_b
    ans = int(run(x).strip())
    assert ans <= upper, f'answer {ans} exceeds possible distinct values <= {r}'

def test_lower_bound_by_subrange(run, x):
    l_str, r_str = x.strip().split()
    l = int(l_str)
    r = int(r_str)
    # For any subinterval [l, r], the count for [l, r] >= count for [l, r-1] (if r>l) but we can't compare across runs.
    # Instead, take a single value: if l <= v <= r and v is a 2-3-integer, count >= 1.
    # We'll pick one candidate: the smallest power of 2 >= l and <= r, if exists.
    # This is a lower bound of 0 or 1.
    # Compute quickly by iterating over small exponents.
    found = False
    for a in range(0, 32):
        p2 = 1 << a
        if p2 > r:
            break
        if p2 >= l:
            found = True
            break
    if not found:
        # try power of 3
        p3 = 1
        for b in range(0, 40):
            if p3 > r:
                break
            if p3 >= l:
                found = True
                break
            p3 *= 3
    ans = int(run(x).strip())
    if found:
        assert ans >= 1, f'interval contains a 2-3-integer but answer is {ans}'
    # else lower bound is 0, which is always satisfied

def test_exact_for_given_examples(run, x):
    # If the input matches one of the statement examples, answer must match exactly.
    if x == "1 10\n":
        assert run(x).strip() == "7"
    elif x == "100 200\n":
        assert run(x).strip() == "5"
    elif x == "1 2000000000\n":
        assert run(x).strip() == "326"

def test_brute_force_small_r(run, x):
    l_str, r_str = x.strip().split()
    l = int(l_str)
    r = int(r_str)
    # Only brute force if r is small enough to keep test fast
    if r <= 10**6:
        count = 0
        a = 0
        while (1 << a) <= r:
            p2 = 1 << a
            b = 0
            while True:
                val = p2 * (3 ** b)
                if val > r:
                    break
                if val >= l:
                    count += 1
                b += 1
            a += 1
        ans = int(run(x).strip())
        assert ans == count, f'brute force gives {count}, got {ans}'

def test_answer_non_decreasing_with_expanded_range(run, x):
    # Not comparing across runs, but we can check a property on the same input:
    # If l == r and that number is a 2-3-integer, answer must be 1.
    l_str, r_str = x.strip().split()
    l = int(l_str)
    r = int(r_str)
    if l == r:
        # check if l is a 2-3-integer
        n = l
        while n % 2 == 0:
            n //= 2
        while n % 3 == 0:
            n //= 3
        if n == 1:
            ans = int(run(x).strip())
            assert ans == 1, f'single 2-3-integer {l} must yield count 1, got {ans}'

def test_single_point_non_23_integer(run, x):
    l_str, r_str = x.strip().split()
    l = int(l_str)
    r = int(r_str)
    if l == r:
        n = l
        while n % 2 == 0:
            n //= 2
        while n % 3 == 0:
            n //= 3
        if n != 1:
            ans = int(run(x).strip())
            assert ans == 0, f'single non-2-3-integer {l} must yield count 0, got {ans}'

def test_known_small_case_1_to_1(run, x):
    if x == "1 1\n":
        assert run(x).strip() == "1"

def test_known_small_case_2_to_2(run, x):
    if x == "2 2\n":
        assert run(x).strip() == "1"

def test_known_small_case_3_to_3(run, x):
    if x == "3 3\n":
        assert run(x).strip() == "1"

