tests_src:
def test_output_length_or_minus_one(run, x):
    out = run(x).strip()
    if out == "-1":
        return
    n = int(x.split()[0])
    assert len(out) == n, f"Output length {len(out)} != n ({n})"

def test_chars_lowercase(run, x):
    out = run(x).strip()
    if out == "-1":
        return
    assert all('a' <= c <= 'z' for c in out), f"Non-lowercase char in output"

def test_adjacent_different(run, x):
    out = run(x).strip()
    if out == "-1":
        return
    for i in range(len(out)-1):
        assert out[i] != out[i+1], f"Adjacent equal chars at position {i}"

def test_distinct_count(run, x):
    out = run(x).strip()
    if out == "-1":
        return
    k = int(x.split()[1])
    distinct = len(set(out))
    assert distinct == k, f"Distinct chars {distinct} != k ({k})"

def test_prefix_pattern(run, x):
    out = run(x).strip()
    if out == "-1":
        return
    n, k = map(int, x.split())
    # For lexicographically smallest, first part should be 'ab' repeating as long as possible
    # and then distinct letters from c onward.
    # Check that after the alternating 'ab' part, the remaining letters are sorted and distinct.
    i = 0
    while i+1 < len(out) and out[i:i+2] in ('ab', 'ba'):
        i += 2
    # Now check the rest: it should be strictly increasing from 'c' onwards, no repeats.
    rest = out[i:]
    if rest:
        assert all(rest[j] < rest[j+1] for j in range(len(rest)-1)), f"Remaining part not strictly increasing: {rest}"
        # Also first char of rest should be >= 'c' if it exists (since after 'ab' we start with 'c')
        assert rest[0] >= 'c', f"Rest starts with {rest[0]} < 'c'"

def test_minus_one_condition(run, x):
    out = run(x).strip()
    if out == "-1":
        n, k = map(int, x.split())
        # According to spec, impossible when k>26 or k>n or (k==1 and n>1)
        assert k > 26 or k > n or (k == 1 and n > 1), f"Output -1 but conditions allow a string"

def test_not_minus_one_when_possible(run, x):
    out = run(x).strip()
    n, k = map(int, x.split())
    if not (k > 26 or k > n or (k == 1 and n > 1)):
        assert out != "-1", f"Output -1 when a string should exist"

def test_small_bruteforce(run, x):
    n, k = map(int, x.split())
    if n > 8:  # brute force only for tiny n
        return
    out = run(x).strip()
    # Enumerate all strings of length n with lowercase letters, no adjacent equal, exactly k distinct.
    # Find lexicographically smallest.
    import itertools
    best = None
    for letters in itertools.product('abcdefghijklmnopqrstuvwxyz', repeat=n):
        if any(letters[i] == letters[i+1] for i in range(n-1)):
            continue
        if len(set(letters)) != k:
            continue
        s = ''.join(letters)
        if best is None or s < best:
            best = s
    if best is None:
        assert out == "-1", f"Expected -1, got {out}"
    else:
        assert out == best, f"Expected {best}, got {out}"

def test_example_from_statement(run, x):
    if x == "7 4\n":
        out = run(x).strip()
        assert out == "ababacd", f"Example mismatch: expected ababacd, got {out}"
    if x == "4 7\n":
        out = run(x).strip()
        assert out == "-1", f"Example mismatch: expected -1, got {out}"

def test_first_char_a_when_not_minus_one(run, x):
    out = run(x).strip()
    if out == "-1":
        return
    # Lexicographically smallest must start with 'a' if possible
    assert out[0] == 'a', f"First char not 'a' but {out[0]}"

