    if L_mod <= R_mod and R - L < 2019:
        # The min product mod 2019 depends only on residues when range < 2019
        # But we can check a weaker property: answer is same for (L, R) and (L_mod, R_mod+2019) if R_mod < L_mod? Not straightforward.
        # Instead, we check that answer is invariant under adding multiples of 2019 to both L and R.
        # If range < 2019, shifting by 2019 changes residues but not the set of residues.
        # Actually, adding 2019 to both does not change the set of residues modulo 2019, so answer unchanged.
        # We'll verify by brute for small ranges only.
        if R - L <= 100:
            ans1 = int(run(x).strip())
            L2 = L + 2019
            R2 = R + 2019
            # Simulate running on shifted input by computing directly.
            ans2 = min((i * j) % 2019 for i in range(L2, R2+1) for j in range(i+1, R2+1))
            assert ans1 == ans2
        else:
            # Cannot compute, skip
            pass"
    },
