      "name": "test_answer_upper_bound_by_min_residue_product",
      "source": "def test_answer_upper_bound_by_min_residue_product(run, x):
    L, R = map(int, x.split())
    if R - L < 2019:
        residues = [i % 2019 for i in range(L, R+1)]
        # The min product mod 2019 is at most the min product of two distinct residues.
        min_res_prod = min((a * b) % 2019 for i, a in enumerate(residues) for j, b in enumerate(residues) if i < j)
        assert int(run(x).strip()) <= min_res_prod
    else:
        # If range >= 2019, answer must be 0
        assert run(x).strip() == '0'"
