def test_output_is_string(run, x):
    out = run(x)
    assert isinstance(out, str), 'Output must be a string'

def test_ends_with_newline(run, x):
    out = run(x)
    assert out.endswith('\n'), 'Output must end with newline'

def test_exact_yes_or_no(run, x):
    out = run(x)
    assert out in ('Yes\n', 'No\n'), 'Output must be exactly Yes\n or No\n'

def test_yes_when_equal(run, x):
    n, m = map(int, x.strip().split())
    if n == m:
        assert run(x) == 'Yes\n', 'When N == M, output must be Yes\n'

def test_no_when_less(run, x):
    n, m = map(int, x.strip().split())
    if m < n:
        assert run(x) == 'No\n', 'When M < N, output must be No\n'

def test_brute_force_small(run, x):
    n, m = map(int, x.strip().split())
    # Only recompute for small N to keep fast, but all given inputs have N <= 100, which is still trivial
    expected = 'Yes\n' if n == m else 'No\n'
    assert run(x) == expected, 'Output does not match direct computation from spec'

def test_not_empty(run, x):
    out = run(x)
    assert out != '', 'Output must not be empty'

def test_starts_with_Y_or_N(run, x):
    out = run(x)
    assert out.startswith('Y') or out.startswith('N'), 'Output must start with Y or N'

def test_correct_length(run, x):
    out = run(x)
    assert len(out) in (4, 3), 'Output length must be 4 (Yes\n) or 3 (No\n)'

def test_zero_cases(run, x):
    n, m = map(int, x.strip().split())
    if n == 0 and m == 0:
        assert run(x) == 'Yes\n', 'When N=0 and M=0, all test cases passed, output must be Yes\n'

