def test_small_inputs(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    if n > 10:
        return  # too large for brute force
    names = lines[1:1+n]
    valid = {'M', 'A', 'R', 'C', 'H'}
    # brute-force count
    cnt = 0
    for i in range(n):
        if names[i][0] not in valid:
            continue
        for j in range(i+1, n):
            if names[j][0] not in valid:
                continue
            for k in range(j+1, n):
                if names[k][0] not in valid:
                    continue
                if len({names[i][0], names[j][0], names[k][0]}) == 3:
                    cnt += 1
    assert int(run(x).strip()) == cnt


