def test_always_yes_or_no(run, x):
    out = run(x).strip()
    assert out in ("Yes", "No"), f"Output must be Yes or No, got {repr(out)}"

def test_output_format_single_line(run, x):
    out = run(x)
    lines = out.splitlines()
    assert len(lines) == 1, f"Output must be exactly one line, got {len(lines)}"
    assert out.endswith('\n'), "Output must end with newline"

def test_all_equal_implies_no(run, x):
    a, b, c = map(int, x.strip().split())
    if a == b == c:
        out = run(x).strip()
        assert out == "No", f"All equal ({a},{b},{c}) must be No, got {out}"

def test_all_distinct_implies_no(run, x):
    a, b, c = map(int, x.strip().split())
    if a != b and b != c and a != c:
        out = run(x).strip()
        assert out == "No", f"All distinct ({a},{b},{c}) must be No, got {out}"

def test_two_equal_one_different_implies_yes(run, x):
    a, b, c = map(int, x.strip().split())
    if (a == b != c) or (a == c != b) or (b == c != a):
        out = run(x).strip()
        assert out == "Yes", f"Two equal, one different ({a},{b},{c}) must be Yes, got {out}"

def test_no_extra_whitespace(run, x):
    out = run(x).strip()
    assert out == run(x).rstrip('\n'), "Output must have no trailing spaces before newline"

def test_case_sensitive_exact(run, x):
    out = run(x).strip()
    assert out in ("Yes", "No"), f"Output must match exactly 'Yes' or 'No', got {repr(out)}"
    # also ensure it's not 'yes', 'YES', etc
    if out not in ("Yes", "No"):
        raise AssertionError(f"Case mismatch: got {repr(out)}")

def test_consistency_with_definition(run, x):
    a, b, c = map(int, x.strip().split())
    out = run(x).strip()
    # Compute whether the triple is poor by definition
    is_poor = (a == b != c) or (a == c != b) or (b == c != a)
    expected = "Yes" if is_poor else "No"
    assert out == expected, f"For ({a},{b},{c}) expected {expected}, got {out}"

def test_no_other_strings(run, x):
    out = run(x).strip()
    # Already enforced by test_always_yes_or_no, but this one is stricter on format
    if not (out == "Yes" or out == "No"):
        raise AssertionError(f"Output must be exactly Yes or No, got {repr(out)}")

def test_input_range_respected(run, x):
    # The input values are guaranteed 1..9 by the spec, but we just ensure
    # the answer does not depend on values outside that range (though not needed here).
    # This test is weak, but ensures output is not empty.
    out = run(x).strip()
    assert out, "Output must not be empty"

