tests_src:
def test_output_ends_with_newline(run, x):
    out = run(x)
    assert out.endswith('\n'), 'Output must end with newline'

def test_output_no_extra_whitespace(run, x):
    out = run(x)
    stripped = out.rstrip('\n')
    assert stripped == out.rstrip(), 'Output must not have trailing spaces/tabs'

def test_output_case_sensitive(run, x):
    out = run(x).rstrip('\n')
    assert out in ['Yes', 'No'], 'Output must be exactly Yes or No'

def test_output_binary(run, x):
    out = run(x).rstrip('\n')
    assert out in {'Yes', 'No'}, 'Output must be Yes or No'

def test_output_is_string(run, x):
    out = run(x)
    assert isinstance(out, str), 'Output must be a string'

def test_yes_implies_length_4(run, x):
    out = run(x).rstrip('\n')
    if out == 'Yes':
        assert len(x.rstrip('\n')) == 4, 'If output is Yes, input length must be 4'

def test_yes_implies_all_uppercase(run, x):
    out = run(x).rstrip('\n')
    if out == 'Yes':
        s = x.rstrip('\n')
        assert s.isalpha() and s.isupper(), 'If output is Yes, input must be uppercase letters'

def test_no_implies_not_two_twice(run, x):
    out = run(x).rstrip('\n')
    if out == 'No':
        s = x.rstrip('\n')
        chars = set(s)
        cond = (len(chars) == 2 and all(s.count(c) == 2 for c in chars))
        assert not cond, 'If output is No, the condition must not hold'

def test_permutation_consistency_yes(run, x):
    import itertools
    out = run(x).rstrip('\n')
    if out == 'Yes':
        s = x.rstrip('\n')
        # For every permutation, the condition should also hold
        for perm in set(itertools.permutations(s)):
            perm_s = ''.join(perm)
            chars = set(perm_s)
            if not (len(chars) == 2 and all(perm_s.count(c) == 2 for c in chars)):
                assert False, 'If output is Yes, all permutations must satisfy the condition'

def test_permutation_consistency_no(run, x):
    import itertools
    out = run(x).rstrip('\n')
    if out == 'No':
        s = x.rstrip('\n')
        # For every permutation, the condition should also not hold
        for perm in set(itertools.permutations(s)):
            perm_s = ''.join(perm)
            chars = set(perm_s)
            if len(chars) == 2 and all(perm_s.count(c) == 2 for c in chars):
                assert False, 'If output is No, no permutation should satisfy the condition'

