def test_expected(run, x):
    # Directly compute the correct answer from the specification.
    # Since the input size is tiny, we can afford brute-force.
    # This catches any deviation from the spec.
    a, b = map(int, x.split())
    # Define ordering: 2<3<...<13<1
    def stronger(p, q):
        if p == q:
            return 0
        if p == 1:
            return 1 if q != 1 else 0
        if q == 1:
            return -1
        return 1 if p > q else -1
    res = stronger(a, b)
    expected = ('Draw', 'Alice', 'Bob')[res]
    out = run(x).strip()
    assert out == expected, f'Expected {expected}, got {out}'


def test_output_is_one_of_three(run, x):
    out = run(x).strip()
    assert out in {'Alice', 'Bob', 'Draw'}


def test_draw_only_on_equal(run, x):
    a, b = map(int, x.split())
    out = run(x).strip()
    if out == 'Draw':
        assert a == b
    else:
        assert a != b


def test_alice_wins_not_draw(run, x):
    a, b = map(int, x.split())
    out = run(x).strip()
    if out == 'Alice':
        assert a != b


def test_bob_wins_not_draw(run, x):
    a, b = map(int, x.split())
    out = run(x).strip()
    if out == 'Bob':
        assert a != b


def test_alice_one_wins(run, x):
    a, b = map(int, x.split())
    out = run(x).strip()
    if a == 1 and b != 1:
        assert out == 'Alice', f'Alice has 1, Bob has {b}, Alice must win'


def test_bob_one_wins(run, x):
    a, b = map(int, x.split())
    out = run(x).strip()
    if b == 1 and a != 1:
        assert out == 'Bob', f'Bob has 1, Alice has {a}, Bob must win'


def test_no_one_ordering(run, x):
    a, b = map(int, x.split())
    out = run(x).strip()
    if a != 1 and b != 1 and a != b:
        # Without 1, higher number wins.
        if a > b:
            assert out == 'Alice'
        else:
            assert out == 'Bob'


def test_both_one_is_draw(run, x):
    a, b = map(int, x.split())
    out = run(x).strip()
    if a == 1 and b == 1:
        assert out == 'Draw'


def test_parseable_output(run, x):
    # Weakest: just ensure output is a non-empty string without newline inside.
    out = run(x)
    assert isinstance(out, str) and out.strip() == out and out

