tests_src:
def test_output_is_single_character(run, x):
    out = run(x).strip()
    assert len(out) == 1, f'Output must be a single character, got {repr(out)}'

def test_output_is_A_or_a(run, x):
    out = run(x).strip()
    assert out in ('A', 'a'), f'Output must be A or a, got {repr(out)}'

def test_if_input_uppercase_output_A(run, x):
    # x includes newline, so take first character
    c = x.strip()
    if c.isupper():
        out = run(x).strip()
        assert out == 'A', f'Uppercase input {c} must output A, got {repr(out)}'

def test_if_input_lowercase_output_a(run, x):
    c = x.strip()
    if c.islower():
        out = run(x).strip()
        assert out == 'a', f'Lowercase input {c} must output a, got {repr(out)}'

def test_output_has_no_extra_newlines(run, x):
    out = run(x)
    # output should have exactly one newline at end (print adds it)
    # but we allow no trailing newline just in case; we just check it's not multi-line
    lines = out.split('\n')
    assert len(lines) <= 2, f'Output should be at most one line, got {len(lines)} lines'
    if len(lines) == 2:
        assert lines[1] == '', f'Extra characters after newline'

def test_output_matches_ascii_case(run, x):
    c = x.strip()
    out = run(x).strip()
    if 'A' <= c <= 'Z':
        assert out == 'A', f'ASCII uppercase {c} must output A'
    elif 'a' <= c <= 'z':
        assert out == 'a', f'ASCII lowercase {c} must output a'

def test_output_is_not_empty(run, x):
    out = run(x)
    assert out.strip() != '', 'Output must not be empty or only whitespace'

def test_direct_computation(run, x):
    # For this task, input is a single letter, we can compute expected answer directly.
    c = x.strip()
    expected = 'A' if c.isupper() else 'a'
    out = run(x).strip()
    assert out == expected, f'Input {c} expects {expected}, got {out}'

def test_output_does_not_contain_spaces(run, x):
    out = run(x).strip()
    assert ' ' not in out, f'Output contains space: {repr(out)}'

def test_output_is_printable_letter(run, x):
    out = run(x).strip()
    assert out.isalpha(), f'Output must be a letter, got {repr(out)}'

