tests_src:
def test_output_is_three_chars(run, x):
    out = run(x).strip()
    assert len(out) == 3, f'output length is {len(out)}, must be 3'

def test_letters_only(run, x):
    out = run(x).strip()
    assert out.isalpha(), f'output must contain only letters, got {out}'

def test_ABC_for_N_lt_1000(run, x):
    n = int(x.strip())
    if n < 1000:
        assert run(x).strip() == 'ABC', f'For N={n} output must be ABC'

def test_ABD_for_N_ge_1000(run, x):
    n = int(x.strip())
    if n >= 1000:
        assert run(x).strip() == 'ABD', f'For N={n} output must be ABD'

def test_exact_on_small_n(run, x):
    n = int(x.strip())
    if 1 <= n <= 1998:
        # Directly compute correct answer from spec
        expected = 'ABC' if n < 1000 else 'ABD'
        assert run(x).strip() == expected, f'For N={n} expected {expected}'

def test_no_digits(run, x):
    out = run(x).strip()
    assert not any(c.isdigit() for c in out), f'output contains digits: {out}'

def test_boundary_999(run, x):
    n = int(x.strip())
    if n == 999:
        assert run(x).strip() == 'ABC', 'N=999 must be ABC'

def test_boundary_1000(run, x):
    n = int(x.strip())
    if n == 1000:
        assert run(x).strip() == 'ABD', 'N=1000 must be ABD'

def test_not_empty(run, x):
    out = run(x).strip()
    assert out != '', 'output must not be empty'

def test_uppercase(run, x):
    out = run(x).strip()
    assert out.isupper(), f'output must be uppercase, got {out}'

def test_brute_force_correct(run, x):
    lines = x.strip().split('\n')
    a,b,c,d,e,k = map(int, lines[:6])
    coords = [a,b,c,d,e]
    can_all = True
    for i in range(5):
        for j in range(i+1,5):
            if coords[j] - coords[i] > k:
                can_all = False
                break
        if not can_all:
            break
    expected = "Yay!" if can_all else ":("
    output = run(x).strip()
    assert output == expected

def test_max_pair_correct(run, x):
    lines = x.strip().split('\n')
    a,b,c,d,e,k = map(int, lines[:6])
    # According to spec, answer depends only on whether any pair > k.
    # Since coordinates are increasing, max distance is e-a.
    # But we still check all pairs to be safe.
    coords = [a,b,c,d,e]
    ok = all(coords[j] - coords[i] <= k for i in range(5) for j in range(i+1,5))
    expected = "Yay!" if ok else ":("
    output = run(x).strip()
    assert output == expected

def test_output_matches_condition(run, x):
    lines = x.strip().split('\n')
    a,b,c,d,e,k = map(int, lines[:6])
    # Compute correct answer via brute force.
    ok = True
    for i in range(5):
        for j in range(i+1,5):
            # distances not stored, compute on the fly
            p = [a,b,c,d,e][i]
            q = [a,b,c,d,e][j]
            if q - p > k:
                ok = False
                break
        if not ok:
            break
    expected = "Yay!" if ok else ":("
    output = run(x).strip()
    assert output == expected

def test_output_is_valid_string(run, x):
    output = run(x).strip()
    assert output in ("Yay!", ":(")

def test_output_ends_with_newline(run, x):
    output = run(x)
    assert output.endswith('\n'), "Output must end with newline"

def test_output_length_correct(run, x):
    output = run(x).strip()
    assert len(output) in (4, 1), "Yay! has length 4, :( has length 1 (after strip)"

def test_if_max_le_k_then_yay(run, x):
    lines = x.strip().split('\n')
    a,b,c,d,e,k = map(int, lines[:6])
    if e - a <= k:
        # Then all pairs <= k, answer must be Yay!
        output = run(x).strip()
        assert output == "Yay!", f"When e-a <= k, answer must be Yay!, got {output}"

def test_if_any_pair_gt_k_then_sad(run, x):
    lines = x.strip().split('\n')
    a,b,c,d,e,k = map(int, lines[:6])
    coords = [a,b,c,d,e]
    bad = False
    for i in range(5):
        for j in range(i+1,5):
            if coords[j] - coords[i] > k:
                bad = True
                break
        if bad:
            break
    if bad:
        output = run(x).strip()
        assert output == ":(", f"When some pair > k, answer must be :(, got {output}"

def test_no_digits_in_output(run, x):
    output = run(x)
    import string
    for ch in output:
        assert ch not in string.digits, "Output should not contain digits"

def test_output_exactly_two_options(run, x):
    output = run(x).strip()
    assert output == "Yay!" or output == ":(", f"Output must be exactly Yay! or :(, got {output}"

