def test_output_format(run, x):
    out = run(x).strip()
    assert out in ['YES', 'NO', 'Yes', 'No', 'yEs', 'nO', 'yeS', 'nO', 'YEs', 'NO', 'yes', 'no', 'YeS', 'No'], f'Invalid output: {out}'


def test_total_money_limit(run, x):
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    q = int(lines[0])
    if q != 1:
        # This test suite only has single test case inputs
        return
    a, b, n, S = map(int, lines[1].split())
    out = run(x).strip().upper()
    if S > a * n + b:
        assert out == 'NO', f'S exceeds total money, must be NO'


def test_enough_ones(run, x):
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    q = int(lines[0])
    if q != 1:
        return
    a, b, n, S = map(int, lines[1].split())
    out = run(x).strip().upper()
    if S <= b:
        # You can pay with only 1-coins
        assert out == 'YES', f'S <= b, must be YES'


def test_check_yes_condition(run, x):
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    q = int(lines[0])
    if q != 1:
        return
    a, b, n, S = map(int, lines[1].split())
    out = run(x).strip().upper()
    if out == 'YES':
        # There must exist x in [0, a], y in [0, b] with x*n + y = S
        # Equivalently, there exists x in [0, a] such that (S - x*n) is between 0 and b
        possible = False
        # But we cannot iterate over huge a. Use condition: let x0 = min(a, S // n).
        # If we take x = x0, then remainder r = S - x0 * n.
        # If r <= b and r >= 0, then YES is correct.
        # Actually any correct YES must satisfy that for some x in [0,a] remainder between 0 and b.
        # We can check that at least one of the two extremes works:
        # x = min(a, S // n) and x = max(0, (S - b + n - 1) // n) (the smallest x that makes remainder <= b)
        # But simpler: just check that (S % n) <= b and (S // n) <= a? Not sufficient because you might need fewer n-coins if remainder > b.
        # However if answer is YES, then there exists x such that remainder r = S - x*n satisfies 0 <= r <= b.
        # So we can verify by checking that for x = min(a, S // n) down to max(0, (S - b) // n) (but that range may be large).
        # Since a and b can be up to 1e9, we cannot loop. So we skip large a,b.
        if a <= 1000000 and b <= 1000000:
            # brute force over x up to a
            for x in range(0, a + 1):
                if x * n > S:
                    break
                r = S - x * n
                if 0 <= r <= b:
                    possible = True
                    break
            assert possible, f'YES returned but no (x,y) found'


def test_check_no_condition(run, x):
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    q = int(lines[0])
    if q != 1:
        return
    a, b, n, S = map(int, lines[1].split())
    out = run(x).strip().upper()
    if out == 'NO':
        # No pair (x,y) should exist.
        # For large a,b we skip.
        if a <= 1000000 and b <= 1000000:
            possible = False
            for x in range(0, a + 1):
                if x * n > S:
                    break
                r = S - x * n
                if 0 <= r <= b:
                    possible = True
                    break
            assert not possible, f'NO returned but a pair exists'


def test_bruteforce_small(run, x):
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    q = int(lines[0])
    if q != 1:
        return
    a, b, n, S = map(int, lines[1].split())
    # Only brute force when a and b are small enough
    if a <= 1000 and b <= 1000:
        possible = False
        for x in range(0, a + 1):
            if x * n > S:
                break
            r = S - x * n
            if 0 <= r <= b:
                possible = True
                break
        out = run(x).strip().upper()
        if possible:
            assert out == 'YES', f'Brute force says YES but got {out}'
        else:
            assert out == 'NO', f'Brute force says NO but got {out}'


def test_mod_condition(run, x):
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    q = int(lines[0])
    if q != 1:
        return
    a, b, n, S = map(int, lines[1].split())
    out = run(x).strip().upper()
    # A necessary condition for YES: S % n <= b or something? Actually if we take x = S // n, remainder r = S % n.
    # If r <= b and x <= a, then YES. But there might be a solution with fewer n-coins if remainder > b.
    # So this condition is sufficient but not necessary.
    # However we can test that if both conditions hold, answer must be YES.
    x_needed = S // n
    r = S % n
    if x_needed <= a and r <= b:
        assert out == 'YES', f'Sufficient condition satisfied, must be YES'


def test_zero_coins(run, x):
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    q = int(lines[0])
    if q != 1:
        return
    a, b, n, S = map(int, lines[1].split())
    out = run(x).strip().upper()
    if S == 0:
        # You can take 0 n-coins and 0 1-coins
        assert out == 'YES', f'S=0 must be YES'


def test_output_length(run, x):
    out = run(x).strip()
    # Output should be a single token (YES/NO variants)
    tokens = out.split()
    assert len(tokens) == 1, f'Output should be one word'
    # Also length 2-3 characters typical
    assert 2 <= len(out) <= 3, f'Output length unusual'


def test_no_excess_whitespace(run, x):
    out = run(x)
    # Should not have leading/trailing spaces except maybe newline at end.
    # We'll check that stripping yields same as original except possibly newline at end.
    if out.endswith('\n'):
        stripped = out[:-1]
        assert stripped.strip() == stripped, f'Extra spaces before newline'
    else:
        assert out.strip() == out, f'Extra spaces in output'

