def test_small_bruteforce(run, x):
    # Simulate the algorithm directly for small inputs (n <= 10, each a_i <= 20).
    # This is a complete check.
    lines = x.strip().split('\n')
    n = int(lines[0])
    if len(lines) < 2:
        return
    a = list(map(int, lines[1].split()))
    if n > 10 or max(a, default=0) > 20:
        return  # skip large inputs
    # Simulate algorithm
    b = a[:]
    for k in range(1, 10**9 + 1, 2):
        odd, even = k, k + 1
        # replace odd with even
        for i in range(n):
            if b[i] == odd:
                b[i] = even
        # replace even with odd
        for i in range(n):
            if b[i] == even:
                b[i] = odd
    out = list(map(int, run(x).strip().split()))
    assert out == b, f'Brute-force simulation disagrees: expected {b}, got {out}'

