tests_src:
def test_output_is_non_negative_integer(run, x):
    out = run(x)
    val = int(out.strip())
    assert val >= 0

def test_answer_ge_euclidean_steps(run, x):
    a, b = map(int, x.strip().split())
    steps = 0
    while b:
        steps += a // b
        a, b = b, a % b
    ans = int(run(x).strip())
    assert ans >= steps

def test_answer_ge_one_if_not_square(run, x):
    a, b = map(int, x.strip().split())
    ans = int(run(x).strip())
    if a != b:
        assert ans >= 1

def test_matches_example_1(run, x):
    if x.strip() == "2 1":
        assert run(x).strip() == "2"

def test_matches_example_2(run, x):
    if x.strip() == "10 7":
        assert run(x).strip() == "6"

def test_matches_example_3(run, x):
    if x.strip() == "1000000000000 1":
        assert run(x).strip() == "1000000000000"

def test_small_inputs_brute_force(run, x):
    a, b = map(int, x.strip().split())
    if a <= 1000 and b <= 1000:
        # simulate the process directly
        ships = 0
        while a and b:
            if a > b:
                ships += a // b
                a %= b
            else:
                ships += b // a
                b %= a
        ans = int(run(x).strip())
        assert ans == ships

def test_answer_le_upper_bound(run, x):
    a, b = map(int, x.strip().split())
    # upper bound: each division yields a//b ships, then recurse on remainder
    def upper_bound(a, b):
        if b == 0:
            return 0
        if a > b:
            return a // b + upper_bound(b, a % b)
        else:
            return b // a + upper_bound(a, b % a)
    ub = upper_bound(a, b)
    ans = int(run(x).strip())
    assert ans <= ub

def test_answer_is_integer(run, x):
    out = run(x)
    try:
        int(out.strip())
    except ValueError:
        assert False, "Output must be an integer"

def test_answer_not_zero_unless_impossible(run, x):
    a, b = map(int, x.strip().split())
    ans = int(run(x).strip())
    # The only way to get zero ships is if the input is invalid (b >= a) but by spec b < a.
    # So answer must be positive.
    assert ans > 0

