def test_output_format(run, x):
    output = run(x).strip()
    assert output in ("Misha", "Vasya", "Tie"), f"Output must be one of Misha, Vasya, Tie, got '{output}'"

def test_no_empty_output(run, x):
    output = run(x)
    assert output.strip() != '', "Output must not be empty"

def test_zero_time_scores(run, x):
    a,b,c,d = map(int, x.strip().split())
    if c == 0 and d == 0:
        # scores are max(0.3a, a-0) = a, similarly for b
        expected = "Misha" if a > b else "Vasya" if b > a else "Tie"
        assert run(x).strip() == expected, f"With zero times, comparison must be direct a vs b"

def test_same_conditions_tie(run, x):
    a,b,c,d = map(int, x.strip().split())
    if a == b and c == d:
        # identical problems and submission times → identical scores
        assert run(x).strip() == "Tie", f"With a=b={a} and c=d={c}, must be Tie"

def test_early_submission_tie(run, x):
    a,b,c,d = map(int, x.strip().split())
    if a == b and c == 0 and d == 0:
        assert run(x).strip() == "Tie", f"Same problem, both submitted at start → Tie"

def test_symmetry_swapped_inputs(run, x):
    # Not swapping, just checking that output for (a,b,c,d) is opposite of (b,a,d,c) if a≠b or c≠d
    # But we cannot call run again, so instead we check a property: if we swap a↔b and c↔d, the answer should swap Misha↔Vasya, Tie stays Tie.
    # However we cannot compute swapped answer without second run, so we skip this test.
    # Instead, we ensure the output is consistent with the formula by recomputing for small a,b.
    pass

def test_recompute_small(run, x):
    a,b,c,d = map(int, x.strip().split())
    if a <= 1000 and b <= 1000:
        # recompute exactly using integers to avoid floating errors
        misha = max(3*a//10, a - (a//250)*c)
        vasya = max(3*b//10, b - (b//250)*d)
        expected = "Misha" if misha > vasya else "Vasya" if vasya > misha else "Tie"
        assert run(x).strip() == expected, f"Recomputed scores give {expected}"

def test_boundary_output_not_numeric(run, x):
    output = run(x).strip()
    # ensure output is not a number (common mistake)
    try:
        float(output)
        assert False, f"Output must not be a number, got {output}"
    except ValueError:
        pass

def test_no_extra_whitespace(run, x):
    output = run(x)
    assert output == output.strip() + '\n', f"Output must be exactly one line with no trailing spaces"

def test_score_non_negative(run, x):
    # The spec ensures scores are non‑negative because max(0.3p, p - (p/250)*t) ≥ 0 for t ≤ 180 and p ≥ 250.
    # So the comparison is well‑defined; we cannot check scores directly, but we can ensure the answer isn't nonsense.
    pass

