    lines = x.strip().split('\n')
    n_s = list(map(int, lines[0].split()))
    s = n_s[1]
    a = list(map(int, lines[1].split()))
    b = list(map(int, lines[2].split()))
    out = run(x).strip().upper()
    if out == 'YES' and a[s-1] == 0:
        # Must have some i >= s with a[i-1]==1 and b[i-1]==1
        found = False
        for i in range(s, n_s[0]+1):
            if a[i-1] == 1 and b[i-1] == 1:
                found = True
                break
        assert found, 'YES without direct access requires a station i>=s open on both tracks'

