        if a[s-1] == 1:
            assert False, 'Answer NO but station s directly reachable on first track'
        if b[s-1] == 0:
            # No reverse access, check if any i>=s with both open exists
            ok = False
            for i in range(s, n+1):
                if a[i-1] == 1 and b[i-1] == 1:
