def test_small_n_bruteforce(run, x):
    lines = x.strip().split('\n')
    n_s = list(map(int, lines[0].split()))
    n = n_s[0]
    if n > 10:
        return  # Skip large inputs
    s = n_s[1]
    a = list(map(int, lines[1].split()))
    b = list(map(int, lines[2].split()))
    # Brute-force BFS on stations (1-indexed)
    from collections import deque
    reachable = [False]*(n+1)
    reachable[1] = True
    q = deque([1])
    while q:
        u = q.popleft()
        # Move forward on first track
        for v in range(u+1, n+1):
            if a[v-1] == 1:
                if not reachable[v]:
                    reachable[v] = True
                    q.append(v)
            else:
                break  # Cannot pass closed station
        # Move backward on second track
        for v in range(u-1, 0, -1):
            if b[v-1] == 1:
                if not reachable[v]:
                    reachable[v] = True
                    q.append(v)
            else:
                break
    expected = 'YES' if reachable[s] else 'NO'
    assert run(x).strip().upper() == expected, f'Brute-force says {expected}'

