    for inp, out in zip(lines, outputs):
        if not inp:
            continue
        n, k = map(int, inp.split())
        ans = int(out)
        # If n is odd and k>=1, after first operation the number becomes even,
        # because f(n) is odd (smallest divisor >1 of an odd number is odd).
        # odd + odd = even. Thereafter f will be 2.
        # So after the first step, the number is even, and after any further steps
        # it stays even (even+2 stays even).
