def test_bruteforce_small(run, x):
    lines = x.strip().split('\n')
    n, s = map(int, lines[0].split())
    if n > 10:
        return  # skip large inputs
    a = list(map(int, lines[1].split()))
    b = list(map(int, lines[2].split()))
    # BFS over states (station, track) where track 0 = forward, 1 = reverse
    from collections import deque
    visited = [[False, False] for _ in range(n)]
    q = deque()
    if a[0] == 1:
        visited[0][0] = True
        q.append((0, 0))
    if b[0] == 1:
        visited[0][1] = True
        q.append((0, 1))
    while q:
        station, track = q.popleft()
        if station == s-1:
            expected = 'YES'
            break
        if track == 0:
            # forward direction: move to higher stations if open on forward track
            for nxt in range(station+1, n):
                if a[nxt]:
                    if not visited[nxt][0]:
                        visited[nxt][0] = True
                        q.append((nxt, 0))
                # you can switch to reverse track only at stations open on both tracks
                if a[nxt] and b[nxt]:
                    if not visited[nxt][1]:
                        visited[nxt][1] = True
                        q.append((nxt, 1))
        else:
            # reverse direction: move to lower stations if open on reverse track
            for nxt in range(station-1, -1, -1):
                if b[nxt]:
                    if not visited[nxt][1]:
                        visited[nxt][1] = True
                        q.append((nxt, 1))
                if a[nxt] and b[nxt]:
                    if not visited[nxt][0]:
                        visited[nxt][0] = True
                        q.append((nxt, 0))
    else:
        expected = 'NO'
    out = run(x).strip().upper()
    assert out == expected, f'Brute-force says {expected}, got {out}'

def test_YES_requires_path_exists(run, x):
    out = run(x).strip().upper()
    if out != 'YES':
        return
    lines = x.strip().split('\n')
    n, s = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))
    b = list(map(int, lines[2].split()))
    # If YES, there must be a forward path to some station i>=s-1 with both tracks open, then reverse to s-1.
    # At least one of these must hold:
    # 1. a[0]==1 and a[s-1]==1 (direct forward).
    # 2. There exists i >= s-1 with a[i]==b[i]==1 and a[0]==1 and b[i]==1 (go forward to i, switch, reverse to s).
    ok = False
    if a[0] == 1:
        if a[s-1] == 1:
            ok = True
        else:
            for i in range(s-1, n):
                if a[i] == 1 and b[i] == 1:
                    # check we can reach i forward and s-1 reverse from i
                    # forward reachability to i: all stations up to i on forward track? Not necessarily all, but we can move forward skipping closed stations.
                    # Since we can only move forward on forward track, we need a sequence of open stations from 0 to i.
                    # Instead, we use a simpler necessary condition: i must be reachable forward, meaning there is no closed station blocking the way.
                    # The simplest safe check: if a[0]==1 and a[i]==1, we can at least move forward if all a between are 1.
                    # We'll do a quick BFS limited to n <= 1000.
                    from collections import deque
                    visited = [False]*n
                    q = deque()
                    visited[0] = True
                    q.append(0)
                    while q:
                        u = q.popleft()
                        if u == i:
                            # forward reachable
                            # now check reverse from i to s-1
                            rev_ok = True
                            for j in range(i, s-2, -1):
                                if j == s-1:
                                    break
                                if b[j] == 0:
                                    rev_ok = False
                                    break
                            if rev_ok:
                                ok = True
                                break
                        for v in range(u+1, n):
                            if a[v] and not visited[v]:
                                visited[v] = True
                                q.append(v)
                    if ok:
                        break
    assert ok, f'Answer is YES but no obvious path exists per spec'

def test_forward_track_open_continuity(run, x):
    lines = x.strip().split('\n')
    n, s = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))
    # If all stations from 1 to s are open on forward track, answer must be YES.
    if all(a[i] == 1 for i in range(s)):
        assert run(x).strip().upper() == 'YES', f'All forward stations open from 1 to {s}, must be YES'

def test_reverse_track_usage(run, x):
    out = run(x).strip().upper()
    if out != 'YES':
        return
    lines = x.strip().split('\n')
    n, s = map(int, lines[0].split())
