    b = list(map(int, lines[2].split()))
    # If answer is YES and a[s-1]==0, then we must have used reverse track.
    if a[s-1] == 0:
        # Then b[s-1] must be 1 (target open on reverse) and there exists i >= s-1 with a[i]==b[i]==1.
        assert b[s-1] == 1, f'Answer YES but target closed on forward and reverse track closed at target'
        exists = False
        for i in range(s-1, n):
            if a[i] == 1 and b[i] == 1:
                exists = True
                break
        assert exists, f'Answer YES but no station >= {s} open on both tracks to switch'

