def test_small_n_bruteforce(run, x):
    import sys
    data = x.strip().split('\n')
    n_k = list(map(int, data[0].split()))
    if len(data) < 2:
        temps = []
    else:
        temps = list(map(int, data[1].split()))
    n, k = n_k
    if n > 8:
        return  # skip, too large for brute force
    # brute force over all sequences of tire choices: 0=summer,1=winter
    best = None
    for mask in range(1 << n):
        valid = True
        # condition: summer only allowed if temp >=0
        for i in range(n):
            if temps[i] < 0 and ((mask >> i) & 1) == 0:
                valid = False
                break
        if not valid:
            continue
        # winter tires used at most k days total
        winter_days = sum(1 for i in range(n) if ((mask >> i) & 1) == 1)
        if winter_days > k:
            continue
        # count switches: start with summer (mask=0) before day 0
        switches = 0
        prev = 0  # 0 summer, 1 winter before first day
        for i in range(n):
            cur = (mask >> i) & 1
            if cur != prev:
                switches += 1
            prev = cur
        if best is None or switches < best:
            best = switches
    out = run(x).strip()
    if best is None:
        # impossible
        if out != '-1':
            assert False, f"brute force says impossible, answer {out}"
    else:
