def test_output_is_integer(run, x):
    out = run(x).strip()
    # must be an integer, possibly with leading/trailing spaces
    int(out)

def test_output_non_negative(run, x):
    out = run(x).strip()
    val = int(out)
    assert val >= 0

def test_output_lt_mod(run, x):
    out = run(x).strip()
    val = int(out)
    MOD = 10**9 + 7
    assert 0 <= val < MOD

def test_example1(run, x):
    if x == ')(()()\n':
        out = run(x).strip()
        assert out == '6'

def test_example2(run, x):
    if x == '()()()\n':
        out = run(x).strip()
        assert out == '7'

def test_example3(run, x):
    if x == ')))\n':
        out = run(x).strip()
        assert out == '0'

def test_all_open_returns_zero(run, x):
    if x.strip().count(')') == 0:
        out = run(x).strip()
        assert out == '0'

def test_all_close_returns_zero(run, x):
    if x.strip().count('(') == 0:
        out = run(x).strip()
        assert out == '0'

def test_bruteforce_small(run, x):
    s = x.strip()
    if len(s) <= 10:
        MOD = 10**9 + 7
        n = len(s)
        total = 0
        from itertools import combinations
        for mask in range(1 << n):
            subseq = []
            for i in range(n):
                if (mask >> i) & 1:
                    subseq.append(s[i])
            if len(subseq) % 2 != 0 or len(subseq) == 0:
                continue
            half = len(subseq)//2
            ok = True
            for j in range(half):
                if subseq[j] != '(':
                    ok = False
                    break
            for j in range(half, len(subseq)):
                if subseq[j] != ')':
                    ok = False
                    break
            if ok:
                total += 1
        expected = total % MOD
        out = int(run(x).strip())
        assert out == expected

def test_answer_at_most_total_subsequences(run, x):
    s = x.strip()
    n = len(s)
    total_subs = (1 << n) - 1  # all non-empty subsequences
    MOD = 10**9 + 7
    out = int(run(x).strip())
    assert out <= total_subs % MOD

