def test_odd_n_parity(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    if n % 2 == 0:
        return
    a = list(map(int, lines[1].split()))
    # For odd n, the sum (a_i - i) mod n is invariant under pushes.
    # Because each push adds +1 to even indices and -1 to odd indices.
    # Sum over i of (a_i - i) changes by sum_{even} 1 + sum_{odd} (-1).
    # Number of even indices = (n+1)//2, odd = n//2, difference = 1.
    # So each push adds 1 mod n.
    # Therefore if the target sum is S_target = sum(i) mod n = n(n-1)/2 mod n.
    # The initial sum S0 = sum(a_i) mod n.
    # There exists k such that S0 + k = S_target mod n  <=>  k = S_target - S0 mod n.
    # Since k can be 0..n, we need that S_target - S0 is in [0,n-1] (always true).
    # So for odd n, the condition reduces to checking that S0 equals S_target.
    # Wait, but k must be integer 0..n, and the invariant is that S0 + k = S_target (mod n).
    # That means S_target - S0 must be 0 mod n, i.e., S0 ≡ S_target (mod n).
    # Because k is taken modulo n? Actually each push adds exactly 1 to the sum modulo n.
    # After k pushes, sum = S0 + k (mod n). Need S0 + k ≡ S_target (mod n) for some k in 0..n.
    # Since k runs through all residues mod n (because n pushes cycle), it's possible iff S0 ≡ S_target (mod n).
    # So for odd n, necessary and sufficient condition is sum(a_i) ≡ n(n-1)/2 (mod n).
    # Compute target sum modulo n.
    target = (n * (n - 1) // 2) % n
    s0 = sum(a) % n
    reachable = (s0 == target)
    out = run(x).strip()
    if reachable:
        assert out == "Yes", f'For odd n={n}, sum condition satisfied so must be Yes, got {out}'
    else:
        assert out == "No", f'For odd n={n}, sum condition not satisfied so must be No, got {out}'

def test_shift_invariance(run, x):
    # Adding a constant c to all a_i (mod n) does not affect solvability
    # because if we shift initial state, we can shift the target similarly.
    # More formally, if we replace a_i by (a_i + c) mod n, then after k pushes,
    # each a_i changes by ±k depending on parity, so the new sequence becomes
    # (a_i + c ± k) mod n. The target becomes (i + c) mod n.
    # So solvability unchanged.
    # We can test with c=1 on small n where brute force is possible.
    lines = x.strip().split('\n')
    n = int(lines[0])
    if n > 7:  # brute force up to n=7 is fine
        return
    a = list(map(int, lines[1].split()))
    c = 1
    a2 = [(v + c) % n for v in a]
    # Simulate brute force on original a
    reachable_original = False
    for pushes in range(n+1):
        cur = a[:]
        for _ in range(pushes):
            for i in range(n):
                if i % 2 == 0:
                    cur[i] = (cur[i] + 1) % n
                else:
                    cur[i] = (cur[i] - 1) % n
        if all(cur[i] == i for i in range(n)):
            reachable_original = True
            break
    # Simulate brute force on shifted a2
    reachable_shifted = False
    for pushes in range(n+1):
        cur = a2[:]
        for _ in range(pushes):
            for i in range(n):
                if i % 2 == 0:
                    cur[i] = (cur[i] + 1) % n
                else:
                    cur[i] = (cur[i] - 1) % n
        if all(cur[i] == i for i in range(n)):
            reachable_shifted = True
            break
    # They must match
    if reachable_original != reachable_shifted:
        # This should never happen for a correct solution.
        # But we cannot directly compare outputs because we only have one run.
        # Instead we can note that the output for the original input must be consistent
        # with the reachable_original we computed.
        out = run(x).strip()
        expected = "Yes" if reachable_original else "No"
        assert out == expected, f'Brute force says {expected}, got {out}'
    # else pass

