tests_src:
def test_output_is_yes_or_no(run, x):
    out = run(x)
    out_stripped = out.strip()
    assert out_stripped == 'YES' or out_stripped == 'NO', f'Output must be YES or NO, got {out!r}'

def test_if_k_1_then_whole_is_palindrome(run, x):
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    s = lines[0]
    try:
        k = int(lines[1])
    except:
        return
    if k != 1:
        return
    out = run(x).strip()
    correct = s == s[::-1]
    expected = 'YES' if correct else 'NO'
    assert out == expected, f'For k=1, expected {expected} for palindrome {s} but got {out}'

def test_yes_implies_length_divisible_and_palindrome_substrings(run, x):
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    s = lines[0]
    try:
        k = int(lines[1])
    except:
        return
    out = run(x).strip()
    if out == 'YES':
        assert len(s) % k == 0, f'YES but length {len(s)} not divisible by k={k}'
        step = len(s) // k
        for i in range(k):
            sub = s[i*step:(i+1)*step]
            assert sub == sub[::-1], f'YES but substring {sub} is not a palindrome'
    # If NO, no further constraint

def test_palindrome_substrings_full_check(run, x):
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    s = lines[0]
    try:
        k = int(lines[1])
    except:
        return
    out = run(x).strip()
    if out == 'YES':
        step = len(s) // k
        for i in range(k):
            sub = s[i*step:(i+1)*step]
            # full palindrome check
            if sub != sub[::-1]:
                assert False, f'YES but substring {sub} is not a palindrome'
    # NO case fine

def test_no_implies_some_substring_fails_or_length_not_divisible(run, x):
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    s = lines[0]
    try:
        k = int(lines[1])
    except:
        return
    out = run(x).strip()
    if out == 'NO':
        if len(s) % k == 0:
            step = len(s) // k
            all_palindrome = True
            for i in range(k):
                sub = s[i*step:(i+1)*step]
                if sub != sub[::-1]:
                    all_palindrome = False
                    break
            # If all are palindromes, answer should be YES, so contradiction
            if all_palindrome:
                assert False, f'NO but length divisible and all substrings are palindromes'
        # else condition satisfied: length not divisible

def test_length_not_divisible_implies_no(run, x):
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    s = lines[0]
    try:
        k = int(lines[1])
    except:
        return
    if len(s) % k != 0:
        out = run(x).strip()
        assert out == 'NO', f'Length {len(s)} not divisible by k={k}, must output NO, got {out}'

def test_output_exactly_yes_or_no_with_newline(run, x):
    out = run(x)
    # Must be exactly 'YES\n' or 'NO\n' (common practice)
    assert out in ('YES\n', 'NO\n'), f'Output must be exactly YES\n or NO\n, got {out!r}'

def test_substrings_contiguous_and_equal_length(run, x):
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    s = lines[0]
    try:
        k = int(lines[1])
    except:
        return
    out = run(x).strip()
    if out == 'YES':
        step = len(s) // k
        # reconstruct concatenation
        reconstructed = ''.join(s[i*step:(i+1)*step] for i in range(k))
        assert reconstructed == s, f'YES but substrings do not concatenate to original string'
    # NO case fine

def test_all_palindromes_and_length_divisible_implies_yes(run, x):
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    s = lines[0]
    try:
        k = int(lines[1])
    except:
        return
    if len(s) % k == 0:
        step = len(s) // k
        all_palindrome = True
        for i in range(k):
            sub = s[i*step:(i+1)*step]
            if sub != sub[::-1]:
                all_palindrome = False
                break
        if all_palindrome:
            out = run(x).strip()
            assert out == 'YES', f'All substrings are palindromes and length divisible, must output YES, got {out}'

def test_brute_force_small_inputs(run, x):
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    s = lines[0]
    try:
        k = int(lines[1])
    except:
        return
    # Only for small strings where brute force is cheap
    if len(s) > 20:
        return
    # brute force correct answer
    n = len(s)
    if n % k != 0:
        correct = 'NO'
    else:
        step = n // k
        ok = True
        for i in range(k):
            sub = s[i*step:(i+1)*step]
            if sub != sub[::-1]:
                ok = False
                break
        correct = 'YES' if ok else 'NO'
    out = run(x).strip()
    assert out == correct, f'Brute force says {correct}, got {out}'

