def test_output_format(run, x):
    out = run(x)
    assert out in ("YES\n", "NO\n"), f"Output must be exactly YES or NO with newline, got {repr(out)}"

def test_hash_count_multiple_of_five_if_yes(run, x):
    out = run(x).strip()
    if out == "YES":
        lines = x.strip().split('\n')
        n = int(lines[0])
        board = lines[1:]
        cnt = sum(row.count('#') for row in board)
        assert cnt % 5 == 0, f"YES but number of '#' ({cnt}) not divisible by 5"

def test_all_dot_is_yes(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    board = lines[1:]
    if all(c == '.' for row in board for c in row):
        assert run(x).strip() == "YES", f"Board with no '#' must be YES"

def test_greedy_success_implies_yes(run, x):
    # Simulate the greedy algorithm from the submission
    lines = x.strip().split('\n')
    n = int(lines[0])
    board = [list(row) for row in lines[1:]]
    k = 1
    for i in range(n):
        for j in range(n):
            if board[i][j] == '#':
                if i+2 <= n-1 and j-1 >= 0 and j+1 <= n-1:
                    if board[i+1][j-1] == '#' and board[i+1][j] == '#' and board[i+1][j+1] == '#' and board[i+2][j] == '#':
                        board[i+1][j-1] = '.'
                        board[i+1][j] = '.'
                        board[i+1][j+1] = '.'
                        board[i+2][j] = '.'
                        board[i][j] = '.'
                    else:
                        k = 0
                        break
                else:
                    k = 0
                    break
        if k == 0:
            break
    if k == 1:
        # greedy succeeded, so answer must be YES
        assert run(x).strip() == "YES", f"Greedy algorithm found a covering, so answer must be YES"
    # if greedy failed, we don't enforce anything

def test_bruteforce_n3(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    if n > 3:
        return  # only run for n <= 3
    board = [list(row) for row in lines[1:]]
    # brute-force search for placing crosses
    # cross shape: (i,j) top, then (i+1,j-1),(i+1,j),(i+1,j+1),(i+2,j)
    from itertools import product
    cells = [(r,c) for r in range(n) for c in range(n)]
    # precompute all possible cross placements
    placements = []
    for i in range(n-2):
        for j in range(1, n-1):
            pts = [(i,j), (i+1,j-1), (i+1,j), (i+1,j+1), (i+2,j)]
            placements.append(pts)
    # backtracking
    def dfs(idx, covered):
        # find first uncovered '#' cell
        for r,c in cells:
            if board[r][c] == '#' and (r,c) not in covered:
                break
        else:
            return True  # all '#' covered
        # try each placement that covers (r,c) and doesn't conflict
        for pts in placements:
            if (r,c) in pts:
                ok = True
                for pr,pc in pts:
                    if board[pr][pc] != '#' or (pr,pc) in covered:
                        ok = False
                        break
                if ok:
                    covered.update(pts)
                    if dfs(idx+1, covered):
                        return True
                    for pr,pc in pts:
                        covered.remove((pr,pc))
        return False
    possible = dfs(0, set())
    expected = "YES" if possible else "NO"
    assert run(x).strip() == expected, f"Brute-force says {expected}, got {run(x).strip()}"

