def test_small_bruteforce(run, x):
    n = int(x.strip())
    if n > 30:
        return  # skip large inputs
    # brute-force DP: dp[remaining][last] = max steps
    from functools import lru_cache
    @lru_cache(None)
    def dfs(rem, last):
        best = 0
        for take in range(1, rem+1):
            if take != last:
                best = max(best, 1 + dfs(rem - take, take))
        return best
    ans = dfs(n, 0)
    got = int(run(x).strip())
    assert got == ans, f"brute force says {ans}, got {got}"


def test_monotonic_non_decreasing(run, x):
    n = int(x.strip())
    got = int(run(x).strip())
    # For n >= 2, answer(n) >= answer(n-1).
    # Because we can always mimic the optimal for n-1 by taking same sequence and possibly an extra 1 at the end.
    # But need to compute answer for n-1; we can't call run again.
    # So we compute answer for n-1 by brute if small, otherwise skip.
    if n <= 30:
        # compute answer for n-1 using same brute force
        from functools import lru_cache
        @lru_cache(None)
        def dfs(rem, last):
            best = 0
            for take in range(1, rem+1):
                if take != last:
                    best = max(best, 1 + dfs(rem - take, take))
            return best
        ans_n_minus_1 = dfs(n-1, 0) if n > 1 else 0
        assert got >= ans_n_minus_1, f"answer({n})={got} < answer({n-1})={ans_n_minus_1}"


def test_answer_parity_constraint(run, x):
    n = int(x.strip())
    got = int(run(x).strip())
    # From known pattern, answer is either floor(2n/3) or floor(2n/3)+1.
    # So got mod 2 should equal (floor(2n/3) mod 2) or one more.
    base = 2 * (n // 3)
    if got == base or got == base + 1:
        return  # ok
    # also possibly base+2 if the suspicious adjustment subtracts 1? but spec doesn't allow.
    # If not within {base, base+1}, definitely wrong.
    assert False, f"answer {got} not in {{{base}, {base+1}}}"


def test_answer_bounds(run, x):
    n = int(x.strip())
    got = int(run(x).strip())
    # answer must be between 1 and n (since each present uses at least 1 stone)
    assert 1 <= got <= n, f"answer {got} out of [1, {n}]"


def test_mod3_consistency(run, x):
    n = int(x.strip())
    got = int(run(x).strip())
    # If n % 3 == 0, answer should be 2*n//3.
    if n % 3 == 0:
        expected = 2 * (n // 3)
        assert got == expected, f"n={n} divisible by 3, expected {expected}, got {got}"


def test_specific_examples(run, x):
    n = int(x.strip())
    got = int(run(x).strip())
    # Examples from the statement
    if n == 1:
        assert got == 1
    if n == 2:
        assert got == 1
    if n == 3:
        assert got == 2
    if n == 4:
        assert got == 3


def test_recurrence_relation(run, x):
    n = int(x.strip())
    if n <= 30:
        # compute answer by brute force for n, n-1, n-2
        from functools import lru_cache
        @lru_cache(None)
        def dfs(rem, last):
            best = 0
            for take in range(1, rem+1):
                if take != last:
                    best = max(best, 1 + dfs(rem - take, take))
            return best
        ans_n = dfs(n, 0)
        # known recurrence: ans(n) = max( ans(n-1), 1+ans(n-2) )? Not always.
        # but we can check that ans(n) <= 1 + ans(n-1) (trivial)
        if n > 1:
            ans_n_minus_1 = dfs(n-1, 0)
            assert ans_n <= 1 + ans_n_minus_1, f"violates ans({n}) <= 1 + ans({n-1})"
        got = int(run(x).strip())
        # compare got with brute-force ans_n
        assert got == ans_n, f"recurrence mismatch: brute {ans_n}, got {got}"


def test_suspicious_adjustment_range(run, x):
    n = int(x.strip())
    got = int(run(x).strip())
    base = 2 * (n // 3)
    # The submitted code adds adjustment=1 for n%3==1 and n>10 and (n-4)%9==0.
    # That would make answer = base+2, since base+1 is the normal else case.
    # But normal else case is base+1. So if adjustment triggers, answer = base+2.
    # This seems suspicious. Check that answer is either base or base+1 unless n meets that condition.
    if not (n % 3 == 1 and n > 10 and (n - 4) % 9 == 0):
        # then answer should be base or base+1
        assert got in (base, base + 1), f"unexpected answer {got} for n={n} not in suspicious set"


def test_answer_integer(run, x):
    output = run(x).strip()
    # must be a valid integer
    int(output)  # will raise ValueError if not


def test_nearby_values_consistency(run, x):
    n = int(x.strip())
    if n <= 30:
        # brute force for n, n+1, n+2 and check monotonicity
        from functools import lru_cache
        @lru_cache(None)
        def dfs(rem, last):
            best = 0
            for take in range(1, rem+1):
                if take != last:
                    best = max(best, 1 + dfs(rem - take, take))
            return best
        ans_n = dfs(n, 0)
        if n+1 <= 30:
            ans_np1 = dfs(n+1, 0)
            # answer should not decrease when n increases
            assert ans_np1 >= ans_n, f"non‑monotonic at {n}->{n+1}"
        got = int(run(x).strip())
        assert got == ans_n, f"brute mismatch {ans_n} vs {got}"

