def test_output_is_integer(run, x):
    out = run(x)
    assert out.strip().lstrip('-').isdigit()

def test_output_between_1_and_n(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0].split()[0])
    out = int(run(x).strip())
    assert 1 <= out <= n

def test_output_at_least_longest_alternating_segment(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0].split()[0])
    a = list(map(int, lines[1].split()))
    max_len = 1
    cur = 1
    for i in range(1, n):
        if a[i] != a[i-1]:
            cur += 1
        else:
            cur = 1
        if cur > max_len:
            max_len = cur
    out = int(run(x).strip())
    assert out >= max_len

def test_output_at_most_n(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0].split()[0])
    out = int(run(x).strip())
    assert out <= n

def test_if_no_adjacent_equal_then_output_n(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0].split()[0])
    a = list(map(int, lines[1].split()))
    all_diff = all(a[i] != a[i-1] for i in range(1, n))
    if all_diff:
        out = int(run(x).strip())
        assert out == n

def test_brute_force_for_small_n(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0].split()[0])
    if n > 20:
        return
    a = list(map(int, lines[1].split()))
    best = 0
    for l in range(n):
        for r in range(l, n):
            ok = True
            for i in range(l+1, r+1):
                if a[i] == a[i-1]:
                    ok = False
                    break
            if ok:
                best = max(best, r-l+1)
    out = int(run(x).strip())
    assert out == best

def test_output_at_least_1(run, x):
    out = int(run(x).strip())
    assert out >= 1

def test_output_consistent_with_examples(run, x):
    if x == "8 3\n1 2 3 3 2 1 2 2\n":
        out = int(run(x).strip())
        assert out == 4
    if x == "3 2\n1 2 2\n":
        out = int(run(x).strip())
        assert out == 2

def test_output_integer_non_negative(run, x):
    out = int(run(x).strip())
    assert out >= 0

def test_output_parses_as_single_line(run, x):
    out = run(x)
    lines = out.strip().split('\n')
    assert len(lines) == 1 and lines[0].strip().lstrip('-').isdigit()

