        out = run(x)
        climb = int(out.split()[0])
        assert climb == 0, 'If heights never decrease, max climb must be 0'"
    },
    {
      "name": "test_if_heights_non_increasing_then_descent_zero",
      "source": "def test_if_heights_non_increasing_then_descent_zero(run, x):
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    grid = lines[1:]
    heights = []
    for col in range(m):
        h = 0
        for row in range(n):
            if grid[row][col] == '*':
                h += 1
        heights.append(h)
    non_increasing = all(heights[i] >= heights[i+1] for i in range(m-1))
    if non_increasing:
        out = run(x)
        descent = int(out.split()[1])
        assert descent == 0, 'If heights never increase, max descent must be 0'"
    },
    {
      "name": "test_climb_bounded_by_max_height_difference",
      "source": "def test_climb_bounded_by_max_height_difference(run, x):
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    grid = lines[1:]
    heights = []
    for col in range(m):
        h = 0
        for row in range(n):
            if grid[row][col] == '*':
                h += 1
        heights.append(h)
    max_diff = max(abs(heights[i] - heights[i-1]) for i in range(1, m)) if m>1 else 0
    out = run(x)
    climb = int(out.split()[0])
    descent = int(out.split()[1])
    assert climb <= max_diff, 'Max climb cannot exceed the maximum absolute height difference between consecutive columns'
    assert descent <= max_diff, 'Max descent cannot exceed the maximum absolute height difference between consecutive columns'"
