    grid = lines[1:]
    heights = []
    for col in range(m):
        h = 0
        for row in range(n):
            if grid[row][col] == '*':
                h += 1
        heights.append(h)
    if all(h == heights[0] for h in heights):
        out = run(x)
        climb, descent = map(int, out.split())
        assert climb == 0 and descent == 0, 'If all heights equal, both max climb and max descent must be 0'"
    },
    {
      "name": "test_climb_and_descent_at_most_max_height",
      "source": "def test_climb_and_descent_at_most_max_height(run, x):
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    grid = lines[1:]
    max_h = 0
    for col in range(m):
        h = 0
        for row in range(n):
            if grid[row][col] == '*':
                h += 1
        if h > max_h:
            max_h = h
    out = run(x)
    climb, descent = map(int, out.split())
    assert climb <= max_h, 'Max climb cannot exceed the maximum column height'
    assert descent <= max_h, 'Max descent cannot exceed the maximum column height'"
