      "name": "test_small_input_exact",
      "source": "def test_small_input_exact(run, x):
    # only run brute‑force verification for inputs small enough (n,m ≤ 20)
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    if n > 20 or m > 20:
        return  # skip, too large for brute‑force in a test
    grid = lines[1:]
    # compute heights
    heights = []
    for col in range(m):
        h = 0
        for row in range(n):
            if grid[row][col] == '*':
                h += 1
        heights.append(h)
    # compute correct answer by definition
    max_up = 0
    max_down = 0
    for i in range(1, m):
        diff = heights[i] - heights[i-1]
        if diff > 0:
            max_up = max(max_up, diff)
        else:
            max_down = max(max_down, -diff)
    out = run(x)
    climb, descent = map(int, out.split())
    assert climb == max_up and descent == max_down, 'Answer does not match the computed correct values for this small input'"
