    n, m = map(int, lines[0].split())
    grid = lines[1:]
    heights = []
    for col in range(m):
        h = 0
        for row in range(n):
            if grid[row][col] == '*':
                h += 1
        heights.append(h)
    out = run(x)
    climb, descent = map(int, out.split())
