    {
      "name": "test_output_preserves_relative_order_of_last_occurrences",
      "source": "def test_output_preserves_relative_order_of_last_occurrences(run, x):
    # This is a restatement of the ordering property: the sequence of last occurrences (most recent first) equals output order.
    inp_lines = x.strip().split('\n')[1:]
    last_seen = {}
    for idx, name in enumerate(inp_lines):
        last_seen[name] = idx
    # Build list of unique names sorted by last index descending
    expected_order = sorted(last_seen.keys(), key=lambda n: -last_seen[n])
    out = run(x).strip()
