      "name": "test_small_input_brute_force",
      "source": "def test_small_input_brute_force(run, x):
    # Only run brute‑force simulation for n ≤ 20 (all given inputs satisfy this).
    lines = x.strip().split('\n')
    n = int(lines[0])
