    n = int(lines[0])
    s = lines[1]
    L = len(s)
    # Only run brute force when n and L are small enough
    if n > 6 or L > 6:
        return
    # Simulate all possibilities for Vasya's moves (he can choose 'a' or 'b' on his turns)
    # Vasya's turn indices: j such that (j-1) % n == 0
    vasya_turn_indices = [j for j in range(1, L+1) if (j-1) % n == 0]
    best = 0
    # Enumerate all choices for Vasya's moves (2^k possibilities)
    k = len(vasya_turn_indices)
    for mask in range(1 << k):
        # Build sequence seq of length L, same as s except Vasya's turns replaced
        seq = list(s)
        for idx, turn in enumerate(vasya_turn_indices):
            if (mask >> idx) & 1:
                seq[turn-1] = 'a'
            else:
                seq[turn-1] = 'b'
        # Compute drinks for Vasya
        drinks = 0
