                if seq[j-1] == seq[j-2] and seq[j-1] == seq[j-3] and seq[j-1] == seq[j-4]:
                    drinks += 1
        if drinks > best:
            best = drinks
    out = run(x).strip()
    val = int(out)
    assert val == best, f"Optimal drinks should be {best}, got {val}""
