        assert run(x) == "NO\n", f'No button lights any bulb, so impossible, expected NO, got {run(x)}'

def test_single_button_covers_all(run, x):
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    for i in range(1, n+1):
        parts = list(map(int, lines[i].split()))
        if parts[0] == m and set(parts[1:]) == set(range(1, m+1)):
            assert run(x) == "YES\n", f'Button {i} lights all bulbs, expected YES, got {run(x)}'

def test_all_bulbs_appear_yes(run, x):
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    seen = set()
    for i in range(1, n+1):
        parts = list(map(int, lines[i].split()))
        seen.update(parts[1:])
    if seen == set(range(1, m+1)):
        assert run(x) == "YES\n", f'Every bulb appears in some button, expected YES, got {run(x)}'

def test_missing_bulb_no(run, x):
    lines = x.strip().split('\n')
