        parts = list(map(int, lines[i].split()))
        seen.update(parts[1:])
    if len(seen) < m:
        assert run(x) == "NO\n", f'Only {len(seen)} distinct bulbs appear, missing some, expected NO, got {run(x)}'

def test_m_zero_always_yes(run, x):
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    if m == 0:
        assert run(x) == "YES\n", f'Zero bulbs, all already lit, expected YES, got {run(x)}'

