tests_src:
def test_non_negative_integer(run, x):
    out = run(x).strip()
    val = int(out)
    assert val >= 0

def test_output_less_than_MOD(run, x):
    out = run(x).strip()
    val = int(out)
    MOD = 10**9 + 7
    assert 0 <= val < MOD

def test_small_bruteforce(run, x):
    L, R = map(int, x.strip().split())
    if R - L + 1 > 2000:
        return  # too big for brute‑force
    MOD = 10**9 + 7
    ans = 0
    for xv in range(L, R + 1):
        for yv in range(xv, R + 1):
            if yv % xv == (yv ^ xv):
                ans = (ans + 1) % MOD
    out = int(run(x).strip())
    assert out == ans

def test_L_equals_R_always_one(run, x):
    L, R = map(int, x.strip().split())
    if L == R:
        out = int(run(x).strip())
        assert out == 1

def test_at_least_number_of_diagonal_pairs(run, x):
    L, R = map(int, x.strip().split())
    out = int(run(x).strip())
    # (y, y) always satisfies because y % y = 0 and y ^ y = 0
    assert out >= (R - L + 1)

def test_special_L_equals_1_small_R(run, x):
    L, R = map(int, x.strip().split())
    if L != 1 or R > 1000:
        return  # only test when small
    MOD = 10**9 + 7
    ans = 0
    for xv in range(1, R + 1):
        for yv in range(xv, R + 1):
            if yv % xv == (yv ^ xv):
                ans = (ans + 1) % MOD
    out = int(run(x).strip())
    assert out == ans

def test_single_value_answer_one(run, x):
    L, R = map(int, x.strip().split())
    if L == R:
        out = int(run(x).strip())
        assert out == 1

def test_two_consecutive_values(run, x):
    L, R = map(int, x.strip().split())
    if R - L != 1 or L > 5000:
        return  # only test small consecutive pairs
    MOD = 10**9 + 7
    ans = 0
    for xv in range(L, R + 1):
        for yv in range(xv, R + 1):
            if yv % xv == (yv ^ xv):
                ans = (ans + 1) % MOD
    out = int(run(x).strip())
    assert out == ans

def test_output_is_integer(run, x):
    out = run(x).strip()
    # try parsing to int; if fails, test fails
    int(out)

def test_modulo_consistency_for_small_inputs(run, x):
    L, R = map(int, x.strip().split())
    if R - L + 1 > 100:
        return
    MOD = 10**9 + 7
    ans = 0
    for xv in range(L, R + 1):
        for yv in range(xv, R + 1):
            if yv % xv == (yv ^ xv):
                ans += 1
    out = int(run(x).strip())
    assert out % MOD == ans % MOD

