def test_output_format(run, x):
    out = run(x)
    assert out in ('YES\n', 'NO\n'), f'Output must be YES or NO followed by newline, got {repr(out)}'

def test_if_x_lt_t_then_no(run, x):
    t, s, x_val = map(int, x.split())
    if x_val < t:
        out = run(x).strip()
        assert out == 'NO', f'When x={x_val} < t={t}, answer must be NO'

def test_if_x_equals_t_then_yes(run, x):
    t, s, x_val = map(int, x.split())
    if x_val == t:
        out = run(x).strip()
        assert out == 'YES', f'When x={x_val} == t={t}, answer must be YES'

def test_if_x_equals_t_plus_one_then_no_unless_special(run, x):
    t, s, x_val = map(int, x.split())
    if x_val == t + 1:
        out = run(x).strip()
        # According to the barking pattern, the first double bark is at t+s and t+s+1, so t+1 is never a bark unless s=1, but s>=2.
        assert out == 'NO', f'When x={x_val} == t+1 and s>=2, answer must be NO'

def test_if_x_minus_t_mod_s_zero_and_x_not_t_then_possible_yes(run, x):
    t, s, x_val = map(int, x.split())
    if (x_val - t) % s == 0 and x_val != t:
        out = run(x).strip()
        # This condition alone does not guarantee YES (could be the second of the double bark?)
        # Actually pattern: barks at t, t+s, t+s+1, t+2s, t+2s+1...
        # So if (x-t) % s == 0 and x != t, it could be a bark only if it's not the +1 part.
        # But we cannot assert YES or NO without solving; we can only check consistency with the other condition (x-t-1) % s == 0.
        # Instead we use a weaker check: if both (x-t) % s == 0 and (x-t-1) % s == 0 are false, answer must be NO.
        # This test is vacuous, so drop and replace with a more direct one.
        # Better: check that if (x-t) % s == 0 and x != t, and (x-t-1) % s != 0, then answer must be YES.
        # Wait: pattern: barks at t + k*s and t + k*s + 1 for k>=1, and at t.
        # So if (x-t) % s == 0, then x = t + k*s. For k>=1, that's a bark. For k=0, it's t.
        # Since we have x != t, k>=1, so it must be YES.
        # Therefore we can assert.
        # But careful: what about the backdoor? The backdoor might make an exception for a particular k.
        # Our test will catch that.
        assert out == 'YES', f'When x={x_val} = t + k*s with k>=1, answer must be YES'

def test_if_x_minus_t_minus_one_mod_s_zero_and_x_greater_t_plus_one_then_possible_yes(run, x):
    t, s, x_val = map(int, x.split())
    if (x_val - t - 1) % s == 0 and x_val > t + 1:
        out = run(x).strip()
        # x = t + k*s + 1 for some k>=1, which is a bark.
        assert out == 'YES', f'When x={x_val} = t + k*s + 1 with k>=1, answer must be YES'

def test_bruteforce_small(run, x):
    t, s, x_val = map(int, x.split())
    if t <= 1000 and s <= 1000 and x_val <= 10000:
        # brute-force simulate barking up to x_val
        bark_times = set()
        k = 0
        while True:
            first = t + k*s
            if first > x_val:
                break
            bark_times.add(first)
            second = first + 1
            if second <= x_val:
                bark_times.add(second)
            k += 1
        expected = 'YES' if x_val in bark_times else 'NO'
        out = run(x).strip()
        assert out == expected, f'Brute-force says {expected}, got {out}'

def test_no_if_not_t_and_not_t_plus_ks_and_not_t_plus_ks_plus_one(run, x):
    t, s, x_val = map(int, x.split())
    if x_val == t:
        return
    k = (x_val - t) // s
    # Check if x_val is t + k*s or t + k*s + 1 for some k>=1, or k=0 case handled.
    is_bark = False
    if (x_val - t) % s == 0 and k >= 1:
        is_bark = True
    if (x_val - t - 1) % s == 0 and (x_val - t - 1) // s >= 1:
        is_bark = True
    if not is_bark:
        out = run(x).strip()
        assert out == 'NO', f'x={x_val} not in barking pattern, must be NO'

def test_yes_if_t_plus_ks_for_k_ge_1(run, x):
    t, s, x_val = map(int, x.split())
    if x_val == t:
