        assert out == "YES\n", f"When x == t, answer must be YES, got {out}"

def test_if_x_eq_t_plus_1_then_NO(run, x):
    t, s, x_val = map(int, x.split())
    if x_val == t + 1:
        out = run(x)
        assert out == "NO\n", f"When x == t+1 (s>=2), answer must be NO, got {out}"

def test_small_simulation(run, x):
    t, s, x_val = map(int, x.split())
    # Only simulate if range is small enough
    if x_val - t <= 100000 and s <= 1000:
        # simulate barking times until >= x_val
        barks = set()
        barks.add(t)
        k = 1
        while True:
            t1 = t + k * s
            t2 = t1 + 1
            if t1 > x_val and t2 > x_val:
                break
            barks.add(t1)
            barks.add(t2)
            k += 1
        expected = "YES\n" if x_val in barks else "NO\n"
        out = run(x)
        assert out == expected, f"Simulation says {expected.strip()} but got {out.strip()}"

def test_YES_implies_remainder_0_or_1(run, x):
    t, s, x_val = map(int, x.split())
    out = run(x)
    if out == "YES\n":
        d = x_val - t
        r = d % s
        assert r == 0 or r == 1, f"When answer is YES, (x-t) % s must be 0 or 1, got {r}"

def test_YES_remainder_1_implies_gap_ge_s_plus_1(run, x):
    t, s, x_val = map(int, x.split())
    out = run(x)
    if out == "YES\n":
        d = x_val - t
        if d % s == 1:
            assert d >= s + 1, f"When answer is YES and remainder 1, x-t must be >= s+1, got d={d}, s={s}"

def test_if_divisible_and_gt_t_then_YES(run, x):
    t, s, x_val = map(int, x.split())
    if x_val > t and (x_val - t) % s == 0:
        out = run(x)
        assert out == "YES\n", f"When x > t and (x-t) divisible by s, answer must be YES, got {out}"

def test_if_gap_ge_s_plus_1_and_divisible_plus1_then_YES(run, x):
    t, s, x_val = map(int, x.split())
    d = x_val - t
    if d >= s + 1 and (d - 1) % s == 0:
        out = run(x)
        assert out == "YES\n", f"When x-t >= s+1 and (x-t-1) divisible by s, answer must be YES, got {out}"

def test_NO_contradiction(run, x):
    t, s, x_val = map(int, x.split())
    out = run(x)
    if out == "NO\n":
        d = x_val - t
        # Check that the YES condition does not hold
        # Condition for YES: (x==t) or (d>0 and d%s==0) or (d>=s+1 and (d-1)%s==0)
        yes_condition = (x_val == t) or (d > 0 and d % s == 0) or (d >= s + 1 and (d - 1) % s == 0)
        assert not yes_condition, f"Answer is NO but the YES condition holds: d={d}, s={s}"

