def test_output_is_positive_integer(run, x):
    out = run(x).strip()
    assert out.isdigit() and not out.startswith('0') and out != '0'

def test_answer_is_lunlun_number(run, x):
    out = run(x).strip()
    n = int(out)
    s = str(n)
    for a, b in zip(s, s[1:]):
        if abs(int(a) - int(b)) > 1:
            assert False, 'not a lunlun number'

def test_answer_ge_k(run, x):
    k = int(x.strip())
    ans = int(run(x).strip())
    # The first k lunlun numbers are >= 1, so the k‑th is at least k.
    assert ans >= k

def test_answer_le_safe_bound(run, x):
    k = int(x.strip())
    ans = int(run(x).strip())
    # A known bound: the K‑th lunlun number is < 10^10 for K ≤ 10^5.
    # (We can safely use 10**12 to be extra safe.)
    assert ans < 10**12

def test_bruteforce_small_k(run, x):
    k = int(x.strip())
    if k > 20:
        return   # skip large K
    # generate first k lunlun numbers by brute force up to a safe limit.
    def is_lunlun(n):
        s = str(n)
        return all(abs(int(a)-int(b)) <= 1 for a,b in zip(s, s[1:]))
    cnt = 0
    for n in range(1, 10**6):
        if is_lunlun(n):
            cnt += 1
            if cnt == k:
                expected = n
                break
    ans = int(run(x).strip())
    assert ans == expected

def test_no_leading_zero_in_output(run, x):
    out = run(x).strip()
    assert out == str(int(out))   # no leading zeros

def test_answer_is_increasing_for_given_list(run, x):
    # We are given a fixed list of 30 inputs; we can pre‑compute the answers
    # for them by running the provided code? NO, we cannot re‑run the submitted
    # code on other inputs; instead we compare only within the single run we get.
    # This test must be a no‑op because we cannot compare across inputs.
    # Instead, we implement a dummy that always passes.
    pass

def test_answer_digits_in_range(run, x):
    out = run(x).strip()
    for ch in out:
        assert '0' <= ch <= '9'

def test_k_1_is_1(run, x):
    k = int(x.strip())
    if k == 1:
        assert run(x).strip() == '1'

def test_no_extra_output(run, x):
    out = run(x)
    lines = out.strip().split('\n')
    assert len(lines) == 1 and lines[0].strip() != ''

