    # Actually, we can't assert any fixed parity. So this test is vacuous.
    # Instead, check that the answer is integer (already done).
    # We'll replace with a weaker bound: answer <= N^4.
    assert ans <= N**4
    # Also answer >= 0 already checked.

def test_small_bruteforce_N1(run, x):
    N, K = map(int, x.strip().split())
    if N != 1:
        return
    ans = int(run(x).strip())
    count = 0
    for a in range(1, N+1):
        for b in range(1, N+1):
            for c in range(1, N+1):
                for d in range(1, N+1):
                    if a + b - c - d == K:
                        count += 1
    assert ans == count

