def test_output_is_valid_pokemon(run, x):
    valid = {'vaporeon', 'jolteon', 'flareon', 'espeon', 'umbreon', 'leafeon', 'glaceon', 'sylveon'}
    out = run(x).strip()
    assert out in valid

def test_output_length_matches_n(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    out = run(x).strip()
    assert len(out) == n

def test_output_matches_pattern(run, x):
    lines = x.strip().split('\n')
    pattern = lines[1].strip()
    out = run(x).strip()
    assert len(out) == len(pattern)
    for i, (c_out, c_pat) in enumerate(zip(out, pattern)):
        if c_pat != '.' and c_out != c_pat:
            assert False, f'Mismatch at position {i}: {c_out} != {c_pat}'

def test_pattern_matches_first(run, x):
    lines = x.strip().split('\n')
    pattern = lines[1].strip()
    out = run(x).strip()
    for i, (c_out, c_pat) in enumerate(zip(out, pattern)):
        if c_pat != '.' and c_out != c_pat:
            assert False

def test_output_lowercase(run, x):
    out = run(x).strip()
    assert out.islower()

def test_all_dot_pattern_unique(run, x):
    lines = x.strip().split('\n')
    pattern = lines[1].strip()
    if all(c == '.' for c in pattern):
        n = int(lines[0])
        valid_by_len = {
            6: {'espeon', 'umbreon'},
            7: {'jolteon', 'flareon', 'leafeon', 'glaceon', 'sylveon'},
            8: {'vaporeon', 'leafeon', 'glaceon', 'sylveon'}
        }
        out = run(x).strip()
        assert out in valid_by_len[n]

def test_full_word_input_matches(run, x):
    lines = x.strip().split('\n')
    pattern = lines[1].strip()
    if all(c != '.' for c in pattern):
        out = run(x).strip()
        assert out == pattern

def test_exact_example_1(run, x):
    if x == '7\nj......\n':
        out = run(x).strip()
        assert out == 'jolteon'

def test_exact_example_2(run, x):
    if x == '7\n...feon\n':
        out = run(x).strip()
        assert out == 'leafeon'

def test_exact_example_3(run, x):
    if x == '7\n.l.r.o.\n':
        out = run(x).strip()
        assert out == 'flareon'

