def test_answer_length_matches_n(run, x):
    lines = x.strip('\n').split('\n')
    n = int(lines[0])
    ans = run(x).strip()
    assert len(ans) == n, f'Answer length {len(ans)} != {n}'

def test_answer_is_valid_pokemon(run, x):
    pokemon = {"vaporeon", "jolteon", "flareon", "espeon", "umbreon", "leafeon", "glaceon", "sylveon"}
    ans = run(x).strip()
    assert ans in pokemon, f'{ans} not a valid Pokémon'

def test_answer_matches_known_letters(run, x):
    lines = x.strip('\n').split('\n')
    pattern = lines[1]
    ans = run(x).strip()
    for i, ch in enumerate(pattern):
        if ch != '.':
            assert i < len(ans) and ans[i] == ch, f'Letter mismatch at position {i}'

def test_answer_is_lowercase(run, x):
    ans = run(x).strip()
    assert ans.islower(), f'Answer not lowercase: {ans}'

def test_n_is_between_6_and_8(run, x):
    lines = x.strip('\n').split('\n')
    n = int(lines[0])
    assert 6 <= n <= 8, f'n={n} out of range'

def test_pattern_length_matches_n(run, x):
    lines = x.strip('\n').split('\n')
    n = int(lines[0])
    pattern = lines[1]
    assert len(pattern) == n, f'Pattern length {len(pattern)} != {n}'

def test_pattern_contains_only_lowercase_or_dot(run, x):
    import string
    lines = x.strip('\n').split('\n')
    pattern = lines[1]
    allowed = set(string.ascii_lowercase + '.')
    for ch in pattern:
        assert ch in allowed, f'Invalid character in pattern: {ch}'

def test_answer_has_no_extra_whitespace(run, x):
    ans = run(x)
    assert ans.strip() == ans, 'Answer has leading/trailing whitespace'

def test_brute_force_match_for_small_n(run, x):
    # Since n ≤ 8, we can brute force the unique match
    lines = x.strip('\n').split('\n')
    n = int(lines[0])
    pattern = lines[1]
    pokemon = ["vaporeon", "jolteon", "flareon", "espeon", "umbreon", "leafeon", "glaceon", "sylveon"]
    matches = []
    for p in pokemon:
        if len(p) != n:
            continue
        ok = True
        for i, ch in enumerate(pattern):
            if ch != '.' and p[i] != ch:
                ok = False
                break
        if ok:
            matches.append(p)
    # Specification says exactly one matches
    assert len(matches) == 1, f'Expected exactly one match, got {matches}'
    ans = run(x).strip()
    assert ans == matches[0], f'Answer {ans} != unique match {matches[0]}'

def test_answer_starts_with_pattern_first_non_dot(run, x):
    lines = x.strip('\n').split('\n')
    pattern = lines[1]
    ans = run(x).strip()
    for i, ch in enumerate(pattern):
        if ch != '.':
            assert ans[i] == ch, f'First non-dot at {i} does not match'
            break

