def test_output_format(run, x):
    output = run(x)
    lines = output.split('\n')
    # Should have 11 lines (9 board rows + 2 empty separators)
    # Actually the format is 9 rows of board data, each with spaces between subfields, plus empty lines between big rows.
    # The examples show 11 lines total (including empty separators).
    # We'll check that every character is one of 'x','o','.','!',' ' or newline.
    allowed = {'x', 'o', '.', '!', ' ', '\n'}
    for ch in output:
        assert ch in allowed, f'Invalid character in output: {repr(ch)}'
    # Check that the board structure matches input: split into parts as in input reading.
    # We'll parse the input board to get a 9x9 grid, and the output to get another 9x9 grid.
    # The output must be identical except '.' may become '!'.
    input_lines = x.strip('\n').split('\n')
    # The input has 11 lines as well. We'll parse similarly to the submitted solution.
    a_input = [[None]*9 for _ in range(9)]
    idx = 0
    for k in range(3):
        for i in range(3):
            parts = input_lines[idx].split()
            for j in range(3):
                for l in range(3):
                    a_input[k*3+i][j*3+l] = parts[j][l]
            idx += 1
        if k != 2:
            # skip empty line
            idx += 1
    # Parse output similarly (but output has trailing spaces and maybe extra newline).
    out_lines = output.split('\n')
    # Remove trailing empty lines
    while out_lines and out_lines[-1] == '':
        out_lines.pop()
    # Should have 11 lines (9 data + 2 empties) or maybe 11 lines including last empty?
    # We'll just try to parse the same way, but we need to know where empty lines are.
    # Instead, we can flatten the output lines ignoring spaces.
    # Collect all non-space characters.
    out_chars = []
    for line in out_lines:
        out_chars.extend([c for c in line if c != ' '])
    # Should be 81 characters.
    assert len(out_chars) == 81, f'Output must have exactly 81 board characters, got {len(out_chars)}'
    # Compare cell by cell
    for i in range(9):
        for j in range(9):
            inp = a_input[i][j]
            out = out_chars[i*9 + j]
            # Only '.' can change to '!', others must stay same.
            if inp == '.':
                assert out == '!' or out == '.', f'Empty cell at ({i},{j}) must become ! or stay ., got {out}'
            else:
                assert out == inp, f'Occupied cell at ({i},{j}) must not change, expected {inp} got {out}'


