    while True:
        if turn == 0:
            # Mahmoud's turn: must choose even a, 1 ≤ a ≤ n
            possible = [a for a in range(2, n+1, 2) if a <= n]
            if not possible:
                winner = "Ehab"
                break
            # optimal: choose largest even to minimize opponent's options
            a = possible[-1]
        else:
            # Ehab's turn: must choose odd a
            possible = [a for a in range(1, n+1, 2) if a <= n]
            if not possible:
                winner = "Mahmoud"
                break
            a = possible[-1]
        n -= a
        turn = 1 - turn
    out = run(x).strip()
    assert out == winner, f'For n={int(x.strip())}, expected {winner}, got {out}'

