tests_src:
def test_output_format(run, x):
    out = run(x).strip()
    assert out.isdigit() or (out == '' and x.strip() == '1\nR'), f'Output must be a non-negative integer, got {repr(out)}'
    if out:
        int(out)  # should not raise

def test_non_negative(run, x):
    out = run(x).strip()
    if out:
        ans = int(out)
        assert ans >= 0, f'Answer must be non-negative, got {ans}'

def test_upper_bound(run, x):
    N = int(x.split('\n')[0])
    total_triples = N * (N-1) * (N-2) // 6
    out = run(x).strip()
    if out:
        ans = int(out)
        assert ans <= total_triples, f'Answer {ans} exceeds total triples {total_triples}'

def test_small_brute(run, x):
    lines = x.strip().split('\n')
    N = int(lines[0])
    if N > 50:
        return  # too big for O(N^3)
    S = lines[1]
    expected = 0
    for i in range(N):
        for j in range(i+1, N):
            for k in range(j+1, N):
                if S[i] != S[j] and S[i] != S[k] and S[j] != S[k]:
                    if j - i != k - j:
                        expected += 1
    out = run(x).strip()
    if out:
        ans = int(out)
        assert ans == expected, f'Expected {expected}, got {ans}'

def test_color_product_minus_equal_spacing(run, x):
    lines = x.strip().split('\n')
    N = int(lines[0])
    if N > 200:
        return  # skip large N to keep fast
    S = lines[1]
    R = S.count('R')
    G = S.count('G')
    B = S.count('B')
    total_colorful = R * G * B
    # subtract those with equal spacing
    subtract = 0
    for i in range(N):
        for j in range(i+1, N):
            k = 2*j - i
            if k < N and S[i] != S[j] and S[j] != S[k] and S[i] != S[k]:
                subtract += 1
    out = run(x).strip()
    if out:
        ans = int(out)
        assert ans == total_colorful - subtract, f'Expected {total_colorful - subtract}, got {ans}'

def test_parity(run, x):
    lines = x.strip().split('\n')
    N = int(lines[0])
    if N > 30:
        return
    S = lines[1]
    # compute parity by brute force
    cnt = 0
    for i in range(N):
        for j in range(i+1, N):
            for k in range(j+1, N):
                if S[i] != S[j] and S[i] != S[k] and S[j] != S[k] and j - i != k - j:
                    cnt += 1
    out = run(x).strip()
    if out:
        ans = int(out)
        assert ans % 2 == cnt % 2, f'Parity mismatch: expected {cnt%2}, got {ans%2}'

def test_all_same(run, x):
    lines = x.strip().split('\n')
    S = lines[1]
    if len(set(S)) == 1:
        out = run(x).strip()
        if out:
            ans = int(out)
            assert ans == 0, f'All same characters => answer must be 0, got {ans}'

def test_N_lt_3(run, x):
    N = int(x.split('\n')[0])
    if N < 3:
        out = run(x).strip()
        if out:
            ans = int(out)
            assert ans == 0, f'N < 3 => answer must be 0, got {ans}'

def test_only_two_colors(run, x):
    lines = x.strip().split('\n')
    S = lines[1]
    if len(set(S)) == 2:
        N = len(S)
        total_triples = N * (N-1) * (N-2) // 6
        out = run(x).strip()
        if out:
            ans = int(out)
            assert ans < total_triples, f'Only two colors => answer < total triples {total_triples}, got {ans}'

def test_tiny_exhaustive(run, x):
    lines = x.strip().split('\n')
    N = int(lines[0])
    if N > 10:
        return
    S = lines[1]
    cnt = 0
    for i in range(N):
        for j in range(i+1, N):
            for k in range(j+1, N):
                if S[i] != S[j] and S[i] != S[k] and S[j] != S[k] and j - i != k - j:
                    cnt += 1
    out = run(x).strip()
    if out:
        ans = int(out)
        assert ans == cnt, f'Expected {cnt}, got {ans}'

