def test_answer_is_in_range(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0].split()[0])
    ans = int(run(x).strip())
    assert 1 <= ans <= n, f'answer {ans} not in 1..{n}'

def test_answer_is_integer(run, x):
    out = run(x).strip()
    assert out.isdigit() or (out[0]=='-' and out[1:].isdigit()), 'output not an integer'

def test_bruteforce_small_inputs(run, x):
    lines = x.strip().split('\n')
    n, x_val, y_val = map(int, lines[0].split())
    if n > 30:
        return  # skip large inputs
    arr = list(map(int, lines[1].split()))
    ans = int(run(x).strip())
    # brute‑force check
    for d in range(1, n+1):
        ok = True
        for j in range(max(1, d - x_val), min(n, d + y_val) + 1):
            if j == d:
                continue
            if arr[d-1] >= arr[j-1]:
                ok = False
                break
        if ok:
            assert ans == d, f'earliest not‑so‑rainy day is {d}, got {ans}'
            return
    # specification guarantees answer exists, so we never reach here
    assert False, 'no valid day found (should not happen)'

def test_condition_holds_at_answer(run, x):
    lines = x.strip().split('\n')
    n, x_val, y_val = map(int, lines[0].split())
    arr = list(map(int, lines[1].split()))
    ans = int(run(x).strip())
    d = ans
    # check the condition for this d
    for j in range(max(1, d - x_val), min(n, d + y_val) + 1):
        if j == d:
            continue
        assert arr[d-1] < arr[j-1], f'condition fails: a[{d}]={arr[d-1]} >= a[{j}]={arr[j-1]}'

def test_no_earlier_valid_day(run, x):
    lines = x.strip().split('\n')
    n, x_val, y_val = map(int, lines[0].split())
    arr = list(map(int, lines[1].split()))
    ans = int(run(x).strip())
    # check that no day < ans satisfies the condition
    for d in range(1, ans):
        ok = True
        for j in range(max(1, d - x_val), min(n, d + y_val) + 1):
            if j == d:
                continue
            if arr[d-1] >= arr[j-1]:
                ok = False
                break
        assert not ok, f'day {d} is earlier and also not‑so‑rainy'

def test_answer_value_is_min_in_window(run, x):
    lines = x.strip().split('\n')
    n, x_val, y_val = map(int, lines[0].split())
    arr = list(map(int, lines[1].split()))
    ans = int(run(x).strip())
    left = max(1, ans - x_val)
    right = min(n, ans + y_val)
    window = arr[left-1:right]
    assert arr[ans-1] == min(window), f'a[{ans}] is not the minimum in its window'

def test_early_index_property(run, x):
    lines = x.strip().split('\n')
    n, x_val, y_val = map(int, lines[0].split())
    arr = list(map(int, lines[1].split()))
    ans = int(run(x).strip())
    # If the answer is not 1, then day 1 must violate the condition.
    if ans > 1:
        d = 1
        ok = True
        for j in range(max(1, d - x_val), min(n, d + y_val) + 1):
            if j == d:
                continue
            if arr[d-1] < arr[j-1]:
                pass
            else:
                ok = False
                break
        assert not ok, f'day 1 is not‑so‑rainy, so answer should be 1, got {ans}'

