    N = int(x.strip())
    if N == 4:
        # N! = 24, divisors: 1,2,3,4,6,8,12,24 -> none have 75 divisors -> answer 0
        output = run(x)
        assert output.strip() == '0', f'For N=4, expected 0, got {output}'

def test_N5_bruteforce(run, x):
    N = int(x.strip())
    if N == 5:
        # N! = 120, divisors: many, but none have 75 divisors (75=3*5^2, would need p^2*q^4 or p^74 etc., not possible with small primes) -> answer 0
        # We can brute force to be sure
        import math
        nfact = math.factorial(5)
        def divisor_count(num):
            cnt = 0
            for d in range(1, int(num**0.5)+1):
                if num % d == 0:
                    cnt += 1
                    if d*d != num:
                        cnt += 1
            return cnt
        answer = 0
        for d in range(1, nfact+1):
            if nfact % d == 0:
                if divisor_count(d) == 75:
                    answer += 1
        output = run(x)
        assert output.strip() == str(answer), f'For N=5, expected {answer}, got {output}'

