def test_answer_small_input_bruteforce(run, x):
    import sys
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    if n > 2 or m > 2:
        return  # skip large inputs
    matrix = [list(map(int, line.split())) for line in lines[1:1+n]]
    max_val = max(max(row) for row in matrix)
    if max_val > 10:
        return  # skip large numbers
    # Brute-force compute minimal moves
    # Precompute primes up to max_val + 500 (since increments may be needed)
    limit = max_val + 500
    is_prime = [True] * (limit + 1)
    is_prime[0] = is_prime[1] = False
    for p in range(2, int(limit**0.5)+1):
        if is_prime[p]:
            for k in range(p*p, limit+1, p):
                is_prime[k] = False
    # For each cell, compute cost to reach each prime within limit
    INF = 10**9
    best = INF
    # Try all rows
    for i in range(n):
        cost = 0
        for j in range(m):
            v = matrix[i][j]
            # find smallest prime >= v
            while v <= limit and not is_prime[v]:
                v += 1
            if v > limit:
                cost = INF
                break
            cost += v - matrix[i][j]
        best = min(best, cost)
    # Try all columns
    for j in range(m):
        cost = 0
        for i in range(n):
            v = matrix[i][j]
            while v <= limit and not is_prime[v]:
                v += 1
            if v > limit:
                cost = INF
                break
            cost += v - matrix[i][j]
        best = min(best, cost)
    ans = int(run(x).strip())
    assert ans == best

def test_answer_bounds(run, x):
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    matrix = [list(map(int, line.split())) for line in lines[1:1+n]]
    upper = 0
    for row in matrix:
        for val in row:
            # worst case: increment to a prime <= 2*10^5 (since val <= 10^5 and prime gap small)
            # but we use a safe huge bound: 10**5 * n * m
            pass
    upper = 10**5 * n * m  # very loose bound
    ans = int(run(x).strip())
    assert ans <= upper

def test_answer_upper_bound_rows(run, x):
    # Compute min over rows of sum of distances to next prime
    import math
    def next_prime(v):
        while True:
            if v <= 1:
                v = 2
            # primality test
            ok = v > 1
            for d in range(2, int(math.isqrt(v)) + 1):
                if v % d == 0:
                    ok = False
                    break
            if ok:
                return v
            v += 1
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    matrix = [list(map(int, line.split())) for line in lines[1:1+n]]
    row_sum = []
    for i in range(n):
        cost = 0
        for j in range(m):
            v = matrix[i][j]
            p = next_prime(v)
            cost += p - v
        row_sum.append(cost)
    upper = min(row_sum) if row_sum else 0
    ans = int(run(x).strip())
    assert ans <= upper

