def test_answer_lower_bound(run, x):
    import math
    def distance_to_prime(v):
        orig = v
        while True:
            if v <= 1:
                v = 2
            ok = v > 1
            for d in range(2, int(math.isqrt(v)) + 1):
                if v % d == 0:
                    ok = False
                    break
            if ok:
                return v - orig
            v += 1
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    matrix = [list(map(int, line.split())) for line in lines[1:1+n]]
