def test_answer_parity_check(run, x):
    # For inputs where all numbers are even and >2, making a number prime requires an odd increment.
    # So any row/column sum of increments must have parity equal to number of cells mod 2.
    # This is a weak sanity check.
    import math
    def is_prime(v):
        if v <= 1:
            return False
        for d in range(2, int(math.isqrt(v)) + 1):
            if v % d == 0:
                return False
        return True
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    matrix = [list(map(int, line.split())) for line in lines[1:1+n]]
    all_even = all(v % 2 == 0 for row in matrix for v in row)
    all_greater2 = all(v > 2 for row in matrix for v in row)
    if all_even and all_greater2:
        # For each cell, distance to next prime is odd (since even->odd prime).
        # So sum over row of m cells: parity = m mod 2.
        # Similarly for column: parity = n mod 2.
        # The answer is min over rows/cols, so its parity must match either m mod 2 or n mod 2.
        # Since both n,m <=500, we can just check that answer parity is among {m%2, n%2}.
        ans = int(run(x).strip())
        expected_parities = {m % 2, n % 2}
        assert ans % 2 in expected_parities

def test_answer_exact_for_small_matrix(run, x):
