def test_small_bruteforce(run, x):
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    if n * m > 12:  # too big for brute‑force
        return
    grid = lines[1:]
    # brute‑force all paths
    from collections import deque
    next_char = {'D':'I','I':'M','M':'A','A':'D'}
    max_passes = 0
    for i in range(n):
        for j in range(m):
            if grid[i][j] != 'D':
                continue
            # BFS/DFS over states (position, current_char_index)
            # state (i,j,char) where char is current letter, start with 'D'
            q = deque()
            q.append((i,j,'D',0,set()))  # passes count so far
            while q:
                ci,cj,ch,passes,visited = q.popleft()
                key = (ci,cj,ch)
                if key in visited:
                    # cycle, infinite possible
                    out = run(x).strip()
                    assert out == "Poor Inna!", f"Small grid has infinite loop, expected 'Poor Inna!' got '{out}'"
                    return
                if ch == 'A':
                    # after A we go to D, and passes increase when we finish M->A
                    # we count a pass when we reach A
                    passes2 = passes + 1
                    nch = 'D'
                else:
                    passes2 = passes
                    nch = next_char[ch]
                new_visited = set(visited)
                new_visited.add(key)
                for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                    ni,nj = ci+dx, cj+dy
                    if 0<=ni<n and 0<=nj<m and grid[ni][nj]==nch:
                        q.append((ni,nj,nch,passes2,new_visited))
                # also allow staying? no, must move to adjacent.
            # if we exhausted all paths from this start, update max
            # but we need to track passes per path. Actually we should do DFS with memoization.
    # For simplicity, we implement a proper DP on (i,j,step) with step 0..3 (D,I,M,A).
    # Since n*m ≤ 12, we can do DFS with cycle detection.
    # We'll compute the maximum number of complete passes reachable from each D.
    # If any cycle reachable, answer infinite.
    # This is a bit long but doable.
    # Let's implement a simpler but correct brute‑force:
    # each path is a sequence of distinct positions? Not necessarily distinct.
    # We'll do DFS with visited set per path to avoid loops within same path.
    max_found = 0
    infinite = False
    for si in range(n):
        for sj in range(m):
            if grid[si][sj] != 'D':
                continue
            stack = [(si,sj,'D',0,set())]
            while stack:
                ci,cj,ch,passes,visited = stack.pop()
                key = (ci,cj,ch)
                if key in visited:
                    infinite = True
                    break
                nv = set(visited)
                nv.add(key)
                if ch == 'A':
                    passes2 = passes + 1
                    nch = 'D'
                else:
                    passes2 = passes
                    nch = next_char[ch]
                any_move = False
                for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                    ni,nj = ci+dx, cj+dy
                    if 0<=ni<n and 0<=nj<m and grid[ni][nj]==nch:
                        any_move = True
                        stack.append((ni,nj,nch,passes2,nv))
                if not any_move:
                    max_found = max(max_found, passes2)
            if infinite:
                break
        if infinite:
            break
    out = run(x).strip()
    if infinite:
        assert out == "Poor Inna!", f"Small grid has infinite loop, expected 'Poor Inna!' got '{out}'"
    elif max_found == 0:
        assert out == "Poor Dima!", f"Small grid no pass possible, expected 'Poor Dima!' got '{out}'"
    else:
        assert out.isdigit() and int(out) == max_found, f"Small grid expected {max_found} got '{out}'"

