def test_output_is_one_of_two_strings(run, x):
    output = run(x)
    assert output in ("CHAT WITH HER!\n", "IGNORE HIM!\n")

def test_output_ends_with_newline(run, x):
    output = run(x)
    assert output.endswith('\n')

def test_output_non_empty(run, x):
    output = run(x)
    assert len(output) > 0

def test_output_exact_match(run, x):
    output = run(x)
    assert output == "CHAT WITH HER!\n" or output == "IGNORE HIM!\n"

def test_output_length(run, x):
    output = run(x)
    assert len(output) in (14, 15)  # 14 for 'IGNORE HIM!\n', 15 for 'CHAT WITH HER!\n'

def test_output_starts_with_correct_prefix(run, x):
    output = run(x)
    assert output.startswith("CHAT") or output.startswith("IGNORE")

def test_single_distinct_char(run, x):
    # if all characters are the same, distinct count = 1 → odd → IGNORE HIM!
    s = x.strip()
    if len(set(s)) == 1:
        assert run(x) == "IGNORE HIM!\n"

def test_all_distinct_chars(run, x):
    s = x.strip()
    if len(s) == len(set(s)):
        # distinct count = length
        expected = "IGNORE HIM!\n" if len(s) % 2 == 1 else "CHAT WITH HER!\n"
        assert run(x) == expected

def test_length_one_input(run, x):
    s = x.strip()
    if len(s) == 1:
        # one distinct character → odd → IGNORE HIM!
        assert run(x) == "IGNORE HIM!\n"

def test_length_two_different_chars(run, x):
    s = x.strip()
    if len(s) == 2 and s[0] != s[1]:
        # distinct count = 2 → even → CHAT WITH HER!
        assert run(x) == "CHAT WITH HER!\n"

