    assert out in ('CHAT WITH HER!\n', 'IGNORE HIM!\n')

def test_output_consistent_with_parity_of_distinct_chars(run, x):
    # Compute distinct characters ignoring the code's special case
    s = x.strip()
    distinct = len(set(s))
    expected_parity = distinct % 2
    out = run(x)
    # If expected parity is odd → 'IGNORE HIM!', else 'CHAT WITH HER!'
    if expected_parity == 1:
        assert out == 'IGNORE HIM!\n'
    else:
        assert out == 'CHAT WITH HER!\n'

def test_single_char_string(run, x):
    s = x.strip()
    if len(s) == 1:
        # One distinct character → odd → IGNORE HIM!
        assert run(x) == 'IGNORE HIM!\n'

def test_all_distinct_chars(run, x):
    s = x.strip()
    if len(set(s)) == len(s):
        # All characters distinct → parity is parity of length
        if len(s) % 2 == 1:
            assert run(x) == 'IGNORE HIM!\n'
        else:
            assert run(x) == 'CHAT WITH HER!\n'

def test_duplicate_string(run, x):
    s = x.strip()
    if len(s) > 0 and len(set(s)) == 1:
        # All same character → exactly one distinct → odd → IGNORE HIM!
        assert run(x) == 'IGNORE HIM!\n'

def test_no_extra_whitespace(run, x):
    out = run(x)
    # Must be exactly one of the two strings, no extra spaces or empty lines
    assert out == out.strip() + '\n'

def test_parity_toggle_by_adding_new_char(run, x):
    s = x.strip()
    if len(s) >= 2:
        # Take prefix of length len(s)-1
        prefix = s[:-1]
        # Simulate input for prefix
        # We cannot call run again, but we can compute expected parity for both
        distinct_full = len(set(s))
        distinct_prefix = len(set(prefix))
        # Adding one character can change distinct count by 0 or 1
        # If it changes by 1, parity toggles; if by 0, parity stays same.
        change = distinct_full - distinct_prefix
        # We cannot compare outputs directly, but we can check consistency:
        # The output for s must match parity of distinct_full.
        out = run(x)
        if distinct_full % 2 == 1:
            assert out == 'IGNORE HIM!\n'
        else:
            assert out == 'CHAT WITH HER!\n'

def test_direct_bruteforce_small(run, x):
    s = x.strip()
    if len(s) <= 10:
        # Compute answer directly from specification
        distinct = len(set(s))
        expected = 'IGNORE HIM!' if distinct % 2 == 1 else 'CHAT WITH HER!'
        out = run(x).strip()
        assert out == expected

def test_leading_q_special_case(run, x):
    s = x.strip()
    if s.startswith('q'):
