        true_distinct = len(set(s))
        out = run(x)
        if true_distinct % 2 == 1:
            assert out == 'IGNORE HIM!\n'
        else:
            assert out == 'CHAT WITH HER!\n'

def test_output_length(run, x):
    out = run(x)
    # Output must be one of the two fixed strings, so length is known
    assert len(out) in (len('CHAT WITH HER!\n'), len('IGNORE HIM!\n'))

