def test_output_format(run, x):
    out = run(x).strip()
    if out == 'Poor Dima!' or out == 'Poor Inna!':
        return
    # otherwise must be a non‑negative integer without extra whitespace
    i = int(out)
    assert i >= 0
    assert out == str(i)  # no leading/trailing spaces


def test_no_d_means_poor_dima(run, x):
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    data = ''.join(lines[1:])
    if 'D' not in data:
        out = run(x).strip()
        assert out == 'Poor Dima!', f'No D cell must yield \"Poor Dima!\", got {out}'


def test_single_cell_d(run, x):
    lines = x.strip().split('\n')
    if len(lines) != 2 or lines[1] != 'D':
        return
    out = run(x).strip()
    assert out == 'Poor Dima!', f'Single D cell cannot complete DIMA, got {out}'


def test_brute_force_small(run, x):
    import sys
    sys.setrecursionlimit(10000)
    lines = x.strip().split('\n')
    if not lines:
        return
    n_m = lines[0].split()
    if len(n_m) != 2:
        return
    n, m = map(int, n_m)
    if n * m > 20:   # brute force only tiny grids
        return
    grid = lines[1:]
    # compute answer by DFS with cycle detection
    letters = {'D':0, 'I':1, 'M':2, 'A':3}
    dirs = [(1,0),(-1,0),(0,1),(0,-1)]
    g = [[letters[ch] for ch in row] for row in grid]
    visited = [[0]*m for _ in range(n)]
    instack = [[False]*m for _ in range(n)]
    dp = [[-1]*m for _ in range(n)]
    def dfs(r,c):
        if visited[r][c]:
            return dp[r][c]
        if instack[r][c]:
            return float('inf')
        instack[r][c] = True
        best = 0
        val = g[r][c]
        nxt = (val + 1) % 4
        for dr,dc in dirs:
            nr, nc = r+dr, c+dc
            if 0 <= nr < n and 0 <= nc < m and g[nr][nc] == nxt:
                res = dfs(nr,nc)
                if res == float('inf'):
                    best = float('inf')
                    break
                best = max(best, res + (1 if val == 3 else 0))
        dp[r][c] = best
        instack[r][c] = False
        visited[r][c] = 1
        return best
    ans = 0
    inf = False
    for i in range(n):
        for j in range(m):
            if g[i][j] == 0:
                res = dfs(i,j)
                if res == float('inf'):
                    inf = True
                    break
                ans = max(ans, res)
        if inf:
            break
    expected = 'Poor Inna!' if inf else ('Poor Dima!' if ans == 0 else str(ans))
    out = run(x).strip()
    assert out == expected, f'Brute force says {expected}, got {out}'


def test_answer_nonnegative_or_phrases(run, x):
    out = run(x).strip()
    if out == 'Poor Dima!' or out == 'Poor Inna!':
        return
    i = int(out)
    assert i >= 0, f'Integer answer {i} negative'


def test_cycle_if_no_path_then_poor_dima(run, x):
    # if there is no D->I->M->A path of length 4, answer must be Poor Dima!
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    n_m = lines[0].split()
    if len(n_m) != 2:
        return
    n, m = map(int, n_m)
    grid = lines[1:]
    # quick BFS from any D to any A through I,M
    from collections import deque
    letters = {'D':0, 'I':1, 'M':2, 'A':3}
    g = [[letters[ch] for ch in row] for row in grid]
    dirs = [(1,0),(-1,0),(0,1),(0,-1)]
    found = False
    for i in range(n):
        for j in range(m):
            if g[i][j] != 0:
                continue
            # BFS for pattern D->I->M->A
            q = deque()
            q.append((i,j,0))
            vis = [[False]*m for _ in range(n)]
            vis[i][j] = True
            while q:
                r,c,step = q.popleft()
                nxt = (step + 1) % 4
                for dr,dc in dirs:
                    nr, nc = r+dr, c+dc
                    if 0 <= nr < n and 0 <= nc < m and not vis[nr][nc] and g[nr][nc] == nxt:
                        if nxt == 3:
                            found = True
                            break
                        vis[nr][nc] = True
                        q.append((nr,nc,nxt))
                if found:
                    break
            if found:
                break
        if found:
            break
    if not found:
        out = run(x).strip()
        assert out == 'Poor Dima!', f'No DIMA path exists, expected Poor Dima!, got {out}'


def test_upper_bound_by_count(run, x):
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    data = ''.join(lines[1:])
    cntD = data.count('D')
    cntI = data.count('I')
    cntM = data.count('M')
    cntA = data.count('A')
    # each DIMA uses one of each letter in order
    max_possible = min(cntD, cntI, cntM, cntA)
    out = run(x).strip()
    if out == 'Poor Dima!' or out == 'Poor Inna!':
        return
    k = int(out)
    assert k <= max_possible, f'Answer {k} exceeds letter‑count bound {max_possible}'


def test_simple_cycle_detection(run, x):
    # if there is a reachable cycle in the D->I->M->A->D graph, answer must be Poor Inna!
    # we do a simple DFS on a small grid only
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    n_m = lines[0].split()
    if len(n_m) != 2:
        return
    n, m = map(int, n_m)
    if n * m > 30:   # keep it small
        return
    grid = lines[1:]
    letters = {'D':0, 'I':1, 'M':2, 'A':3}
    g = [[letters[ch] for ch in row] for row in grid]
    dirs = [(1,0),(-1,0),(0,1),(0,-1)]
    visited = [[0]*m for _ in range(n)]
    instack = [[False]*m for _ in range(n)]
    def has_cycle(r,c):
        if visited[r][c]:
            return False
        if instack[r][c]:
            return True
        instack[r][c] = True
        val = g[r][c]
        nxt = (val + 1) % 4
        for dr,dc in dirs:
            nr, nc = r+dr, c+dc
            if 0 <= nr < n and 0 <= nc < m and g[nr][nc] == nxt:
                if has_cycle(nr,nc):
                    return True
        instack[r][c] = False
        visited[r][c] = 1
        return False
    cycle = False
    for i in range(n):
        for j in range(m):
            if g[i][j] == 0 and has_cycle(i,j):
                cycle = True
                break
        if cycle:
            break
    out = run(x).strip()
    if cycle:
        assert out == 'Poor Inna!', f'Cycle detected, expected Poor Inna!, got {out}'


