    if hires >= crimes:
        assert ans <= crimes - hires  # Actually, ans <= crimes - hires? Wait, hires >= crimes => worst case untreated = crimes - hires? No: each hire can handle one crime, so if hires >= crimes, untreated can be 0. So ans >= 0 is already covered. Better: if hires >= crimes, then ans <= crimes - hires is nonsense (negative). Let's do: ans <= crimes - (hires - something) is not safe. Instead use: ans <= max(0, crimes - hires). That's always true. So:
        assert ans <= max(0, crimes - hires)
    # else no constraint

def test_brute_force_small(run, x):
