def test_single_event(run, x):
    events = list(map(int, x.strip().split()[1:]))
    if len(events) == 1:
        e = events[0]
        ans = int(run(x).strip())
        if e == -1:
            assert ans == 1
        else:
            assert ans == 0

def test_cumulative_officers_nonnegative_after_adjust(run, x):
    # This is a known property: after each crime, if officers were negative, we set to zero and count untreated.
    # So after processing all events, officers >= 0. But we don't have officers output, only ans.
    # Instead we can check that ans >= max(0, -min_balance) where min_balance is the lowest cumulative officers if we treat each crime as -1 and hires as +e.
    events = list(map(int, x.strip().split()[1:]))
    balance = 0
    min_balance = 0
    for e in events:
        if e == -1:
            balance -= 1
        else:
            balance += e
        if balance < min_balance:
            min_balance = balance
    # The minimum balance is the point where officers would be most negative.
    # The number of untreated crimes must be at least -min_balance, because each untreated crime corresponds to a drop below zero.
    ans = int(run(x).strip())
    assert ans >= -min_balance

