def test_output_format(run, x):
    out = run(x).strip()
    if out == '':
        return
    lines = out.split('\n')
    for line in lines:
        stripped = line.strip()
        if stripped == '-1':
            continue
        # must be a positive integer
        assert stripped.isdigit() and int(stripped) > 0, f'Invalid output line: {line}'


def test_sum_bounds(run, x):
    lines = x.strip().split('\n')
    first = list(map(int, lines[0].split()))
    n, q = first[0], first[1]
    out_lines = run(x).strip().split('\n')
    for i in range(q):
        t, k, d = map(int, lines[i+1].split())
        ans_line = out_lines[i].strip()
        if ans_line == '-1':
            continue
        s = int(ans_line)
        # smallest possible sum of k smallest ids: 1+2+...+k = k*(k+1)//2
        min_sum = k * (k + 1) // 2
        # largest possible sum of k smallest ids: (n-k+1) + (n-k+2) + ... + n = k*n - k*(k-1)//2
        max_sum = k * n - k * (k - 1) // 2
        assert min_sum <= s <= max_sum, f'Sum {s} for k={k}, n={n} out of bounds [{min_sum},{max_sum}]'


def test_no_negative_sum(run, x):
    out = run(x).strip()
    if out == '':
        return
    for line in out.split('\n'):
        stripped = line.strip()
        if stripped != '-1':
            val = int(stripped)
            assert val >= 0, f'Non-negative sum expected, got {val}'


def test_line_counts_match_q(run, x):
    lines = x.strip().split('\n')
    first = list(map(int, lines[0].split()))
    n, q = first[0], first[1]
    out_lines = run(x).strip().split('\n')
    if out_lines == ['']:
        assert q == 0, 'Empty output but q>0'
    else:
        assert len(out_lines) == q, f'Expected {q} output lines, got {len(out_lines)}'


def test_sum_positive_when_not_negative1(run, x):
    out = run(x).strip()
    if out == '':
        return
    for line in out.split('\n'):
        stripped = line.strip()
        if stripped != '-1':
            val = int(stripped)
            assert val > 0, f'Sum must be positive when task is accepted, got {val}'


def test_sum_integer(run, x):
    out = run(x).strip()
    if out == '':
        return
    for line in out.split('\n'):
        stripped = line.strip()
        if stripped == '-1':
