    out = run(x).strip('\n')
    lines = out.split('\n')
    for line in lines:
        # line should not have leading/trailing spaces
        assert line == line.strip(), f'Extra whitespace in line: {repr(line)}'


def test_all_lines_parsable(run, x):
    out = run(x).strip()
    if out == '':
        return
    for line in out.split('\n'):
        stripped = line.strip()
        try:
            int(stripped)
        except ValueError:
            assert False, f'Cannot parse line as integer: {repr(line)}'


def test_brute_force_small(run, x):
    lines = x.strip().split('\n')
    first = list(map(int, lines[0].split()))
    n, q = first[0], first[1]
    # only brute-force when small
    if n > 5 or q > 5:
        return
    # brute-force simulation
    busy_until = [0] * n
    out_lines = run(x).strip().split('\n')
    for i in range(q):
        t, k, d = map(int, lines[i+1].split())
        free = []
        for sid in range(n):
            if busy_until[sid] < t:
                free.append(sid)
            if len(free) == k:
                break
        if len(free) < k:
            expected = '-1'
        else:
            # sum of ids (1‑based)
            s = sum(sid + 1 for sid in free)
            for sid in free:
                busy_until[sid] = t + d - 1
            expected = str(s)
        got = out_lines[i].strip()
        assert got == expected, f'Line {i+1}: expected {expected}, got {got}'


def test_sum_mod_1(run, x):
    lines = x.strip().split('\n')
    first = list(map(int, lines[0].split()))
    n, q = first[0], first[1]
    out_lines = run(x).strip().split('\n')
    # simulate free servers at each task, but only for k=1
    busy_until = [0] * n
    for i in range(q):
        t, k, d = map(int, lines[i+1].split())
        got = out_lines[i].strip()
        if k == 1:
            # find smallest free server id
            chosen = -1
            for sid in range(n):
                if busy_until[sid] < t:
                    chosen = sid
                    break
            if chosen == -1:
                expected = '-1'
            else:
                expected = str(chosen + 1)
                # update busy_until for this server
                busy_until[chosen] = t + d - 1
            assert got == expected, f'Task {i+1} with k=1: expected {expected}, got {got}'
        else:
            # for k>1 we cannot check easily, just update busy_until using the answer
            if got != '-1':
                s = int(got)
                # we don't know which servers were used, but we can update all possible?
                # Instead, we just skip updating busy_until for k>1 to keep the test simple.
                # This test is only about k=1.
                pass

