def test_small_bruteforce(run, x):
    lines = x.strip().split('\n')
    nk = list(map(int, lines[0].split()))
    if len(nk) != 2:
        return
    n, k = nk
    if n > 20:
        return
    xs = list(map(int, lines[1].split()))
    if len(xs) != n:
        return
    # BFS to compute minimal number of bicycles
    from collections import deque
    INF = 10**9
    dist = [INF] * n
    dist[0] = 1
    q = deque([0])
    while q:
        i = q.popleft()
        d = dist[i]
        for j in range(i+1, n):
            if xs[j] - xs[i] <= k:
                if dist[j] > d + 1:
                    dist[j] = d + 1
                    q.append(j)
            else:
                break
    expected = dist[n-1] if dist[n-1] < INF else -1
    out = run(x).strip()
    if out == '':
        return
    ans = int(out)
    assert ans == expected, f'Brute-force gives {expected}, got {ans}'

