def test_answer_consistent_with_greedy_lower_bound(run, x):
    lines = x.strip().split('\n')
    nk = list(map(int, lines[0].split()))
    if len(nk) != 2:
        return
    n, k = nk
    if n < 2:
        return
    xs = list(map(int, lines[1].split()))
    if len(xs) != n:
        return
    gaps = [xs[i] - xs[i-1] for i in range(1, n)]
    if any(g > k):
        return
    # greedy simulation: take bike as far as k allows
    pos = xs[0]
    idx = 0
    count = 0
    while idx < n-1:
        count += 1
        farthest = pos + k
        # find the farthest station ≤ farthest
        nxt = idx
        while nxt+1 < n and xs[nxt+1] <= farthest:
            nxt += 1
        if nxt == idx:
            # cannot move
            return
        idx = nxt
        pos = xs[idx]
    out = run(x).strip()
    if out == '':
        return
    ans = int(out)
    # greedy gives an upper bound, answer cannot be larger than greedy count
    assert ans <= count, f'Answer {ans} > greedy upper bound {count}'

