def test_no_leading_zero(run, x):
    out = run(x).strip()
    if out != "Impossible":
        assert out[0] != '0'

def test_output_length(run, x):
    out = run(x).strip()
    if out != "Impossible":
        p, _ = map(int, x.split())
        assert len(out) == p

def test_numeric_output(run, x):
    out = run(x).strip()
    if out != "Impossible":
        # Must be a valid positive integer without leading zeros
        assert out.isdigit() and int(out) > 0

def test_rotation_condition(run, x):
    out = run(x).strip()
    if out != "Impossible":
        p, x_val = map(int, x.split())
        last = out[-1]
        rotated = last + out[:-1]
        # rotated must equal original * x_val
        assert int(rotated) == int(out) * x_val

def test_rotation_condition_integer(run, x):
    out = run(x).strip()
    if out != "Impossible":
        p, x_val = map(int, x.split())
        # Check that (last_digit * 10^{p-1} + rest) == x_val * (rest*10 + last_digit) would be redundant, 
        # but we already did in previous test.
        # This test double‑checks that the multiplication does not overflow sanity.
        n = int(out)
        last = n % 10
        rest = n // 10
        rotated = last * (10 ** (p-1)) + rest
        assert rotated == n * x_val

def test_minimality_among_rotation_satisfying(run, x):
    out = run(x).strip()
    if out != "Impossible":
        p, x_val = map(int, x.split())
        # For small p we can brute‑force check minimality.
        if p <= 6:
            best = None
            for cand in range(10**(p-1), 10**p):
                s = str(cand)
                if s[0] == '0':
                    continue
                last = s[-1]
                rotated = int(last + s[:-1])
                if rotated == cand * x_val:
                    if best is None or cand < best:
                        best = cand
            if best is not None:
                assert int(out) == best

def test_positive_and_no_leading_zero_redundant(run, x):
    out = run(x).strip()
    if out != "Impossible":
        assert int(out) > 0
        # Already checked leading zero, but also ensure it's exactly p digits
        p, _ = map(int, x.split())
        assert len(out) == p

def test_impossible_case_small_p(run, x):
    # For small p we can verify that if output is Impossible, indeed no number exists.
    p, x_val = map(int, x.split())
    if p <= 6:
        exists = False
        for cand in range(10**(p-1), 10**p):
            s = str(cand)
            if s[0] == '0':
                continue
            last = s[-1]
            rotated = int(last + s[:-1])
            if rotated == cand * x_val:
                exists = True
                break
        out = run(x).strip()
        if exists:
            assert out != "Impossible"
        else:
            assert out == "Impossible"

def test_brute_small_p(run, x):
    p, x_val = map(int, x.split())
    if p <= 6:
        # Exhaustive search for the minimal number satisfying the condition.
        best = None
        for cand in range(10**(p-1), 10**p):
            s = str(cand)
            if s[0] == '0':
                continue
            last = s[-1]
            rotated = int(last + s[:-1])
            if rotated == cand * x_val:
                best = cand
                break  # because we iterate in increasing order
        out = run(x).strip()
        if best is None:
            assert out == "Impossible"
        else:
            assert int(out) == best

def test_output_is_minimal_by_prefix(run, x):
    # This is a weaker test: if we take the last digit and prepend it, 
    # the resulting number must be exactly x times the original.
    # And among all such, the original must be minimal.
    # We cannot check minimality without brute‑force, but we can check 
    # that the number is indeed a solution (already done) and that it has no leading zero.
    out = run(x).strip()
    if out != "Impossible":
        p, x_val = map(int, x.split())
        # Already tested rotation condition in other tests; just a sanity duplicate.
        n = int(out)
        last = n % 10
        rest = n // 10
        rotated = last * (10 ** (p-1)) + rest
        assert rotated == n * x_val
        # Also ensure rest is exactly p-1 digits (no leading zero in original).
        assert rest >= 10**(p-2) if p > 1 else rest == 0

