def test_output_shape(run, x):
    lines = run(x).strip().split('\n')
    # split the first line to count columns, ignoring trailing spaces
    cols = len(lines[0].strip().split()) if lines[0].strip() else 0
    # get n,m from input
    n, m, _ = map(int, x.strip().split('\n')[0].split())
    assert len(lines) == n, f'Expected {n} rows, got {len(lines)}'
    assert cols == m, f'Expected {m} columns, got {cols}'

def test_colors_in_range(run, x):
    out = run(x)
    for line in out.strip().split('\n'):
        parts = line.strip().split()
        for p in parts:
            val = int(p)
            assert 0 <= val <= 10**9, f'Color {val} out of allowed range'

def test_brute_force_for_small_grid(run, x):
    first = x.strip().split('\n')[0]
    n, m, k = map(int, first.split())
    if n * m > 10000:   # avoid heavy computation
        return
    # simulate
    grid = [[0]*m for _ in range(n)]
    for idx, line in enumerate(x.strip().split('\n')[1:]):
        if not line.strip():
            continue
        t, pos, col = map(int, line.split())
        pos -= 1
        if t == 1:
            for j in range(m):
                grid[pos][j] = col
        else:
            for i in range(n):
                grid[i][pos] = col
    # compare with output
    out_lines = run(x).strip().split('\n')
    for i in range(n):
        out_vals = list(map(int, out_lines[i].strip().split()))
        for j in range(m):
            if out_vals[j] != grid[i][j]:
                assert False, f'Mismatch at ({i},{j}): expected {grid[i][j]}, got {out_vals[j]}'

def test_unpainted_cells_zero(run, x):
    first = x.strip().split('\n')[0]
    n, m, k = map(int, first.split())
    # collect painted rows and columns
    painted_rows = set()
    painted_cols = set()
    for line in x.strip().split('\n')[1:]:
        if not line.strip():
            continue
        parts = line.split()
        t = int(parts[0])
        pos = int(parts[1])
        if t == 1:
            painted_rows.add(pos)
        else:
            painted_cols.add(pos)
    out_lines = run(x).strip().split('\n')
    for i in range(n):
        out_vals = list(map(int, out_lines[i].strip().split()))
        for j in range(m):
            # cell (i+1, j+1) is never painted if row i+1 and column j+1 are never painted
            if (i+1 not in painted_rows) and (j+1 not in painted_cols):
                assert out_vals[j] == 0, f'Cell ({i+1},{j+1}) never painted, should be 0, got {out_vals[j]}'

def test_last_operation_per_cell(run, x):
    first = x.strip().split('\n')[0]
    n, m, k = map(int, first.split())
    # record operations with index
    ops = []
    for idx, line in enumerate(x.strip().split('\n')[1:]):
        if not line.strip():
            continue
        t, pos, col = map(int, line.split())
        ops.append((t, pos, col, idx))
    out_lines = run(x).strip().split('\n')
    for i in range(n):
        out_vals = list(map(int, out_lines[i].strip().split()))
        for j in range(m):
            # find the last operation affecting this cell
            last_col = 0
            last_idx = -1
            for (t, pos, col, idx) in ops:
                if (t == 1 and pos == i+1) or (t == 2 and pos == j+1):
                    last_col = col
                    last_idx = idx
            # cell must have that color
            if out_vals[j] != last_col:
                assert False, f'Cell ({i+1},{j+1}) last op idx {last_idx} gives color {last_col}, got {out_vals[j]}'

def test_row_operation_overwrites_column(run, x):
    first = x.strip().split('\n')[0]
    n, m, k = map(int, first.split())
    out_lines = run(x).strip().split('\n')
    # collect all row operations
    row_ops = []
    col_ops = []
    for line in x.strip().split('\n')[1:]:
        if not line.strip():
            continue
        t, pos, col = map(int, line.split())
        if t == 1:
            row_ops.append((pos, col))
        else:
            col_ops.append((pos, col))
    # if the very last operation is a row paint, that entire row must be uniform
    if row_ops:
        last_op_line = x.strip().split('\n')[-1]
        last = list(map(int, last_op_line.split()))
        if last[0] == 1:
            r = last[1]
            expected = last[2]
            row_vals = list(map(int, out_lines[r-1].strip().split()))
            for v in row_vals:
                if v != expected:
                    assert False, f'Last operation paints row {r} color {expected}, but row contains {v}'

def test_column_operation_overwrites_row(run, x):
    first = x.strip().split('\n')[0]
