def test_parses_as_int(run, x):
    out = run(x)
    int(out.strip())  # must not raise

def test_non_negative(run, x):
    out = run(x)
    ans = int(out.strip())
    assert ans >= 0

def test_k1_equals_dot_count(run, x):
    lines = x.strip().split('\n')
    n, m, k = map(int, lines[0].split())
    if k != 1:
        return
    dots = sum(row.count('.') for row in lines[1:])
    ans = int(run(x).strip())
    assert ans == dots

def test_trivial_bound(run, x):
    lines = x.strip().split('\n')
    n, m, k = map(int, lines[0].split())
    # each empty seat can be the first of a horizontal segment, each row gives max(m-k+1,0) per row
    max_h = n * max(m - k + 1, 0)
    max_v = m * max(n - k + 1, 0)
    upper = max_h + max_v
    ans = int(run(x).strip())
    assert ans <= upper

def test_zero_when_k_too_large(run, x):
    lines = x.strip().split('\n')
    n, m, k = map(int, lines[0].split())
    if k > max(n, m):
        ans = int(run(x).strip())
        assert ans == 0

def test_all_occupied_gives_zero(run, x):
    lines = x.strip().split('\n')
    n, m, k = map(int, lines[0].split())
    if all(c == '*' for row in lines[1:] for c in row):
        ans = int(run(x).strip())
        assert ans == 0

def test_answer_integer_format(run, x):
    out = run(x)
    stripped = out.strip()
    assert stripped == str(int(stripped))  # no extra spaces, newline allowed

def test_no_extra_output(run, x):
    out = run(x)
    lines = out.strip().split('\n')
    assert len(lines) == 1

def test_examples(run, x):
    # if the input matches one of the statement examples, check the answer matches the given output
    examples = {
        '2 3 2\n**.\n...\n': 3,
        '1 2 2\n..\n': 1,
        '3 3 4\n.*.\n*.*\n.*.\n': 0
    }
    if x in examples:
        ans = int(run(x).strip())
        assert ans == examples[x]

def test_brute_force_small(run, x):
    lines = x.strip().split('\n')
    n, m, k = map(int, lines[0].split())
    if n * m > 25:  # small enough for brute force
        return
    grid = lines[1:]
    expected = 0
    for i in range(n):
        for j in range(m - k + 1):
            if all(grid[i][j+t] == '.' for t in range(k)):
                expected += 1
    for i in range(n - k + 1):
        for j in range(m):
            if all(grid[i+t][j] == '.' for t in range(k)):
                expected += 1
    ans = int(run(x).strip())
    assert ans == expected

