tests_src:
def test_output_is_non_negative_integer(run, x):
    out = run(x).strip()
    assert out.isdigit() or (out[0] == '-' and out[1:].isdigit())
    val = int(out)
    assert val >= 0

def test_output_does_not_exceed_total_cost(run, x):
    k, n, w = map(int, x.split())
    total = k * w * (w + 1) // 2
    out = int(run(x).strip())
    assert out <= total

def test_output_is_zero_if_n_sufficient(run, x):
    k, n, w = map(int, x.split())
    total = k * w * (w + 1) // 2
    if n >= total:
        assert int(run(x).strip()) == 0

def test_output_equals_total_minus_n_when_n_insufficient(run, x):
    k, n, w = map(int, x.split())
    total = k * w * (w + 1) // 2
    if n < total:
        out = int(run(x).strip())
        assert out == total - n

def test_output_is_integer(run, x):
    out = run(x).strip()
    assert out.lstrip('-').isdigit()

def test_output_consistent_with_mod_k(run, x):
    k, n, w = map(int, x.split())
    total = k * w * (w + 1) // 2
    out = int(run(x).strip())
    if out == 0:
        assert n >= total
    else:
        assert (total - out) % k == n % k

def test_small_inputs_brute_force(run, x):
    k, n, w = map(int, x.split())
    if w <= 1000 and k <= 1000:
        total = 0
        for i in range(1, w + 1):
            total += i * k
        borrow = max(0, total - n)
        assert int(run(x).strip()) == borrow

def test_output_non_negative_for_all_inputs(run, x):
    out = int(run(x).strip())
    assert out >= 0

def test_output_bounds_by_specification(run, x):
    k, n, w = map(int, x.split())
    total = k * w * (w + 1) // 2
    out = int(run(x).strip())
    assert 0 <= out <= total

def test_output_changes_monotonically_with_n(run, x):
    k, n, w = map(int, x.split())
    out = int(run(x).strip())
    total = k * w * (w + 1) // 2
    if n == 0:
        assert out == total
    if n >= total:
        assert out == 0

