def test_answer_is_integer_in_range(run, x):
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    ans_str = run(x).strip()
    ans = int(ans_str)
    # Answer must be between 0 and n*m inclusive (all flats off to all flats on)
    assert 0 <= ans <= n * m

def test_all_windows_on_gives_all_flats(run, x):
    # If every window is '1', then every flat has at least one light on.
    # So answer must be n*m.
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    all_on = True
    for i in range(1, n+1):
        line = lines[i].replace(' ', '')
        if line != '1' * (2*m):
            all_on = False
            break
    if all_on:
        ans = int(run(x).strip())
        assert ans == n * m

def test_all_windows_off_gives_zero(run, x):
    # If every window is '0', then no flat has light on.
    # Answer must be 0.
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    all_off = True
    for i in range(1, n+1):
        line = lines[i].replace(' ', '')
        if line != '0' * (2*m):
            all_off = False
            break
    if all_off:
        ans = int(run(x).strip())
        assert ans == 0

def test_answer_non_negative(run, x):
    ans_str = run(x).strip()
    ans = int(ans_str)
    assert ans >= 0

def test_monotonicity_on_single_bit_flip(run, x):
    # If we take the input and change a single '0' to '1', the answer cannot decrease.
    # We'll compute the original answer, then for each position, if it's '0', flip it and recompute via brute-force (since input size is small).
    # This holds for any correct solution: adding a lit window can only turn a flat from off to on, never the opposite.
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    if n * m > 20:  # too big for brute-force; skip
        return
    # Helper to compute answer from a given list of floor strings.
    def compute(floors):
        total = 0
        for floor in floors:
            s = floor.replace(' ', '')
            for j in range(m):
                if s[2*j] == '1' or s[2*j+1] == '1':
                    total += 1
        return total
    original_floors = [lines[i].replace(' ', '') for i in range(1, n+1)]
    orig_ans = int(run(x).strip())
    # For each floor, each position
    for i in range(n):
        s = list(original_floors[i])
        for pos in range(2*m):
            if s[pos] == '0':
                s[pos] = '1'
                new_floors = original_floors.copy()
                new_floors[i] = ''.join(s)
                new_ans = compute(new_floors)
                # original answer must be <= new answer
                assert orig_ans <= new_ans, f'Monotonicity violated: orig {orig_ans}, new {new_ans}'
                s[pos] = '0'  # restore

