def test_positive_integer(run, x):
    ans = run(x).strip()
    assert ans.isdigit() and int(ans) > 0

def test_single_bucket_divisible(run, x):
    lines = x.strip().split('\n')
    n, k = map(int, lines[0].split())
    if n == 1:
        a = int(lines[1].strip())
        if k % a == 0:
            ans = int(run(x).strip())
            assert ans == k // a

def test_upper_bound_by_k(run, x):
    lines = x.strip().split('\n')
    k = int(lines[0].split()[1])
    ans = int(run(x).strip())
    assert ans <= k

def test_answer_not_exceed_any_divisor_hours(run, x):
    lines = x.strip().split('\n')
    n, k = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))
    ans = int(run(x).strip())
    for val in a:
        if k % val == 0:
            assert ans <= k // val

def test_lower_bound_one(run, x):
    ans = int(run(x).strip())
    assert ans >= 1

def test_k_equals_one_answer_one(run, x):
    lines = x.strip().split('\n')
    k = int(lines[0].split()[1])
    if k == 1:
        ans = int(run(x).strip())
        assert ans == 1

def test_all_buckets_same_divisible(run, x):
    lines = x.strip().split('\n')
    n, k = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))
    if all(val == a[0] for val in a) and k % a[0] == 0:
        ans = int(run(x).strip())
        assert ans == k // a[0]

def test_k_multiple_of_24_hours_not_6_if_bucket_allows_less(run, x):
    lines = x.strip().split('\n')
    n, k = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))
    ans = int(run(x).strip())
    if k % 24 == 0:
        # If any bucket gives hours < 6, answer must be <= that
        for val in a:
            if k % val == 0 and k // val < 6:
                assert ans <= k // val

def test_brute_force_small_inputs(run, x):
    lines = x.strip().split('\n')
    n, k = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))
    if n <= 5 and k <= 10:  # small enough to brute force
        correct = float('inf')
        for val in a:
            if k % val == 0:
                correct = min(correct, k // val)
        ans = int(run(x).strip())
        assert ans == correct

def test_answer_is_integer_division_of_k_by_some_bucket(run, x):
    lines = x.strip().split('\n')
    n, k = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))
    ans = int(run(x).strip())
    possible = False
    for val in a:
        if k % val == 0 and k // val == ans:
            possible = True
            break
    assert possible

def test_integer(run, x):
    output = run(x)
    try:
        int(output.strip())
    except ValueError:
        assert False, 'Output must be an integer'

def test_nonnegative(run, x):
    output = run(x)
    ans = int(output.strip())
    assert ans >= 0, 'Answer must be non-negative'

def test_upper_bound_trivial(run, x):
    N = int(x.strip())
    ans = int(run(x).strip())
    # trivial upper bound: each M_i <= i, sum <= N(N+1)/2
    assert ans <= N * (N + 1) // 2, 'Answer exceeds trivial upper bound'

def test_lower_bound_construction(run, x):
    N = int(x.strip())
    ans = int(run(x).strip())
    # lower bound from permutation (2,3,...,N,1)
    construction_sum = N * (N - 1) // 2
    assert ans >= construction_sum, 'Answer is less than construction lower bound'

def test_bruteforce_small(run, x):
    N = int(x.strip())
    if N > 10:
        return  # skip large N
    # brute force over all permutations
    import itertools
    best = -1
    for perm in itertools.permutations(range(1, N + 1)):
        total = 0
        for i, p in enumerate(perm, start=1):
            total += i % p
        if total > best:
            best = total
    ans = int(run(x).strip())
    assert ans == best, f'For N={N}, answer {ans} does not match brute-force maximum {best}'

def test_sample_n1(run, x):
    if x.strip() != '1':
        return
    ans = int(run(x).strip())
    assert ans == 0, 'For N=1, answer must be 0'

def test_sample_n2(run, x):
    if x.strip() != '2':
        return
    ans = int(run(x).strip())
    assert ans == 1, 'For N=2, answer must be 1'

def test_output_format(run, x):
    import re
    output = run(x)
    assert re.fullmatch(r'\d+\n', output), 'Output must be a positive integer followed by newline'

def test_no_leading_zeros(run, x):
    output = run(x)
    s = output.strip()
    assert not (len(s) > 1 and s[0] == '0'), 'Output integer must not have leading zeros'

def test_formula_match(run, x):
    N = int(x.strip())
    ans = int(run(x).strip())
    expected = N * (N - 1) // 2
    assert ans == expected, f'Answer {ans} does not equal expected {expected}'

