      "source": "def test_monotonicity_subsegment(run, x):
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    a = list(map(int, lines[1].split()))
    ans = int(run(x).strip())
    # for every k from 1 to ans, there must exist a non‑decreasing subsegment of length k
    n = len(a)
    for k in range(1, ans+1):
        found = False
        for i in range(n - k + 1):
            ok = all(a[j] <= a[j+1] for j in range(i, i+k-1))
