    # This is a property that holds for this problem: appending an element equal to the last does not decrease answer.
    # But we can't modify input and call run again.
    # Instead we can check a weaker property: if the array has a run of equal values, answer >= length of that run.
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    a = list(map(int, lines[1].split()))
    ans = int(run(x).strip())
    # find longest run of equal values
    best_run = 1
    cur = 1
    for i in range(1, len(a)):
        if a[i] == a[i-1]:
            cur += 1
            best_run = max(best_run, cur)
        else:
            cur = 1
    assert ans >= best_run"
    },
