        return
    a = list(map(int, lines[1].split()))
    ans = int(run(x).strip())
    # If there is at least one adjacent non‑decreasing pair, answer >=2.
    has_pair = any(a[i] <= a[i+1] for i in range(len(a)-1))
    if has_pair and len(a) >= 2:
        assert ans >= 2
    else:
        # all strict decreasing or length 1
        if len(a) == 1:
            assert ans == 1
        # else ans can be 1
        pass"
    }
  ]
}

