def test_non_negative_integer(run, x):
    out = run(x).strip()
    # Must be integer
    val = int(out)
    assert val >= 0

def test_modulo_range(run, x):
    out = run(x).strip()
    val = int(out)
    mod = 10**9 + 7
    assert 0 <= val < mod

def test_single_digit_zero(run, x):
    s = x.strip()
    if len(s) == 1:
        # For a single digit, the only non-empty substring is the whole string, result is 0
        assert run(x).strip() == '0'

def test_input_zero(run, x):
    if x.strip() == '0':
        # For input '0', the only possible removal is the whole string, result 0
        assert run(x).strip() == '0'

def test_bruteforce_small(run, x):
    s = x.strip()
    n = len(s)
    if n > 15:
        # Skip brute force for large inputs (but our inputs are up to length 15)
        return
    mod = 10**9 + 7
    total = 0
    # Enumerate all substrings to remove
    for i in range(n):
        for j in range(i, n):
            # remove substring s[i:j+1]
            remaining = s[:i] + s[j+1:]
            if remaining == '':
                val = 0
            else:
                val = int(remaining)  # leading zeros allowed
            total = (total + val) % mod
    assert int(run(x).strip()) == total

def test_all_digits_same_small(run, x):
    s = x.strip()
    if len(s) > 10:
        return
    if len(set(s)) != 1:
        return
    # All digits same digit d
    d = int(s[0])
    n = len(s)
    mod = 10**9 + 7
    # Compute sum manually by enumerating removals
    total = 0
    for i in range(n):
        for j in range(i, n):
            remaining_len = n - (j - i + 1)
            if remaining_len == 0:
                val = 0
            else:
                # remaining digits all d, so number is d * (111...1) with remaining_len digits
                ones = (10**remaining_len - 1) // 9
                val = d * ones
            total = (total + val) % mod
    assert int(run(x).strip()) == total

def test_sum_of_all_substring_removals_includes_zero(run, x):
    s = x.strip()
    # The removal of the whole string yields 0, so the sum must be at least 0
    # Actually the sum could be 0 only if all other removals also yield 0, which is unlikely.
    # But we can check that the answer is non-negative (already covered).
    # This test ensures that the answer is not negative.
    out = run(x).strip()
    val = int(out)
    assert val >= 0

def test_leading_zeros_allowed(run, x):
    # This test is to ensure that the answer respects leading zeros.
    # We can test on input '10' where removing '1' yields '0' (value 0) and removing '0' yields '1', removing '10' yields 0.
    # Sum = 0+1+0 = 1.
    if x.strip() == '10':
        assert run(x).strip() == '1'
    if x.strip() == '101':
        # brute force already covers
        pass

def test_compare_with_known_examples(run, x):
    known = {'107': '42', '100500100500': '428101984', '1': '0', '0': '0'}
    s = x.strip()
    if s in known:
        assert run(x).strip() == known[s]

def test_parity_small(run, x):
    s = x.strip()
    if len(s) > 7:
        return
    # Compute sum modulo 2 via brute force and compare
    mod = 10**9 + 7
    total_mod2 = 0
    for i in range(len(s)):
        for j in range(i, len(s)):
            remaining = s[:i] + s[j+1:]
            if remaining == '':
                val = 0
            else:
                val = int(remaining)
            total_mod2 = (total_mod2 + val) % 2
    ans = int(run(x).strip())
    assert ans % 2 == total_mod2

