def test_exact_small(run, x):
    # Only run on small inputs where we can compute the exact answer by brute force.
    lines = x.strip().split('\n')
    n = int(lines[0])
    if n > 20:
        return  # too big, skip
    # Build graph
    projects = {}
    i = 1
    for _ in range(n):
        name, ver = lines[i].split(); i+=1
        cnt = int(lines[i]); i+=1
        deps = []
        for __ in range(cnt):
            dep_name, dep_ver = lines[i].split(); i+=1
            deps.append((dep_name, dep_ver))
        projects[(name, ver)] = deps
        if i < len(lines) and lines[i] == '':
            i+=1
    root = list(projects.keys())[0]
    # BFS to compute distances
    from collections import deque
    dist = {root: 0}
    q = deque([root])
    while q:
        cur = q.popleft()
        for dep in projects.get(cur, []):
            if dep not in dist:
                dist[dep] = dist[cur] + 1
                q.append(dep)
    # For each name, choose version with minimal distance, tie‑break larger version
    best = {}
    for (name, ver), d in dist.items():
        v = int(ver)
        if name not in best:
            best[name] = (d, v, ver)
        else:
            d0, v0, ver0 = best[name]
            if d < d0 or (d == d0 and v > v0):
                best[name] = (d, v, ver)
    # Remove root
    root_name = root[0]
    if root_name in best:
        del best[root_name]
    # Compute expected output lines
    expected = []
    for name in sorted(best.keys()):
        d, v, ver = best[name]
        expected.append(f'{name} {ver}')
    out_lines = run(x).strip().split('\n')
    if len(out_lines) == 1 and out_lines[0] == '':
        out_lines = []
    if len(out_lines) > 0:
        out_k = int(out_lines[0])
        out_projs = out_lines[1:]
    else:
        out_k = 0
        out_projs = []
    if out_k != len(expected):
        assert False, f'count mismatch: expected {len(expected)} got {out_k}'
    for a, b in zip(sorted(out_projs), sorted(expected)):
        if a != b:
            assert False, f'project mismatch: expected {b} got {a}'
    if sorted(out_projs) != sorted(expected):
        assert False, 'project set mismatch'

