tests_src:
def test_output_format(run, x):
    out = run(x).strip()
    assert out in {"YES", "NO"}

def test_output_length(run, x):
    out = run(x)
    assert len(out) <= 4  # YES\n or NO\n

def test_first_last_dot(run, x):
    lines = x.strip().split('\n')
    nk = lines[0].split()
    n = int(nk[0])
    s = lines[1]
    if len(s) != n:
        s = s[:n]  # adjust if input malformed
    if s[0] == '#' or s[-1] == '#':
        assert run(x).strip() == 'NO'

def test_all_dots(run, x):
    lines = x.strip().split('\n')
    s = lines[1]
    if '#' not in s:
        assert run(x).strip() == 'YES'

def test_all_rocks_except_ends(run, x):
    lines = x.strip().split('\n')
    nk = lines[0].split()
    n = int(nk[0])
    s = lines[1]
    if len(s) != n:
        s = s[:n]
    if s[0]=='.' and s[-1]=='.' and all(ch=='#' for ch in s[1:-1]):
        assert run(x).strip() == 'NO'

def test_jump_over_single_rock(run, x):
    lines = x.strip().split('\n')
    nk = lines[0].split()
    n = int(nk[0]); k = int(nk[1])
    s = lines[1]
    if len(s) != n:
        s = s[:n]
    if n >= 3 and s[1]=='#' and all(ch=='.' for ch in s[2:]) and k >= 2:
        assert run(x).strip() == 'YES'

def test_immediate_block(run, x):
    lines = x.strip().split('\n')
    nk = lines[0].split()
    n = int(nk[0]); k = int(nk[1])
    s = lines[1]
    if len(s) != n:
        s = s[:n]
    if n >= 2 and s[1]=='#' and k == 1:
        assert run(x).strip() == 'NO'

def test_k_eq_1_and_no_adjacent_rocks(run, x):
    lines = x.strip().split('\n')
    nk = lines[0].split()
    n = int(nk[0]); k = int(nk[1])
    s = lines[1]
    if len(s) != n:
        s = s[:n]
    if k == 1 and '##' not in s:
        assert run(x).strip() == 'YES'

def test_k_large_enough_to_skip_all(run, x):
    lines = x.strip().split('\n')
    nk = lines[0].split()
    n = int(nk[0]); k = int(nk[1])
    if k >= n-1:
        assert run(x).strip() == 'YES'

def test_known_examples(run, x):
    examples = [
        ("2 1\n..\n", "YES"),
        ("5 2\n.#.#.\n", "YES"),
        ("7 3\n.#.###.\n", "NO")
    ]
    for inp, exp in examples:
        if x == inp:
            assert run(x).strip() == exp
            return
    # if not one of the examples, pass
    pass

