def test_small_bruteforce_1(run, x):
    lines = x.strip().split('\n')
    n_k = list(map(int, lines[0].split()))
    n, k = n_k[0], n_k[1]
    if n > 10:
        return
    a = list(map(int, lines[1].split()))
    b = []
    if k > 0:
        b = list(map(int, lines[2].split()))
    fixed = set(b)
    # brute force over all possible changes to non‑fixed positions
    from itertools import product
    INF = 10**9 + 5
    best = INF
    # we can only assign integers, but bound search: we can try values in range [1, INF]
    # For small n we can try a limited set: original values and maybe +-n
    candidates = set(a)
    for v in a:
        for d in range(-n, n+1):
            if 1 <= v+d <= INF:
                candidates.add(v+d)
    # Also include 1 and INF
    candidates.add(1)
    candidates.add(INF)
    # limit size
    if len(candidates) > 100:
        return  # give up
    for changes in product(candidates, repeat=len([i for i in range(n) if i+1 not in fixed])):
        arr = a[:]
        idx = 0
        for i in range(n):
            if i+1 not in fixed:
                arr[i] = changes[idx]
                idx += 1
        if all(arr[i] < arr[i+1] for i in range(n-1)):
            ops = sum(1 for i in range(n) if i+1 not in fixed and arr[i] != a[i])
            if ops < best:
                best = ops
    out = run(x).strip()
    if best == INF:
        assert out == '-1', f'Brute says impossible but got {out}'
    else:
        assert out != '-1', f'Brute says possible with {best} ops but got -1'
        val = int(out)
        assert val == best, f'Brute says {best}, got {val}'

