def test_output_format(run, x):
    output = run(x).strip()
    lines = output.split('\n')
    t = int(x.strip().split('\n')[0])
    assert len(lines) == t, f'Expected {t} lines, got {len(lines)}'
    for line in lines:
        line = line.strip()
        assert line != '', 'Empty line'
        # Must be an integer, possibly negative
        if line[0] == '-':
            assert line[1:].isdigit(), f'Invalid integer: {line}'
        else:
            assert line.isdigit(), f'Invalid integer: {line}'


def test_brute_force_small(run, x):
    lines = x.strip().split('\n')
    t = int(lines[0])
    for i in range(1, t+1):
        n = int(lines[i])
        if n <= 20:  # small enough to brute-force
            total = 0
            for k in range(1, n+1):
                if (k & (k-1)) == 0:  # k is power of two
                    total -= k
                else:
                    total += k
            got = int(run(x).strip().split('\n')[i-1])
            assert got == total, f'n={n}: expected {total}, got {got}'


def test_parity(run, x):
    lines = x.strip().split('\n')
    t = int(lines[0])
    outputs = run(x).strip().split('\n')
    for i in range(t):
        n = int(lines[i+1])
        ans = int(outputs[i])
        # Compute parity of the sum modulo 2
        # The sum S = sum_{k=1}^n k - 2 * sum_{powers of two ≤ n} k
        # Let P = sum of powers of two ≤ n
        # Then S = n(n+1)//2 - 2*P
        # So S mod 2 = (n(n+1)//2) mod 2, because 2*P is even.
        parity_expected = (n*(n+1)//2) % 2
        parity_got = ans % 2
        if parity_got < 0:
            parity_got = (-parity_got) % 2  # ensure non-negative modulo
        assert parity_got == parity_expected, f'n={n}: parity mismatch'


def test_monotonicity_power_of_two(run, x):
    # If input has exactly one n and n is a power of two, then answer for n should be less than answer for n-1
    # because we subtract n instead of adding it.
    lines = x.strip().split('\n')
    t = int(lines[0])
    if t != 1:
        return  # skip for multiple queries
    n = int(lines[1])
    if n > 1 and (n & (n-1)) == 0:  # n is a power of two
        # compute answer for n-1 using brute force (small only)
        if n-1 <= 30:
            total_n_minus_1 = 0
            for k in range(1, n):
                if (k & (k-1)) == 0:
                    total_n_minus_1 -= k
                else:
                    total_n_minus_1 += k
            ans_n = int(run(x).strip())
            assert ans_n < total_n_minus_1, f'For power of two n={n}, answer should be less than for n-1'


def test_bound_magnitude(run, x):
    lines = x.strip().split('\n')
    t = int(lines[0])
    outputs = run(x).strip().split('\n')
    for i in range(t):
        n = int(lines[i+1])
        ans = int(outputs[i])
        max_possible = n*(n+1)//2  # all positive
        min_possible = -max_possible  # all negative
        assert min_possible <= ans <= max_possible, f'n={n}: answer {ans} out of bounds'


def test_sign_for_small_n(run, x):
    lines = x.strip().split('\n')
    t = int(lines[0])
    outputs = run(x).strip().split('\n')
    for i in range(t):
        n = int(lines[i+1])
        ans = int(outputs[i])
        if n == 1:
            assert ans == -1, f'n=1 must give -1'
        elif n == 2:
            # -1 -2 = -3
            assert ans == -3, f'n=2 must give -3'
        elif n == 3:
            # -1 -2 +3 = 0
            assert ans == 0, f'n=3 must give 0'
        elif n == 4:
            # -4 (given in statement)
            assert ans == -4, f'n=4 must give -4'


def test_consistency_with_statement_example(run, x):
    # If the input exactly matches the statement example, check the output matches.
    if x == '2\n4\n1000000000\n':
        output = run(x).strip()
        expected = '-4\n499999998352516354'
        assert output == expected, f'Statement example mismatch'


def test_no_extra_output(run, x):
    output = run(x)
    lines = output.strip().split('\n')
    t = int(x.strip().split('\n')[0])
    assert len(lines) == t, f'Expected exactly {t} output lines'
    # also ensure no extra whitespace at end of lines
    for line in lines:
        assert line.strip() == line, f'Extra whitespace in line: "{line}"'


def test_answer_is_integer(run, x):
    output = run(x).strip()
    for line in output.split('\n'):
        try:
            int(line)
        except ValueError:
            assert False, f'Not an integer: {line}'


def test_negative_for_power_of_two(run, x):
    lines = x.strip().split('\n')
    t = int(lines[0])
    outputs = run(x).strip().split('\n')
    for i in range(t):
        n = int(lines[i+1])
        ans = int(outputs[i])
        # For n that is a power of two and n>=2, the answer should be negative
        # because we subtract that large power and previous terms may not compensate.
        # Verified by brute force for small n.
        if n >= 2 and (n & (n-1)) == 0 and n <= 30:
            total = 0
            for k in range(1, n+1):
                if (k & (k-1)) == 0:
                    total -= k
                else:
                    total += k
            assert ans == total, f'n={n} (power of two) brute-force mismatch'
            # Also check it's negative (holds for n=2,4,8,16,32)
            if n >= 2:
                assert ans < 0, f'n={n} (power of two) should be negative'

