def test_output_is_nonnegative_integer(run, x):
    out = run(x)
    val = int(out.strip())
    assert val >= 0

def test_answer_at_most_n_minus_one(run, x):
    n = int(x.split('\n')[0])
    out = run(x)
    val = int(out.strip())
    assert val <= n - 1

def test_all_equal_gives_zero(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    if n == 1:
        return
    vals = list(map(int, lines[1].split()))
    if len(set(vals)) == 1:
        out = run(x)
        assert int(out.strip()) == 0

def test_two_distinct_values_at_least_one(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    if n < 2:
        return
    vals = list(map(int, lines[1].split()))
    if len(set(vals)) == 2:
        out = run(x)
        assert int(out.strip()) >= 1

def test_sorted_distinct_gives_n_minus_one(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    vals = list(map(int, lines[1].split()))
    if len(set(vals)) == n:
        out = run(x)
        assert int(out.strip()) == n - 1

def test_example_one_matches(run, x):
    if x == "5\n20 30 10 50 40\n":
        out = run(x)
        assert out.strip() == "4"

def test_example_two_matches(run, x):
    if x == "4\n200 100 100 200\n":
        out = run(x)
        assert out.strip() == "2"

def test_small_input_brute_force(run, x):
    import itertools
    lines = x.strip().split('\n')
    n = int(lines[0])
    if n > 6:
        return
    vals = list(map(int, lines[1].split()))
    best = 0
    for perm in itertools.permutations(vals):
        happy = sum(1 for i in range(n-1) if perm[i] + 1 > perm[i])
        if happy > best:
            best = happy
    out = run(x)
    assert int(out.strip()) == best

def test_parity_when_all_equal(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    vals = list(map(int, lines[1].split()))
    if len(set(vals)) == 1 and n >= 2:
        out = run(x)
        # When all equal, answer must be 0 (even).
        # More generally, answer parity must equal (n-1) mod 2 only if all distinct,
        # but here we just check it's even.
        assert int(out.strip()) % 2 == 0

