def test_answer_le_number_of_distinct_passwords(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    passwords = lines[1:1+n]
    distinct = len(set(passwords))
    ans = int(run(x).strip())
    assert ans <= distinct

def test_answer_ge_number_of_letter_components(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    passwords = lines[1:1+n]
    # Build graph of 26 letters, union letters within each password
    parent = list(range(26))
    def find(u):
        while parent[u] != u:
            parent[u] = parent[parent[u]]
            u = parent[u]
        return u
    def union(u, v):
        ru, rv = find(u), find(v)
        if ru != rv:
            parent[rv] = ru
    for p in passwords:
        chars = [ord(c)-97 for c in p]
        for c in chars[1:]:
            union(chars[0], c)
    roots = set()
    letters_used = set()
    for p in passwords:
        for ch in p:
            letters_used.add(ord(ch)-97)
    for l in letters_used:
        roots.add(find(l))
    components = len(roots)
    ans = int(run(x).strip())
    # The minimal number must be at least the number of components
    # because passwords from different components cannot be equivalent
    assert ans >= components

def test_single_password_always_1(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    if n == 1:
        ans = int(run(x).strip())
        assert ans == 1

def test_answer_at_least_1(run, x):
