tests_src:
def test_ends_with_it(run, x):
    output = run(x).strip()
    assert output.endswith('it'), "Output must end with 'it'"

def test_starts_with_I_hate(run, x):
    output = run(x).strip()
    assert output.startswith('I hate'), "Output must start with 'I hate'"

def test_alternating_pattern(run, x):
    output = run(x).strip()
    words = output.split()
    # emotion words are at positions 1, 4, 7, ... until before 'it'
    emotions = []
    for i in range(len(words)):
        if words[i] in ('hate', 'love'):
            emotions.append(words[i])
    # emotions should alternate starting with hate
    for idx, em in enumerate(emotions):
        if idx % 2 == 0:
            assert em == 'hate', f"Emotion at index {idx} must be 'hate', got '{em}'"
        else:
            assert em == 'love', f"Emotion at index {idx} must be 'love', got '{em}'"

def test_correct_number_of_that(run, x):
    n = int(x.strip())
    output = run(x).strip()
    that_count = output.count('that')
    if n == 1:
        assert that_count == 0, f"For n=1 there should be 0 'that', got {that_count}"
    else:
        assert that_count == n - 1, f"For n={n} there should be {n-1} 'that', got {that_count}"

def test_only_allowed_words(run, x):
    allowed = {'I', 'hate', 'love', 'that', 'it'}
    output = run(x).strip()
    words = set(output.split())
    for w in words:
        assert w in allowed, f"Word '{w}' not allowed in output"

def test_length_grows(run, x):
    n = int(x.strip())
    output = run(x).strip()
    # minimal length for n=1 is "I hate it" (8 chars)
    # each extra layer adds " that I love" (12) or " that I hate" (12) 
    # but we just ensure it's not empty and length roughly increases with n
    # This is a weak sanity check
    if n == 1:
        assert len(output) >= 8, "Output too short for n=1"
    else:
        assert len(output) >= 8 + (n-1)*12 - 3, f"Output seems too short for n={n}"

def test_exact_n1(run, x):
    n = int(x.strip())
    if n == 1:
        output = run(x).strip()
        assert output == 'I hate it', f"For n=1 output must be 'I hate it', got '{output}'"

def test_final_emotion_even_n(run, x):
    n = int(x.strip())
    if n % 2 == 0:
        output = run(x).strip()
        assert output.endswith('love it'), f"For even n final must be 'love it', got '{output}'"

def test_final_emotion_odd_n(run, x):
    n = int(x.strip())
    if n % 2 == 1 and n > 1:
        output = run(x).strip()
        assert output.endswith('hate it'), f"For odd n>1 final must be 'hate it', got '{output}'"

def test_regex_pattern(run, x):
    import re
    output = run(x).strip()
    # pattern: I hate (that I love that I hate ... ) it
    # We'll build a regex that matches exactly the allowed pattern
    n = int(x.strip())
    # Construct pattern programmatically
    parts = []
    for i in range(1, n+1):
        if i % 2 == 1:
            parts.append('I hate')
        else:
            parts.append('I love')
    # join with ' that ' between all but last
    expected_pattern = ' that '.join(parts) + ' it'
    assert output == expected_pattern, f"Output does not match expected pattern"

def test_non_negative(run, x):
    out = run(x)
    val = float(out.strip())
    assert val >= -1e-12, f'Output {val} is negative'

def test_at_most_total_substrings(run, x):
    s = x.strip()
    n = len(s)
    total_substrings = n * (n + 1) // 2
    out = run(x)
    val = float(out.strip())
    assert val <= total_substrings + 1e-9, f'Output {val} exceeds total substrings {total_substrings}'

def test_length_one(run, x):
    s = x.strip()
    if len(s) == 1:
        vowels = {'I', 'E', 'A', 'O', 'U', 'Y'}
        expected = 1.0 if s[0] in vowels else 0.0
        out = run(x)
        val = float(out.strip())
        assert abs(val - expected) <= 1e-9, f'Length 1: expected {expected}, got {val}'

def test_all_vowels(run, x):
    s = x.strip()
    vowels = {'I', 'E', 'A', 'O', 'U', 'Y'}
    if all(ch in vowels for ch in s):
        n = len(s)
        expected = n * (n + 1) / 2
        out = run(x)
        val = float(out.strip())
        assert abs(val - expected) <= 1e-9, f'All vowels: expected {expected}, got {val}'

def test_all_consonants(run, x):
    s = x.strip()
    vowels = {'I', 'E', 'A', 'O', 'U', 'Y'}
    if all(ch not in vowels for ch in s):
        expected = 0.0
        out = run(x)
        val = float(out.strip())
        assert abs(val - expected) <= 1e-9, f'All consonants: expected 0, got {val}'

def test_small_bruteforce(run, x):
    s = x.strip()
    if len(s) <= 10:
        vowels = {'I', 'E', 'A', 'O', 'U', 'Y'}
        n = len(s)
        total = 0.0
        for i in range(n):
            for j in range(i, n):
                cnt = sum(1 for k in range(i, j+1) if s[k] in vowels)
                total += cnt / (j - i + 1)
        out = run(x)
        val = float(out.strip())
        assert abs(val - total) <= 1e-9, f'Brute force mismatch: expected {total}, got {val}'

def test_examples(run, x):
    s = x.strip()
    if s == 'IEAIAIO':
        expected = 28.0
        out = run(x)
        val = float(out.strip())
        assert abs(val - expected) <= 1e-6, f'Example 1 mismatch'
    elif s == 'BYOB':
        expected = 5.8333333
        out = run(x)
        val = float(out.strip())
        assert abs(val - expected) <= 1e-6, f'Example 2 mismatch'
    elif s == 'YISVOWEL':
        expected = 17.05
