def test_symmetry(run, x):
    s = x.strip()
    rev = s[::-1]
    # The prettiness of s and rev must be equal because the set of substrings is symmetric.
    # We cannot call run twice, so we cannot directly compare. Instead we check a property:
    # For every substring s[i..j], there is a substring rev[(n-1-j)..(n-1-i)] with same length and vowel count.
    # Thus the prettiness is identical. Since we cannot compute rev's answer, we use a small-size check.
    # For small strings we can compute both and compare.
    if len(s) <= 10:
        vowels = {'I', 'E', 'A', 'O', 'U', 'Y'}
        def compute(s):
            n = len(s)
            total = 0.0
            for i in range(n):
                for j in range(i, n):
                    cnt = sum(1 for k in range(i, j+1) if s[k] in vowels)
                    total += cnt / (j - i + 1)
            return total
        val_s = compute(s)
        val_rev = compute(rev)
        assert abs(val_s - val_rev) <= 1e-9, f'Symmetry broken for small string'

def test_medium_bruteforce(run, x):
    s = x.strip()
    if len(s) <= 100:
        vowels = {'I', 'E', 'A', 'O', 'U', 'Y'}
        n = len(s)
        total = 0.0
        for i in range(n):
            vowel_cnt = 0
            for j in range(i, n):
                if s[j] in vowels:
                    vowel_cnt += 1
                total += vowel_cnt / (j - i + 1)
        out = run(x)
        val = float(out.strip())
        assert abs(val - total) <= 1e-9, f'Medium brute force mismatch: expected {total}, got {val}'

