def test_odd_small_pattern(run, x):
    n = int(x.strip())
    if n <= 0 or n > 20:
        return
    # We compute the correct answer by brute-force as in test_brute_force_small_n but only for odd n.
    # Reuse the same brute-force logic but only for n <=5 to keep safe.
    if n > 5:
        return
    total_cells = n * n
    full_mask = (1 << total_cells) - 1
    from functools import lru_cache
    def neighbor_mask(idx):
        i, j = divmod(idx, n)
        forbidden = []
        if i > 0: forbidden.append(idx - n)
        if i < n-1: forbidden.append(idx + n)
        if j > 0: forbidden.append(idx - 1)
        if j < n-1: forbidden.append(idx + 1)
        res = 1 << idx
        for nb in forbidden:
            res |= 1 << nb
        return res
    @lru_cache(None)
    def win(mask):
        if mask == 0:
            return False
        idx = 0
        m = mask
        while m:
            if m & 1:
                taken = neighbor_mask(idx)
                new_mask = mask & ~taken
                if not win(new_mask):
                    return True
            idx += 1
            m >>= 1
        return False
    first_can_win = win(full_mask)
    expected = 1 if first_can_win else 2
    out = int(run(x).strip())
    assert out == expected, f'For odd n={n}, expected {expected}, got {out}'

