tests_src:
def test_exact_output_format(run, x):
    out = run(x)
    assert out in ('Happy Alex\n', 'Poor Alex\n'), f'Output must be exactly \"Happy Alex\\n\" or \"Poor Alex\\n\", got {repr(out)}'

def test_newline_present(run, x):
    out = run(x)
    assert out.endswith('\n'), 'Output must end with newline'

def test_no_extra_output(run, x):
    out = run(x)
    lines = out.split('\n')
    # Allow empty line after newline
    assert len([l for l in lines if l.strip() != '']) == 1, 'Output must be exactly one line'

def test_brute_force_small(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    if n > 10:
        return  # skip, too large for brute force in test
    pairs = []
    for i in range(1, n+1):
        a, b = map(int, lines[i].split())
        pairs.append((a, b))
    happy = False
    for i in range(n):
        for j in range(n):
            if i == j:
                continue
            if pairs[i][0] < pairs[j][0] and pairs[i][1] > pairs[j][1]:
                happy = True
                break
        if happy:
            break
    expected = 'Happy Alex\n' if happy else 'Poor Alex\n'
    assert run(x) == expected, f'Brute force says {expected.strip()} but got {run(x).strip()}'

def test_output_parsable(run, x):
    out = run(x).strip()
    assert out == 'Happy Alex' or out == 'Poor Alex', f'Output must be \"Happy Alex\" or \"Poor Alex\" without extra spaces'

def test_no_whitespace_before(run, x):
    out = run(x)
    assert out == out.lstrip(), 'Output must not start with whitespace'

def test_length_constraint(run, x):
    out = run(x).strip()
    assert len(out) == len('Happy Alex') or len(out) == len('Poor Alex'), 'Output length mismatch'

def test_case_sensitive(run, x):
    out = run(x).strip()
    assert out == 'Happy Alex' or out == 'Poor Alex', 'Output must match exact case'

def test_no_extra_chars(run, x):
    out = run(x).strip()
    import re
    assert re.fullmatch(r'(Happy Alex|Poor Alex)', out), 'Output contains extra characters'

def test_check_poor_if_sorted_qualities(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    pairs = []
    for i in range(1, n+1):
        a, b = map(int, lines[i].split())
        pairs.append((a, b))
    # sort by price
    pairs.sort()
    # check if qualities are also strictly increasing
    strictly_increasing = all(pairs[i][1] < pairs[i+1][1] for i in range(n-1))
    if strictly_increasing:
        # then Alex is wrong, answer must be Poor Alex
        assert run(x) == 'Poor Alex\n', f'When prices sorted and qualities strictly increasing, answer must be Poor Alex, got {run(x).strip()}'

