def test_output_line_count(run, x):
    lines = run(x).strip().split('\n')
    # Should have exactly k lines
    n_k = x.strip().split('\n')[0].split()
    if len(n_k) < 2:
        return
    k = int(n_k[1])
    assert len(lines) == k, f'Expected {k} lines, got {len(lines)}'

def test_each_line_integer(run, x):
    lines = run(x).strip().split('\n')
    for line in lines:
        try:
            int(line)
        except ValueError:
            assert False, f'Non-integer line: {line}'

def test_non_negative(run, x):
    lines = run(x).strip().split('\n')
    for line in lines:
        val = int(line)
        assert val >= 0, f'Negative value: {val}'

def test_bounded_by_max(run, x):
    lines = run(x).strip().split('\n')
    # parse array
    parts = x.strip().split('\n')
    if len(parts) < 2:
        return
    arr = list(map(int, parts[1].split()))
    if not arr:
        return
    max_a = max(arr)
    for line in lines:
        val = int(line)
        assert val <= max_a, f'Value {val} exceeds max element {max_a}'

def test_first_is_min(run, x):
    lines = run(x).strip().split('\n')
    if not lines:
        return
    parts = x.strip().split('\n')
    if len(parts) < 2:
        return
    arr = list(map(int, parts[1].split()))
    min_a = min(arr)
    first = int(lines[0])
    assert first == min_a, f'First printed {first} but min element is {min_a}'

def test_non_decreasing(run, x):
    lines = run(x).strip().split('\n')
    prev = -1
    for line in lines:
        val = int(line)
        assert val >= prev, f'Sequence decreased: {prev} -> {val}'
        prev = val

def test_zero_tail(run, x):
    lines = run(x).strip().split('\n')
    seen_zero = False
    for line in lines:
        val = int(line)
        if seen_zero:
            assert val == 0, f'Non-zero after zero: {val}'
        if val == 0:
            seen_zero = True

def test_distinct_positive_count(run, x):
    lines = run(x).strip().split('\n')
    printed_positives = {int(line) for line in lines if int(line) > 0}
    parts = x.strip().split('\n')
    if len(parts) < 2:
        return
    arr = list(map(int, parts[1].split()))
    original_positives = {v for v in arr if v > 0}
    assert len(printed_positives) <= len(original_positives), f'Too many distinct positive printed values'

def test_printed_value_in_original_plus_cumulative(run, x):
    lines = run(x).strip().split('\n')
    parts = x.strip().split('\n')
    if len(parts) < 2:
        return
    arr = list(map(int, parts[1].split()))
    original_set = set(arr)
    cumulative = 0
    for line in lines:
        val = int(line)
        if val > 0:
            if (cumulative + val) not in original_set:
                assert False, f'Printed {val} but {cumulative + val} not in original array'
        cumulative += val

def test_brute_force_small(run, x):
    parts = x.strip().split('\n')
    if len(parts) < 2:
        return
    nk = list(map(int, parts[0].split()))
    if len(nk) < 2:
        return
    n, k = nk[0], nk[1]
    if n > 20 or k > 20:
        # Skip large inputs
        return
    arr = list(map(int, parts[1].split()))
    # simulate
    out = []
    cur = 0
    a = arr.copy()
    for _ in range(k):
        # find min non-zero
        mn = None
        for v in a:
            if v > 0:
                if mn is None or v < mn:
                    mn = v
        if mn is None:
            out.append(0)
        else:
            out.append(mn)
            # subtract mn from all positive
            for i in range(n):
                if a[i] > 0:
                    a[i] -= mn
    expected = '\n'.join(map(str, out)) + ('\n' if out else '')
    got = run(x)
    assert got == expected, f'Brute-force mismatch'

