def test_output_is_integer(run, x):
    out = run(x).strip()
    # The output must be a single integer
    int(out)  # raises ValueError if not parseable as int

def test_output_is_possible_joy_value(run, x):
    lines = x.strip().split('\n')
    n, k = map(int, lines[0].split())
    joys = []
    for i in range(1, n+1):
        f, t = map(int, lines[i].split())
        if t <= k:
            joy = f
        else:
            joy = f - (t - k)
        joys.append(joy)
    ans = int(run(x).strip())
    # The output must be one of the possible joy values (since they choose exactly one restaurant)
    assert ans in joys, f"Output {ans} not among possible joys {joys}"

def test_output_ge_max_f_when_all_t_le_k(run, x):
