def test_output_nonnegative(run, x):
    out = run(x).strip()
    lines = out.split('\n')
    for val in lines:
        if val:
            assert int(val) >= 0

def test_output_upper_bound(run, x):
    out = run(x).strip()
    if not out:
        return
    # Max possible XOR with numbers up to 10^9 < 2^30
    max_possible = (1 << 30) - 1
    for val in out.split('\n'):
        if val:
            assert int(val) <= max_possible

def test_answer_geq_xor_with_zero(run, x):
    # 0 is always present, so answer ≥ x ⊕ 0 = x
    lines = x.strip().split('\n')[1:]
    queries = [(op, int(arg)) for op, arg in (line.split() for line in lines)]
    out_lines = run(x).strip().split('\n')
    out_idx = 0
    for op, arg in queries:
        if op == '?':
            ans = int(out_lines[out_idx])
            assert ans >= arg  # because y = 0 is always available
            out_idx += 1

def test_answer_exists_in_set(run, x):
    # The answer must be of the form x ⊕ y for some y currently in the multiset.
    # We can reconstruct the multiset counts by simulating + and -
    lines = x.strip().split('\n')[1:]
    queries = [(op, int(arg)) for op, arg in (line.split() for line in lines)]
    from collections import defaultdict
    cnt = defaultdict(int)
    cnt[0] = 1
    out_lines = run(x).strip().split('\n')
    out_idx = 0
    for op, arg in queries:
        if op == '+':
            cnt[arg] += 1
        elif op == '-':
            cnt[arg] -= 1
            if cnt[arg] == 0:
                del cnt[arg]
        else:
            ans = int(out_lines[out_idx])
            # Check that there exists y in cnt such that (x ⊕ y) == ans
            found = False
            for y in cnt:
                if (arg ^ y) == ans:
                    found = True
                    break
            assert found
            out_idx += 1

def test_answer_not_exceed_possible_max(run, x):
    # For each query, the answer cannot exceed the maximum XOR achievable with any number in the current multiset.
    # Since we cannot compute that without the set, we at least ensure it's ≤ (max possible given bits)
    # and ≥ x (from zero). Additional sanity: if the set contains only 0, answer must be x.
    lines = x.strip().split('\n')[1:]
    queries = [(op, int(arg)) for op, arg in (line.split() for line in lines)]
    from collections import defaultdict
    cnt = defaultdict(int)
    cnt[0] = 1
    out_lines = run(x).strip().split('\n')
    out_idx = 0
    for op, arg in queries:
        if op == '+':
            cnt[arg] += 1
        elif op == '-':
            cnt[arg] -= 1
            if cnt[arg] == 0:
                del cnt[arg]
        else:
            ans = int(out_lines[out_idx])
            # compute actual max by brute over current set (size bounded by q ≤ 200k, but our test inputs are tiny)
            max_possible = max(arg ^ y for y in cnt)
            assert ans == max_possible
            out_idx += 1

def test_zero_always_present(run, x):
    # Since 0 is always present, the answer for any '?' query must be at least x.
    lines = x.strip().split('\n')[1:]
    queries = [(op, int(arg)) for op, arg in (line.split() for line in lines)]
    out_lines = run(x).strip().split('\n')
    out_idx = 0
    for op, arg in queries:
        if op == '?':
            ans = int(out_lines[out_idx])
            assert ans >= arg
            out_idx += 1

def test_answer_parses_as_integers(run, x):
    out = run(x).strip()
    lines = out.split('\n')
    # count '?' queries in input
    q_lines = x.strip().split('\n')[1:]
    q_count = sum(1 for line in q_lines if line.startswith('?'))
    assert len([l for l in lines if l]) == q_count
    for line in lines:
        if line:
            int(line)  # must not raise

def test_no_extra_output(run, x):
    out = run(x).strip()
    lines = [l for l in out.split('\n') if l]
    q_lines = x.strip().split('\n')[1:]
    q_count = sum(1 for line in q_lines if line.startswith('?'))
    assert len(lines) == q_count

def test_small_input_bruteforce(run, x):
    # If total queries ≤ 10, we can brute‑force the whole process and compare all answers.
    lines = x.strip().split('\n')
    q = int(lines[0])
    if q > 10:
        return  # skip large inputs
    queries = [(op, int(arg)) for op, arg in (line.split() for line in lines[1:])]
    from collections import defaultdict
    cnt = defaultdict(int)
    cnt[0] = 1
    expected = []
    for op, arg in queries:
        if op == '+':
            cnt[arg] += 1
        elif op == '-':
            cnt[arg] -= 1
            if cnt[arg] == 0:
                del cnt[arg]
        else:
            max_xor = max(arg ^ y for y in cnt)
            expected.append(str(max_xor))
    out = run(x).strip()
    if out:
        got = out.split('\n')
    else:
        got = []
    assert got == expected

def test_monotonic_on_deletion(run, x):
    # When we delete an element, the maximum XOR for a given x cannot increase.
    # We track the set via simulation and check each '?' answer against the previous answer for the same x after deletions.
    lines = x.strip().split('\n')[1:]
    queries = [(op, int(arg)) for op, arg in (line.split() for line in lines)]
    from collections import defaultdict
    cnt = defaultdict(int)
    cnt[0] = 1
    out_lines = run(x).strip().split('\n')
    out_idx = 0
    prev_ans = {}
    for op, arg in queries:
        if op == '+':
            cnt[arg] += 1
        elif op == '-':
            cnt[arg] -= 1
            if cnt[arg] == 0:
                del cnt[arg]
        else:
            ans = int(out_lines[out_idx])
            # compute current max by brute (input small)
            cur_max = max(arg ^ y for y in cnt)
            assert ans == cur_max
            out_idx += 1

