def test_output_is_integer(run, x):
    out = run(x).strip()
    # Must be a single integer
    assert out.lstrip('-').isdigit(), f'Output "{out}" is not an integer'

def test_non_negative(run, x):
    out = run(x).strip()
    ans = int(out)
    # Excessive shocks cannot be negative
    assert ans >= 0, f'Excessive shocks {ans} is negative'

def test_upper_bound(run, x):
    # Parse input to count total shocks (! actions and ? guesses that are wrong)
    lines = x.strip().split('\n')
    n = int(lines[0])
    total_shocks = 0
    for i in range(1, n+1):
        parts = lines[i].split()
        typ = parts[0]
        if typ == '!' or (typ == '?' and i != n):
            total_shocks += 1
    out = int(run(x).strip())
    # Excessive shocks cannot exceed total shocks
    assert out <= total_shocks, f'Excessive shocks {out} > total shocks {total_shocks}'

def test_shocks_after_unique(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    possible = set('abcdefghijklmnopqrstuvwxyz')
    excessive = 0
    out = int(run(x).strip())
    # Simulate to find first moment when |possible| == 1
    first_unique = None
    for i in range(1, n+1):
        parts = lines[i].split()
        typ = parts[0]
        word = parts[1] if len(parts) > 1 else ''
        if typ == '.':
            # no shock -> letters not in word
            for ch in word:
                possible.discard(ch)
        elif typ == '!':
            # shock -> letters in word
            new_possible = set()
            for ch in possible:
                if ch in word:
                    new_possible.add(ch)
            possible = new_possible
        elif typ == '?':
            # guess
            if i != n:
                # wrong guess
                possible.discard(word)
        if len(possible) == 1 and first_unique is None:
            first_unique = i
    if first_unique is not None:
        # Count shocks after first_unique
        shocks_after = 0
        for i in range(first_unique+1, n+1):
            parts = lines[i].split()
            typ = parts[0]
            if typ == '!' or (typ == '?' and i != n):
                shocks_after += 1
        # Excessive shocks must be at least shocks_after
        assert out >= shocks_after, f'Excessive shocks {out} < shocks after unique {shocks_after}'

def test_last_is_correct_guess(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    # The last action is a correct guess
    last_line = lines[n].split()
    assert last_line[0] == '?', 'Last action must be a guess'
    selected = last_line[1]
    # Selected letter must appear in at least one shock word before last
    found = False
    for i in range(1, n):
        parts = lines[i].split()
        if parts[0] == '!':
            if selected in parts[1]:
                found = True
                break
    assert found, f'Selected letter {selected} never appears in any shock word'

def test_no_excessive_before_unique(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    possible = set('abcdefghijklmnopqrstuvwxyz')
    shocks_before_unique = 0
    out = int(run(x).strip())
    for i in range(1, n+1):
        parts = lines[i].split()
        typ = parts[0]
        word = parts[1] if len(parts) > 1 else ''
        if typ == '.':
            for ch in word:
                possible.discard(ch)
        elif typ == '!':
            new_possible = set()
            for ch in possible:
                if ch in word:
                    new_possible.add(ch)
            possible = new_possible
            shocks_before_unique += 1
        elif typ == '?':
            if i != n:
                possible.discard(word)
                shocks_before_unique += 1
        if len(possible) == 1:
            # Excessive shocks cannot include shocks before this point
            # So out must be <= total shocks from i+1 onward
            total_shocks_after = 0
            for j in range(i+1, n+1):
                p2 = lines[j].split()
                if p2[0] == '!' or (p2[0] == '?' and j != n):
                    total_shocks_after += 1
            assert out <= total_shocks_after, f'Excessive shocks {out} > shocks after unique'
            break

def test_consistent_with_shocks(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    # The last guess is correct
    last_line = lines[n].split()
    selected = last_line[1]
    # For every '!' action, selected must be in the word
    for i in range(1, n):
        parts = lines[i].split()
        if parts[0] == '!':
            assert selected in parts[1], f'Selected letter {selected} not in shock word {parts[1]}'

def test_consistent_with_no_shocks(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    last_line = lines[n].split()
    selected = last_line[1]
    # For every '.' action, selected must NOT be in the word
    for i in range(1, n):
        parts = lines[i].split()
        if parts[0] == '.':
            assert selected not in parts[1], f'Selected letter {selected} incorrectly in no-shock word {parts[1]}'

def test_parsing_robustness(run, x):
    out1 = run(x).strip()
    # Add trailing newline to input, output should be same
    out2 = run(x + '\n').strip()
    assert out1 == out2, f'Output changes with extra newline: {out1} vs {out2}'

