def test_small_brute_force_len3(run, x):
    lines = x.strip().split('\n')
    t = int(lines[0])
    outputs = run(x).strip().split('\n')
    for idx in range(t):
        s = lines[idx+1]
        if len(s) == 3:
            # brute-force game tree
            from functools import lru_cache
            @lru_cache(None)
            def win(state, turn):  # turn 0 = Alice, 1 = Bob
                if len(state) < 2:
                    return False  # cannot move, current player loses
                moves = False
                for i in range(len(state)-1):
                    if state[i] != state[i+1]:
                        new_state = state[:i] + state[i+2:]
                        if not win(new_state, 1-turn):
