def test_parity_min_counts(run, x):
    # Known optimal strategy: each move removes one 0 and one 1, so total possible moves = min(count0, count1).
    # Alice wins if that min is odd. This holds for all inputs (proven).
    lines = x.strip().split('\n')
    t = int(lines[0])
    outputs = run(x).strip().split('\n')
    for idx in range(t):
        s = lines[idx+1]
        c0 = s.count('0')
        c1 = s.count('1')
        expected = 'DA' if (min(c0, c1) % 2 == 1) else 'NET'
        assert outputs[idx].strip().upper() == expected, f'Parity mismatch: {s}'


