def test_offset_non_decreasing_after_type2_only(run, x):
    # If an input contains only type2 and type3 operations, the offset (c) should never decrease.
    # But because the code may reset c when (type_3_count % 3) == 0, we cannot guarantee monotonicity.
    # Instead, check a weaker property: after a type2, querying the same index should not give a smaller value
    # than before if there were no type1 in between.
    # We'll implement by brute‑force simulation for small inputs only.
    lines = x.strip().split('\n')
    if len(lines) < 3:
        return
    n, m = map(int, lines[0].split())
    if n * m > 200:  # keep it fast
        return
    # Simulate the specification directly.
    a = list(map(int, lines[1].split()))
    queries = []
    for i in range(2, 2 + m):
        parts = list(map(int, lines[i].split()))
        if parts[0] == 1:
            a[parts[1] - 1] = parts[2]
        elif parts[0] == 2:
            y = parts[1]
            for j in range(n):
                a[j] += y
        else:
            queries.append(a[parts[1] - 1])
    output = run(x)
    out_vals = list(map(int, output.strip().split('\n'))) if output.strip() else []
    assert out_vals == queries


def test_single_type1_then_query(run, x):
    # If the only operation before a query is a type1 on the queried index,
    # the answer must equal the assigned x_i.
    lines = x.strip().split('\n')
    if len(lines) < 3:
        return
    n, m = map(int, lines[0].split())
    a_init = list(map(int, lines[1].split()))
    # Look for a prefix ending with a type3 that queries an index
    # where the last modification to that index was a type1 with no type2 in between.
    # We'll brute‑force simulate again for small inputs.
    if n * m > 200:
        return
    a = a_init[:]
    offset = 0
    expected_queries = []
    for i in range(2, 2 + m):
        parts = list(map(int, lines[i].split()))
        if parts[0] == 1:
            a[parts[1] - 1] = parts[2] - offset
        elif parts[0] == 2:
            offset += parts[1]
        else:
            expected_queries.append(a[parts[1] - 1] + offset)
    output = run(x)
    out_vals = list(map(int, output.strip().split('\n'))) if output.strip() else []
    assert out_vals == expected_queries


def test_immediate_query_after_type2(run, x):
    # After a type2 y, the next query (if any) should be at least y larger than the previous query
    # if it queries the same index and there was no type1 in between.
    # Again, brute‑force for small inputs.
    lines = x.strip().split('\n')
    if len(lines) < 3:
        return
    n, m = map(int, lines[0].split())
    if n * m > 200:
        return
    a = list(map(int, lines[1].split()))
    last_val = {}
    queries = []
    for i in range(2, 2 + m):
        parts = list(map(int, lines[i].split()))
        if parts[0] == 1:
            a[parts[1] - 1] = parts[2]
            last_val.pop(parts[1] - 1, None)
        elif parts[0] == 2:
            y = parts[1]
            for j in range(n):
                a[j] += y
        else:
            idx = parts[1] - 1
            val = a[idx]
            if idx in last_val:
                # Since type2 adds to all, val should be >= last_val[idx]
                assert val >= last_val[idx]
            last_val[idx] = val
            queries.append(val)
    output = run(x)
    out_vals = list(map(int, output.strip().split('\n'))) if output.strip() else []
    assert out_vals == queries


def test_no_type2_then_queries_equal_initial(run, x):
