    has_type2 = False
    for i in range(2, 2 + m):
        if i >= len(lines):
            break
        parts = list(map(int, lines[i].split()))
        if parts[0] == 2:
            has_type2 = True
            break
    if has_type2:
        return  # not applicable
    # Simulate without type2
    a = list(map(int, lines[1].split()))
    expected = []
    for i in range(2, 2 + m):
        parts = list(map(int, lines[i].split()))
        if parts[0] == 1:
            a[parts[1] - 1] = parts[2]
        elif parts[0] == 3:
            expected.append(a[parts[1] - 1])
