def test_consistency_same_index_queries(run, x):
    # If two consecutive queries are on the same index and there is no operation between them,
    # they should return the same value.
    lines = x.strip().split('\n')
    if len(lines) < 3:
        return
    n, m = map(int, lines[0].split())
    # Look for pattern: line i is type3 q, line i+1 is type3 same q.
    # We'll parse the operations.
    ops = []
    for i in range(2, 2 + m):
        if i >= len(lines):
            break
        parts = list(map(int, lines[i].split()))
        ops.append(parts)
    # Collect query positions
    query_positions = []
    for idx, op in enumerate(ops):
        if op[0] == 3:
            query_positions.append((idx, op[1]))
    # Check consecutive queries on same index with no intervening ops that change that index.
    # For simplicity, just check that if there are two consecutive type3 on same index and
    # there is no type1 or type2 between them, answers must match.
    # We'll brute‑force simulate for small inputs.
    if n * m > 200:
        return
    a = list(map(int, lines[1].split()))
    expected = []
    for op in ops:
        if op[0] == 1:
            a[op[1] - 1] = op[2]
        elif op[0] == 2:
            y = op[1]
            for j in range(n):
                a[j] += y
        else:
            expected.append(a[op[1] - 1])
    output = run(x)
    out_vals = list(map(int, output.strip().split('\n'))) if output.strip() else []
    assert out_vals == expected


