def test_bruteforce_len_leq_6(run, x):
    import sys
    sys.setrecursionlimit(10000)
    def optimal_can_win(s):
        # s is tuple of 0/1
        memo = {}
        def rec(state, turn):  # turn 0 = Alice, 1 = Bob
            if state in memo and memo[state][turn] is not None:
                return memo[state][turn][turn]
            # generate moves
            moves = []
            for i in range(len(state)-1):
                if state[i] != state[i+1]:
                    new = state[:i] + state[i+2:]
                    moves.append(new)
            if not moves:
                return False  # current player loses
            # current player wants any move leading to opponent losing
            for nxt in moves:
                if not rec(nxt, 1-turn):
                    if state not in memo:
                        memo[state] = [None, None]
                    memo[state][turn] = (not rec(nxt, 1-turn), )
                    return True
            # no winning move
            return False
        return rec(tuple(s), 0)
    lines = x.strip().split('\n')
    t = int(lines[0])
    out_lines = run(x).strip().split('\n')
    if len(out_lines) != t:
        raise AssertionError('wrong number of output lines')
    idx = 0
    for i in range(1, t+1):
        s = lines[i].strip()
        if len(s) <= 6:
            expected = 'DA' if optimal_can_win(s) else 'NET'
            got = out_lines[idx].strip().upper()
            if got not in ('DA', 'NET'):
                raise AssertionError(f'invalid output {got}')
            if got != expected:
                raise AssertionError(f'length {len(s)} string {s}: expected {expected}, got {got}')
        idx += 1

