def test_no_move_when_min_zero(run, x):
    # If min(count0, count1) == 0, then no adjacent pair of different bits exists,
    # so Alice cannot move and loses. Output must be NET.
    lines = x.strip().split('\n')
    t = int(lines[0])
    out_lines = run(x).strip().split('\n')
    if len(out_lines) != t:
        raise AssertionError('wrong number of output lines')
    idx = 0
    for i in range(1, t+1):
        s = lines[i].strip()
        c0 = s.count('0')
        c1 = s.count('1')
        if min(c0, c1) == 0:
            got = out_lines[idx].strip().upper()
            if got != 'NET':
                raise AssertionError(f'string {s} has min zero, expected NET, got {got}')
        idx += 1

def test_output_format(run, x):
    # Output must be exactly t lines, each line case-insensitively DA or NET.
    lines = x.strip().split('\n')
    t = int(lines[0])
    out = run(x)
    out_lines = out.strip().split('\n')
    if len(out_lines) != t:
        raise AssertionError(f'expected {t} output lines, got {len(out_lines)}')
    for line in out_lines:
        stripped = line.strip().upper()
        if stripped not in ('DA', 'NET'):
            raise AssertionError(f'output line "{line}" is not DA or NET')

def test_reversal_invariant(run, x):
    # Reversing the string does not change the game outcome.
    # For each test case, we can't call run again, but we can check
    # that within the same input, if there are two test cases that are reverses,
    # they must have same output.
    lines = x.strip().split('\n')
    t = int(lines[0])
    if t < 2:
        return
    out_lines = run(x).strip().split('\n')
    if len(out_lines) != t:
        return
    # build map from string to its output
    seen = {}
    for i in range(t):
        s = lines[i+1].strip()
        rev = s[::-1]
        got = out_lines[i].strip().upper()
        if s in seen:
            if seen[s] != got:
                raise AssertionError(f'string {s} output inconsistent')
        if rev in seen:
            if seen[rev] != got:
                raise AssertionError(f'reverse mismatch: {s} vs {rev}')
        seen[s] = got

