def test_valid_integer(run, x):
    n = int(x.strip())
    out = run(x).strip()
    # Must be non-empty
    assert out != ''
    # No leading zero
    assert out[0] != '0'
    # All characters are digits
    assert out.isdigit()
    # Must be a positive integer
    assert int(out) > 0

def test_segment_count_eq_n(run, x):
    n = int(x.strip())
    out = run(x).strip()
    seg_cost = {'0':6, '1':2, '2':5, '3':5, '4':4, '5':5, '6':6, '7':3, '8':7, '9':6}
    total = sum(seg_cost[d] for d in out)
    assert total == n  # must use exactly all segments

def test_matches_greedy(run, x):
    n = int(x.strip())
    # compute greedy answer
    if n % 2 == 1 and n >= 3:
        expected = '7' + '1' * ((n - 3) // 2)
    else:
        expected = '1' * (n // 2)
    out = run(x).strip()
    assert out == expected

def test_bruteforce_small_n(run, x):
    n = int(x.strip())
    if n > 20:
        return  # skip, too large
    out = run(x).strip()
    # brute-force all digit sequences (no leading zero) with total segments <= n
    seg_cost = {'0':6, '1':2, '2':5, '3':5, '4':4, '5':5, '6':6, '7':3, '8':7, '9':6}
    best = -1
    from itertools import product
    # limit length: max digits = n // 2 (since min cost 2)
    max_len = n // 2
    for length in range(1, max_len + 1):
        for digits in product('0123456789', repeat=length):
            if digits[0] == '0':
                continue
            total = sum(seg_cost[d] for d in digits)
            if total > n:
                continue
            num = int(''.join(digits))
            if num > best:
                best = num
    # also consider shorter lengths? already covered.
    assert int(out) == best

def test_length_correct(run, x):
    n = int(x.strip())
    out = run(x).strip()
    if n % 2 == 0:
        expected_len = n // 2
    else:
        expected_len = (n - 3) // 2 + 1
    assert len(out) == expected_len

def test_first_digit_parity(run, x):
    n = int(x.strip())
    out = run(x).strip()
    if n % 2 == 0:
        # even n: first digit should be '1'
        assert out[0] == '1'
    else:
        # odd n: first digit should be '7' (since n>=3)
        assert out[0] == '7'

def test_no_zero_digit(run, x):
    out = run(x).strip()
    assert '0' not in out

def test_output_positive(run, x):
    out = run(x).strip()
    assert int(out) > 0

def test_digits_only_1_or_7(run, x):
    out = run(x).strip()
    for ch in out:
        assert ch in '17'

def test_segment_count_at_most_n(run, x):
    n = int(x.strip())
    out = run(x).strip()
    seg_cost = {'0':6, '1':2, '2':5, '3':5, '4':4, '5':5, '6':6, '7':3, '8':7, '9':6}
    total = sum(seg_cost[d] for d in out)
    assert total <= n  # at most n

