            for v in sub:
                b = 0
                while (1 << b) <= v:
                    if v >> b & 1:
                        bits[b] = bits.get(b, 0) + 1
                    b += 1
            val = 0
            need = max(1, k-2)
            for b, cnt in bits.items():
                if cnt >= need:
                    val |= 1 << b
