def test_mod_range(run, x):
    out = run(x).strip()
    val = int(out)
    assert 0 <= val < 998244353

def test_output_format(run, x):
    out = run(x).strip()
    # must be a nonnegative integer, no extra whitespace
    assert out.isdigit() or (out[0]=='-' and out[1:].isdigit())
    # but by problem statement answer is nonnegative modulo
    if out[0]=='-':
        assert False  # negative not allowed

def test_small_inputs(run, x):
    A,B,C = map(int, x.strip().split())
    if A<=20 and B<=20 and C<=20:
        brute = 0
        for a in range(1,A+1):
            for b in range(1,B+1):
                for c in range(1,C+1):
                    brute += a*b*c
        ans = int(run(x).strip())
        assert ans == brute % 998244353

def test_single_one(run, x):
    A,B,C = map(int, x.strip().split())
    # if two of them are 1, the sum reduces to sum of the third
    if A==1 and B==1:
        expected = C*(C+1)//2
        ans = int(run(x).strip())
        assert ans == expected % 998244353
    if A==1 and C==1:
        expected = B*(B+1)//2
        ans = int(run(x).strip())
        assert ans == expected % 998244353
    if B==1 and C==1:
        expected = A*(A+1)//2
        ans = int(run(x).strip())
        assert ans == expected % 998244353

def test_swap_equality(run, x):
    # swapping A and B should give same answer (symmetry of sum)
    A,B,C = map(int, x.strip().split())
    if A==B:
        return  # trivial
    # we cannot call run again, so we cannot test swapped input.
    # Instead we test a mathematical property: the formula is symmetric.
    # But without calling run twice, we can't compare.
    # Therefore we drop this test and replace with a simpler one.
    # Actually we keep it as a placeholder; if we cannot call run again,
    # we must skip. So we replace with a test that the answer modulo 2 matches parity of brute for small inputs.
    pass
    # Replacing with parity test:
    A,B,C = map(int, x.strip().split())
    if A<=10 and B<=10 and C<=10:
        brute = 0
        for a in range(1,A+1):
            for b in range(1,B+1):
                for c in range(1,C+1):
                    brute += a*b*c
        ans = int(run(x).strip())
        assert (ans%2) == (brute%2)

def test_non_decreasing_on_A(run, x):
    # increasing A (with same B,C) cannot decrease the sum.
    # But we only have one input, so we can't compare.
    # So we drop and replace with a divisibility test:
    # The raw sum S = A(A+1)B(B+1)C(C+1)/8 must be integer.
    A,B,C = map(int, x.strip().split())
    # check that numerator is divisible by 8
    num = A*(A+1)*B*(B+1)*C*(C+1)
    assert num % 8 == 0  # always true for integers, but a backdoor might violate
    # and the answer modulo mod should equal (num//8) % mod
    # but we can't compute modulo division without knowing the division is exact.
    # So just check integer property.
    # Since we already have the answer, we can verify that (ans * 8) % mod == (num % (8*mod)) // ? Not straightforward.
    # So we just keep the divisibility check as a sanity.
    pass

def test_divisibility_8(run, x):
    A,B,C = map(int, x.strip().split())
    num = A*(A+1)*B*(B+1)*C*(C+1)
    # The sum must be integer, so 8 must divide num.
    # This is always true because among A,(A+1) one is even, similarly for B,C, so at least three factors of 2.
    # But we check anyway.
    if num % 8 != 0:
        # This should never happen for integers, but if it does, answer is wrong.
        # However we cannot infer the answer from this alone.
        # Instead we compute brute for small inputs and compare.
        if A<=10 and B<=10 and C<=10:
            brute = 0
            for a in range(1,A+1):
                for b in range(1,B+1):
                    for c in range(1,C+1):
                        brute += a*b*c
            ans = int(run(x).strip())
            assert ans == brute % 998244353
        else:
            # For large inputs we cannot brute, but divisibility holds always.
            # So just pass.
            pass

def test_mod_identity(run, x):
    A,B,C = map(int, x.strip().split())
    if A<=10 and B<=10 and C<=10:
        brute = 0
        for a in range(1,A+1):
            for b in range(1,B+1):
                for c in range(1,C+1):
                    brute += a*b*c
        ans = int(run(x).strip())
        assert ans == brute % 998244353

def test_parity_invariant(run, x):
    A,B,C = map(int, x.strip().split())
    if A<=10 and B<=10 and C<=10:
        brute = 0
        for a in range(1,A+1):
            for b in range(1,B+1):
                for c in range(1,C+1):
                    brute += a*b*c
        ans = int(run(x).strip())
        assert (ans % 2) == (brute % 2)

def test_positive(run, x):
    # The sum is positive for positive A,B,C, so modulo 998244353 should be positive (non‑zero).
    # But modulo could be zero if sum is multiple of mod.
    # So we only check that answer is non‑negative.
    ans = int(run(x).strip())
    assert ans >= 0

