def test_output_format(run, x):
    out = run(x)
    lines = out.strip().split('\n')
    # count queries from input
    parts = x.strip().split('\n')
    hw_line = parts[0].split()
    h, w = map(int, hw_line)
    q_line_idx = h + 1
    q = int(parts[q_line_idx])
    assert len(lines) == q, f'Expected {q} lines, got {len(lines)}'
    for line in lines:
        s = line.strip()
        # must be an integer
        try:
            v = int(s)
        except ValueError:
            assert False, f'Not an integer: {repr(s)}'
        # no extra characters
        assert str(v) == s, f'Extra whitespace or leading zeros'


def test_nonnegative(run, x):
    out = run(x)
    for line in out.strip().split('\n'):
        v = int(line.strip())
        assert v >= 0, f'Negative answer: {v}'


def test_bound_by_cells(run, x):
    # Parse grid dimensions
    lines = x.strip().split('\n')
    h, w = map(int, lines[0].split())
    q = int(lines[h+1])
    # Read queries
    queries = []
    for i in range(h+2, h+2+q):
        r1, c1, r2, c2 = map(int, lines[i].split())
        queries.append((r1, c1, r2, c2))
    out_vals = list(map(int, run(x).strip().split()))
    for (r1,c1,r2,c2), ans in zip(queries, out_vals):
        cells = (r2-r1+1)*(c2-c1+1)
        # A domino uses two cells, so maximum placements <= cells//2
        assert ans <= cells // 2, f'Answer {ans} > cells//2 ({cells//2}) for rectangle {r1},{c1},{r2},{c2}'


def test_bound_by_empty_minus_one(run, x):
    # Parse grid
    lines = x.strip().split('\n')
    h, w = map(int, lines[0].split())
    grid = lines[1:1+h]
    q = int(lines[h+1])
    queries = []
    for i in range(h+2, h+2+q):
        queries.append(list(map(int, lines[i].split())))
    out_vals = list(map(int, run(x).strip().split()))
    for (r1,c1,r2,c2), ans in zip(queries, out_vals):
        # count empty cells in the rectangle by brute force (h,w <= 500, rectangle area <= 250000, but we just loop over rows)
        empty = 0
        for r in range(r1-1, r2):
            row = grid[r]
            for c in range(c1-1, c2):
                if row[c] == '.':
                    empty += 1
        # Each domino needs two empty cells, so answer <= empty - 1 when empty >= 2? Not exactly.
        # Actually, the maximum possible placements is floor(empty/2), but we already have that bound.
        # A stronger bound: answer <= empty - 1 if empty >= 1? No, because empty=2 could have 1 placement.
        # Better: answer <= empty // 2, which we already test in another test.
        # This test will instead check that answer <= empty - 1 when empty >= 1? That's false for empty=2, answer=1.
        # So we drop this test and replace with a more straightforward one.
        # Instead we check that answer <= number of adjacent empty pairs (horizontal+vertical) inside rectangle.
        # We can compute that bound quickly for the whole rectangle.
        # Compute horizontal adjacent empty pairs in rectangle
        horiz_pairs = 0
        for r in range(r1-1, r2):
            row = grid[r]
            for c in range(c1-1, c2-1):
                if row[c] == '.' and row[c+1] == '.':
                    horiz_pairs += 1
        vert_pairs = 0
        for r in range(r1-1, r2-1):
            for c in range(c1-1, c2):
                if grid[r][c] == '.' and grid[r+1][c] == '.':
                    vert_pairs += 1
        max_possible = horiz_pairs + vert_pairs
        assert ans <= max_possible, f'Answer {ans} > possible adjacent pairs ({max_possible}) for rectangle {r1},{c1},{r2},{c2}'


