    {
      "name": "test_parse_grammar",
      "source": "def test_parse_grammar(run, x):
    import re
    expr = run(x).strip()
    # Check allowed characters only
    allowed = set('xyz!&|()')
    for ch in expr:
        if ch not in allowed:
            assert False, f'Invalid character {ch}'
    # Rough grammar check: parentheses balanced, no consecutive binary ops, not starting/ending with binary op
    stack = []
    for i, ch in enumerate(expr):
        if ch == '(':
            stack.append(ch)
        elif ch == ')':
            if not stack:
                assert False, 'Unmatched )'
            stack.pop()
    if stack:
        assert False, 'Unmatched ('
    if expr and expr[0] in '&|' or expr[-1] in '&|' or expr[-1] == '!':
        assert False, 'Invalid start/end'
    for i in range(len(expr)-1):
        if expr[i] in '&|' and expr[i+1] in '&|':
            assert False, 'Consecutive binary ops'
        if expr[i] == '!' and expr[i+1] in '&|':
            assert False, '! followed by binary op'"
    },
    {
      "name": "test_truth_table_match",
      "source": "def test_truth_table_match(run, x):
    import itertools
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return  # malformed input, but given inputs are valid
    n = int(lines[0])
    # we only care about the first truth table because each test runs on a single case
    # Input format: first line is n, then n lines of truth tables.
    # For n=1, the second line is the truth table.
    # For n>1, we take the first truth table (since each test input has exactly one function).
    truth_str = lines[1]
    expr = run(x).strip()
    # Evaluate expression for all 8 combinations
    for bits in itertools.product([0,1], repeat=3):
        xv, yv, zv = bits
        env = {'x': xv, 'y': yv, 'z': zv}
        # Safe eval using lambda: replace variables with values, evaluate &,|,! as Python operators
        # Build a safe string: replace ! with not, & with and, | with or, but careful with precedence.
        # Instead, evaluate using a simple stack evaluator.
        def evaluate(e):
            # Shunting-yard to RPN and evaluate
            prec = {'!':3, '&':2, '|':1, '(':0, ')':0}
            output = []
            stack = []
            i = 0
            while i < len(e):
                ch = e[i]
                if ch in 'xyz':
                    output.append(env[ch])
                elif ch == '!':
                    stack.append('!')
                elif ch == '(':
                    stack.append('(')
                elif ch == ')':
                    while stack and stack[-1] != '(':
                        output.append(stack.pop())
                    stack.pop()  # remove '('
                elif ch in '&|':
                    while stack and prec[stack[-1]] >= prec[ch]:
                        output.append(stack.pop())
                    stack.append(ch)
                i += 1
            while stack:
                output.append(stack.pop())
            # evaluate RPN
            eval_stack = []
            for token in output:
                if token in (0,1):
                    eval_stack.append(token)
                elif token == '!':
                    a = eval_stack.pop()
                    eval_stack.append(1 if a==0 else 0)
                elif token == '&':
                    b = eval_stack.pop()
                    a = eval_stack.pop()
                    eval_stack.append(1 if a==1 and b==1 else 0)
                elif token == '|':
                    b = eval_stack.pop()
                    a = eval_stack.pop()
                    eval_stack.append(1 if a==1 or b==1 else 0)
