            else:  # left edge
                return 3*a + (a - y)
        p1 = pos_on_perimeter(xs1, ys1)
        p2 = pos_on_perimeter(xs2, ys2)
        diff = p2 - p1
        if diff < -1e-9:
            diff += 4*a  # wrap around
        assert abs(diff - d) < 1e-4, f'Step {i} to {i+1} distance mismatch: diff={diff}, d={d}'

def test_on_boundary(run, x):
    out = run(x)
    lines = out.strip().split('\n')
    a = float(x.split('\n')[0].split()[0])
    for line in lines:
        if line:
            xs, ys = line.split()
            xf = float(xs)
            yf = float(ys)
            # Must be exactly on the boundary: one coordinate 0 or a, and the other between 0 and a inclusive.
            on = (abs(xf) < 1e-9 or abs(xf - a) < 1e-9 or abs(yf) < 1e-9 or abs(yf - a) < 1e-9)
            in_range = (0 - 1e-9 <= xf <= a + 1e-9) and (0 - 1e-9 <= yf <= a + 1e-9)
            assert on and in_range, f'Point ({xf},{yf}) not on square boundary'

def test_monotonic_perimeter_pos(run, x):
    # The perimeter position (distance from start) should be strictly increasing (with wrap) for consecutive points.
    out = run(x)
    lines = out.strip().split('\n')
    if len(lines) < 2:
        return
    a = float(x.split('\n')[0].split()[0])
    def pos(xc, yc):
        if abs(yc) < 1e-9:
            return xc
        elif abs(xc - a) < 1e-9:
            return a + yc
        elif abs(yc - a) < 1e-9:
            return 2*a + (a - xc)
        else:
            return 3*a + (a - yc)
    prev = pos(*map(float, lines[0].split()))
    for line in lines[1:]:
        cur = pos(*map(float, line.split()))
        # Since d>0, the next position should be greater, but may wrap after 4*a
        if cur < prev - 1e-9:
            cur += 4*a
        assert cur > prev - 1e-9, f'Perimeter position not strictly increasing: {prev} -> {cur}'

def test_exact_example1(run, x):
    if x == '2 5\n2\n':
        out = run(x)
        expected = '1.0000000000 2.0000000000\n2.0000000000 0.0000000000\n'
        # Allow small error in output format
        lines_out = out.strip().split('\n')
        lines_exp = expected.strip().split('\n')
        if len(lines_out) != len(lines_exp):
            assert False, f'Line count mismatch'
        for lo, le in zip(lines_out, lines_exp):
            xo, yo = map(float, lo.split())
            xe, ye = map(float, le.split())
            assert abs(xo - xe) < 1e-4 and abs(yo - ye) < 1e-4, f'Point mismatch'

