def test_output_format(run, x):
    out = run(x)
    lines = out.strip().split('\n')
    n = int(x.split('\n')[1])
    assert len(lines) == n, f'Expected {n} lines, got {len(lines)}'
    for line in lines:
        parts = line.split()
        assert len(parts) == 2, f'Line does not contain two numbers: {line}'
        xf, yf = float(parts[0]), float(parts[1])
        # Numbers should be within reasonable bounds (square side up to 1e5)
        assert -1e-9 <= xf <= 1e5 + 1e-9 and -1e-9 <= yf <= 1e5 + 1e-9, f'Coordinates out of plausible range'

def test_total_distance(run, x):
    # The last point should be at distance n*d along the perimeter (modulo 4*a).
    out = run(x)
    lines = out.strip().split('\n')
    if not lines:
        return
    a_str, d_str = x.split('\n')[0].split()
    a = float(a_str)
    d = float(d_str)
    n = int(x.split('\n')[1])
    total = n * d
    perimeter = 4 * a
    # Reduce total modulo perimeter
    total_mod = total % perimeter
    if total_mod < 1e-9:
        total_mod = 0.0
    # Compute perimeter position of last point
    xl, yl = map(float, lines[-1].split())
    def pos(xc, yc):
        if abs(yc) < 1e-9:
            return xc
        elif abs(xc - a) < 1e-9:
            return a + yc
        elif abs(yc - a) < 1e-9:
            return 2*a + (a - xc)
        else:
            return 3*a + (a - yc)
    last_pos = pos(xl, yl)
    # Allow wrap: if last_pos is near perimeter and total_mod near 0, treat as 0
    if abs(last_pos - perimeter) < 1e-9 and total_mod < 1e-9:
        last_pos = 0.0
    assert abs(last_pos - total_mod) < 1e-4, f'Last point position mismatch: expected {total_mod}, got {last_pos}'

def test_first_point_distance(run, x):
    # First point should be at distance d along the perimeter.
    out = run(x)
    lines = out.strip().split('\n')
    if not lines:
        return
    a_str, d_str = x.split('\n')[0].split()
    a = float(a_str)
    d = float(d_str)
    xf, yf = map(float, lines[0].split())
    def pos(xc, yc):
