def test_no_duplicate_points_unless_wrap(run, x):
    # Points should be distinct unless the distance d is a multiple of perimeter (or after many steps).
    # But we can check that consecutive points are not identical (within epsilon).
    out = run(x)
    lines = out.strip().split('\n')
    a = float(x.split('\n')[0].split()[0])
    d = float(x.split('\n')[0].split()[1])
    perimeter = 4 * a
    if abs(d % perimeter) < 1e-9:
        # All points at same location (start), skip
        return
    for i in range(len(lines)-1):
        x1, y1 = map(float, lines[i].split())
        x2, y2 = map(float, lines[i+1].split())
        assert not (abs(x1 - x2) < 1e-9 and abs(y1 - y2) < 1e-9), f'Consecutive points identical: ({x1},{y1})'

