            anc = v
            for _ in range(h - i):
                anc //= 2
            if L <= anc <= R:
                correct = 1
            else:
                correct = 0
            if correct != ans:
                return False
        return True
    possible = [v for v in leaves if satisfies(v)]
    assert leaf in possible, f'Output leaf {leaf} not in possible leaves {possible}'

