def test_small_brute_force(run, x):
    data = x.split('\n')
    n, m = map(int, data[0].split()[:2])
    if n > 10 or m > 10:
        return  # skip large inputs
    edges = []
    for i in range(1, 1 + m):
        a, b, c = map(int, data[i].split())
        edges.append((a-1, b-1, c-1))  # zero‑index
    q_line_idx = 1 + m
    q = int(data[q_line_idx].strip())
    queries = []
    for i in range(q):
        u, v = map(int, data[q_line_idx + 1 + i].split())
        queries.append((u-1, v-1))
    # For each color, build adjacency and compute connectivity
    color_adj = {col: [[] for _ in range(n)] for col in range(m)}
    for a, b, col in edges:
        color_adj[col][a].append(b)
        color_adj[col][b].append(a)
    def dfs_color(start, target, col, visited):
        if start == target:
            return True
        visited[start] = True
        for nb in color_adj[col][start]:
            if not visited[nb]:
                if dfs_color(nb, target, col, visited):
                    return True
        return False
    expected = []
    for u, v in queries:
        cnt = 0
        for col in range(m):
            visited = [False]*n
            if dfs_color(u, v, col, visited):
                cnt += 1
        expected.append(cnt)
    out = run(x).strip()
    actual = list(map(int, out.split('\n')))
    assert actual == expected, f'brute‑force mismatch: expected {expected}, got {actual}'


