tests_src:
def test_length_matches_n(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0].split()[0])
    output = run(x).strip()
    assert len(output) == n

def test_all_lowercase_letters(run, x):
    output = run(x).strip()
    for c in output:
        assert 'a' <= c <= 'z'

def test_ascii_range(run, x):
    output = run(x).strip()
    for c in output:
        assert 97 <= ord(c) <= 122

def test_non_empty_if_n_positive(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0].split()[0])
    if n > 0:
        output = run(x).strip()
        assert len(output) > 0

def test_no_whitespace_in_output(run, x):
    output = run(x).strip()
    assert output.isalpha()

def test_exact_n_chars_no_extra_newline(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0].split()[0])
    output = run(x).rstrip('\n')
    assert len(output) == n

def test_first_char_letter(run, x):
    output = run(x).strip()
    if output:
        assert 'a' <= output[0] <= 'z'

def test_last_char_letter(run, x):
    output = run(x).strip()
    if output:
        assert 'a' <= output[-1] <= 'z'

def test_stripped_length_n(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0].split()[0])
    output = run(x).rstrip('\n')
    assert len(output) == n

def test_brute_force_small_inputs(run, x):
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    if n > 10 or m > 10:
        return
    s = lines[1]
    swaps = []
    for i in range(m):
        x_i, y_i = lines[2 + i].split()
        swaps.append((x_i, y_i))
    cur = list(s)
    for x_i, y_i in swaps:
        for idx in range(n):
            if cur[idx] == x_i:
                cur[idx] = y_i
            elif cur[idx] == y_i:
                cur[idx] = x_i
    expected = ''.join(cur)
    output = run(x).strip()
    assert output == expected

def test_output_format(run, x):
    # Output must be one integer per test case, no extra whitespace
    out = run(x)
    lines = out.strip().split()
    t = int(x.strip().split('\n')[0])
    assert len(lines) == t, f'Expected {t} integers, got {len(lines)}'
    for line in lines:
        assert line.isdigit() or (line[0]=='-' and line[1:].isdigit()), f'Not an integer: {line}'


def test_answer_nonnegative(run, x):
    out = run(x)
    for val in out.strip().split():
        v = int(val)
        assert v >= 0, f'Negative answer {v}'


def test_answer_at_least_3_if_nonzero(run, x):
    out = run(x)
    lines = out.strip().split()
    inputs = x.strip().split('\n')[1:]
    for ans, s in zip(lines, inputs):
        v = int(ans)
        if v != 0:
            assert v >= 3, f'Nonzero answer {v} < 3'


def test_answer_at_most_len(run, x):
    out = run(x)
    lines = out.strip().split()
    inputs = x.strip().split('\n')[1:]
    for ans, s in zip(lines, inputs):
        v = int(ans)
        assert v <= len(s), f'Answer {v} > length {len(s)}'


def test_zero_if_missing_char(run, x):
    out = run(x)
    lines = out.strip().split()
    inputs = x.strip().split('\n')[1:]
    for ans, s in zip(lines, inputs):
        v = int(ans)
        has1 = '1' in s
        has2 = '2' in s
        has3 = '3' in s
        if not (has1 and has2 and has3):
            assert v == 0, f'Missing character but answer {v} != 0'


def test_nonzero_if_all_chars_present(run, x):
    out = run(x)
    lines = out.strip().split()
    inputs = x.strip().split('\n')[1:]
    for ans, s in zip(lines, inputs):
        v = int(ans)
        has1 = '1' in s
        has2 = '2' in s
        has3 = '3' in s
        if has1 and has2 and has3:
            assert v != 0, f'All chars present but answer is 0'


def test_answer_bruteforce_small(run, x):
    out = run(x)
    lines = out.strip().split()
    inputs = x.strip().split('\n')[1:]
    for ans, s in zip(lines, inputs):
        if len(s) > 30:   # brute force only for small strings
            continue
        v = int(ans)
        # brute force shortest substring containing 1,2,3
        best = 0
        n = len(s)
        for i in range(n):
            seen = set()
            for j in range(i, n):
                seen.add(s[j])
                if len(seen) == 3:
                    length = j - i + 1
                    if best == 0 or length < best:
                        best = length
                    break
        assert v == best, f'Brute force says {best}, got {v}'


def test_answer_not_1_or_2(run, x):
    out = run(x)
    for val in out.strip().split():
        v = int(val)
        assert v != 1 and v != 2, f'Impossible answer {v} (must be 0 or >=3)'


def test_answer_matches_example(run, x):
    # Check the provided example from statement
    example_input = '7\n123\n12222133333332\n112233\n332211\n12121212\n333333\n31121\n'
    example_output = '3\n3\n4\n4\n0\n0\n4\n'
    if x == example_input:
        out = run(x)
        assert out == example_output, f'Example mismatch: expected {example_output!r}, got {out!r}'


def test_answer_consistent_with_substring(run, x):
    out = run(x)
    lines = out.strip().split()
    inputs = x.strip().split('\n')[1:]
    for ans, s in zip(lines, inputs):
        v = int(ans)
        if v == 0:
            continue
        # There must exist a substring of length v containing 1,2,3
        found = False
        for i in range(len(s) - v + 1):
            sub = s[i:i+v]
            if '1' in sub and '2' in sub and '3' in sub:
                found = True
                break
        assert found, f'No substring of length {v} contains 1,2,3'

