def test_bruteforce_small_1(run, x):
    a_str, b_str = x.strip().split('\n')
    if len(a_str) > 6 or len(b_str) > 6:
        return  # too large for brute force
    q = (1 + 5**0.5)/2
    def val(s):
        total = 0
        n = len(s)
        for i,ch in enumerate(s):
            total += int(ch) * q**(n-1-i)
        return total
    va = val(a_str)
    vb = val(b_str)
    expected = '=' if abs(va-vb) < 1e-9 else '>' if va > vb else '<'
    assert run(x).strip() == expected

def test_bruteforce_small_2(run, x):
    # same as test_bruteforce_small_1 but using recurrence for q^n
    a,b = x.strip().split('\n')
    if len(a) > 8 or len(b) > 8:
        return
    # q^n satisfies q^{n+1}=q^n+q^{n-1}
    qp = [1.0, (1+5**0.5)/2]
    for i in range(2, max(len(a),len(b))+5):
        qp.append(qp[-1]+qp[-2])
    def val(s):
        n = len(s)
        total = 0
        for i,ch in enumerate(s):
            if ch == '1':
                total += qp[n-1-i]
        return total
    va, vb = val(a), val(b)
    expected = '=' if abs(va-vb) < 1e-9 else '>' if va > vb else '<'
    assert run(x).strip() == expected

def test_bruteforce_small_3(run, x):
    # using high-precision fractions via golden ratio recurrence
    a,b = x.strip().split('\n')
    if len(a)+len(b) > 12:
        return
    # represent q^n as pair (coeff of sqrt5, integer coeff)?? easier: use decimal with high precision
    import decimal
    decimal.getcontext().prec = 50
    q = (decimal.Decimal(1) + decimal.Decimal(5).sqrt()) / decimal.Decimal(2)
    def val(s):
        n = len(s)
        total = decimal.Decimal(0)
        for i,ch in enumerate(s):
            if ch == '1':
                total += q ** (n-1-i)
        return total
    va, vb = val(a), val(b)
    expected = '=' if va == vb else '>' if va > vb else '<'
    assert run(x).strip() == expected

def test_output_format(run, x):
    out = run(x).strip()
    assert out in ('>', '<', '=')

def test_swap_symmetry(run, x):
    # If we swap the two lines, the answer should flip (or stay '=').
    # But we cannot call run twice, so we cannot test that directly.
    # Instead we check that for the given input, if answer is '>', then
    # for the swapped input the answer would be '<', but we cannot run swapped.
    # This is a property of the single answer we have? Not checkable without second call.
    # So we change: We'll check that answer is consistent with a trivial case:
    # If strings are identical (ignoring leading zeros?), answer should be '='.
    a,b = x.strip().split('\n')
    a_stripped = a.lstrip('0') or '0'
    b_stripped = b.lstrip('0') or '0'
    if a_stripped == b_stripped:
        assert run(x).strip() == '='

def test_leading_zeros_equality(run, x):
    # If strings differ only by leading zeros, numbers are equal.
    a,b = x.strip().split('\n')
    a_stripped = a.lstrip('0') or '0'
    b_stripped = b.lstrip('0') or '0'
    if a_stripped == b_stripped:
        assert run(x).strip() == '='

def test_single_digit_cases(run, x):
    a,b = x.strip().split('\n')
    if len(a) == 1 and len(b) == 1:
        # only possibilities: 0,1
        va, vb = int(a), int(b)
        expected = '=' if va == vb else '>' if va > vb else '<'
        assert run(x).strip() == expected

def test_bruteforce_up_to_4(run, x):
    a,b = x.strip().split('\n')
    if len(a) <= 4 and len(b) <= 4:
        # compute exactly using golden ratio recurrence
        # q^0=1, q^1=q, q^{n+1}=q^n+q^{n-1}
        # precompute q^n as float (enough for small n)
        qn = [1.0, 1.618033988749895]
        for i in range(2, 9):
            qn.append(qn[-1]+qn[-2])
        def val(s):
            total = 0.0
            n = len(s)
            for i,ch in enumerate(s):
                if ch == '1':
                    total += qn[n-1-i]
            return total
        va, vb = val(a), val(b)
        expected = '=' if abs(va-vb) < 1e-12 else '>' if va > vb else '<'
        assert run(x).strip() == expected

