    # Because if for some i that condition fails, then removing i might still cover all lamps,
    # but not guaranteed (other rows might have count>1 but still not cover).
    # So we can only check that if answer is NO, then for each row i there is a lamp j with count[j]==1 and a[i][j]=='1'.
    # Parse input
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    a = lines[1:]
    count = [0]*m
    for i in range(n):
        for j in range(m):
            if a[i][j] == '1':
                count[j] += 1
    out = run(x).strip()
    if out == "NO":
        for i in range(n):
            has_single = False
            for j in range(m):
                if count[j] == 1 and a[i][j] == '1':
                    has_single = True
                    break
            if not has_single:
                # then row i could potentially be removed while keeping all lamps on
                # So answer should not be NO (could be YES).
                # This is a contradiction => output is wrong.
                assert False, f"Row {i} has no lamp with count 1, yet answer is NO."


def test_exact_bruteforce(run, x):
    # Brute-force check for small inputs (n,m <= 10) to be safe.
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    if n > 10 or m > 10:
        return  # skip, too big
    a = lines[1:]
    # compute if there exists a row i such that removing i still covers all lamps
    found = False
    for skip in range(n):
        ok = True
        for j in range(m):
            covered = False
            for i in range(n):
                if i == skip:
                    continue
                if a[i][j] == '1':
                    covered = True
                    break
            if not covered:
                ok = False
                break
        if ok:
            found = True
            break
    expected = "YES" if found else "NO"
    out = run(x).strip()
    assert out == expected, f"Brute-force says {expected}, got {out}"


