    # If there is a lamp that is covered by exactly one switch, 
    # and that switch is present in every row (i.e., all rows have '1' in that column),
    # then removing any row would leave that lamp uncovered -> answer must be NO.
    # Actually if a lamp is covered by exactly one switch, that switch must be kept.
    # So if there are at least two such lamps covered by distinct switches, answer must be NO.
    # But easier: if every lamp is covered by at least two switches, answer must be YES.
    # We'll implement a necessary condition: if answer is YES, then there exists a row i such that for every lamp j with count[j]==1, a[i][j]=='0'.
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    a = lines[1:]
    count = [0]*m
    for i in range(n):
        for j in range(m):
            if a[i][j] == '1':
                count[j] += 1
    out = run(x).strip()
    if out == "YES":
        # There must exist at least one row i that does not touch any uniquely covered lamp.
        exists_row = False
        for i in range(n):
            bad = False
            for j in range(m):
                if count[j] == 1 and a[i][j] == '1':
                    bad = True
                    break
            if not bad:
                exists_row = True
                break
        assert exists_row, "YES but every row covers a uniquely covered lamp"


def test_must_be_yes_if_all_rows_redundant(run, x):
    # If every lamp is covered by at least two switches, answer must be YES.
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    a = lines[1:]
    count = [0]*m
    for i in range(n):
        for j in range(m):
            if a[i][j] == '1':
                count[j] += 1
    all_two = all(c >= 2 for c in count)
    if all_two:
        out = run(x).strip()
        assert out == "YES", f"All lamps covered by >=2 switches, must be YES, got {out}"


