def test_output_format(run, x):
    out = run(x)
    assert out.endswith('\n'), 'output must end with newline'
    stripped = out.strip()
    assert stripped in {'sjfnb', 'cslnb'}, 'output must be exactly sjfnb or cslnb'

def test_example1(run, x):
    if x == '1\n0\n':
        out = run(x).strip()
        assert out == 'cslnb', 'example 1 must output cslnb'

def test_example2(run, x):
    if x == '2\n1 0\n':
        out = run(x).strip()
        assert out == 'cslnb', 'example 2 must output cslnb'

def test_example3(run, x):
    if x == '2\n2 2\n':
        out = run(x).strip()
        assert out == 'sjfnb', 'example 3 must output sjfnb'

def test_example4(run, x):
    if x == '3\n2 3 1\n':
        out = run(x).strip()
        assert out == 'sjfnb', 'example 4 must output sjfnb'

def test_all_zero(run, x):
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    n = int(lines[0].strip())
    a = list(map(int, lines[1].strip().split()))
    if all(v == 0 for v in a):
        out = run(x).strip()
        assert out == 'cslnb', 'all piles zero => first player cannot move, must output cslnb'

def test_brute_force_small(run, x):
    import sys
    sys.setrecursionlimit(10000)
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    n = int(lines[0].strip())
    a = list(map(int, lines[1].strip().split()))
    if n > 6 or max(a) > 10:
        # too big for brute-force
        return
    from functools import lru_cache
    @lru_cache(None)
    def win(state):
        # state is tuple of sorted pile sizes
        if all(v == 0 for v in state):
            return False  # current player loses because no move and it's his turn? Actually, if all piles empty before his turn, he loses. That means if state is all zeros, the previous player already won? In our recursion, win(state) returns True if current player can force a win. At start, it's Tokitsukaze's turn.
            # But spec: A player loses if all of the piles are empty before his turn.
            # So if state is all zeros, the game already ended; we shouldn't reach this state as a current player's turn.
            # So we treat as losing for the player who would be to move? Actually, we only call win on states reachable where it's someone's turn.
            # Since you cannot move from all zeros, the player whose turn it is loses immediately.
            return False
        # generate moves
        for i, val in enumerate(state):
            if val == 0:
                continue
            new_list = list(state)
            new_list[i] = val - 1
            new_state = tuple(sorted(new_list))
            # check if after move there are two piles with same number
            if len(set(new_state)) != len(new_state):
                continue  # move illegal
            if not win(new_state):
                return True
        return False
    initial = tuple(sorted(a))
    expected = 'sjfnb' if win(initial) else 'cslnb'
    out = run(x).strip()
    assert out == expected, f'brute-force expects {expected}, got {out}'

def test_no_extra_whitespace(run, x):
    out = run(x)
    stripped = out.strip()
    # there should be no extra spaces before or after
    lines = out.split('\n')
    # after stripping, only one non-empty line
    non_empty = [line for line in lines if line.strip()!='']
    assert len(non_empty) == 1, 'output should have exactly one non-empty line'
    assert non_empty[0] == stripped, 'extra whitespace in line'

def test_case_sensitive(run, x):
    out = run(x).strip()
    assert out in {'sjfnb', 'cslnb'}, 'output must be exactly sjfnb or cslnb (case-sensitive)'
    # ensure no lowercase/uppercase mix
    if out == 'sjfnb':
        assert out.islower()
    else:
        assert out.islower()  # cslnb is also all lowercase

def test_output_length(run, x):
    out = run(x).strip()
    assert len(out) in (5, 6), 'output length must be 5 (cslnb) or 6 (sjfnb)'
    if len(out) == 5:
        assert out == 'cslnb'
    else:
        assert out == 'sjfnb'

