tests_src:
def test_output_is_integer(run, x):
    out = run(x).strip()
    assert out.lstrip('-').isdigit(), 'Output must be an integer'

def test_negative_one_only_if_impossible(run, x):
    n, m, k = map(int, x.strip().split())
    out = run(x).strip()
    if out == '-1':
        # If impossible, then k > (n-1)+(m-1) because each cut can at most separate one row or column
        assert k > (n-1)+(m-1), 'Should not output -1 if cuts are possible'

def test_answer_non_negative(run, x):
    out = run(x).strip()
    if out != '-1':
        ans = int(out)
        assert ans >= 0, 'Answer must be non-negative'

def test_answer_does_not_exceed_area(run, x):
    n, m, k = map(int, x.strip().split())
    out = run(x).strip()
    if out != '-1':
        ans = int(out)
        assert ans <= n * m, 'Answer cannot exceed total area'

def test_answer_divides_area_if_positive(run, x):
    n, m, k = map(int, x.strip().split())
    out = run(x).strip()
    if out != '-1':
        ans = int(out)
        if ans > 0:
            area = n * m
            assert area % ans == 0, 'If answer>0, it must divide total area because pieces are formed by full unit squares'

def test_upper_bound_k_plus_one(run, x):
    n, m, k = map(int, x.strip().split())
    out = run(x).strip()
    if out != '-1':
        ans = int(out)
        # After k cuts, there are at most k+1 pieces, so the smallest piece cannot exceed area/(k+1)
        assert ans <= (n * m) // (k + 1) if (k + 1) <= n * m else True, 'Smallest piece cannot exceed total area divided by (k+1)'

def test_small_inputs_bruteforce(run, x):
    n, m, k = map(int, x.strip().split())
    # Only run brute-force for very small sizes where we can enumerate all cuts
    if n <= 3 and m <= 3 and k <= 5:
        # Brute-force simulation of cuts is complex; instead we compute the answer by reasoning:
        # We can only cut between rows/columns, so cuts are at most (n-1)+(m-1).
        max_cuts = (n-1)+(m-1)
        if k > max_cuts:
            expected = -1
        else:
            # The optimal strategy is to distribute cuts between rows and columns to maximize the smallest piece.
            # For small n,m we can compute by trying all splits of cuts into horizontal (h) and vertical (v).
            best = 0
            for h in range(min(k, n-1)+1):
                v = k - h
                if v > m-1:
                    continue
                rows = h + 1
                cols = v + 1
                piece = (n // rows) * (m // cols)
                if piece > best:
                    best = piece
            expected = best
        out = run(x).strip()
        assert out == str(expected), f'For small input, answer must be optimal'

def test_answer_not_zero_unless_area_zero(run, x):
    n, m, k = map(int, x.strip().split())
    out = run(x).strip()
    if out != '-1':
        ans = int(out)
        if n > 0 and m > 0:
            assert ans > 0, 'Answer should be positive if cuts are possible and area>0'

def test_impossible_if_k_too_large(run, x):
    n, m, k = map(int, x.strip().split())
    max_cuts = (n-1)+(m-1)
    out = run(x).strip()
    if k > max_cuts:
        assert out == '-1', f'Must output -1 when k > (n-1)+(m-1)'

def test_answer_consistent_with_possible_cuts(run, x):
    n, m, k = map(int, x.strip().split())
    out = run(x).strip()
    if out != '-1':
        ans = int(out)
        max_cuts = (n-1)+(m-1)
        assert k <= max_cuts, 'Output not -1 but cuts are impossible'

