def test_answer_is_integer_or_minus_one(run, x):
    out = run(x).strip()
    if out == '-1':
        return
    # otherwise it must be an integer
    int(out)

def test_answer_not_negative(run, x):
    out = run(x).strip()
    if out == '-1':
        return
    assert int(out) >= 0

def test_answer_leq_sum_all_flight_costs(run, x):
    out = run(x).strip()
    if out == '-1':
        return
    # parse flights
    lines = x.strip().split('\n')
    n, m, k = map(int, lines[0].split())
    total = 0
    for i in range(1, m+1):
        _, _, _, c = map(int, lines[i].split())
        total += c
    # any solution uses a subset of flights, cost cannot exceed sum of all costs
    assert int(out) <= total

def test_answer_geq_min_possible_for_each_city(run, x):
    out = run(x).strip()
    if out == '-1':
        return
    lines = x.strip().split('\n')
    n, m, k = map(int, lines[0].split())
    INF = 10**18
    min_to = [INF] * (n+1)
    min_back = [INF] * (n+1)
    for i in range(1, m+1):
        d, f, t, c = map(int, lines[i].split())
        if t == 0:  # flight to Metropolis
            if c < min_to[f]:
                min_to[f] = c
        else:  # flight from Metropolis
            if c < min_back[t]:
                min_back[t] = c
    min_cost = 0
    for city in range(1, n+1):
        if min_to[city] == INF or min_back[city] == INF:
            # impossible for this city, but overall answer might still be -1?
            # but since answer is not -1, each city must have both flights.
            # Actually the specification says if impossible output -1.
            # So if answer is not -1, then every city must have both directions.
            # We'll just compute a lower bound assuming missing flights mean INF.
            pass
        else:
            min_cost += min_to[city] + min_back[city]
    # The answer must be at least this sum, because each city needs at least one to and one back flight.
    if min_cost < INF:
        assert int(out) >= min_cost

def test_answer_modulo_trivial_case(run, x):
    lines = x.strip().split('\n')
    n, m, k = map(int, lines[0].split())
    if n == 0:
        # n >= 1 per spec, but guard anyway
        return
    if m == 0:
        # no flights -> impossible
        out = run(x).strip()
        assert out == '-1'

def test_answer_parity_and_small_input_bruteforce(run, x):
    # only run brute force if input is small
    lines = x.strip().split('\n')
    n, m, k = map(int, lines[0].split())
    if n > 4 or m > 8:
        return
    # brute force over subsets of flights? That's exponential in m.
    # Instead, brute force over days for each city.
    # Since n small, we can enumerate all possible arrival/departure days.
    # This is a full verification, so we compute the exact answer.
    from itertools import product
    INF = 10**18
    flights = []
    for i in range(1, m+1):
        d, f, t, c = map(int, lines[i].split())
        flights.append((d, f, t, c))
    best = INF
    # each city choose a to-flight and a back-flight
    to_flights = [[] for _ in range(n+1)]
    back_flights = [[] for _ in range(n+1)]
    for (d, f, t, c) in flights:
        if t == 0:
            to_flights[f].append((d, c))
        else:
            back_flights[t].append((d, c))
    # check each city has at least one to and one back
    for city in range(1, n+1):
        if not to_flights[city] or not back_flights[city]:
            best = -1  # impossible
            break
    if best != -1:
        # generate all combinations
        choices = []
        for city in range(1, n+1):
            choices.append(city)
        # we need to pick one to and one back for each city
        # product over cities
        def dfs(city_idx, cur_cost, earliest_back, latest_arr):
            nonlocal best
            if city_idx > n:
                # all cities chosen
                # check that there is a window of at least k days between latest arrival and earliest departure
                if earliest_back - latest_arr > k:
                    best = min(best, cur_cost)
                return
            city = city_idx
            for (d_arr, c_arr) in to_flights[city]:
                for (d_dep, c_dep) in back_flights[city]:
                    if d_arr >= d_dep:
                        continue  # arrival must be before departure
                    dfs(city_idx+1, cur_cost + c_arr + c_dep, min(earliest_back, d_dep), max(latest_arr, d_arr))
        dfs(1, 0, 10**9, 0)
        if best == INF:
            best = -1
    out = run(x).strip()
    if out == '-1':
        assert best == -1
    else:
        assert int(out) == best

def test_answer_consistent_with_cheapest_per_city_if_one_day(run, x):
    lines = x.strip().split('\n')
    n, m, k = map(int, lines[0].split())
    if k != 1:
        return
    # For k=1, any pair of arrival before departure with at least one day in between works.
    # But we can still check a lower bound: each city needs at least cheapest to and cheapest back.
    INF = 10**18
    min_to = [INF] * (n+1)
    min_back = [INF] * (n+1)
    for i in range(1, m+1):
        d, f, t, c = map(int, lines[i].split())
        if t == 0:
            if c < min_to[f]:
                min_to[f] = c
        else:
            if c < min_back[t]:
                min_back[t] = c
    min_possible = 0
    for city in range(1, n+1):
        if min_to[city] == INF or min_back[city] == INF:
            min_possible = INF
            break
        min_possible += min_to[city] + min_back[city]
    out = run(x).strip()
    if out == '-1':
        # then at least one city missing a flight
        assert min_possible == INF
    else:
        # answer must be >= min_possible
        if min_possible < INF:
            assert int(out) >= min_possible

def test_answer_not_zero_unless_zero_cost_flights(run, x):
    out = run(x).strip()
    if out == '-1':
        return
    if int(out) == 0:
        # check if any flight has cost 0
        lines = x.strip().split('\n')
        n, m, k = map(int, lines[0].split())
        has_zero = False
        for i in range(1, m+1):
            _, _, _, c = map(int, lines[i].split())
            if c == 0:
                has_zero = True
                break
        # spec says c_i >= 1, so no zero-cost flights
        assert False, "cost cannot be zero because all c_i >= 1"

def test_answer_fits_64bit(run, x):
    out = run(x).strip()
    if out == '-1':
        return
    val = int(out)
    # maximum possible: n=1e5, each flight cost up to 1e6, each city needs at least two flights
    # but could be more flights if staying extra days, but total cost cannot exceed sum of all flight costs.
    # sum of all flight costs <= m * 1e6 <= 1e5 * 1e6 = 1e11, which fits in 64-bit.
    # We just ensure it's not ridiculously huge (e.g., overflow).
    assert val <= 10**18  # generous bound

def test_answer_days_order_ignored(run, x):
    # This test does not re-run with permuted input; instead, it checks that if we have
    # a flight that arrives after another flight departs for the same city, the answer
    # should not be less than the sum of the cheapest pair that satisfies the k-day gap.
    # However, constructing that check without re-running is tricky.
    # Instead, we do a simple sanity: if there is only one city and one to/one back flight,
    # and they are spaced exactly k+1 days apart, the answer must be sum of their costs.
    lines = x.strip().split('\n')
    n, m, k = map(int, lines[0].split())
    if n != 1 or m != 2:
        return
    f1 = list(map(int, lines[1].split()))
    f2 = list(map(int, lines[2].split()))
    # ensure one to and one back
    to = None
    back = None
    for d, f, t, c in [f1, f2]:
        if t == 0:
            to = (d, c)
        else:
            back = (d, c)
    if to is None or back is None:
        return
    arr_day, arr_cost = to
    dep_day, dep_cost = back
    if arr_day < dep_day and dep_day - arr_day > k:
        # then the only possible cost is arr_cost + dep_cost
        out = run(x).strip()
        if out != '-1':
            assert int(out) == arr_cost + dep_cost
    # otherwise there might be other flights (but m=2), so it's fine.

