        return  # only for even k
    piles = list(map(int, data[1].split()))[:n]
    if any(p > 10 for p in piles):
        return  # too large for brute-force
    # Simulate impartial game via recursion with memoization.
    from functools import lru_cache
    @lru_cache(None)
    def grundy(p):
        if p == 0:
            return 0
        moves = {grundy(p-1)}
        if p % 2 == 0:
            moves.add(grundy(p//2) if k == 1 else 0)  # For k even, splitting yields k piles of size p/2, Grundy is xor of k copies.
            # Since k is even, xor of an even number of copies of g is 0.
            # Actually, when k is even, the move from 2x to k piles of x gives Grundy = (grundy(x) XOR ... XOR grundy(x)) (k times) = 0 if k even.
            # So the move contributes Grundy 0, which is already in the set via grundy(p-1) possibly.
            # But we must compute correctly. Let's compute properly for small p.
        # We'll instead compute by brute-force simulation of moves.
        # Recompute moves set correctly.
        moves = set()
        # move type 1: remove one cow
        moves.add(grundy(p-1))
        # move type 2: split even pile into k piles of size p//2
        if p % 2 == 0:
            g = grundy(p//2)
            if k % 2 == 0:
                moves.add(0)          # xor of even copies of g is 0
            else:
                moves.add(g)          # xor of odd copies of g is g
        # mex
        g = 0
        while g in moves:
            g += 1
        return g
    # Compute overall XOR
    xor_sum = 0
    for p in piles:
        xor_sum ^= grundy(p)
