def test_output_format(run, x):
    out = run(x).strip()
    assert out.lower() in ['yes', 'no'], f'Output must be "Yes" or "No", got "{out}"'

def test_example_1(run, x):
    if x == '3\n101\n':
        assert run(x).strip().lower() == 'yes', 'Example 1 must output Yes'

def test_example_2(run, x):
    if x == '4\n1011\n':
        assert run(x).strip().lower() == 'no', 'Example 2 must output No'

def test_example_3(run, x):
    if x == '5\n10001\n':
        assert run(x).strip().lower() == 'no', 'Example 3 must output No'

def test_no_adjacent_occupied_if_yes(run, x):
    out = run(x).strip().lower()
    if out == 'yes':
        lines = x.strip().split('\n')
        n = int(lines[0])
        s = lines[1]
        # Check no '11' in the original string
        assert '11' not in s, 'If output is Yes, there cannot be adjacent occupied chairs'

def test_no_three_empty_consecutive_if_yes(run, x):
    out = run(x).strip().lower()
    if out == 'yes':
        lines = x.strip().split('\n')
        n = int(lines[0])
        s = lines[1]
        padded = '0' + s + '0'
        # If there is a gap of three zeros, one more person can be seated
        assert '000' not in padded, 'If output is Yes, there cannot be three consecutive empty chairs (including boundaries)'

def test_yes_implies_maximal_condition(run, x):
    out = run(x).strip().lower()
    if out == 'yes':
        lines = x.strip().split('\n')
        n = int(lines[0])
        s = lines[1]
        # Check condition 1: no adjacent occupied (already tested above, but repeat for completeness)
        if '11' in s:
            assert False, 'Yes output but adjacent occupied chairs found'
        # Check condition 2: cannot seat another person
        # Try every position: if empty and both neighbors (if exist) are empty, then we could seat someone
        for i in range(n):
            if s[i] == '0':
                left_ok = (i == 0) or s[i-1] == '0'
                right_ok = (i == n-1) or s[i+1] == '0'
                if left_ok and right_ok:
                    # This seat is available for seating -> not maximal
                    assert False, f'Yes output but seat {i} is available for seating'
        # If loop passes, condition 2 holds

def test_no_implies_violation(run, x):
    out = run(x).strip().lower()
    if out == 'no':
        lines = x.strip().split('\n')
        n = int(lines[0])
        s = lines[1]
        padded = '0' + s + '0'
        # Either there is '11' (adjacent occupied) or there is '000' (three consecutive empty allowing another person)
        # Edge case n=1: '0' is not maximal (can seat someone) -> output No, but padded = '000'? Actually padded = '0' + '0' + '0' = '000' includes '000', so condition holds.
        # Edge case n=1 with '1' is maximal -> output Yes, not covered here.
        # So for No, at least one of the two violations must occur.
        if '11' not in s and '000' not in padded:
            # No obvious violation, but maybe n=2 special case? For n=2, '00' padded = '0000' -> contains '000', so condition holds.
            # If still no violation, then the output No is suspicious.
            assert False, 'No output but no adjacent occupied chairs and no three consecutive empty chairs found'

def test_single_chair_0(run, x):
    if x == '1\n0\n':
        # One empty chair: not maximal because we can seat someone
        assert run(x).strip().lower() == 'no', 'Single empty chair must be No'

def test_single_chair_1(run, x):
    if x == '1\n1\n':
        # One occupied chair: maximal (no neighbors, cannot seat another)
        assert run(x).strip().lower() == 'yes', 'Single occupied chair must be Yes'

