def test_output_is_yes_or_no(run, x):
    out = run(x).strip()
    assert out.upper() in ('YES', 'NO'), f'Output must be YES or NO, got {out}'

def test_example1(run, x):
    if x.strip() == '2\n1 2':
        out = run(x).strip().upper()
        assert out == 'YES', f'For n=2 edge tree, answer must be YES, got {out}'

def test_example2(run, x):
    if x.strip() == '3\n1 2\n2 3':
        out = run(x).strip().upper()
        assert out == 'NO', f'For path of 3 nodes, answer must be NO, got {out}'

def test_star_center_degree_gt2(run, x):
    # If tree is a star with center degree >=3, answer must be NO (example 3)
    # Parse edges
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    n = int(lines[0])
    if n <= 2:
        return
    deg = [0] * n
    for line in lines[1:]:
        if not line:
            continue
        a, b = map(int, line.split())
        deg[a-1] += 1
        deg[b-1] += 1
    # check if it's a star: one node degree == n-1, others degree == 1
    if max(deg) == n-1 and deg.count(1) == n-1:
        out = run(x).strip().upper()
        assert out == 'NO', f'Star with center degree {n-1} must output NO, got {out}'

def test_example3_input(run, x):
    if x.strip() == '5\n1 2\n1 3\n1 4\n2 5':
        out = run(x).strip().upper()
        assert out == 'NO', f'For example 3 input, answer must be NO, got {out}'

def test_path_length_gt2(run, x):
    # For a simple path of more than 2 nodes, answer must be NO
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    n = int(lines[0])
    if n <= 2:
        return
    deg = [0] * n
    edges = []
    for line in lines[1:]:
        if not line:
            continue
        a, b = map(int, line.split())
        edges.append((a-1, b-1))
        deg[a-1] += 1
        deg[b-1] += 1
    # Check if it's a path: exactly two nodes degree 1, rest degree 2
    if deg.count(1) == 2 and deg.count(2) == n-2:
        out = run(x).strip().upper()
        assert out == 'NO', f'Path with n>2 must output NO, got {out}'

def test_two_leaves_only(run, x):
    # If tree has exactly two leaves (a path), answer must be NO for n>2
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    n = int(lines[0])
    if n == 2:
        return
    deg = [0] * n
    for line in lines[1:]:
        if not line:
            continue
        a, b = map(int, line.split())
        deg[a-1] += 1
        deg[b-1] += 1
    leaves = sum(1 for d in deg if d == 1)
    if leaves == 2:
        out = run(x).strip().upper()
        assert out == 'NO', f'Tree with exactly two leaves (path) must output NO for n>2, got {out}'

def test_answer_no_if_any_node_degree_2(run, x):
    # Actually the problem's condition is more subtle, but we test a known property from examples:
    # For the given examples, if there is any node with degree 2, answer is NO? Not always true (see star).
    # So we skip this to avoid false positives.
    # Instead we check that for a caterpillar with exactly two leaves? Too complex.
    # We'll leave this as a placeholder and just pass.
    pass

