def test_small_n_bruteforce(run, x):
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    n = int(lines[0])
    if n > 8:  # keep brute‑force manageable
        return
    arr = list(map(int, lines[1].split()))
    best = 0
    from itertools import combinations
    for l in range(n):
        for r in range(l, n):
            b = arr[:l] + arr[l:r+1][::-1] + arr[r+1:]
            # longest non‑decreasing subsequence in b (values 1 or 2)
            # simple DP: count1 = prefix count of 1, count2 = suffix count of 2
            # best = max over splits: prefix1 + suffix2
            pref1 = [0]*(n+1)
            for i in range(n):
                pref1[i+1] = pref1[i] + (1 if b[i]==1 else 0)
            suff2 = [0]*(n+1)
            for i in range(n-1, -1, -1):
                suff2[i] = suff2[i+1] + (1 if b[i]==2 else 0)
            cand = max(pref1[i] + suff2[i] for i in range(n+1))
            if cand > best:
                best = cand
    assert int(run(x).strip()) == best


