        return bal == 0
    correct_rev = 0
    for i in range(n):
        lst = list(rev_flipped)
        lst[i] = '(' if lst[i] == ')' else ')'
        if is_regular(''.join(lst)):
            correct_rev += 1
    ans = int(run(x).strip())
    assert ans == correct_rev, f'symmetry mismatch: original answer {ans}, reversed‑flipped brute‑force {correct_rev}'"
    },
