      "source": "def test_prefix_balance_nonnegative(run, x):
    # For a regular sequence, every prefix balance must be ≥0.
    # When p=+2, flipping a ')' to '(' cannot create a negative prefix.
    # When p=-2, flipping a '(' to ')' cannot create a negative prefix.
    # This test is weak but catches some impossible answers.
    # We just check that the reported answer is plausible by brute‑force when n≤20.
    n_str, s_str = x.strip().split('\n')
    n = int(n_str)
    if n > 20:
        return
    p = s_str.count('(') - s_str.count(')')
    if abs(p) != 2:
        return
    ans = int(run(x).strip())
    # enumerate all positions that could be flipped to regular
    def is_regular(t):
