tests_src:
def test_output_is_nonnegative_integer(run, x):
    out = run(x).strip()
    val = int(out)
    assert val >= 0

def test_output_does_not_exceed_N(run, x):
    n, _, _ = map(int, x.strip().split())
    out = int(run(x).strip())
    assert out <= n

def test_output_upper_bound_by_cycles(run, x):
    n, a, b = map(int, x.strip().split())
    if a == 0:
        return
    cycles = n // (a + b)
    remainder = n % (a + b)
    max_possible = a * cycles + min(remainder, a)
    out = int(run(x).strip())
    assert out <= max_possible

def test_small_N_bruteforce(run, x):
    n, a, b = map(int, x.strip().split())
    if n > 10**6:
        return
    # simulate first n balls
    blue = 0
    pos = 0
    while pos < n:
        for _ in range(a):
            if pos >= n:
                break
            blue += 1
            pos += 1
        for _ in range(b):
            if pos >= n:
                break
            pos += 1
    out = int(run(x).strip())
    assert out == blue

def test_A_zero_implies_zero(run, x):
    n, a, b = map(int, x.strip().split())
    if a == 0:
        out = int(run(x).strip())
        assert out == 0

def test_B_zero_bruteforce_small(run, x):
    n, a, b = map(int, x.strip().split())
    if b != 0 or n > 10**6:
        return
    # only blue balls placed each cycle
    blue = 0
    pos = 0
    while pos < n:
        for _ in range(a):
            if pos >= n:
                break
            blue += 1
            pos += 1
    out = int(run(x).strip())
    assert out == blue

def test_exact_cycle_multiple(run, x):
    n, a, b = map(int, x.strip().split())
    if a + b == 0:
        return
    if n % (a + b) == 0:
        expected = a * (n // (a + b))
        out = int(run(x).strip())
        assert out == expected

def test_N_le_A_implies_N(run, x):
    n, a, b = map(int, x.strip().split())
    if a > 0 and n <= a:
        out = int(run(x).strip())
        assert out == n

def test_output_integer_printable(run, x):
    out = run(x).strip()
    # check it's a valid integer without extra whitespace
    int(out)
    assert out == str(int(out))

def test_lower_bound_by_full_cycles(run, x):
    n, a, b = map(int, x.strip().split())
    cycles = n // (a + b)
    lower = a * cycles
    out = int(run(x).strip())
    assert out >= lower

