def test_output_is_integer(run, x):
    out = run(x).strip()
    # Must parse as int
    int(out)

def test_positive_if_not_minus_one(run, x):
    out = run(x).strip()
    val = int(out)
    if val != -1:
        assert val > 0

def test_k_equals_1(run, x):
    if x.strip() == '1':
        out = run(x).strip()
        assert out == '1'

def test_k_equals_7(run, x):
    if x.strip() == '7':
        out = run(x).strip()
        assert out == '1'

def test_power_of_10_is_minus_one(run, x):
    k = int(x.strip())
    # Check if k is a power of 10
    if k > 0 and (k == 10**len(str(k).rstrip('0'))):
        out = run(x).strip()
        assert out == '-1'

def test_small_k_bruteforce(run, x):
    k = int(x.strip())
    if k <= 1000:
        # Brute-force sequence until k+1 terms (by pigeonhole principle)
        r = 0
        for i in range(1, k+2):
            r = (10 * r + 7) % k
            if r == 0:
                expected = str(i)
                break
        else:
            expected = '-1'
        out = run(x).strip()
        assert out == expected

def test_if_not_minus_one_then_mod_zero(run, x):
    k = int(x.strip())
    out = run(x).strip()
    if out != '-1':
        pos = int(out)
        # Compute the pos-th term mod k
        r = 0
        for _ in range(pos):
            r = (10 * r + 7) % k
        assert r == 0

def test_answer_le_k_if_found(run, x):
    out = run(x).strip()
    if out != '-1':
        pos = int(out)
        k = int(x.strip())
        assert 1 <= pos <= k

def test_even_k_greater_2_is_minus_one(run, x):
    k = int(x.strip())
    if k > 2 and k % 2 == 0:
        out = run(x).strip()
        assert out == '-1'

def test_k_divisible_by_5_is_minus_one(run, x):
    k = int(x.strip())
    if k % 5 == 0 and k > 0:
        out = run(x).strip()
        assert out == '-1'

