def test_distances_non_decreasing_after_zero(run, x):
    lines = x.strip().split('\n')
    a = list(map(int, lines[1].split()))
    output = run(x).strip()
    distances = list(map(int, output.split()))
    n = len(a)
    # from left to right
    last_zero = -float('inf')
    for i in range(n):
        if a[i] == 0:
            last_zero = i
