                # not necessarily an error because there could be a closer zero on the right
                pass  # we cannot assert equality without solving
    # symmetric from right to left
    next_zero = float('inf')
    for i in range(n-1, -1, -1):
        if a[i] == 0:
            next_zero = i
        if next_zero != float('inf'):
            expected_min = next_zero - i
            if distances[i] > expected_min:
                pass
    # but we can assert that distances[i] ≤ min(i - last_zero, next_zero - i) if both exist
    for i in range(n):
        left_dist = float('inf')
        for j in range(i, -1, -1):
