def test_output_format(run, x):
    output = run(x)
    assert output in ('Yes\n', 'No\n'), f'Output must be Yes\n or No\n, got {repr(output)}'

def test_known_sample_11(run, x):
    if x == '11\n':
        assert run(x) == 'Yes\n', 'For N=11, answer must be Yes'

def test_known_sample_1(run, x):
    if x == '1\n':
        assert run(x) == 'No\n', 'For N=1, answer must be No'

def test_known_sample_4(run, x):
    if x == '4\n':
        assert run(x) == 'Yes\n', 'For N=4, answer must be Yes'

def test_brute_force_small(run, x):
    N = int(x.strip())
    # Brute-force check if any combination of cakes (4) and doughnuts (7) equals N
    possible = False
    for i in range(N // 4 + 1):
        for j in range(N // 7 + 1):
            if 4 * i + 7 * j == N:
                possible = True
                break
        if possible:
            break
    expected = 'Yes\n' if possible else 'No\n'
    assert run(x) == expected, f'For N={N}, expected {expected.strip()}'

def test_answer_consistent_with_mod(run, x):
    # If answer is Yes, then N must be representable as 4a+7b, so N mod gcd(4,7)=1 must be possible.
    # But this is not a necessary condition because all residues modulo 1 are possible.
    # Instead, we check that if output is Yes, then N must be >= 4 or >=7 or 0, but spec allows zero of each, so N can be 0? No, N between 1 and 100.
    # Actually, we can check a known necessary condition: if N is less than 4 and not 0, answer must be No.
    N = int(x.strip())
    output = run(x)
    if N < 4 and N != 0:
        assert output == 'No\n', f'For N={N} < 4, answer must be No'

def test_output_no_extra_spaces(run, x):
    output = run(x)
    assert output.endswith('\n'), 'Output must end with newline'
    stripped = output.strip()
    assert stripped in ('Yes', 'No'), f'Stripped output must be Yes or No, got {stripped}'

def test_answer_parity_not_required(run, x):
    # No parity condition is forced, but we can check that output is not empty.
    output = run(x)
    assert len(output) >= 3, 'Output too short'  # 'Yes\n' or 'No\n' are at least 3 chars
    # This is a weak sanity check.

def test_against_brute_force_up_to_30(run, x):
    N = int(x.strip())
    if N <= 30:  # Keep it small, but our inputs are all <=100, this is fine
        possible = False
        for i in range(N // 4 + 1):
            for j in range(N // 7 + 1):
                if 4 * i + 7 * j == N:
                    possible = True
                    break
            if possible:
                break
        expected = 'Yes\n' if possible else 'No\n'
        assert run(x) == expected, f'For N={N}, brute-force says {expected.strip()}'

def test_no_impossible_high_values(run, x):
    # For N >= 4*7 - 4 - 7 + 1 = 18, every integer is representable as 4a+7b? Not exactly, but the Frobenius number for 4,7 is 4*7 -4 -7 = 17, so every N >= 18 is representable.
