def test_output_format(run, x):
    output = run(x)
    assert output in ('Yes\n', 'No\n'), f'Output must be exactly Yes\\n or No\\n, got {repr(output)}'

def test_no_on_1_2_3(run, x):
    n = int(x.strip())
    if n in (1, 2, 3):
        assert run(x) == 'No\n', f'N={n} is impossible, must output No'

def test_yes_implies_n_ge_4(run, x):
    n = int(x.strip())
    if run(x) == 'Yes\n':
        assert n >= 4, f'Output Yes but N={n} < 4'

def test_brute_force_verification(run, x):
    n = int(x.strip())
    # brute‑force correct answer for N up to 100 (well within limits)
    possible = False
    for i in range(0, n // 4 + 1):
        for j in range(0, n // 7 + 1):
            if i == 0 and j == 0:
                continue
            if 4 * i + 7 * j == n:
                possible = True
                break
        if possible:
            break
    expected = 'Yes\n' if possible else 'No\n'
    assert run(x) == expected, f'For N={n}, expected {expected.strip()}, got {run(x).strip()}'

def test_answer_is_deterministic(run, x):
    # run is a callable that always runs the same program on the same input;
    # but we can still check that the same run call returns the same string
    out1 = run(x)
    out2 = run(x)  # calling run again is allowed because it's the same input
    assert out1 == out2, f'Output changed between calls: {repr(out1)} vs {repr(out2)}'

def test_no_for_prime_under_4(run, x):
    n = int(x.strip())
    if n == 2 or n == 3:
        assert run(x) == 'No\n', f'Prime N={n} <4 cannot be made with 4 and 7'

def test_yes_for_4(run, x):
    n = int(x.strip())
    if n == 4:
        assert run(x) == 'Yes\n', f'N=4 can be made with one cake'

def test_yes_for_7(run, x):
    n = int(x.strip())
    if n == 7:
        assert run(x) == 'Yes\n', f'N=7 can be made with one doughnut'

def test_yes_for_8(run, x):
    n = int(x.strip())
    if n == 8:
        assert run(x) == 'Yes\n', f'N=8 can be made with two cakes'

def test_same_input_same_output(run, x):
    # trivial consistency: the same x should produce the same output
    # (this is weaker than determinism across runs, but still a spec requirement)
    out = run(x)
    # no need to assert anything else, just ensure run doesn't crash
    # This test is weak; I'd drop it first if needed.
    pass

