tests_src:
def test_output_format(run, x):
    out = run(x).strip()
    assert out in ('Yes', 'No'), f'Output must be Yes or No, got {repr(out)}'

def test_no_extra_output(run, x):
    out = run(x)
    lines = out.strip().split('\n')
    assert len(lines) == 1, f'Expected exactly one line, got {len(lines)}'

def test_answer_starts_with_Y_or_N(run, x):
    out = run(x).strip()
    assert out == '' or out[0] in 'YN', f'Output must start with Y or N, got {repr(out)}'

def test_case_sensitive(run, x):
    out = run(x).strip()
    if out:
        assert out in ('Yes', 'No'), f'Output must be exactly Yes or No, got {repr(out)}'

def test_no_when_impossible_length(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    if n < 3:
        # This never happens because N >= 3, but keeping for safety
        out = run(x).strip()
        assert out == 'No', f'For N < 3 answer must be No, got {out}'
    # else no assertion

def test_yes_if_all_pairs_doublets(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    if n >= 3:
        all_doublets = True
        for i in range(1, n+1):
            parts = lines[i].split()
            if len(parts) >= 2:
                a, b = parts[0], parts[1]
                if a != b:
                    all_doublets = False
                    break
        if all_doublets:
            out = run(x).strip()
            assert out == 'Yes', f'All rolls are doublets, must output Yes, got {out}'

def test_no_if_no_doublets_at_all(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    any_doublet = False
    for i in range(1, n+1):
        parts = lines[i].split()
        if len(parts) >= 2:
            a, b = parts[0], parts[1]
            if a == b:
                any_doublet = True
                break
    if not any_doublet:
        out = run(x).strip()
        assert out == 'No', f'No doublets at all, must output No, got {out}'

def test_yes_if_three_consecutive_doublets_by_parsing(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    if n < 3:
        return
    found = False
    for i in range(1, n-1):
        parts1 = lines[i].split()
        parts2 = lines[i+1].split()
        parts3 = lines[i+2].split()
        if len(parts1) >= 2 and len(parts2) >= 2 and len(parts3) >= 2:
            if parts1[0] == parts1[1] and parts2[0] == parts2[1] and parts3[0] == parts3[1]:
                found = True
                break
    if found:
        out = run(x).strip()
        assert out == 'Yes', f'Found three consecutive doublets, must output Yes, got {out}'

def test_no_if_no_three_consecutive_by_bruteforce_small(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    if n > 20:  # Keep brute‑force small
        return
    doublets = []
    for i in range(1, n+1):
        parts = lines[i].split()
        if len(parts) >= 2:
            doublets.append(parts[0] == parts[1])
    consecutive = False
    for i in range(len(doublets)-2):
        if doublets[i] and doublets[i+1] and doublets[i+2]:
            consecutive = True
            break
    if not consecutive:
        out = run(x).strip()
        assert out == 'No', f'No three consecutive doublets, must output No, got {out}'

def test_answer_matches_input_size(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    if len(lines) != n+1:
        # Input malformed? skip
        return
    out = run(x).strip()
    # No direct constraint, but we can at least ensure the answer is valid for any N>=3
    assert out in ('Yes', 'No'), f'Invalid answer {repr(out)} for N={n}'

