def test_output_format(run, x):
    out = run(x)
    assert out in ('Yes\n', 'No\n'), f'output must be Yes or No with newline, got {repr(out)}'

def test_yes_on_already_sorted(run, x):
    import sys
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    N = int(lines[0])
    if N == 0:
        return
    H = list(map(int, lines[1].split()))
    # check if already non‑decreasing
    ok = True
    for i in range(1, N):
        if H[i] < H[i-1]:
            ok = False
            break
    if ok:
        out = run(x)
        assert out == 'Yes\n', f'input already non‑decreasing, answer must be Yes, got {repr(out)}'

def test_no_on_large_drop(run, x):
    import sys
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    N = int(lines[0])
    if N <= 1:
        return
    H = list(map(int, lines[1].split()))
    # if there is an index where H[i] < H[i-1] - 1, even after decreasing H[i-1] by 1 we get H[i] < H[i-1]-1 <= (H[i-1]-1)-1 ?
    # Actually simpler: after decreasing any previous by at most 1, the max possible value for H[i-1] is H[i-1]; the min possible for H[i] is H[i]-1.
    # So if H[i] < H[i-1] - 1, then even after decreasing H[i] we have H[i]-1 < H[i-1]-1, i.e. still < H[i-1] (since we can also decrease H[i-1] by 1).
    # More directly: condition for impossible is when H[i] < H[i-1] - 1, because we cannot make H[i] >= H[i-1] after operations.
    for i in range(1, N):
        if H[i] < H[i-1] - 1:
            out = run(x)
            assert out == 'No\n', f'large drop at index {i}, answer must be No, got {repr(out)}'
            break

def test_no_if_first_cant_be_increased(run, x):
    import sys
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    N = int(lines[0])
    if N == 0:
        return
    H = list(map(int, lines[1].split()))
    # The first element can only be decreased, so if there exists an i such that H[i] < H[0] - 1, impossible.
    for i in range(1, N):
        if H[i] < H[0] - 1:
            out = run(x)
            assert out == 'No\n', f'element {i} too small compared to first, answer must be No, got {repr(out)}'
            break

def test_yes_on_all_equal(run, x):
    import sys
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    H = list(map(int, lines[1].split()))
    if len(H) == 0:
        return
    if all(h == H[0] for h in H):
        out = run(x)
        assert out == 'Yes\n', f'all heights equal, answer must be Yes, got {repr(out)}'

def test_no_on_strict_decreasing_by_more_than_one(run, x):
    import sys
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    H = list(map(int, lines[1].split()))
    for i in range(1, len(H)):
        if H[i] <= H[i-1] - 2:
            # This is essentially the same as large drop test, but we keep it.
            out = run(x)
            assert out == 'No\n', f'strict decreasing by >=2 at {i}, answer must be No, got {repr(out)}'
            break

def test_yes_when_always_ge_max_minus_one(run, x):
    import sys
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    H = list(map(int, lines[1].split()))
    if len(H) <= 1:
        return
    # If every element is at least the maximum seen so far minus 1, the greedy algorithm says Yes.
    # This is a sufficient condition, not necessary, so we cannot demand Yes.
    # But we can test: if this condition holds, answer must be Yes.
    ok = True
    cur_max = H[0]
    for h in H:
        if h < cur_max - 1:
            ok = False
            break
        cur_max = max(cur_max, h)
    if ok:
        out = run(x)
        assert out == 'Yes\n', f'always within 1 of running max, answer must be Yes, got {repr(out)}'

def test_brute_force_small(run, x):
    import sys
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    N = int(lines[0])
    if N > 10:   # brute force only for small N
        return
    H = list(map(int, lines[1].split()))
    # brute force over 2^N possibilities
    possible = False
    from itertools import product
    for mask in product([0, -1], repeat=N):
        arr = [H[i] + mask[i] for i in range(N)]
        if all(arr[i] <= arr[i+1] for i in range(N-1)):
            possible = True
            break
    expected = 'Yes\n' if possible else 'No\n'
    out = run(x)
    assert out == expected, f'brute force says {expected.strip()}, got {repr(out)}'

def test_no_if_prefix_decreasing_fast(run, x):
    import sys
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    H = list(map(int, lines[1].split()))
    # If we ever see H[i] < H[i-1] - 1, answer must be No.
    # This is already covered by test_no_on_large_drop, but we keep a variant.
    for i in range(1, len(H)):
        if H[i] < H[i-1] - 1:
            out = run(x)
            assert out == 'No\n', f'fast drop at {i}, answer must be No, got {repr(out)}'
            break

def test_yes_on_single_element(run, x):
    import sys
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    N = int(lines[0])
    if N == 1:
        out = run(x)
        assert out == 'Yes\n', f'single element always Yes, got {repr(out)}'

