    if T * S < D:
        out = run(x)
        assert out == 'No\n', f'When T*S < D, answer must be No, got {repr(out)}'

def test_yes_if_zero_distance(run, x):
    D, T, S = map(int, x.strip().split())
    if D == 0:
        out = run(x)
        assert out == 'Yes\n', f'When D=0, answer must be Yes, got {repr(out)}'

def test_yes_if_enough_time_even_with_slow_speed(run, x):
    D, T, S = map(int, x.strip().split())
    if S == 1 and T >= D:
        out = run(x)
        assert out == 'Yes\n', f'When speed is 1 m/min and T >= D, answer must be Yes, got {repr(out)}'

def test_no_if_time_zero(run, x):
    D, T, S = map(int, x.strip().split())
    if T == 0 and D > 0:
        out = run(x)
        assert out == 'No\n', f'When T=0 and D>0, answer must be No, got {repr(out)}'

def test_yes_when_distance_exactly_T_times_S(run, x):
    D, T, S = map(int, x.strip().split())
    if D == T * S:
        out = run(x)
        assert out == 'Yes\n', f'When D == T*S, answer must be Yes, got {repr(out)}'

def test_small_inputs_bruteforce(run, x):
    D, T, S = map(int, x.strip().split())
    if D <= 1000 and T <= 1000 and S <= 1000:
        # Direct computation using floating point to match specification's exact requirement
        time_needed = D / S
        expected = 'Yes\n' if time_needed <= T else 'No\n'
        out = run(x)
        assert out == expected, f'For small input, expected {repr(expected)} got {repr(out)}'

def test_no_if_one_minute_too_few(run, x):
    D, T, S = map(int, x.strip().split())
    if D > T * S:
        out = run(x)
        assert out == 'No\n', f'When D > T*S, answer must be No, got {repr(out)}'

def test_output_case_sensitive(run, x):
    out = run(x)
    assert out == 'Yes\n' or out == 'No\n', f'Output must be exactly Yes or No with capital first letter and newline'

def test_yes_when_time_large_enough(run, x):
