def test_output_is_float_between_0_and_1(run, x):
    out = run(x).strip()
    try:
        f = float(out)
    except ValueError:
        assert False, "Output must be a valid float"
    assert 0.0 <= f <= 1.0, "Probability must be between 0 and 1 inclusive"

def test_brute_force_small_N(run, x):
    N = int(x.strip())
    if N <= 20:
        odd_count = (N + 1) // 2
        expected = odd_count / N
        out = run(x).strip()
        got = float(out)
        if abs(got - expected) > 1e-9:
            assert False, f"For N={N}, expected {expected}, got {got}"

def test_even_N_exact_half(run, x):
    N = int(x.strip())
    if N % 2 == 0:
        out = run(x).strip()
        got = float(out)
        if abs(got - 0.5) > 1e-9:
            assert False, f"For even N={N}, probability must be exactly 0.5, got {got}"

def test_odd_N_formula(run, x):
    N = int(x.strip())
    if N % 2 == 1:
        M = N // 2
        expected = (M + 1) / N
        out = run(x).strip()
        got = float(out)
        if abs(got - expected) > 1e-9:
            assert False, f"For odd N={N}, expected {expected}, got {got}"

def test_output_parsable(run, x):
    out = run(x).strip()
    # Must be a single token
    tokens = out.split()
    assert len(tokens) == 1, "Output must be a single value"
    # Must be a float
    try:
        float(tokens[0])
    except ValueError:
        assert False, "Output must be a valid floating-point number"

def test_error_tolerance(run, x):
    N = int(x.strip())
    if N <= 30:
        odd_count = (N + 1) // 2
        expected = odd_count / N
        out = run(x).strip()
        got = float(out)
        diff = abs(got - expected)
        rel = diff / max(1.0, expected)
        if diff > 1e-6 and rel > 1e-6:
            assert False, f"Error too large: diff={diff}, rel={rel}"

def test_large_odd_above_half(run, x):
    N = int(x.strip())
    if N > 50 and N % 2 == 1:
        out = run(x).strip()
        got = float(out)
        if got <= 0.5:
            assert False, f"For large odd N={N}, probability must be >0.5, got {got}"

def test_monotonic(run, x):
    N = int(x.strip())
    out = run(x).strip()
    got = float(out)
    # For odd N, probability is (k+1)/(2k+1) where k = N//2
    # For even N, probability is 0.5
    # This test checks that when N increases by 1, probability decreases or stays same
    # Actually, probability decreases when going from odd to even, stays same from even to odd.
    # This is a property of the correct formula, not explicitly required by spec.
    # We'll just check consistency: if N is odd, probability > 0.5; if even, ==0.5.
    if N % 2 == 0:
        if abs(got - 0.5) > 1e-9:
            assert False, f"Even N must give 0.5, got {got}"
    else:
        if got <= 0.5:
            assert False, f"Odd N must give >0.5, got {got}"

def test_non_negative(run, x):
    out = run(x).strip()
    got = float(out)
    assert got >= 0.0, "Probability cannot be negative"

def test_rational_form(run, x):
    N = int(x.strip())
    out = run(x).strip()
    got = float(out)
    # The exact answer is rational: odd_count / N
    odd_count = (N + 1) // 2
    exact = odd_count / N
    # Check if got is exactly representable as odd_count/N up to 1e-12
    if abs(got - exact) > 1e-12:
        # Allow floating-point rounding, but if difference is large, suspect
        # Recompute using rational arithmetic
        if abs(got * N - odd_count) > 1e-9:
            assert False, f"Probability should be {odd_count}/{N} = {exact}, got {got}"

