def test_bound(run, x):
    # The answer must be an integer between 0 and N.
    out = run(x).strip()
    assert out.isdigit() or (out[0]=='-' and out[1:].isdigit())
    ans = int(out)
    lines = x.strip().split('\n')
    N = int(lines[0])
    assert 0 <= ans <= N

def test_no_testimonies_all_honest(run, x):
    # If every A_i is 0, the maximum honest persons is N.
    lines = x.strip().split('\n')
    N = int(lines[0])
    idx = 1
    all_zero = True
    for i in range(N):
        if idx >= len(lines):
            break
        a = int(lines[idx]); idx += 1
        if a != 0:
            all_zero = False
        idx += a  # skip testimonies
    if all_zero:
        assert int(run(x).strip()) == N

def test_single_person(run, x):
    # For N=1, there are no testimonies (since x_ij != i), so the answer must be 1.
    lines = x.strip().split('\n')
    N = int(lines[0])
    if N == 1:
        assert int(run(x).strip()) == 1

def test_contradiction_zero(run, x):
    # If there is a testimony from i about x saying y=1, and another from x about i saying y=0,
    # they cannot both be honest. This test doesn't compute the exact answer, but checks that
    # the answer is at most N-1 in such a contradictory pair.
    # We only apply if N is small (≤5) to keep it simple.
    lines = x.strip().split('\n')
    N = int(lines[0])
    if N > 5:
        return
    # Build testimonies.
    testimonies = [[] for _ in range(N)]
    idx = 1
    for i in range(N):
        a = int(lines[idx]); idx += 1
        for _ in range(a):
            xij, yij = map(int, lines[idx].split()); idx += 1
            testimonies[i].append((xij-1, yij))
    # Look for a direct contradiction: i says x is honest (1), x says i is unkind (0).
    contradiction = False
    for i in range(N):
        for (x, y) in testimonies[i]:
            if y == 1:
                # Check if x says i is unkind.
                for (x2, y2) in testimonies[x]:
                    if x2 == i and y2 == 0:
                        contradiction = True
                        break
        if contradiction:
            break
    if contradiction:
        assert int(run(x).strip()) <= N-1

def test_self_consistent_subset(run, x):
    # If we find a subset of persons S such that all testimonies from persons in S
    # are consistent with S being exactly the honest set, then the answer must be at least |S|.
    # We only check the subset of all persons (i.e., if everyone being honest is consistent).
    lines = x.strip().split('\n')
    N = int(lines[0])
    testimonies = [[] for _ in range(N)]
    idx = 1
    for i in range(N):
        a = int(lines[idx]); idx += 1
        for _ in range(a):
            xij, yij = map(int, lines[idx].split()); idx += 1
            testimonies[i].append((xij-1, yij))
    # Check consistency when everyone is honest.
    consistent = True
    for i in range(N):
        for (x, y) in testimonies[i]:
            if y != 1:  # if i says x is unkind, but x is honest (since all honest)
                consistent = False
                break
        if not consistent:
            break
    if consistent:
        assert int(run(x).strip()) == N

def test_brute_force_small(run, x):
    # For N ≤ 8, brute-force all subsets to compute the exact answer.
    lines = x.strip().split('\n')
    N = int(lines[0])
    if N > 8:
        return
    testimonies = [[] for _ in range(N)]
    idx = 1
    for i in range(N):
        a = int(lines[idx]); idx += 1
        for _ in range(a):
            xij, yij = map(int, lines[idx].split()); idx += 1
            testimonies[i].append((xij-1, yij))
    best = 0
    for mask in range(1 << N):
        ok = True
        for i in range(N):
            if (mask >> i) & 1:  # i is honest
