    out = run(x).strip()
    assert out.isdigit() or (out[0]=='-' and out[1:].isdigit())

def test_trivial_all_unkind(run, x):
    # The subset of zero honest persons is always consistent.
    # So answer must be at least 0.
    # Actually the bound test already ensures that, but we also check that if there is
    # a testimony from someone claiming another is honest, then all-unkind may be inconsistent.
    # However, we just ensure answer >=0.
    ans = int(run(x).strip())
    assert ans >= 0

def test_monotonicity_clique(run, x):
    # If we have a clique of k persons each testifying that all others are honest,
    # then at least k-1 can be honest (since if all k are honest, it's consistent).
    # Actually, if all k are honest, it's consistent, so answer >= k.
    # This is not a general property, but we detect a specific pattern.
    lines = x.strip().split('\n')
    N = int(lines[0])
    if N > 10:
        return
    testimonies = [[] for _ in range(N)]
    idx = 1
    for i in range(N):
        a = int(lines[idx]); idx += 1
        for _ in range(a):
            xij, yij = map(int, lines[idx].split()); idx += 1
            testimonies[i].append((xij-1, yij))
    # Find a clique of size k where each person in the clique testifies all others are honest.
    # We'll just check for a pair (i,j) with mutual testimonies of honesty.
    for i in range(N):
        for j in range(N):
            if i == j:
                continue
            i_says_j_honest = any(x==j and y==1 for (x,y) in testimonies[i])
            j_says_i_honest = any(x==i and y==1 for (x,y) in testimonies[j])
            if i_says_j_honest and j_says_i_honest:
