def test_output_is_safe_or_unsafe(run, x):
    out = run(x).strip()
    assert out in ['safe', 'unsafe'], f"Output must be 'safe' or 'unsafe', got {repr(out)}"


def test_output_ends_with_newline(run, x):
    out = run(x)
    assert out.endswith('\n'), f"Output must end with newline, got {repr(out)}"


def test_when_wolf_greater_than_sheep(run, x):
    # For inputs where W > S, output must be 'unsafe'
    s, w = map(int, x.strip().split())
    if w > s:
        out = run(x).strip()
        assert out == 'unsafe', f"When W={w} > S={s}, must output 'unsafe', got {repr(out)}"


def test_when_sheep_greater_than_wolf(run, x):
    # For inputs where S > W, output must be 'safe'
    s, w = map(int, x.strip().split())
    if s > w:
        out = run(x).strip()
        assert out == 'safe', f"When S={s} > W={w}, must output 'safe', got {repr(out)}"


def test_when_equal(run, x):
    # For inputs where S == W, output must be 'unsafe' (since W >= S)
    s, w = map(int, x.strip().split())
    if s == w:
        out = run(x).strip()
        assert out == 'unsafe', f"When S={s} == W={w}, must output 'unsafe', got {repr(out)}"


def test_output_lowercase(run, x):
    out = run(x).strip()
    assert out.islower(), f"Output must be lowercase, got {repr(out)}"


def test_no_extra_output(run, x):
    out = run(x)
    lines = out.strip('\n').split('\n')
    assert len(lines) == 1, f"Output must be exactly one line, got {len(lines)}"


def test_small_exact(run, x):
    # For all given inputs (all small), we can recompute the exact correct answer
    s, w = map(int, x.strip().split())
    expected = 'unsafe' if w >= s else 'safe'
