def test_digit_range(run, x):
    out = run(x).strip()
    assert out.isdigit() and 0 <= int(out) <= 9

def test_output_is_integer(run, x):
    out = run(x).strip()
    # Should be a single integer, no extra characters
    assert out.isdigit() or (out[0] == '-' and out[1:].isdigit())  # but task says digit 0–9, so just isdigit
    # Actually digit, so length 1
    assert len(out) == 1

def test_brute_force_small_k(run, x):
    # Only run for small k because brute force is O(k log k) – limit k <= 1000
    lines = x.strip().split('\n')
    if len(lines) != 2:
        return  # not a single query; but all given inputs are single query
    k = int(lines[1])
    if k > 1000:
        return  # skip large k
    # Build sequence until we have k-th digit
    seq = []
    i = 1
    while len(seq) < k:
        for j in range(1, i+1):
            seq.extend(str(j))
        i += 1
    expected = seq[k-1]
    got = run(x).strip()
    assert got == expected

def test_example1(run, x):
    # Only apply if input exactly matches the first example
    if x == '5\n1\n3\n20\n38\n56\n':
        got = run(x).strip()
        expected = '1\n2\n5\n2\n0'
        assert got == expected

def test_example2(run, x):
    if x == '4\n2132\n506\n999999999\n1000000000\n':
        got = run(x).strip()
        expected = '8\n2\n9\n8'
        assert got == expected

def test_position_1(run, x):
    if x == '1\n1\n':
        got = run(x).strip()
        assert got == '1'

def test_position_56(run, x):
    if x == '1\n56\n':
        got = run(x).strip()
        assert got == '0'

def test_position_101(run, x):
    # The suspicious branch returns '1' for k=101.
    # Actually we can compute by hand: sequence up to block 13? Let's trust brute-force test for k<=1000.
    # This test is redundant with brute_force_small_k, but explicit.
    if x == '1\n101\n':
        # Compute correct digit by brute force (small, safe)
        seq = []
        i = 1
        while len(seq) < 101:
            for j in range(1, i+1):
                seq.extend(str(j))
            i += 1
        expected = seq[100]
        got = run(x).strip()
        assert got == expected

def test_position_110(run, x):
    if x == '1\n110\n':
        seq = []
        i = 1
        while len(seq) < 110:
            for j in range(1, i+1):
                seq.extend(str(j))
            i += 1
        expected = seq[109]
        got = run(x).strip()
        assert got == expected

def test_position_999999999(run, x):
    # From example, answer is 9
    if x == '1\n999999999\n':
        got = run(x).strip()
        assert got == '9'

