def test_brute_force_small(run, x):
    # Only run brute-force if total k sum is small (say < 10000)
    lines = x.strip().split('\n')
    q = int(lines[0])
    total = 0
    for i in range(1, q+1):
        total += int(lines[i])
    if total > 10000:
        return  # too large, skip
    # Build sequence up to max_k
    max_k = max(int(lines[i]) for i in range(1, q+1))
    seq = []
    i = 1
    while len(seq) < max_k:
        for j in range(1, i+1):
            seq.extend(str(j))
        i += 1
    seq = ''.join(seq)
    output = run(x).strip().split('\n')
    for idx, k_str in enumerate(lines[1:]):
        k = int(k_str)
        expected = seq[k-1]
        assert output[idx] == expected, f'At k={k} expected {expected} got {output[idx]}'

