def test_output_format(run, x):
    output = run(x)
    assert output in ('Yes\n', 'No\n'), f'Output must be Yes\n or No\n, got {repr(output)}'

def test_output_ends_with_newline(run, x):
    output = run(x)
    assert output.endswith('\n'), 'Output must end with newline'

def test_output_no_extra_whitespace(run, x):
    output = run(x)
    stripped = output.strip()
    assert stripped in ('Yes', 'No'), f'Stripped output must be Yes or No, got {repr(stripped)}'

def test_yes_when_t_starts_with_s_and_one_extra_char(run, x):
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    S, T = lines[0], lines[1]
    if len(T) == len(S) + 1 and T.startswith(S) and T[-1].islower():
        output = run(x)
        assert output.strip() == 'Yes', f'When T starts with S and has one extra character, output must be Yes, got {output.strip()}'

def test_no_when_length_mismatch(run, x):
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    S, T = lines[0], lines[1]
    if len(T) != len(S) + 1:
        output = run(x)
        assert output.strip() == 'No', f'When |T| != |S|+1, output must be No, got {output.strip()}'

def test_no_when_t_does_not_start_with_s(run, x):
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    S, T = lines[0], lines[1]
    if len(T) == len(S) + 1 and not T.startswith(S):
        output = run(x)
        assert output.strip() == 'No', f'When T has correct length but does not start with S, output must be No, got {output.strip()}'

def test_no_when_t_differs_more_than_one_char(run, x):
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    S, T = lines[0], lines[1]
    if len(T) != len(S) + 1:
        return
    # Count differing positions when aligned at start
    diffs = sum(1 for i in range(len(S)) if S[i] != T[i])
    if diffs > 0:
        output = run(x)
        assert output.strip() == 'No', f'When T differs from S before the end, output must be No, got {output.strip()}'

def test_bruteforce_small(run, x):
    # Only run brute-force check when input is small enough (|S| <= 10 is always small, but limit computation)
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    S, T = lines[0], lines[1]
    # Direct simulation: check all possible single-character appends
    expected = 'Yes' if any(T == S + c for c in 'abcdefghijklmnopqrstuvwxyz') else 'No'
    output = run(x)
    assert output.strip() == expected, f'Brute-force simulation says {expected}, got {output.strip()}'

def test_t_last_char_is_lowercase(run, x):
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    S, T = lines[0], lines[1]
    if len(T) == len(S) + 1 and T.startswith(S):
        last_char = T[-1]
        assert last_char.islower() and 'a' <= last_char <= 'z', f'Last character of T must be lowercase letter'

def test_s_and_t_are_lowercase(run, x):
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    S, T = lines[0], lines[1]
    assert S.islower() and T.islower(), 'S and T must consist of lowercase English letters'

