def test_even_length_identical_halves_must_be_yes(run, x):
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    N = int(lines[0])
    S = lines[1]
    if N % 2 == 0:
        half = N // 2
        if S[:half] == S[half:]:
            out = run(x)
            assert out == "Yes\n", f'For identical halves, output must be Yes, got {repr(out)}'

def test_odd_length_must_be_no(run, x):
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    N = int(lines[0])
    if N % 2 == 1:
        out = run(x)
        assert out == "No\n", f'For odd N, output must be No, got {repr(out)}'

def test_N_1_must_be_no(run, x):
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
