    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    N = int(lines[0])
    S = lines[1]
    if N <= 10:
        half = N // 2
        correct = "Yes\n" if N % 2 == 0 and S[:half] == S[half:] else "No\n"
        out = run(x)
