            if token in ('P', 'W', 'G', 'Y'):
                colors.add(token)
    # guarantee at least P, W, G are present (by problem statement)
    assert 'P' in colors and 'W' in colors and 'G' in colors, f'Missing required color in input {x}'
    output = run(x).strip()
    if output == 'Three':
        # must have exactly three colors, so Y not present
        assert 'Y' not in colors, f'Output Three but Y present in {colors}'
        assert len(colors) == 3, f'Output Three but {len(colors)} colors present'
    else:
        assert output == 'Four', f'Output must be Three or Four, got {output}'
        # must have four colors, so Y present
        assert 'Y' in colors, f'Output Four but Y not present in {colors}'
        assert len(colors) == 4, f'Output Four but {len(colors)} colors present'

def test_answer_is_not_ambiguous(run, x):
    output = run(x).strip()
    # It must be either Three or Four, already checked by format test, but double-check
    assert output in ('Three', 'Four'), f'Invalid output {output}'

def test_answer_matches_color_count(run, x):
    lines = x.strip().split('\n')
    colors = set()
    if len(lines) > 1:
        for token in lines[1].split():
            if token in ('P', 'W', 'G', 'Y'):
                colors.add(token)
    # Compute expected answer
    expected = 'Three' if len(colors) == 3 else 'Four'
    output = run(x).strip()
    assert output == expected, f'Output {output} does not match color count {len(colors)}'

def test_no_extra_output(run, x):
    output = run(x)
    # Should be exactly one line
    lines = output.split('\n')
    # Allow trailing newline, but no extra content after it
    assert len([l for l in lines if l.strip() != '']) == 1, f'Extra output lines: {output!r}'

def test_output_case_sensitive(run, x):
    output = run(x)
    assert output == 'Three\n' or output == 'Four\n', f'Output must be exactly Three\n or Four\n (case-sensitive), got {repr(output)}'

def test_input_guarantees_at_least_three_colors(run, x):
    lines = x.strip().split('\n')
    colors = set()
    if len(lines) > 1:
        for token in lines[1].split():
            if token in ('P', 'W', 'G', 'Y'):
                colors.add(token)
    # By problem statement, there always exist P, W, G
    assert {'P','W','G'}.issubset(colors), f'Input missing required color P, W, or G: {colors}'

def test_reordering_invariant(run, x):
    # Since output depends only on set of colors, reordering the list should not change answer
