    lines = x.strip().split('\n')
    colors = set()
    if len(lines) > 1:
        for token in lines[1].split():
            if token in ('P', 'W', 'G', 'Y'):
                colors.add(token)
    output = run(x).strip()
    # If Y present, must be Four; otherwise Three.
    if 'Y' in colors:
        assert output == 'Four', f'Y present but output {output}'
    else:
        assert output == 'Three', f'Y absent but output {output}'

def test_small_input_brute_force(run, x):
    # For small N (<=10), we can afford to compute expected answer directly.
    # This is the strongest test, but we limit it to avoid performance issues.
    lines = x.strip().split('\n')
