    ans = int(run(x).strip())
    assert 1 <= ans <= n

def test_answer_at_least_one(run, x):
    ans = int(run(x).strip())
    assert ans >= 1

def test_all_neg_one(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    a = list(map(int, lines[1].split()))
    if all(v == -1 for v in a):
        assert run(x).strip() == '1'

def test_n_equals_one(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    if n == 1:
        assert run(x).strip() == '1'

def test_two_equal_positives(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    if n == 2:
        a = list(map(int, lines[1].split()))
        if a[0] == a[1] and a[0] != -1:
            # Two equal numbers can be part of one arithmetic progression
            # So answer must be 1.
            assert run(x).strip() == '1'

def test_two_neg_one(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    if n == 2:
        a = list(map(int, lines[1].split()))
        if a[0] == -1 and a[1] == -1:
            assert run(x).strip() == '1'

def test_two_mixed_one_neg_one(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    if n == 2:
        a = list(map(int, lines[1].split()))
        if (a[0] == -1 and a[1] != -1) or (a[0] != -1 and a[1] == -1):
            # One unknown: we can always set the unknown to match the known
            # So one arithmetic progression suffices.
            assert run(x).strip() == '1'

def test_all_equal_positive(run, x):
    lines = x.strip().split('\n')
    a = list(map(int, lines[1].split()))
    if len(a) > 1 and all(v == a[0] and v != -1 for v in a):
        assert run(x).strip() == '1'

def test_strictly_increasing_by_one(run, x):
    lines = x.strip().split('\n')
    a = list(map(int, lines[1].split()))
    if len(a) > 1 and all(a[i] == a[0] + i for i in range(len(a))):
        assert run(x).strip() == '1'

