tests_src:
def test_brute(run, x):
    # Compute correct answer from input: palindrome iff first digit == third digit.
    # This is a direct implementation of the spec, allowed because input is small.
    s = x.strip()
    if len(s) != 3:
        return  # Should not happen, but guard.
    correct = 'Yes\n' if s[0] == s[2] else 'No\n'
    assert run(x) == correct

def test_output_is_yes_or_no(run, x):
    out = run(x)
    assert out in ('Yes\n', 'No\n')

def test_output_no_extra_whitespace(run, x):
    out = run(x)
    # Must be exactly 'Yes\n' or 'No\n', no leading/trailing spaces.
    assert out == out.strip() + '\n'

def test_yes_implies_first_equals_last(run, x):
    out = run(x)
    if out == 'Yes\n':
        s = x.strip()
        assert s[0] == s[2]

def test_no_implies_first_not_equals_last(run, x):
    out = run(x)
    if out == 'No\n':
        s = x.strip()
        assert s[0] != s[2]

def test_output_length(run, x):
    out = run(x)
    assert len(out) == 4  # 'Yes\n' or 'No\n' both 4 chars

def test_output_starts_with_y_or_n(run, x):
    out = run(x)
    assert out[0] in 'YN'

def test_yes_capital_y(run, x):
    out = run(x)
    if out.startswith('Y'):
        assert out == 'Yes\n'

def test_no_capital_n(run, x):
    out = run(x)
    if out.startswith('N'):
        assert out == 'No\n'

def test_consistent_with_digit_equality(run, x):
    # Equivalent to brute but phrased as consistency check.
    s = x.strip()
    out = run(x)
    if s[0] == s[2]:
        assert out == 'Yes\n'
    else:
        assert out == 'No\n'

