def test_output_non_negative_integer(run, x):
    out = run(x).strip()
    ans = int(out)
    assert ans >= 0

def test_at_most_m(run, x):
    lines = x.strip().split('\n')
    if not lines[0]:
        return
    n_m = list(map(int, lines[0].split()))
    if len(n_m) < 2:
        return
    m = n_m[1]
    out = run(x).strip()
    ans = int(out)
    assert ans <= m

def test_invariant_under_edge_permutation(run, x):
    lines = x.strip().split('\n')
    if not lines[0]:
        return
    header = lines[0]
    edges = lines[1:]
    import random
    random.seed(123)
    random.shuffle(edges)
    shuffled_input = header + '\n' + '\n'.join(edges)
    if shuffled_input[-1] != '\n':
        shuffled_input += '\n'
    out_original = run(x).strip()
    out_shuffled = run(shuffled_input).strip()
    assert out_original == out_shuffled

def test_upper_bound_by_same_weight_edges_in_component(run, x):
    lines = x.strip().split('\n')
    if not lines[0]:
        return
    n, m = map(int, lines[0].split())
    if m == 0:
        return
    edges = []
    for line in lines[1:]:
        if not line.strip():
            continue
        u, v, w = map(int, line.split())
        edges.append((u-1, v-1, w))
    from collections import defaultdict
    weight_to_edges = defaultdict(list)
    for idx, (u, v, w) in enumerate(edges):
        weight_to_edges[w].append((u, v, idx))
    # DSU for connectivity after processing each weight
    parent = list(range(n))
    rank = [0]*n
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    def union(a,b):
        ra, rb = find(a), find(b)
        if ra == rb:
            return False
        if rank[ra] < rank[rb]:
            parent[ra] = rb
        elif rank[ra] > rank[rb]:
            parent[rb] = ra
        else:
            parent[rb] = ra
            rank[ra] += 1
        return True
    # Process edges in increasing weight
    sorted_weights = sorted(weight_to_edges.keys())
    potential_conflicts = 0
    for w in sorted_weights:
        group = weight_to_edges[w]
        # among edges of same weight, count those whose endpoints already connected
        for u, v, _ in group:
            if find(u) == find(v):
                potential_conflicts += 1
        # now union all edges of this weight that connect different components
        for u, v, _ in group:
            union(u, v)
    out = int(run(x).strip())
    assert out <= potential_conflicts

def test_tree_with_distinct_weights_zero(run, x):
    lines = x.strip().split('\n')
    if not lines[0]:
        return
    n, m = map(int, lines[0].split())
    if m != n-1:
        return
    edges = []
    weights = set()
    for line in lines[1:]:
        if not line.strip():
            continue
        u, v, w = map(int, line.split())
        edges.append((u, v, w))
        weights.add(w)
    if len(weights) == m:  # all distinct
        out = run(x).strip()
        assert out == '0'

def test_all_edges_same_weight(run, x):
    lines = x.strip().split('\n')
    if not lines[0]:
        return
    n, m = map(int, lines[0].split())
    if m == 0:
        return
    edges = []
    w0 = None
    for line in lines[1:]:
        if not line.strip():
            continue
        u, v, w = map(int, line.split())
        edges.append((u, v, w))
        if w0 is None:
            w0 = w
        elif w != w0:
            return  # not all same weight
    # For a connected graph with all edges same weight, any spanning tree is MST.
    # To make MST unique we must eliminate all alternative edges.
    # Minimum operations = m - (n-1) because we can keep one tree and increment all others.
    expected = m - (n-1)
    out = int(run(x).strip())
    assert out == expected

def test_brute_force_small(run, x):
    lines = x.strip().split('\n')
    if not lines[0]:
