            else:
                parent[rb] = ra
                rank[ra] += 1
            return True
        mst_cost = 0
        mst_edges = []
        for idx in sorted_idx:
            u, v, _ = edges[idx]
            if find(u) != find(v):
                union(u, v)
                mst_cost += new_weights[idx]
                mst_edges.append(idx)
        # check if MST cost equals original MST cost
        # compute original MST cost
        sorted_idx_orig = sorted(range(m), key=lambda i: (edges[i][2], edges[i][0], edges[i][1]))
        parent2 = list(range(n))
        rank2 = [0]*n
        def find2(x):
            while parent2[x] != x:
                parent2[x] = parent2[parent2[x]]
                x = parent2[x]
            return x
        def union2(a,b):
            ra, rb = find2(a), find2(b)
            if ra == rb:
                return False
            if rank2[ra] < rank2[rb]:
                parent2[ra] = rb
            elif rank2[ra] > rank2[rb]:
                parent2[rb] = ra
            else:
                parent2[rb] = ra
                rank2[ra] += 1
            return True
        orig_mst_cost = 0
        for idx in sorted_idx_orig:
            u, v, _ = edges[idx]
            if find2(u) != find2(v):
                union2(u, v)
                orig_mst_cost += edges[idx][2]
        if mst_cost != orig_mst_cost:
            continue
        # check uniqueness: are there multiple MSTs with new weights?
        # enumerate all subsets of m edges with exactly n-1 edges that form spanning tree
        # and compute total weight, check if any other tree has same weight.
        unique = True
        for tree_edges in itertools.combinations(range(m), n-1):
            # check if tree_edges forms a spanning tree
            parent3 = list(range(n))
            rank3 = [0]*n
            def find3(x):
                while parent3[x] != x:
                    parent3[x] = parent3[parent3[x]]
                    x = parent3[x]
                return x
            def union3(a,b):
                ra, rb = find3(a), find3(b)
                if ra == rb:
                    return False
                if rank3[ra] < rank3[rb]:
                    parent3[ra] = rb
                elif rank3[ra] > rank3[rb]:
                    parent3[rb] = ra
                else:
                    parent3[rb] = ra
                    rank3[ra] += 1
                return True
            connected = True
            for e in tree_edges:
                u, v, _ = edges[e]
                if not union3(u, v):
                    connected = False
                    break
            if not connected:
                continue
            weight = sum(new_weights[e] for e in tree_edges)
            if weight == mst_cost and set(tree_edges) != set(mst_edges):
                unique = False
                break
        if unique:
            best = min(best, inc_count)
    out = int(run(x).strip())
    assert out == best

