def test_exact(run, x):
    # Since |S| = 3, we can compute the correct answer directly.
    s = x.strip()
    # longest consecutive rainy days
    best = 0
    cur = 0
    for ch in s:
        if ch == 'R':
            cur += 1
            if cur > best:
                best = cur
        else:
            cur = 0
    assert int(run(x).strip()) == best

def test_integer(run, x):
    out = run(x)
    # output must be a single integer, possibly with a newline
    try:
        int(out.strip())
    except ValueError:
        assert False, 'Output must be an integer'

def test_range(run, x):
    out = run(x)
    val = int(out.strip())
    # answer must be 0, 1, 2, or 3 because length is 3
    assert 0 <= val <= 3

def test_at_least_one_if_any_R(run, x):
    s = x.strip()
    out = run(x)
    val = int(out.strip())
    if 'R' in s:
        assert val >= 1, 'If there is any rainy day, answer must be at least 1'

def test_zero_if_no_R(run, x):
    s = x.strip()
    out = run(x)
    val = int(out.strip())
    if 'R' not in s:
        assert val == 0, 'If there are no rainy days, answer must be 0'

def test_three_only_if_all_R(run, x):
    s = x.strip()
    out = run(x)
    val = int(out.strip())
    if val == 3:
        assert s == 'RRR', 'Answer can be 3 only if all three days are rainy'

def test_two_requires_two_consecutive(run, x):
    s = x.strip()
    out = run(x)
    val = int(out.strip())
    if val == 2:
        # there must be two consecutive R's somewhere
        assert 'RR' in s, 'Answer 2 requires two consecutive rainy days'

def test_one_if_single_Rs_only(run, x):
    s = x.strip()
    out = run(x)
    val = int(out.strip())
    # If no two consecutive R's and at least one R, answer must be 1
    if 'RR' not in s and 'R' in s:
        assert val == 1, 'With isolated R’s and no consecutive pair, answer must be 1'

def test_consistent_with_counts(run, x):
    s = x.strip()
    out = run(x)
    val = int(out.strip())
    # The answer cannot exceed total number of R's
    rcount = s.count('R')
    assert val <= rcount, 'Consecutive rainy days cannot exceed total rainy days'

def test_answer_matches_pattern(run, x):
    s = x.strip()
    out = run(x)
    val = int(out.strip())
    # If pattern is RRR -> 3, RR? or ?RR -> 2, single R's -> 1, else 0
    if s == 'RRR':
        assert val == 3
    elif s in ('RRS', 'SRR'):
        assert val == 2
    elif s == 'SSS':
        assert val == 0
    # For patterns with isolated R’s (RSR, RSS, SSR, SRS) answer must be 1
    elif 'RR' not in s and 'R' in s:
        assert val == 1
    else:
        # Only remaining case is RR? / ?RR already handled above
        pass

