def test_answer_is_integer_string(run, x):
    out = run(x).strip()
    # Must be a string representing an integer, possibly with leading/trailing whitespace stripped
    assert out.lstrip('-').isdigit(), 'Output must be an integer string'

def test_answer_non_negative(run, x):
    out = run(x).strip()
    ans = int(out)
    assert ans >= 0, 'Cost cannot be negative'

def test_age_0_5_output_zero(run, x):
    a, b = map(int, x.split())
    if a <= 5:
        out = run(x).strip()
        assert out == '0', 'Ages 0–5 must cost 0 yen'

def test_age_13_plus_output_full_b(run, x):
    a, b = map(int, x.split())
    if a >= 13:
        out = run(x).strip()
        assert int(out) == b, 'Ages 13+ must cost full B yen'

def test_age_6_12_output_half_b(run, x):
    a, b = map(int, x.split())
    if 6 <= a <= 12:
        out = run(x).strip()
        assert int(out) == b // 2, 'Ages 6–12 must cost half B yen (integer)'

def test_output_parity_consistent(run, x):
    a, b = map(int, x.split())
    out = int(run(x).strip())
    if a >= 6:
        # B is even, so full B is even, half B is integer. For age≥6, output parity should match expected parity.
        # If age≥13, output==B (even). If 6≤a≤12, output==B//2 (could be odd or even).
        # No strict parity constraint beyond being integer.
        # But we can check: if a>=13, output must be even because B is even.
        if a >= 13:
            assert out % 2 == 0, 'For age≥13, cost must be even (B is even)'

def test_output_does_not_exceed_b(run, x):
    a, b = map(int, x.split())
    out = int(run(x).strip())
    assert out <= b, 'Cost cannot exceed B'

def test_output_is_0_or_b_or_half_b(run, x):
    a, b = map(int, x.split())
    out = int(run(x).strip())
    assert out in {0, b // 2, b}, 'Cost must be 0, half B, or full B'

def test_half_b_is_integer(run, x):
    # B is even, so half is integer; output must be integer (already covered).
    # This test ensures that when output is half B, it equals floor(b/2).
    a, b = map(int, x.split())
    out = int(run(x).strip())
    if 6 <= a <= 12:
        assert out == b // 2, 'Half B must be exact integer division'

def test_no_extra_output(run, x):
    out = run(x)
    lines = out.strip().split('\n')
    assert len(lines) == 1, 'Output must be exactly one line'

