def test_output_is_lowercase_letter(run, x):
    out = run(x)
    ch = out.strip()
    assert ch.isalpha() and ch.islower()

def test_output_codepoint_is_input_plus_one(run, x):
    # Only applies if input is exactly one character
    if len(x.strip()) == 1:
        inp_char = x.strip()
