def test_output_shape(run, x):
    out = run(x).strip()
    assert out in ('<', '>', '='), f'Output must be one of "<", ">", "=", got {repr(out)}'

def test_symmetry(run, x):
    # If we swap x and y, the output should be swapped unless equal
    import io, sys
    x_val, y_val = map(int, x.split())
    swapped_input = f'{y_val} {x_val}'
    out1 = run(x).strip()
    out2 = run(swapped_input).strip()
    if out1 == '<':
        assert out2 == '>', f'Swapped input should invert "<", got {out2}'
    elif out1 == '>':
        assert out2 == '<', f'Swapped input should invert ">", got {out2}'
    else:
        assert out1 == '=', f'Original output should be "=" if symmetric, got {out1}'
        assert out2 == '=', f'Swapped output should be "=", got {out2}'

def test_small_exact_computation(run, x):
    # For small x,y (product ≤ 10^6) compute directly with integers
    x_val, y_val = map(int, x.split())
    if x_val <= 1000 and y_val <= 1000:
        # Compute x**y and y**x directly using Python's big ints
        import math
        if x_val == 1 and y_val == 1:
            expected = '='
        else:
            a = x_val ** y_val
            b = y_val ** x_val
            if a < b:
                expected = '<'
            elif a > b:
                expected = '>'
            else:
                expected = '='
        assert run(x).strip() == expected, f'For small {x_val},{y_val} direct computation gives {expected}'

def test_examples(run, x):
    # Check that the output matches the three given examples
    if x == '5 8\n':
        assert run(x).strip() == '>'
    elif x == '10 3\n':
        assert run(x).strip() == '<'
    elif x == '6 6\n':
        assert run(x).strip() == '='

def test_equal_inputs(run, x):
    x_val, y_val = map(int, x.split())
    if x_val == y_val:
        assert run(x).strip() == '=', f'Equal inputs must yield "=", got {run(x).strip()}'

def test_monotonicity_of_log_ratio(run, x):
    # For x,y > 1, the comparison depends on f(t)=ln(t)/t.
    # If x<y and f(x)>f(y) then x^y < y^x, etc.
    # We check consistency: if x<y and output is '<' then for any z between x and y, the output for (x,z) and (z,y) should also be '<'.
    # Since we cannot call run again, we only check a property that must hold for the given single input: 
    # If output is '<', then ln(x)/x > ln(y)/y must hold (for x,y>1).
    import math
    x_val, y_val = map(int, x.split())
    if x_val > 1 and y_val > 1:
        out = run(x).strip()
        fx = math.log(x_val) / x_val
        fy = math.log(y_val) / y_val
        if out == '<':
            assert fx > fy, f'Output "<" requires ln({x_val})/{x_val} > ln({y_val})/{y_val}, but {fx} <= {fy}'
        elif out == '>':
            assert fx < fy, f'Output ">" requires ln({x_val})/{x_val} < ln({y_val})/{y_val}, but {fx} >= {fy}'
        else:
            assert abs(fx - fy) < 1e-12, f'Output "=" requires ln({x_val})/{x_val} ≈ ln({y_val})/{y_val}, but {fx} vs {fy}'

def test_one_as_base(run, x):
    x_val, y_val = map(int, x.split())
    # If one of them is 1, then 1^y = 1, y^1 = y.
    if x_val == 1 and y_val == 1:
        assert run(x).strip() == '='
    elif x_val == 1:
        # 1^y = 1, y^1 = y -> 1 < y for y>1
        if y_val > 1:
            assert run(x).strip() == '<', f'1^{y_val} < {y_val}^1 should be "<", got {run(x).strip()}'
    elif y_val == 1:
        if x_val > 1:
            assert run(x).strip() == '>', f'{x_val}^1 > 1^{x_val} should be ">", got {run(x).strip()}'

def test_large_equal(run, x):
    # The only integer solutions to x^y = y^x for x≠y are (2,4) and (4,2).
    x_val, y_val = map(int, x.split())
    if x_val != y_val and (x_val == 2 and y_val == 4) or (x_val == 4 and y_val == 2):
        assert run(x).strip() == '=', f'{x_val}^{y_val} == {y_val}^{x_val} should be "="'

def test_known_small_pairs(run, x):
    # A few hand‑checked small pairs.
    known = {
        (2, 3): '<',  # 8 < 9
        (3, 2): '>',  # 9 > 8
        (2, 2): '=',
        (3, 4): '>',  # 81 > 64
        (4, 3): '<',  # 64 < 81
        (2, 5): '>',  # 32 > 25
        (5, 2): '<',  # 25 < 32
        (3, 5): '>',  # 243 > 125
        (5, 3): '<',  # 125 < 243
    }
    x_val, y_val = map(int, x.split())
    if (x_val, y_val) in known:
        assert run(x).strip() == known[(x_val, y_val)], f'Known pair ({x_val},{y_val}) should give {known[(x_val, y_val)]}'

def test_consistency_with_log_inequality(run, x):
    # The core comparison: x^y < y^x  <=>  y*ln(x) < x*ln(y)  (for x,y>0).
    # So the output must match the sign of (y*ln(x) - x*ln(y)).
    import math
    x_val, y_val = map(int, x.split())
    if x_val <= 0 or y_val <= 0:
        return  # not in input range
    lhs = y_val * math.log(x_val)
    rhs = x_val * math.log(y_val)
    out = run(x).strip()
    if out == '<':
        assert lhs < rhs - 1e-12, f'Output "<" requires {lhs} < {rhs}'
    elif out == '>':
        assert lhs > rhs + 1e-12, f'Output ">" requires {lhs} > {rhs}'
    else:
        assert abs(lhs - rhs) < 1e-12, f'Output "=" requires {lhs} ≈ {rhs}'

