        res = []
        seen = set()
        for i, ch in enumerate(chars):
            if ch in seen:
                continue
            seen.add(ch)
            for p in perms_unique(chars[:i] + chars[i+1:]):
                res.append(ch + p)
        return res
    s_perms = perms_unique(sorted(s))
    t_perms = perms_unique(sorted(t))
    possible = any(sp < tp for sp in s_perms for tp in t_perms)
    expected = 'Yes' if possible else 'No'
    assert run(x).strip() == expected

def test_brute_force_len8(run, x):
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    s, t = lines[0], lines[1]
    if len(s) > 10 or len(t) > 10:
        return
    # Direct double loop over permutations, breaking early
    from itertools import permutations
    possible = False
    for sp in permutations(s):
        sp_str = ''.join(sp)
        for tp in permutations(t):
            if sp_str < ''.join(tp):
                possible = True
                break
        if possible:
            break
    expected = 'Yes' if possible else 'No'
    assert run(x).strip() == expected

