                feasible_first.append(ch)
    if feasible_first:
        # The first character of output must be the smallest feasible first character
        # because any lexicographically minimal path must start with the smallest possible.
        first_char = out[0]
        assert first_char == min(feasible_first), f"First char {first_char} not minimal among {feasible_first}"


