def test_brute_force_small(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    if n > 4:
        return
    angles = list(map(int, lines[1:]))
    # brute‑force check
    possible = False
    for mask in range(1 << n):
        s = 0
        for i in range(n):
            if mask & (1 << i):
                s += angles[i]
            else:
                s -= angles[i]
        if s % 360 == 0:
            possible = True
            break
    expected = 'YES' if possible else 'NO'
    out = run(x).strip()
    assert out == expected, f'Brute‑force says {expected}, got {out}'

