tests_src:
def test_output_is_nonnegative_integer(run, x):
    out = run(x).strip()
    val = int(out)
    assert val >= 0
    assert val < 10**6  # safely above N-1


def test_at_least_one_if_full_span(run, x):
    lines = x.strip().split('\n')
    N = int(lines[0].split()[0])
    for line in lines[1:]:
        if not line:
            continue
        a, b = map(int, line.split())
        if a == 1 and b == N:
            assert int(run(x).strip()) >= 1
            return


def test_at_least_one_if_request_not_adjacent(run, x):
    lines = x.strip().split('\n')
    if len(lines) == 1:
        return
    N = int(lines[0].split()[0])
    M = int(lines[0].split()[1])
    if M != 1:
        return
    a, b = map(int, lines[1].split())
    if b > a + 1:
        assert int(run(x).strip()) >= 1


def test_at_least_number_of_disjoint_requests(run, x):
    lines = x.strip().split('\n')
    if len(lines) == 1:
        return
    N = int(lines[0].split()[0])
    M = int(lines[0].split()[1])
    requests = []
    for line in lines[1:]:
        if not line:
            continue
        a, b = map(int, line.split())
        requests.append((a, b))
    # sort by right endpoint
    requests.sort(key=lambda t: t[1])
    count = 0
    last_right = 0
    for a, b in requests:
        if a >= last_right:
            count += 1
            last_right = b
    assert int(run(x).strip()) >= count


def test_at_most_M(run, x):
    lines = x.strip().split('\n')
    M = int(lines[0].split()[1])
    assert int(run(x).strip()) <= M


def test_single_request_adjacent(run, x):
    lines = x.strip().split('\n')
    if len(lines) == 1:
        return
    M = int(lines[0].split()[1])
    if M != 1:
        return
    a, b = map(int, lines[1].split())
    if b == a + 1:
        # removing 0 bridges might already disconnect them? No, they are adjacent, so a bridge connects them.
        # To make traveling impossible, at least one bridge must be removed.
        assert int(run(x).strip()) >= 1


def test_identical_requests(run, x):
    lines = x.strip().split('\n')
    if len(lines) == 1:
        return
    requests = []
    for line in lines[1:]:
        if not line:
            continue
        a, b = map(int, line.split())
        requests.append((a, b))
    if len(requests) == 0:
        return
    a0, b0 = requests[0]
    if all(a == a0 and b == b0 for a, b in requests):
        if b0 > a0 + 1:
            assert int(run(x).strip()) >= 1


def test_output_is_integer(run, x):
    out = run(x).strip()
    int(out)  # raises ValueError if not


def test_single_request_output_binary(run, x):
    lines = x.strip().split('\n')
    if len(lines) == 1:
        return
    M = int(lines[0].split()[1])
    if M != 1:
        return
    ans = int(run(x).strip())
    assert ans == 0 or ans == 1


def test_two_nonoverlapping_requests(run, x):
    lines = x.strip().split('\n')
    if len(lines) < 3:
        return
    M = int(lines[0].split()[1])
    if M != 2:
        return
    r1 = tuple(map(int, lines[1].split()))
    r2 = tuple(map(int, lines[2].split()))
    # sort by right endpoint
    reqs = sorted([r1, r2], key=lambda t: t[1])
    (a1, b1), (a2, b2) = reqs
    if a2 >= b1:  # non‑overlapping
        assert int(run(x).strip()) >= 2

