def test_output_format(run, x):
    out = run(x).strip()
    assert out in ('first', 'second'), f'Output must be "first" or "second", got {repr(out)}'

def test_single_positive(run, x):
    lines = x.strip().split('\n')
    if len(lines) == 2 and lines[1].isdigit():
        out = run(x).strip()
        assert out == 'first', f'Single positive move must win, got {out}'

def test_single_negative(run, x):
    lines = x.strip().split('\n')
    if len(lines) == 2 and lines[1].startswith('-'):
        out = run(x).strip()
        assert out == 'second', f'Single negative move must win, got {out}'

def test_sum_decides_when_unequal(run, x):
    lines = [int(v) for v in x.strip().split('\n')[1:]]
    sum_a = sum(v for v in lines if v > 0)
    sum_b = sum(-v for v in lines if v < 0)
    out = run(x).strip()
    if sum_a > sum_b:
        assert out == 'first', f'first has higher sum {sum_a} > {sum_b}'
    elif sum_b > sum_a:
        assert out == 'second', f'second has higher sum {sum_b} > {sum_a}'

def test_lexicographic_when_sums_equal(run, x):
    lines = [int(v) for v in x.strip().split('\n')[1:]]
    sum_a = sum(v for v in lines if v > 0)
    sum_b = sum(-v for v in lines if v < 0)
    if sum_a != sum_b:
        return
    seq_a = [v for v in lines if v > 0]
    seq_b = [-v for v in lines if v < 0]
    out = run(x).strip()
    if seq_a > seq_b:
        assert out == 'first', f'first lexicographically larger'
    elif seq_b > seq_a:
        assert out == 'second', f'second lexicographically larger'

def test_last_move_when_all_equal(run, x):
    lines = [int(v) for v in x.strip().split('\n')[1:]]
    sum_a = sum(v for v in lines if v > 0)
    sum_b = sum(-v for v in lines if v < 0)
    if sum_a != sum_b:
        return
    seq_a = [v for v in lines if v > 0]
    seq_b = [-v for v in lines if v < 0]
    if seq_a != seq_b:
        return
    last = 1 if lines[-1] < 0 else 0
    out = run(x).strip()
    if last == 0:
        assert out == 'first', f'last move by first'
    else:
        assert out == 'second', f'last move by second'

def test_lexicographic_respects_prefix(run, x):
    lines = [int(v) for v in x.strip().split('\n')[1:]]
    seq_a = [v for v in lines if v > 0]
    seq_b = [-v for v in lines if v < 0]
    # If one is a prefix of the other and sums equal, longer wins
    sum_a = sum(seq_a)
    sum_b = sum(seq_b)
    if sum_a != sum_b:
        return
    out = run(x).strip()
    min_len = min(len(seq_a), len(seq_b))
    if seq_a[:min_len] == seq_b[:min_len]:
        if len(seq_a) > len(seq_b):
            assert out == 'first', f'first longer prefix-equal sequence'
        elif len(seq_b) > len(seq_a):
            assert out == 'second', f'second longer prefix-equal sequence'

def test_no_extra_output(run, x):
    out = run(x)
    assert out.endswith('\n'), 'Output must end with newline'
    lines = out.strip().split('\n')
    assert len(lines) == 1, 'Output must be exactly one line'

def test_brute_force_small(run, x):
    lines = [int(v) for v in x.strip().split('\n')[1:]]
    if len(lines) > 20:
        return  # too large for brute-force in test
    sum_a = sum(v for v in lines if v > 0)
    sum_b = sum(-v for v in lines if v < 0)
    seq_a = [v for v in lines if v > 0]
    seq_b = [-v for v in lines if v < 0]
    last = 1 if lines[-1] < 0 else 0
    if sum_a > sum_b:
        expected = 'first'
    elif sum_b > sum_a:
        expected = 'second'
    elif seq_a > seq_b:
        expected = 'first'
    elif seq_b > seq_a:
        expected = 'second'
    else:
        expected = 'second' if last else 'first'
    out = run(x).strip()
    assert out == expected, f'Brute force expects {expected}'

def test_consistent_with_last_move_rule(run, x):
    lines = [int(v) for v in x.strip().split('\n')[1:]]
    sum_a = sum(v for v in lines if v > 0)
    sum_b = sum(-v for v in lines if v < 0)
    seq_a = [v for v in lines if v > 0]
    seq_b = [-v for v in lines if v < 0]
    if sum_a == sum_b and seq_a == seq_b:
        last = 1 if lines[-1] < 0 else 0
        out = run(x).strip()
        if last == 0:
            assert out == 'first', f'last move first'
        else:
            assert out == 'second', f'last move second'

