def test_1(run, x):
    out = run(x).strip()
    assert out in ("first", "second"), f'Output must be "first" or "second", got {repr(out)}'

def test_2(run, x):
    # If total sum of first wrestler > total sum of second, answer must be "first"
    # Parse input
    lines = x.strip().split('\n')
    n = int(lines[0])
    sum_a = 0
    sum_b = 0
    for i in range(1, n+1):
        val = int(lines[i])
        if val > 0:
            sum_a += val
        else:
            sum_b += -val
    out = run(x).strip()
    if sum_a > sum_b:
        assert out == "first", f'Sum first={sum_a} > second={sum_b}, must be "first", got {repr(out)}'

def test_3(run, x):
    # If total sum of second wrestler > total sum of first, answer must be "second"
    lines = x.strip().split('\n')
    n = int(lines[0])
    sum_a = 0
    sum_b = 0
    for i in range(1, n+1):
        val = int(lines[i])
        if val > 0:
            sum_a += val
        else:
            sum_b += -val
    out = run(x).strip()
    if sum_b > sum_a:
        assert out == "second", f'Sum second={sum_b} > first={sum_a}, must be "second", got {repr(out)}'

def test_4(run, x):
    # When total sums equal, compare sequences lexicographically.
    # If seq_a > seq_b lexicographically, answer must be "first"
    lines = x.strip().split('\n')
    n = int(lines[0])
    seq_a = []
    seq_b = []
    for i in range(1, n+1):
        val = int(lines[i])
        if val > 0:
            seq_a.append(val)
        else:
            seq_b.append(-val)
    sum_a = sum(seq_a)
    sum_b = sum(seq_b)
    if sum_a != sum_b:
        # Not relevant, pass
        return
    # Lexicographic comparison as per spec: compare elementwise until difference.
    i = 0
    while i < len(seq_a) and i < len(seq_b):
        if seq_a[i] != seq_b[i]:
            break
        i += 1
    if i < len(seq_a) and i < len(seq_b):
        # Found differing element at i
        if seq_a[i] > seq_b[i]:
            assert run(x).strip() == "first", f'Sums equal, lexicographically first wins, got {run(x).strip()!r}'

def test_5(run, x):
    # When total sums equal and seq_b > seq_a lexicographically, answer must be "second"
    lines = x.strip().split('\n')
    n = int(lines[0])
    seq_a = []
    seq_b = []
    for i in range(1, n+1):
