    # When total sums equal and sequences are identical (or one is prefix of the other?)
    # If sequences identical, the wrestler who performed last technique wins.
    lines = x.strip().split('\n')
    n = int(lines[0])
    seq_a = []
    seq_b = []
    last = 0  # 0 if first wrestler performed last, 1 if second
    for i in range(1, n+1):
