def test_valid_format(run, x):
    out = run(x).strip()
    if out == '-1':
        return
    # otherwise must be space‑separated integers possibly with trailing space
    parts = out.split()
    for p in parts:
        # each part must be an integer
        assert p.lstrip('-').isdigit()
        # no leading zeros unless the number is '0', but our numbers are positive
        if p != '0' and p.startswith('0'):
            assert False
    # at least one number
    assert len(parts) > 0


def test_minus_one_iff_no_power(run, x):
    l, r, k = map(int, x.strip().split())
    out = run(x).strip()
    # compute whether there is any power in range
    has_power = False
    val = 1
    while val <= r:
        if val >= l:
            has_power = True
            break
        # avoid overflow (val may exceed r quickly)
        if val > r // k:
            break
        val *= k
    if out == '-1':
        assert not has_power
    else:
        assert has_power


def test_all_numbers_in_range(run, x):
    l, r, k = map(int, x.strip().split())
    out = run(x).strip()
    if out == '-1':
        return
    nums = list(map(int, out.split()))
    for n in nums:
        assert l <= n <= r


def test_all_numbers_are_powers_of_k(run, x):
    l, r, k = map(int, x.strip().split())
    out = run(x).strip()
    if out == '-1':
        return
    nums = list(map(int, out.split()))
    for n in nums:
        # check n is a power of k: repeatedly divide
        if n == 0:
            assert False  # not possible given constraints
        if n == 1:
            # 1 is k^0, which is allowed
            continue
        tmp = n
        while tmp % k == 0:
            tmp //= k
        assert tmp == 1


def test_strictly_increasing(run, x):
    out = run(x).strip()
    if out == '-1':
        return
    nums = list(map(int, out.split()))
    for i in range(1, len(nums)):
        assert nums[i-1] < nums[i]


def test_no_missing_power(run, x):
    l, r, k = map(int, x.strip().split())
    out = run(x).strip()
    if out == '-1':
        # already checked by another test
        return
    nums = set(map(int, out.split()))
    val = 1
    while val <= r:
        if val >= l:
            assert val in nums
        if val > r // k:
            break
        val *= k


def test_small_bruteforce(run, x):
    l, r, k = map(int, x.strip().split())
    if r > 10**6:
        # too big to brute‑force quickly, skip
        return
    out = run(x).strip()
    # compute correct answer by brute enumeration
    powers = []
    val = 1
    while val <= r:
        if val >= l:
            powers.append(val)
        if val > r // k:
            break
        val *= k
    expected = ' '.join(map(str, powers)) if powers else '-1'
    # allow trailing space in output
    if out.endswith(' '):
        out = out.rstrip(' ')
    assert out == expected


def test_no_leading_trailing_spaces_for_minus_one(run, x):
    out = run(x).strip()
    if out == '-1':
        # ensure exactly '-1' without extra spaces
        full = run(x)
        assert full.strip() == full.rstrip() == full.lstrip()


def test_single_number_format(run, x):
    out = run(x).strip()
    if out == '-1':
        return
    nums = out.split()
    if len(nums) == 1:
        # single number: output could be like '8' or '8 '
        # strip trailing spaces and compare
        assert out.rstrip(' ') == nums[0]


def test_one_is_included_if_in_range(run, x):
    l, r, k = map(int, x.strip().split())
    out = run(x).strip()
    if out == '-1':
        # then 1 cannot be in range
        assert not (l <= 1 <= r)
        return
    nums = list(map(int, out.split()))
    if l <= 1 <= r:
        assert 1 in nums

