def test_answer_gt_input(run, x):
    y = int(x.strip())
    ans = int(run(x).strip())
    assert ans > y

def test_answer_within_bound(run, x):
    y = int(x.strip())
    ans = int(run(x).strip())
    # Calendar repeats within at most 400 years, but next repeat could be up to 28 normally.
    # Allow a safe upper bound of y + 800 (twice the 400‑year cycle) to be safe.
    assert ans <= y + 800

def test_leap_status_preserved(run, x):
    y = int(x.strip())
    ans = int(run(x).strip())
    def leap(year):
        return year % 400 == 0 or (year % 4 == 0 and year % 100 != 0)
    assert leap(y) == leap(ans)

def test_day_shift_consistency(run, x):
    y = int(x.strip())
    ans = int(run(x).strip())
    def leap(year):
        return year % 400 == 0 or (year % 4 == 0 and year % 100 != 0)
    # days shift from y to ans-1 must be multiple of 7
    shift = 0
    for yr in range(y, ans):
        shift += 366 if leap(yr) else 365
    assert shift % 7 == 0

def test_answer_mod400_cycle(run, x):
    y = int(x.strip())
    ans = int(run(x).strip())
    # Calendar repeats every 400 years in the Gregorian cycle.
    # So if two years have same calendar, (year % 400) must be same.
    # Actually, not exactly: years with same calendar have same leap status and same day-of-week offset,
    # but within 400‑year cycle the pattern repeats exactly, so (year mod 400) must be equal.
    # This is a known property: the Gregorian calendar repeats every 400 years.
    assert y % 400 == ans % 400

def test_brute_force_small(run, x):
    y = int(x.strip())
    if y > 10000:  # skip large inputs to keep test fast
        return
    def leap(year):
        return year % 400 == 0 or (year % 4 == 0 and year % 100 != 0)
    cur = y + 1
    while True:
        shift = 0
        for yr in range(y, cur):
            shift += 366 if leap(yr) else 365
        if shift % 7 == 0 and leap(y) == leap(cur):
            expected = cur
            break
        cur += 1
    assert int(run(x).strip()) == expected

def test_answer_is_integer(run, x):
    out = run(x).strip()
    # must be integer without extra whitespace
    int(out)  # will raise if not

def test_no_extra_output(run, x):
    out = run(x)
    lines = out.strip().split('\n')
    assert len(lines) == 1
    assert lines[0].strip() == out.strip()

def test_answer_not_equal_input(run, x):
    y = int(x.strip())
    ans = int(run(x).strip())
    assert ans != y

def test_answer_follows_28_mod_cycle(run, x):
    y = int(x.strip())
    ans = int(run(x).strip())
    # If both y and ans are not century years (or are divisible by 400),
    # the repeat period is exactly 28 years.
    def leap(year):
        return year % 400 == 0 or (year % 4 == 0 and year % 100 != 0)
    if leap(y) and (y % 100 != 0 or y % 400 == 0):
        # leap year not a special century -> 28‑year cycle
        assert (ans - y) % 28 == 0
    # For other cases we don't enforce anything, pass.

