        x_val, y_val = map(int, lines[i+1].split())
        s = x_val - y_val
        if s == 1:
            assert outputs[i].strip().lower() == 'no', f'When x-y=1, answer must be NO, got {outputs[i]}'


def test_s_prime_greater_than_1(run, x):
    import math
    def is_prime(n):
        if n < 2:
            return False
        if n in (2, 3):
            return True
        if n % 2 == 0 or n % 3 == 0:
            return False
        i = 5
        w = 2
        while i * i <= n:
            if n % i == 0:
                return False
            i += w
            w = 6 - w
        return True
    lines = x.strip().split('\n')
    t = int(lines[0].strip())
    outputs = run(x).strip().splitlines()
    for i in range(t):
        x_val, y_val = map(int, lines[i+1].split())
        s = x_val - y_val
        if s > 1 and is_prime(s):
            assert outputs[i].strip().lower() == 'yes', f'When x-y is prime (>1), answer must be YES, got {outputs[i]}'


