def test_s_power_of_two(run, x):
    def is_power_of_two(n):
        return n > 0 and (n & (n - 1)) == 0
    lines = x.strip().split('\n')
    t = int(lines[0].strip())
    outputs = run(x).strip().splitlines()
    for i in range(t):
