def test_output_is_non_negative_integer(run, x):
    out = run(x).strip()
    val = int(out)
    assert val >= 0

def test_output_upper_bound(run, x):
    a, b, c, d = map(int, x.strip().split())
    max_triangles = (b - a + 1) * (c - b + 1) * (d - c + 1)
    out = int(run(x).strip())
    assert out <= max_triangles

def test_brute_force_small(run, x):
    a, b, c, d = map(int, x.strip().split())
