    for x in range(a, b + 1):
        for y in range(b, c + 1):
            for z in range(c, d + 1):
                if x + y > z and x + z > y and y + z > x:
                    count += 1
    assert int(run(x).strip()) == count

def test_output_is_integer(run, x):
    out = run(x).strip()
    int(out)

def test_output_non_negative(run, x):
    out = int(run(x).strip())
    assert out >= 0

def test_output_single_token(run, x):
    tokens = run(x).strip().split()
    assert len(tokens) == 1

def test_single_point_triangle(run, x):
    a, b, c, d = map(int, x.strip().split())
    if a == b == c == d:
        # only one triple (x,y,z) = (a,a,a)
        # triangle non-degenerate iff 2*a > a (always true for a>0)
        expected = 1 if a > 0 else 0
        assert int(run(x).strip()) == expected

def test_at_least_one_if_possible(run, x):
    a, b, c, d = map(int, x.strip().split())
    # if there exists x in [a,b], y in [b,c], z in [c,d] with x+y>z, then answer >=1
    # simplest candidate: x = min(b, max(a, c))? Not always.
    # Instead, quick check: if max(x)+max(y) > min(z) then possible.
    max_x = b
    max_y = c
    min_z = c
    if max_x + max_y > min_z:
        assert int(run(x).strip()) >= 1

def test_known_examples(run, x):
    known = {
        '1 2 3 4': 4,
        '1 2 2 5': 3,
        '500000 500000 500000 500000': 1,
        '1 1 1 1': 1,
        '2 2 2 2': 1,
        '10 10 10 10': 1,
    }
    inp = x.strip()
    if inp in known:
        assert int(run(x).strip()) == known[inp]

