      "name": "test_brute_force_for_small_n",
      "source": "def test_brute_force_for_small_n(run, x):
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    n = int(lines[0])
    a = list(map(int, lines[1].split()))
    if n > 20:  # too big to brute-force safely in test environment
        return
    interesting = set(a)
    watch = 90
    for start in range(1, 91):
        if all((start + i) not in interesting for i in range(15)):
            watch = start + 14  # last minute before turning off
            break
    out = int(run(x).strip())
    assert out == watch, f'Brute force gives {watch}, got {out}'"
    },
    {
      "name": "test_if_all_gaps_le_14_then_90",
      "source": "def test_if_all_gaps_le_14_then_90(run, x):
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    n = int(lines[0])
    a = list(map(int, lines[1].split()))
    if n == 0:
        return
    gaps_ok = True
    prev = 0
    for t in a:
        if t - prev > 15:
            gaps_ok = False
            break
        prev = t
    if gaps_ok and (90 - a[-1] <= 14):
        out = int(run(x).strip())
        assert out == 90, f'No 15 consecutive boring minutes, answer must be 90'"
    },
