        return
    n = int(lines[0])
    a = list(map(int, lines[1].split()))
    if n == 0:
        return
    out = int(run(x).strip())
    assert out <= a[-1] + 15, f'Answer {out} cannot exceed last interesting minute {a[-1]} + 15'"
    },
