      "name": "test_answer_geq_min_of_90_or_first_gap",
      "source": "def test_answer_geq_min_of_90_or_first_gap(run, x):
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    n = int(lines[0])
    a = list(map(int, lines[1].split()))
    # compute earliest possible turn-off time based on first gap
    prev = 0
    for t in a:
        if t - prev > 15:
            out = int(run(x).strip())
            assert out >= prev + 15, f'Earliest turn-off is {prev+15}, got {out}'
            return
        prev = t
    # if loop finishes, no gap before last interesting minute
    out = int(run(x).strip())
    if 90 - a[-1] > 15:
        # there is a gap after last interesting minute
        assert out >= a[-1] + 15, f'Earliest turn-off after last interesting is {a[-1]+15}, got {out}'
    else:
        # no gap of 15 anywhere
        assert out == 90, f'No gap of 15, must watch whole 90 minutes'"
    },
    {
      "name": "test_answer_integer_consistent_with_gap_rule",
      "source": "def test_answer_integer_consistent_with_gap_rule(run, x):
    # This is a meta-check: if answer is not 90, then there must be a 15-minute boring segment ending at that answer.
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    n = int(lines[0])
    a = list(map(int, lines[1].split()))
    out = int(run(x).strip())
    if out < 90:
        interesting = set(a)
        found = False
        for start in range(1, out - 13):  # start of 15-minute boring segment
            if all((start + i) not in interesting for i in range(15)):
                if start + 14 == out:
                    found = True
                    break
        assert found, f'Answer {out} is not the end of a 15-minute boring segment'"
    }
  ]
}

