def test_output_format(run, x):
    out = run(x).strip()
    # Must be a single integer, possibly negative
    try:
        val = int(out)
        # No extra whitespace or text
        assert str(val) == out.strip()
    except ValueError:
        assert False, f'Output "{out}" is not an integer'

def test_answer_bounds(run, x):
    out = run(x).strip()
    ans = int(out)
    parts = x.strip().split()
    n = int(parts[0])
    # Answer must be -1, 0, 1, ..., n
    assert -1 <= ans <= n

def test_if_m_le_k_then_zero(run, x):
    parts = x.strip().split()
    n, m, k = map(int, parts[:3])
    if m <= k:
        ans = int(run(x).strip())
        assert ans == 0, f'When m <= k, answer must be 0, got {ans}'

def test_if_zero_devices(run, x):
    parts = x.strip().split()
    n, m, k = map(int, parts[:3])
    if m == 0:
        ans = int(run(x).strip())
        assert ans == 0, f'When m=0, answer must be 0, got {ans}'

def test_if_no_sockets_and_no_filters(run, x):
    parts = x.strip().split()
    n, m, k = map(int, parts[:3])
    if k == 0 and n == 0:
        ans = int(run(x).strip())
        # No sockets and no filters → impossible unless m=0
        if m > 0:
            assert ans == -1, f'No sockets and no filters, m>0 must give -1, got {ans}'

def test_if_all_filters_used_still_impossible(run, x):
    parts = x.strip().split()
    n, m, k = map(int, parts[:3])
    a = list(map(int, parts[3:]))
    # Upper bound: total sockets if we use all filters in a chain
    total = k
    for val in sorted(a, reverse=True):
        total += val - 1  # each filter consumes one socket
    if total < m:
        ans = int(run(x).strip())
        assert ans == -1, f'Even using all filters, total sockets {total} < m={m}, must be -1, got {ans}'

def test_answer_not_negative_unless_minus_one(run, x):
    ans = int(run(x).strip())
    assert ans == -1 or ans >= 0, f'Answer {ans} is negative and not -1'

def test_if_k_zero_and_m_positive_requires_filters(run, x):
    parts = x.strip().split()
    n, m, k = map(int, parts[:3])
    if k == 0 and m > 0:
        ans = int(run(x).strip())
        # Need at least one filter to get any socket
        if ans != -1:
            assert ans >= 1, f'When k=0 and m>0, answer must be at least 1 or -1, got {ans}'

def test_brute_force_small_inputs(run, x):
    parts = x.strip().split()
    n, m, k = map(int, parts[:3])
    a = list(map(int, parts[3:]))
    # Only brute‑force when input is small enough
    if n <= 8 and m <= 8 and k <= 8:
        from itertools import combinations
        best = n + 1
        for r in range(n + 1):
            for comb in combinations(range(n), r):
                total = k
                for idx in comb:
                    total += a[idx] - 1
                if total >= m:
                    best = min(best, r)
        correct = -1 if best == n + 1 else best
        ans = int(run(x).strip())
        assert ans == correct, f'Brute‑force says {correct}, got {ans}'

def test_if_one_filter_enough_then_answer_at_most_one(run, x):
    parts = x.strip().split()
    n, m, k = map(int, parts[:3])
    a = list(map(int, parts[3:]))
    # Check if any single filter gives enough sockets
    for val in a:
        if k + val - 1 >= m:
            ans = int(run(x).strip())
            assert 0 <= ans <= 1, f'A single filter works, answer should be 0 or 1, got {ans}'

