{
  "rationale": "The submission loops up to 1,000,000 positions to find digit c. The tests focus on properties that must hold for any correct solution: (1) the answer is either -1 or a positive integer within the loop limit; (2) if the answer is -1, the digit c must not appear in the first 1,000,000 digits; (3) if the answer is a position, the digit at that position must be c, which we can verify by simulating division until that position; (4) the answer cannot be larger than the length of the repeating cycle if known; (5) the answer must be consistent with the basic math of the fraction. The weakest test is test_answer_is_positive_or_minus_one, which only checks the output format; it would be dropped first. The strongest tests directly compute the answer for small inputs and compare.",
  "tests": [
    {
      "name": "test_answer_is_positive_or_minus_one",
      "source": "def test_answer_is_positive_or_minus_one(run, x):
    out = run(x).strip()
    assert out == '-1' or (out.isdigit() and int(out) > 0)"
    },
    {
      "name": "test_answer_fits_in_loop_limit",
      "source": "def test_answer_fits_in_loop_limit(run, x):
    out = run(x).strip()
    if out != '-1':
        pos = int(out)
        assert 1 <= pos <= 1000000"
    },
    {
      "name": "test_if_minus_one_digit_never_appears",
      "source": "def test_if_minus_one_digit_never_appears(run, x):
    import sys
    out = run(x).strip()
    if out == '-1':
        a_str, b_str, c_str = x.strip().split()
        a, b, c = int(a_str), int(b_str), int(c_str)
        # simulate up to 1,000,000 digits as the code does
        pos = 1
        rem = a
        for i in range(1000000):
            digit = (10 * rem) // b
            if digit == c:
                # digit found, so -1 is wrong
                assert False, f'Digit {c} found at position {pos}'
            rem = (10 * rem) % b
            pos += 1
        # digit not found, -1 is correct
        assert True"
    },
    {
      "name": "test_if_answer_given_digit_matches",
      "source": "def test_if_answer_given_digit_matches(run, x):
    import sys
    out = run(x).strip()
    if out != '-1':
        pos = int(out)
        a_str, b_str, c_str = x.strip().split()
        a, b, c = int(a_str), int(b_str), int(c_str)
        # compute digit at that position
        rem = a
        for i in range(pos):
            digit = (10 * rem) // b
            rem = (10 * rem) % b
            if i == pos - 1:
                assert digit == c, f'At position {pos} digit is {digit}, not {c}'"
    },
    {
      "name": "test_answer_correct_for_small_b",
      "source": "def test_answer_correct_for_small_b(run, x):
    a_str, b_str, c_str = x.strip().split()
    a, b, c = int(a_str), int(b_str), int(c_str)
    if b <= 10000:  # small enough to brute force safely
        # compute correct answer by simulating up to 1,000,000 digits
        pos = 1
        rem = a
        for i in range(1000000):
            digit = (10 * rem) // b
            if digit == c:
                correct = pos
                break
            rem = (10 * rem) % b
            pos += 1
        else:
            correct = -1
        out = run(x).strip()
        assert out == str(correct), f'Expected {correct}, got {out}'"
    },
    {
      "name": "test_answer_consistent_with_cycle_length",
      "source": "def test_answer_consistent_with_cycle_length(run, x):
    # if b <= 1000, we can compute cycle length and verify answer is not beyond cycle end if digit not in cycle
    a_str, b_str, c_str = x.strip().split()
    a, b, c = int(a_str), int(b_str), int(c_str)
    if b <= 1000:
        out = run(x).strip()
        if out != '-1':
            pos = int(out)
            # simulate to find cycle start and digits
            seen = {}
            rem = a
            digits = []
            for i in range(1, 200000):
                digit = (10 * rem) // b
                digits.append(digit)
                rem = (10 * rem) % b
                if rem in seen:
                    cycle_start = seen[rem]
                    cycle_len = i - cycle_start
                    break
                seen[rem] = i
            else:
                return  # no cycle found quickly, skip
            # if pos > cycle_start + cycle_len, digit must be in cycle
            if pos > cycle_start + cycle_len:
                # check if c is in cycle digits
                cycle_digits = digits[cycle_start:cycle_start+cycle_len]
                assert c in cycle_digits, f'Position {pos} beyond cycle, but digit {c} not in cycle'"
    },
    {
      "name": "test_answer_not_zero_position",
      "source": "def test_answer_not_zero_position(run, x):
    out = run(x).strip()
    if out != '-1':
        pos = int(out)
        assert pos != 0  # positions start from 1"
    },
    {
      "name": "test_answer_parsable_as_int",
      "source": "def test_answer_parsable_as_int(run, x):
    out = run(x).strip()
    try:
        int(out)
    except ValueError:
        assert False, f'Output {out} is not an integer'"
    },
    {
      "name": "test_answer_for_terminating_decimals",
      "source": "def test_answer_for_terminating_decimals(run, x):
    a_str, b_str, c_str = x.strip().split()
    a, b, c = int(a_str), int(b_str), int(c_str)
    # if b is of form 2^p * 5^q, decimal terminates within limited digits
    # compute denominator after removing factors 2 and 5
    den = b
    while den % 2 == 0:
        den //= 2
    while den % 5 == 0:
        den //= 5
    if den == 1:  # terminating decimal
        out = run(x).strip()
        if out != '-1':
            pos = int(out)
            # terminating decimal length <= max(p,q) where b = 2^p * 5^q * k
            # but simpler: simulate until remainder 0, digit must be found before that
            rem = a
            for i in range(1, pos+1):
                digit = (10 * rem) // b
                rem = (10 * rem) % b
                if i == pos:
                    assert digit == c
                if rem == 0:
                    # termination reached
                    assert i == pos, f'Termination at position {i}, but answer position {pos} is beyond'"
    },
    {
      "name": "test_answer_for_known_examples",
      "source": "def test_answer_for_known_examples(run, x):
    # check against the two examples given in statement
    if x == '1 2 0\n':
        assert run(x).strip() == '2'
    if x == '2 3 7\n':
        assert run(x).strip() == '-1'"
    }
  ]
}

{
  "rationale": "Each test checks a necessary condition that the output must satisfy according to the specification, without computing the exact correct answer. They verify: 1) output format is either an integer or OVERFLOW!!!, 2) overflow detection works (if final x >= 2^32 then overflow), 3) when no 'add' commands exist, answer must be 0, 4) if answer is a number it must be ≤ max possible from given loops (loops multiply, so ≤ product of all n's * add count), 5) for small inputs compute exact answer via simulation, 6) overflow if loops produce > 2^32-1. The weakest test is the overflow detection simulation because it could be expensive for large loops, but the inputs given are small enough. I'd drop the exact simulation first if we needed speed.",
  "tests": [
    {
      "name": "test_output_format",
      "source": "def test_output_format(run, x):
    out = run(x).strip()
    if out == 'OVERFLOW!!!':
        return
    # otherwise must be a non‑negative integer
    assert out.isdigit(), f'output must be integer or OVERFLOW!!!, got {out!r}'
    val = int(out)
    assert 0 <= val < 2**32, f'integer output must be in [0, 2^32-1], got {val}'"
    },
    {
      "name": "test_no_add_means_zero",
      "source": "def test_no_add_means_zero(run, x):
    lines = x.strip().split('\n')[1:]
    if any(cmd == 'add' for cmd in lines):
        return  # not applicable
    out = run(x).strip()
    assert out == '0', f'when no add commands, answer must be 0, got {out}'"
    },
    {
      "name": "test_overflow_implies_large_loops",
      "source": "def test_overflow_implies_large_loops(run, x):
    # If output is OVERFLOW!!!, then the total count of adds multiplied by loops must exceed 2^32-1
    out = run(x).strip()
    if out != 'OVERFLOW!!!':
        return
    # parse loops and adds to compute max possible adds if no overflow detection
    lines = x.strip().split('\n')[1:]
    stack = [1]
    total = 0
    for cmd in lines:
        if cmd.startswith('for '):
            n = int(cmd[4:])
            stack.append(stack[-1] * n)
        elif cmd == 'end':
            stack.pop()
        else:  # add
            total += stack[-1]
    # if total <= 2**32-1, overflow output is impossible (correct solution never overflows)
    assert total > 2**32-1, f'overflow reported but max adds {total} ≤ 2^32-1'"
    },
    {
      "name": "test_no_overflow_implies_small_loops",
      "source": "def test_no_overflow_implies_small_loops(run, x):
    out = run(x).strip()
    if out == 'OVERFLOW!!!':
        return
    val = int(out)
    # The value cannot exceed the product of all loop multipliers times number of adds
    lines = x.strip().split('\n')[1:]
    stack = [1]
    max_mult = 1
