def test_output_format(run, x):
    out = run(x).strip()
    if out == 'OVERFLOW!!!':
        return
    # otherwise must be a non‑negative integer
    assert out.isdigit(), f'output must be integer or OVERFLOW!!!, got {out!r}'
    val = int(out)
    assert 0 <= val < 2**32, f'integer output must be in [0, 2^32-1], got {val}'

def test_no_add_means_zero(run, x):
    lines = x.strip().split('\n')[1:]
    if any(cmd == 'add' for cmd in lines):
        return  # not applicable
    out = run(x).strip()
    assert out == '0', f'when no add commands, answer must be 0, got {out}'

def test_overflow_implies_large_loops(run, x):
    # If output is OVERFLOW!!!, then the total count of adds multiplied by loops must exceed 2^32-1
    out = run(x).strip()
    if out != 'OVERFLOW!!!':
        return
    # parse loops and adds to compute max possible adds if no overflow detection
    lines = x.strip().split('\n')[1:]
    stack = [1]
    total = 0
    for cmd in lines:
        if cmd.startswith('for '):
            n = int(cmd[4:])
            stack.append(stack[-1] * n)
        elif cmd == 'end':
            stack.pop()
        else:  # add
            total += stack[-1]
    # if total <= 2**32-1, overflow output is impossible (correct solution never overflows)
    assert total > 2**32-1, f'overflow reported but max adds {total} ≤ 2^32-1'

def test_no_overflow_implies_small_loops(run, x):
    out = run(x).strip()
    if out == 'OVERFLOW!!!':
        return
    val = int(out)
    # The value cannot exceed the product of all loop multipliers times number of adds
    lines = x.strip().split('\n')[1:]
    stack = [1]
    max_mult = 1
    add_count = 0
    for cmd in lines:
        if cmd.startswith('for '):
            n = int(cmd[4:])
            stack.append(stack[-1] * n)
            if stack[-1] > max_mult:
                max_mult = stack[-1]
        elif cmd == 'end':
            stack.pop()
        else:
            add_count += 1
    # trivial bound: each add multiplied by at most product of all active loops
    # but easier: total adds <= add_count * max_mult
    # Actually, a tighter bound: total <= sum over each add of product of active loops at that point
    # We compute a safe over‑approximation: product of all n's (if we multiply everything) times add_count
    # Since each n ≤ 100 and loops are nested, product can be huge, but we can compute product of all 'for n' ignoring ends?
    # Simpler: simulate without overflow, but limit product to 2**32 to keep it fast.
    # Because input size ≤ 10^5, but our given inputs are small, we can simulate safely.
    prod = 1
    total = 0
    for cmd in lines:
        if cmd.startswith('for '):
            n = int(cmd[4:])
            prod *= n
        elif cmd == 'end':
            # we don't know which for ends, cannot undo easily without stack.
            # So fall back to a very weak bound: each add contributes at most 100^{depth} ≤ 100^{len(lines)}.
            # Since our given inputs are tiny, we can afford a full simulation.
            pass
    # For safety, only run simulation on small inputs.
    if len(lines) <= 30:  # our inputs are all small
        stack = [1]
        sim = 0
        for cmd in lines:
            if cmd.startswith('for '):
                n = int(cmd[4:])
                stack.append(stack[-1] * n)
            elif cmd == 'end':
                stack.pop()
            else:
                sim += stack[-1]
        assert val <= sim, f'output {val} cannot exceed naive simulation {sim}'
    # else skip

def test_overflow_string_exact(run, x):
    out = run(x).strip()
    if out == 'OVERFLOW!!!':
        assert out == 'OVERFLOW!!!', 'overflow output must be exactly OVERFLOW!!!'
    else:
        assert out != 'OVERFLOW!!!', 'non‑overflow output must not be OVERFLOW!!!'

def test_integer_output_non_negative(run, x):
    out = run(x).strip()
    if out == 'OVERFLOW!!!':
        return
    val = int(out)
    assert val >= 0, f'output must be non‑negative, got {val}'

def test_small_input_exact_simulation(run, x):
    lines = x.strip().split('\n')[1:]
    if len(lines) > 20:  # only run on tiny inputs
        return
    # brute‑force simulation as per specification
    stack = [1]
    total = 0
    overflow = False
    for cmd in lines:
        if cmd.startswith('for '):
            n = int(cmd[4:])
            stack.append(stack[-1] * n)
        elif cmd == 'end':
            stack.pop()
        else:
            total += stack[-1]
        if total >= 2**32:
            overflow = True
    expected = 'OVERFLOW!!!' if overflow else str(total)
    assert run(x).strip() == expected, f'for small input exact simulation expects {expected}'

def test_overflow_only_if_exceeds_limit(run, x):
    out = run(x).strip()
    # compute total adds without overflow detection, using Python big ints
    lines = x.strip().split('\n')[1:]
    stack = [1]
    total = 0
    for cmd in lines:
        if cmd.startswith('for '):
            n = int(cmd[4:])
            stack.append(stack[-1] * n)
        elif cmd == 'end':
            stack.pop()
        else:
            total += stack[-1]
    if total < 2**32:
        assert out != 'OVERFLOW!!!', f'overflow output but total adds {total} < 2^32'
    # if total >= 2**32, overflow is allowed (not required, because early break may happen)
    # so we don't enforce overflow in that case

def test_output_consistent_with_early_break(run, x):
    # If overflow occurs early, the returned number may be less than total simulation.
    # But it must still be ≤ total simulation.
    out = run(x).strip()
    if out == 'OVERFLOW!!!':
        return
    val = int(out)
    lines = x.strip().split('\n')[1:]
    stack = [1]
    sim = 0
    for cmd in lines:
        if cmd.startswith('for '):
            n = int(cmd[4:])
            stack.append(stack[-1] * n)
        elif cmd == 'end':
            stack.pop()
        else:
            sim += stack[-1]
    assert val <= sim, f'output {val} cannot exceed full simulation {sim}'

def test_overflow_string_no_extra_chars(run, x):
    out = run(x)
    if out.startswith('OVERFLOW!!!'):
        # must be exactly OVERFLOW!!! possibly followed by newline
        stripped = out.strip()
        assert stripped == 'OVERFLOW!!!', f'overflow string must be exactly OVERFLOW!!!, got {out!r}'

