def test_output_parsing(run, x):
    out = run(x).strip()
    if out == "Impossible":
        return
    parts = out.split()
    assert len(parts) == 3, "Output must be three integers or 'Impossible'"
    for p in parts:
        assert p.isdigit() or (p[0] == '-' and p[1:].isdigit()), "Each part must be an integer"
        val = int(p)
        assert val >= 0, "Bond counts must be non-negative"


def test_valence_equations(run, x):
    out = run(x).strip()
    if out == "Impossible":
        return
    a, b, c = map(int, x.strip().split())
    d, e, f = map(int, out.split())
    assert d + f == a, "First atom valence mismatch"
    assert d + e == b, "Second atom valence mismatch"
    assert e + f == c, "Third atom valence mismatch"


def test_bonds_nonnegative(run, x):
    out = run(x).strip()
    if out == "Impossible":
        return
    d, e, f = map(int, out.split())
    assert d >= 0 and e >= 0 and f >= 0, "Bond counts must be non-negative"


def test_even_sum(run, x):
    a, b, c = map(int, x.strip().split())
    # The sum of valences is twice the total bonds
    # So a+b+c must be even for a solution to exist
    if (a + b + c) % 2 != 0:
        out = run(x).strip()
        assert out == "Impossible", "If sum of valences is odd, must be impossible"


def test_triangle_inequalities(run, x):
    a, b, c = map(int, x.strip().split())
    # For a solution to exist, each valence ≤ sum of the other two
    # because bonds are non‑negative.
    if a > b + c or b > a + c or c > a + b:
        out = run(x).strip()
        assert out == "Impossible", "Valence too large compared to others implies impossible"


def test_small_brute_force_under_10(run, x):
    a, b, c = map(int, x.strip().split())
    if max(a, b, c) > 10:
        return  # too large for brute force
    found = False
    for d in range(a + 1):
        for e in range(b + 1):
            for f in range(c + 1):
                if d + f == a and d + e == b and e + f == c:
                    found = True
                    break
            if found:
                break
        if found:
            break
    out = run(x).strip()
    if found:
        assert out != "Impossible", "Solution exists but output says impossible"
        d_out, e_out, f_out = map(int, out.split())
        assert d_out + f_out == a and d_out + e_out == b and e_out + f_out == c
    else:
        assert out == "Impossible", "No solution exists but output gives numbers"


def test_non_negative_integers_or_impossible(run, x):
    out = run(x).strip()
    if out != "Impossible":
        parts = out.split()
        assert len(parts) == 3, "Output must have three integers"
        for p in parts:
            val = int(p)
            assert val >= 0, "Bond count cannot be negative"


def test_sum_of_bonds_even(run, x):
    a, b, c = map(int, x.strip().split())
    out = run(x).strip()
    if out != "Impossible":
        d, e, f = map(int, out.split())
        total_bonds = d + e + f
        assert total_bonds == (a + b + c) // 2, "Total bonds must equal half the sum of valences"
        assert (a + b + c) % 2 == 0, "Sum of valences must be even (already implied)"


def test_bounds_from_valences(run, x):
    a, b, c = map(int, x.strip().split())
    out = run(x).strip()
    if out == "Impossible":
        return
    d, e, f = map(int, out.split())
    assert 0 <= d <= min(a, b), "d out of possible range"
    assert 0 <= e <= min(b, c), "e out of possible range"
    assert 0 <= f <= min(c, a), "f out of possible range"


def test_small_exact_brute_force_under_6(run, x):
    a, b, c = map(int, x.strip().split())
    if max(a, b, c) > 6:
        return
    solutions = []
    for d in range(a + 1):
        for e in range(b + 1):
            for f in range(c + 1):
                if d + f == a and d + e == b and e + f == c:
                    solutions.append((d, e, f))
    out = run(x).strip()
    if solutions:
        assert out != "Impossible", "Solution exists but output says impossible"
        d_out, e_out, f_out = map(int, out.split())
        assert (d_out, e_out, f_out) in solutions, "Output is not a valid solution"
    else:
        assert out == "Impossible", "No solution exists but output gives numbers"

def test_output_format(run, x):
    out = run(x).strip()
    if out == "Impossible":
        return
    parts = out.split()
    assert len(parts) == 3, "When not Impossible, output must be three integers"
    for p in parts:
        assert p.isdigit() or (p[0] == '-' and p[1:].isdigit()), "Output must be integers"
    d, e, f = map(int, parts)
    # additional checks done in other tests


def test_bonds_nonnegative(run, x):
    out = run(x).strip()
    if out == "Impossible":
        return
    d, e, f = map(int, out.split())
    assert d >= 0 and e >= 0 and f >= 0, "Bond counts cannot be negative"


def test_bonds_are_nonnegative_integers(run, x):
    out = run(x).strip()
    if out == "Impossible":
        return
    parts = out.split()
    d, e, f = map(int, parts)
    assert d >= 0 and e >= 0 and f >= 0, "Bond counts must be non‑negative integers"
    # also check they are integers (already done by parsing)


def test_valence_satisfied(run, x):
    a, b, c = map(int, x.strip().split())
    out = run(x).strip()
    if out == "Impossible":
        return
    d, e, f = map(int, out.split())
    # d = bonds between 1 and 2, e = between 2 and 3, f = between 3 and 1
    assert d + f == a, f"Atom 1 must have exactly {a} bonds"
    assert d + e == b, f"Atom 2 must have exactly {b} bonds"
    assert e + f == c, f"Atom 3 must have exactly {c} bonds"


def test_impossible_parity(run, x):
    a, b, c = map(int, x.strip().split())
    out = run(x).strip()
    # Known necessary condition: a+b+c must be even
    if (a + b + c) % 2 != 0:
        assert out == "Impossible", f"Sum {a+b+c} is odd, must be Impossible"


def test_impossible_triangle_inequality(run, x):
    a, b, c = map(int, x.strip().split())
    out = run(x).strip()
    # For non‑negative bonds we need: a <= b + c, b <= a + c, c <= a + b
    if a > b + c or b > a + c or c > a + b:
        assert out == "Impossible", f"Valence violates triangle inequality, must be Impossible"


def test_small_input_bruteforce(run, x):
    a, b, c = map(int, x.strip().split())
    if max(a, b, c) > 10:  # brute force only for small numbers, keep test fast
        return
    out = run(x).strip()
    # brute force all possible non‑negative d, e, f up to max valence
    found = False
    maxv = max(a, b, c)
    for d in range(maxv + 1):
        for e in range(maxv + 1):
            for f in range(maxv + 1):
                if d + f == a and d + e == b and e + f == c:
                    found = True
                    if out != "Impossible":
                        d1, e1, f1 = map(int, out.split())
                        if (d1, e1, f1) == (d, e, f):
                            return  # exact match, okay
    if found:
        # at least one solution exists, so output must be a solution
        assert out != "Impossible", f"Solution exists but output is Impossible"
        d1, e1, f1 = map(int, out.split())
        assert d1 + f1 == a and d1 + e1 == b and e1 + f1 == c, "Output does not satisfy valence"
    else:
        # no solution exists
        assert out == "Impossible", f"No solution exists but output is not Impossible"


def test_output_integer_bounds(run, x):
    a, b, c = map(int, x.strip().split())
    out = run(x).strip()
    if out == "Impossible":
        return
    d, e, f = map(int, out.split())
    # each bond count cannot exceed the smaller valence of the two atoms it connects
    # but the spec does not explicitly forbid extra bonds, only that total per atom matches.
    # However, bonds are non‑negative and the equations already enforce the totals.
    # So we only check they are integers (already done) and non‑negative.
    assert d >= 0 and e >= 0 and f >= 0


def test_consistency_with_given_examples(run, x):
    # For the three example inputs from the statement, output must match exactly.
    if x == "1 1 2\n":
        assert run(x).strip() == "0 1 1"
    elif x == "3 4 5\n":
        assert run(x).strip() == "1 3 2"
    elif x == "4 1 1\n":
        assert run(x).strip() == "Impossible"


def test_impossible_if_any_valence_zero(run, x):
    a, b, c = map(int, x.strip().split())
    out = run(x).strip()
    # Actually, valence numbers are at least 1 per problem constraints (1 ≤ a,b,c).
    # So this test is redundant, but kept as a placeholder for a generic property.
    # Instead, we check that if the output is not Impossible, the equations hold.
    if out != "Impossible":
        d, e, f = map(int, out.split())
        assert d + f == a and d + e == b and e + f == c

