def test_output_length_matches_input(run, x):
    lines = x.strip('\n').split('\n')
    direction = lines[0]
    typed = lines[1]
    output = run(x).strip('\n')
    assert len(output) == len(typed), f'Output length {len(output)} != typed length {len(typed)}'

def test_output_characters_are_keyboard_chars(run, x):
    keyboard = set('qwertyuiopasdfghjkl;zxcvbnm,./')
    output = run(x).strip('\n')
    for ch in output:
        assert ch in keyboard, f'Output char {ch} not in keyboard'

def test_output_contains_no_spaces(run, x):
    output = run(x).strip('\n')
    assert ' ' not in output, 'Output contains space'

def test_mapping_reversibility(run, x):
    lines = x.strip('\n').split('\n')
    direction = lines[0]
    typed = lines[1]
    output = run(x).strip('\n')
    rows = ['qwertyuiop', 'asdfghjkl;', 'zxcvbnm,./']
    for out_ch, in_ch in zip(output, typed):
        found = False
        for row in rows:
            if out_ch in row:
                idx = row.index(out_ch)
                if direction == 'R':
                    # shifting left from output should give input
                    expected_in = row[idx-1] if idx > 0 else None
                else:  # 'L'
                    expected_in = row[idx+1] if idx+1 < len(row) else None
                if expected_in == in_ch:
                    found = True
                break
        assert found, f'Mapping mismatch: out={out_ch}, in={in_ch}, dir={direction}'

def test_no_impossible_shift(run, x):
    lines = x.strip('\n').split('\n')
    direction = lines[0]
    typed = lines[1]
    output = run(x).strip('\n')
    rows = ['qwertyuiop', 'asdfghjkl;', 'zxcvbnm,./']
    for out_ch, in_ch in zip(output, typed):
        for row in rows:
            if out_ch in row:
                idx = row.index(out_ch)
                if direction == 'R':
                    # output is left of input, so out_ch cannot be rightmost
                    assert idx != len(row)-1, f'Out char {out_ch} at right end for R shift'
                else:  # 'L'
                    # output is right of input, so out_ch cannot be leftmost
                    assert idx != 0, f'Out char {out_ch} at left end for L shift'
                break

def test_first_row_left_shift_valid(run, x):
    lines = x.strip('\n').split('\n')
    direction = lines[0]
    typed = lines[1]
    output = run(x).strip('\n')
    if direction != 'L':
        return
    first_row = 'qwertyuiop'
    for out_ch, in_ch in zip(output, typed):
        if in_ch in first_row:
            idx = first_row.index(in_ch)
            expected_out = first_row[idx+1] if idx+1 < len(first_row) else None
            if expected_out is not None:
                assert out_ch == expected_out, f'First row L shift mismatch: in={in_ch}, out={out_ch}'

def test_last_row_right_shift_valid(run, x):
    lines = x.strip('\n').split('\n')
    direction = lines[0]
    typed = lines[1]
    output = run(x).strip('\n')
    if direction != 'R':
        return
    last_row = 'zxcvbnm,./'
    for out_ch, in_ch in zip(output, typed):
        if in_ch in last_row:
            idx = last_row.index(in_ch)
            expected_out = last_row[idx-1] if idx > 0 else None
            if expected_out is not None:
                assert out_ch == expected_out, f'Last row R shift mismatch: in={in_ch}, out={out_ch}'

def test_middle_row_boundary(run, x):
    lines = x.strip('\n').split('\n')
    direction = lines[0]
    typed = lines[1]
    output = run(x).strip('\n')
    middle_row = 'asdfghjkl;'
    for out_ch, in_ch in zip(output, typed):
        if in_ch == 'a' and direction == 'R':
            # shifting right from 'a' gives 'q' (not in middle row)
            # so out_ch should not be from middle row
            if out_ch in middle_row:
                assert False, f'R shift from a gave middle row char {out_ch}'
        if in_ch == ';' and direction == 'L':
            # shifting left from ';' gives 'l' (in middle row)
            # actually specification guarantees input is on keyboard, so ';' shifted left is 'l'
            # but we just check that out_ch is 'l'
            assert out_ch == 'l', f'L shift from ; gave {out_ch} not l'

def test_all_rows_covered(run, x):
    lines = x.strip('\n').split('\n')
    typed = lines[1]
    output = run(x).strip('\n')
    rows = ['qwertyuiop', 'asdfghjkl;', 'zxcvbnm,./']
    for out_ch in output:
        assert any(out_ch in row for row in rows), f'Output char {out_ch} not in any row'

def test_non_empty_output_for_non_empty_input(run, x):
    lines = x.strip('\n').split('\n')
    typed = lines[1]
    output = run(x).strip('\n')
    if typed:
        assert output, 'Output empty for non-empty input'

