tests_src:
def test_output_format(run, x):
    out = run(x).strip()
    if out == '-1':
        return
    # Must be a non-negative integer without leading zeros
    assert out.isdigit(), f'Output must be digits, got {out!r}'
    if out != '0':
        assert out[0] != '0', f'Leading zero in {out!r}'


def test_divisible_by_90_if_not_minus1(run, x):
    out = run(x).strip()
    if out == '-1':
        return
    num = int(out)
    assert num % 90 == 0, f'Output {num} not divisible by 90'


def test_digits_are_only_0_or_5(run, x):
    out = run(x).strip()
    if out == '-1':
        return
    for ch in out:
        assert ch in '05', f'Digit {ch} not allowed'


def test_digit_counts_do_not_exceed_input(run, x):
    out = run(x).strip()
    if out == '-1':
        return
    lines = x.strip().split('\n')
    n = int(lines[0])
    cards = list(map(int, lines[1].split()))
    available_0 = cards.count(0)
    available_5 = cards.count(5)
    used_0 = out.count('0')
    used_5 = out.count('5')
    assert used_0 <= available_0, f'Used {used_0} zeros but only {available_0} available'
    assert used_5 <= available_5, f'Used {used_5} fives but only {available_5} available'


def test_if_no_zeros_then_minus1(run, x):
    lines = x.strip().split('\n')
    cards = list(map(int, lines[1].split()))
    if 0 not in cards:
        out = run(x).strip()
        assert out == '-1', f'No zero cards, output must be -1, got {out!r}'


def test_if_some_zeros_and_no_fives_then_0(run, x):
    lines = x.strip().split('\n')
    cards = list(map(int, lines[1].split()))
    if 0 in cards and 5 not in cards:
        out = run(x).strip()
        assert out == '0', f'Only zeros, output must be 0, got {out!r}'


def test_output_is_not_empty_if_not_minus1(run, x):
    out = run(x).strip()
    if out == '-1':
        return
    assert out != '', 'Output cannot be empty'


def test_output_is_maximum_by_brute_force(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    if n > 10:
        return  # too big for brute force
    cards = list(map(int, lines[1].split()))
    best = -1
    from itertools import combinations
    for r in range(1, n + 1):
        for combo in combinations(cards, r):
            # generate all permutations of combo
            from itertools import permutations
            seen = set()
            for perm in permutations(combo):
                if perm[0] == 0 and len(perm) > 1:
                    continue
                num = int(''.join(str(d) for d in perm))
                if num % 90 == 0:
                    if num > best:
                        best = num
    # also consider using zero alone
    if 0 in cards:
        if 0 > best:
            best = 0
    out = run(x).strip()
    if best == -1:
        assert out == '-1', f'Brute force says impossible, got {out!r}'
    else:
        assert out != '-1', f'Brute force found {best}, but output is -1'
        assert int(out) == best, f'Brute force max is {best}, got {out!r}'


def test_output_length_not_exceed_n(run, x):
    out = run(x).strip()
    if out == '-1':
        return
    lines = x.strip().split('\n')
    n = int(lines[0])
    assert len(out) <= n, f'Output length {len(out)} exceeds n={n}'


def test_output_is_non_negative(run, x):
    out = run(x).strip()
    if out == '-1':
        return
    num = int(out)
    assert num >= 0, f'Output {num} is negative'

