tests_src:
def test_output_is_integer(run, x):
    output = run(x).strip()
    # Must be a valid integer
    int(output)

def test_output_nonnegative(run, x):
    output = run(x).strip()
    val = int(output)
    assert val >= 0

def test_example_00(run, x):
    if x.strip() == '00':
        output = run(x).strip()
        assert output == '4'

def test_example_89(run, x):
    if x.strip() == '89':
        output = run(x).strip()
        assert output == '2'

def test_example_73(run, x):
    if x.strip() == '73':
        output = run(x).strip()
        assert output == '15'

def test_output_range_1_to_100(run, x):
    output = run(x).strip()
    val = int(output)
    assert 1 <= val <= 100

def test_no_extra_whitespace(run, x):
    output = run(x)
    # Should be exactly digits followed by newline
    assert output == output.strip() + '\n'

def test_symmetric_digits(run, x):
    # Swapping digits should give same answer
    s = x.strip()
    if len(s) == 2 and s[0] != s[1]:
        swapped = s[1] + s[0] + '\n'
        # We cannot call run again, so we cannot test this.
        # This test is invalid under the one-call rule.
        # Instead we just pass.
        pass

def test_perfect_square_if_digits_equal(run, x):
    s = x.strip()
    if len(s) == 2 and s[0] == s[1]:
        output = run(x).strip()
        val = int(output)
        import math
        root = int(math.isqrt(val))
        assert root * root == val

def test_at_most_100(run, x):
    output = run(x).strip()
    val = int(output)
    assert val <= 100

