def test_output_format(run, x):
    out = run(x)
    lines = out.strip('\n').split('\n')
    assert len(lines) == 1, 'Output must be a single line'
    val = lines[0]
    assert val.isdigit() or (val[0]=='-' and val[1:].isdigit()), 'Output must be an integer'
    int_val = int(val)
    # no further restriction


def test_non_negative(run, x):
    out = run(x)
    val = int(out.strip())
    assert val >= 0, 'Number of faces cannot be negative'


def test_upper_bound(run, x):
    lines = x.strip('\n').split('\n')
    n, m = map(int, lines[0].split())
    out = run(x)
    ans = int(out.strip())
    max_possible = max(0, (n-1)*(m-1))
    assert ans <= max_possible, f'Answer {ans} exceeds maximum possible 2x2 squares ({max_possible})'


def test_one_row_or_col_zero(run, x):
    lines = x.strip('\n').split('\n')
    n, m = map(int, lines[0].split())
    if n == 1 or m == 1:
        out = run(x)
        ans = int(out.strip())
        assert ans == 0, 'No 2x2 square possible with n=1 or m=1'


def test_all_x_zero(run, x):
    lines = x.strip('\n').split('\n')
    n, m = map(int, lines[0].split())
    grid = lines[1:]
    if all(ch == 'x' for row in grid for ch in row):
        out = run(x)
        ans = int(out.strip())
        assert ans == 0, 'All x’s => no face'


def test_2x2_only_0_or_1(run, x):
    lines = x.strip('\n').split('\n')
    n, m = map(int, lines[0].split())
    if n == 2 and m == 2:
        out = run(x)
        ans = int(out.strip())
        assert ans in (0, 1), 'For 2x2 board answer can only be 0 or 1'


def test_contains_at_least_one_face_square(run, x):
    lines = x.strip('\n').split('\n')
    n, m = map(int, lines[0].split())
    grid = lines[1:]
    # look for any 2x2 that is exactly the letters f,a,c,e in any order
    for i in range(n-1):
        for j in range(m-1):
            chars = {grid[i][j], grid[i][j+1], grid[i+1][j], grid[i+1][j+1]}
            if chars == {'f','a','c','e'}:
                out = run(x)
                ans = int(out.strip())
                assert ans >= 1, f'Input contains a face square at ({i},{j}) but answer is 0'
                return
    # if we didn't find any, test passes


def test_two_nonoverlapping_faces_at_least_two(run, x):
    lines = x.strip('\n').split('\n')
    n, m = map(int, lines[0].split())
    grid = lines[1:]
    faces_found = 0
    # we look for two faces that do not share a cell
    used = [[False]*m for _ in range(n)]
    for i in range(n-1):
        for j in range(m-1):
            chars = {grid[i][j], grid[i][j+1], grid[i+1][j], grid[i+1][j+1]}
            if chars == {'f','a','c','e'}:
                if not (used[i][j] or used[i][j+1] or used[i+1][j] or used[i+1][j+1]):
                    faces_found += 1
                    used[i][j] = used[i][j+1] = used[i+1][j] = used[i+1][j+1] = True
    if faces_found >= 2:
        out = run(x)
        ans = int(out.strip())
        assert ans >= 2, f'Input contains at least two non‑overlapping face squares, answer {ans} too small'


def test_exhaustive_3x3(run, x):
    lines = x.strip('\n').split('\n')
    n, m = map(int, lines[0].split())
    if n == 3 and m == 3:
        grid = lines[1:]
        correct = 0
        for i in range(2):
            for j in range(2):
                chars = {grid[i][j], grid[i][j+1], grid[i+1][j], grid[i+1][j+1]}
                if chars == {'f','a','c','e'}:
                    correct += 1
        out = run(x)
        ans = int(out.strip())
        assert ans == correct, f'Exhaustive count for 3x3 gives {correct}, got {ans}'


def test_exhaustive_2x3(run, x):
    lines = x.strip('\n').split('\n')
