    if n == 2 and m == 3:
        grid = lines[1:]
        correct = 0
        for i in range(1):
            for j in range(2):
                chars = {grid[i][j], grid[i][j+1], grid[i+1][j], grid[i+1][j+1]}
                if chars == {'f','a','c','e'}:
                    correct += 1
        out = run(x)
        ans = int(out.strip())
        assert ans == correct, f'Exhaustive count for 2x3 gives {correct}, got {ans}'

