def test_quotes_and_dash(run, x):
    out = run(x).strip().split('\n')
    assert len(out) == 2
    a_line, b_line = out
    # a line
    if a_line == '-':
        pass  # OK
    else:
        assert a_line.startswith('"') and a_line.endswith('"')
        inner = a_line[1:-1]
        # If inner is empty, that's allowed (no numbers)
        if inner != '':
            # No leading/trailing commas except from empty words in original? Actually empty words become '' in b, but in a they can't be numbers, so inner can't be empty unless there were no numbers.
            # But we just check format: no stray quotes inside
            assert '"' not in inner
    # b line
    if b_line == '-':
        pass
    else:
        assert b_line.startswith('"') and b_line.endswith('"')
        inner = b_line[1:-1]
        if inner != '':
            assert '"' not in inner
    # At least one of a_line or b_line is not '-', because there is at least one word (since s length >=1 and empty words count as words). Wait: if s is a single separator, e.g., ',' then words are ['','']? Actually split on ',' gives ['','']? Let's not assume; but spec says if no number words then a_line is '-', if all number words then b_line is '-'. So both can't be '-', because there is at least one word. We'll not enforce that because it's not required by spec? Actually spec says: if there are no words that are numbers print dash on first line. If all words are numbers print dash on second line. If there is at least one word, then either some are numbers or none are numbers. If none are numbers then a_line='-', b_line has content. If all are numbers then a_line has content, b_line='-'. If mixed then both have content. So both '-' would imply zero words total, which cannot happen because s length >=1 and words are defined as largest sequences between separators, so empty string is a word. Thus there is always at least one word. So both '-' cannot happen. We'll enforce:
