def test_output_is_integer(run, x):
    out = run(x)
    assert out.strip().lstrip('-').isdigit(), 'Output must be an integer'

def test_answer_non_negative(run, x):
    out = run(x)
    ans = int(out.strip())
    assert ans >= 0, 'Answer cannot be negative'

def test_answer_at_most_total_spells(run, x):
    lines = x.strip().split('\n')
    if not lines or lines[0].strip() == '':
        n = m = 0
    else:
        n, m = map(int, lines[0].split())
    ans = int(run(x).strip())
    assert ans <= n + m, 'Cannot remove more spells than exist'

def test_at_least_vertical_blocking_column1(run, x):
    lines = x.strip().split('\n')
    if not lines or lines[0].strip() == '':
        n = m = 0
    else:
        n, m = map(int, lines[0].split())
    vert = []
    idx = 1
    for _ in range(n):
        vert.append(int(lines[idx].strip()))
        idx += 1
    block1 = sum(1 for v in vert if v == 1)
    ans = int(run(x).strip())
    assert ans >= block1, 'Must remove vertical spells blocking column 1 to go straight up'

def test_remove_all_works(run, x):
    lines = x.strip().split('\n')
    if not lines or lines[0].strip() == '':
        n = m = 0
    else:
        n, m = map(int, lines[0].split())
    ans = int(run(x).strip())
    assert ans <= n + m, 'Removing all spells always allows reaching the top'

def test_small_brute_force(run, x):
    lines = x.strip().split('\n')
    if not lines or lines[0].strip() == '':
        n = m = 0
    else:
        n, m = map(int, lines[0].split())
    if n + m > 5:
        return
    import sys
    sys.setrecursionlimit(10000)
    vert = []
    horiz = []
    idx = 1
    for _ in range(n):
        vert.append(int(lines[idx].strip()))
        idx += 1
    for _ in range(m):
        x1, x2, y = map(int, lines[idx].split())
        horiz.append((x1, x2, y))
        idx += 1
    def reachable(removed_vert, removed_horiz):
        blocked_col = set(removed_vert)
        blocked_horiz = set(removed_horiz)
        visited = set()
        stack = [(1, 1)]
        while stack:
            cx, cy = stack.pop()
            if (cx, cy) in visited:
                continue
            visited.add((cx, cy))
            if cy == 10**9:
                return True
            # up
            ny = cy + 1
            ok = True
            for (x1, x2, y) in horiz:
                if (x1, x2, y) in blocked_horiz:
                    continue
                if y == cy and x1 <= cx <= x2:
                    ok = False
                    break
            if ok:
                stack.append((cx, ny))
            # down
            ny = cy - 1
            if ny >= 1:
                ok = True
                for (x1, x2, y) in horiz:
                    if (x1, x2, y) in blocked_horiz:
                        continue
                    if y == cy - 1 and x1 <= cx <= x2:
                        ok = False
                        break
                if ok:
                    stack.append((cx, ny))
            # right
            nx = cx + 1
            if nx <= 10**9:
                if cx not in blocked_col:
                    stack.append((nx, cy))
            # left
            nx = cx - 1
            if nx >= 1:
                if nx not in blocked_col:
                    stack.append((nx, cy))
        return False
    best = n + m
    for maskv in range(1 << n):
        for maskh in range(1 << m):
            if reachable(
                [vert[i] for i in range(n) if (maskv >> i) & 1],
                [horiz[i] for i in range(m) if (maskh >> i) & 1]
            ):
                removed = bin(maskv).count('1') + bin(maskh).count('1')
                if removed < best:
                    best = removed
    ans = int(run(x).strip())
    assert ans == best, f'Brute‑force minimum is {best}, got {ans}'

def test_no_spells_zero(run, x):
    lines = x.strip().split('\n')
    if not lines or lines[0].strip() == '':
        n = m = 0
    else:
        n, m = map(int, lines[0].split())
    if n == 0 and m == 0:
        ans = int(run(x).strip())
        assert ans == 0, 'With no spells answer must be 0'

def test_answer_in_range(run, x):
    ans = int(run(x).strip())
    assert 0 <= ans <= 200000, 'Answer must be between 0 and 2*10^5 (max spells)'

def test_vertical_at_x_equals_10_9(run, x):
    lines = x.strip().split('\n')
    if not lines or lines[0].strip() == '':
