        idx += 1
    if 10**9 in vert:
        ans = int(run(x).strip())
        assert ans >= 1, 'Vertical spell at x=10^9 blocks moving right from column 10^9, must remove at least one spell'

def test_order_independent(run, x):
    lines = x.strip().split('\n')
    if not lines or lines[0].strip() == '':
        return
    first = lines[0]
    rest = lines[1:]
    n, m = map(int, first.split())
    vert = rest[:n]
    horiz = rest[n:]
    sorted_input = '\n'.join([first] + sorted(vert) + sorted(horiz))
    ans1 = int(run(x).strip())
    ans2 = int(run(sorted_input).strip())
    assert ans1 == ans2, 'Answer should not depend on order of spells'

