def test_output_length_matches_input(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    output = run(x).strip().split()
    assert len(output) == n

def test_all_outputs_are_integers(run, x):
    output = run(x).strip().split()
    for token in output:
        try:
            int(token)
        except ValueError:
            assert False, f'Not an integer: {token}'

def test_output_either_equal_or_one_less(run, x):
    lines = x.strip().split('\n')
    a = list(map(int, lines[1].split()))
    output = list(map(int, run(x).strip().split()))
    for inp, out in zip(a, output):
        assert out == inp or out == inp - 1

def test_output_within_range(run, x):
    output = list(map(int, run(x).strip().split()))
    for v in output:
        assert 1 <= v <= 10**9

def test_odd_inputs_unchanged(run, x):
    lines = x.strip().split('\n')
    a = list(map(int, lines[1].split()))
    output = list(map(int, run(x).strip().split()))
    for inp, out in zip(a, output):
        if inp % 2 == 1:
            assert out == inp

def test_even_inputs_become_odd(run, x):
    output = list(map(int, run(x).strip().split()))
    for v in output:
        assert v % 2 == 1

def test_small_bruteforce(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    a = list(map(int, lines[1].split()))
    # Only run brute force for tiny inputs to stay fast
    if n <= 10 and all(v <= 20 for v in a):
        # Simulate the algorithm as described
        arr = a[:]
        for i in range(1, 10**9 // 2 + 1):
            odd = 2*i - 1
            even = 2*i
            # Replace odd -> even
            arr = [even if x == odd else x for x in arr]
            # Replace even -> odd
            arr = [odd if x == even else x for x in arr]
        expected = arr
        output = list(map(int, run(x).strip().split()))
        assert output == expected

def test_output_no_greater_than_input(run, x):
    lines = x.strip().split('\n')
