        if cnt % p != 0:
            good.append(x)
    out = run(x).strip().split('\n')
    if len(good) == 0:
        assert out[0] == '0', f'Expected 0 good integers, got {out[0]}.'
    else:
        k = int(out[0])
        vals = list(map(int, out[1].split()))
        assert k == len(good) and vals == good, f'Brute force mismatch. Expected {good}, got {vals}.'


