def test_small_bruteforce_n4(run, x):
    import sys, itertools
    data = x.strip().split('\n')
    n, p = map(int, data[0].split())
    if n > 4:
        return
    a = list(map(int, data[1].split()))
    # brute force up to reasonable range
    maxx = max(a) + n
    good = []
    for x in range(1, min(maxx, 10)+1):
        cnt = 0
        for perm in itertools.permutations(range(n)):
            cur = x
            ok = True
            for idx in perm:
                if cur >= a[idx]:
                    cur += 1
