def test_output_non_negative_integer(run, x):
    out = run(x)
    val = int(out.strip())
    assert val >= 0

def test_zero_if_already_prime_row_or_column(run, x):
    import math
    def is_prime(v):
        if v <= 1:
            return False
        for d in range(2, int(math.isqrt(v)) + 1):
            if v % d == 0:
                return False
        return True
    lines = x.strip().splitlines()
    n_m = list(map(int, lines[0].split()))
    if len(n_m) < 2:
        return
    n, m = n_m[0], n_m[1]
    mat = [list(map(int, lines[i+1].split())) for i in range(n)]
    # check if any row is all primes
    prime_row = any(all(is_prime(mat[i][j]) for j in range(m)) for i in range(n))
    # check if any column is all primes
    prime_col = any(all(is_prime(mat[i][j]) for i in range(n)) for j in range(m))
    if prime_row or prime_col:
        out = run(x)
        assert out.strip() == '0'

def test_zero_if_all_cells_prime(run, x):
    import math
    def is_prime(v):
        if v <= 1:
            return False
        for d in range(2, int(math.isqrt(v)) + 1):
            if v % d == 0:
                return False
        return True
    lines = x.strip().splitlines()
    n_m = list(map(int, lines[0].split()))
    if len(n_m) < 2:
        return
    n, m = n_m[0], n_m[1]
    mat = [list(map(int, lines[i+1].split())) for i in range(n)]
    if all(is_prime(mat[i][j]) for i in range(n) for j in range(m)):
        out = run(x)
        assert out.strip() == '0'

def test_answer_upper_bound(run, x):
    import math
    lines = x.strip().splitlines()
    n_m = list(map(int, lines[0].split()))
    if len(n_m) < 2:
        return
    n, m = n_m[0], n_m[1]
    mat = [list(map(int, lines[i+1].split())) for i in range(n)]
    # each cell can be increased to the next prime ≤ 2*10^5 (since 10^5+dist).
    # The distance to next prime for any v ≤ 100000 is at most 100000 (actually less).
    max_per_cell = 100000  # safe upper bound
    trivial_bound = n * m * max_per_cell
    out = run(x)
    ans = int(out.strip())
    assert 0 <= ans <= trivial_bound

def test_1x1_case(run, x):
    import math
    lines = x.strip().splitlines()
    n_m = list(map(int, lines[0].split()))
    if len(n_m) < 2:
        return
    n, m = n_m[0], n_m[1]
    if n != 1 or m != 1:
        return
    v = int(lines[1].strip())
    def is_prime(w):
        if w <= 1:
            return False
        for d in range(2, int(math.isqrt(w)) + 1):
            if w % d == 0:
                return False
        return True
    dist = 0
    while not is_prime(v + dist):
        dist += 1
    out = run(x)
    ans = int(out.strip())
    assert ans == dist

def test_single_row_distance_sum(run, x):
    import math
    lines = x.strip().splitlines()
    n_m = list(map(int, lines[0].split()))
    if len(n_m) < 2:
        return
    n, m = n_m[0], n_m[1]
    if n != 1:
        return
    row = list(map(int, lines[1].split()))
    def is_prime(w):
        if w <= 1:
            return False
        for d in range(2, int(math.isqrt(w)) + 1):
            if w % d == 0:
                return False
        return True
    def dist_to_prime(w):
        d = 0
        while not is_prime(w + d):
            d += 1
        return d
    total_dist = sum(dist_to_prime(v) for v in row)
    out = run(x)
    ans = int(out.strip())
    # The minimal moves for a single row is exactly sum of distances to primes,
    # because making the whole row prime is the only way.
    assert ans == total_dist

def test_single_column_distance_sum(run, x):
