def test_trivial_2x2_manual(run, x):
    import math, itertools
    lines = x.strip().splitlines()
    n_m = list(map(int, lines[0].split()))
    if len(n_m) < 2:
        return
    n, m = n_m[0], n_m[1]
    if n > 4 or m > 4:
        return
    mat = [list(map(int, lines[i+1].split())) for i in range(n)]
    # skip if any value > 20 to keep brute‑force small
    if any(v > 20 for row in mat for v in row):
        return
    # brute‑force minimal moves
    def is_prime(w):
        if w <= 1:
            return False
        for d in range(2, int(math.isqrt(w)) + 1):
            if w % d == 0:
                return False
        return True
    best = float('inf')
    # We only need to increase cells up to +20 each because original ≤20.
    # Try all possible total increments per cell up to a limit.
    limit_inc = 20
    # generate all increment matrices
    from itertools import product
    increments = product(range(limit_inc+1), repeat=n*m)
    for inc_flat in increments:
        inc = [list(inc_flat[i*m:(i+1)*m]) for i in range(n)]
        ok = False
        # check rows
        for i in range(n):
            if all(is_prime(mat[i][j] + inc[i][j]) for j in range(m)):
                ok = True
                break
        if not ok:
            for j in range(m):
                if all(is_prime(mat[i][j] + inc[i][j]) for i in range(n)):
                    ok = True
                    break
        if ok:
            moves = sum(sum(row) for row in inc)
            if moves < best:
                best = moves
    out = run(x)
    ans = int(out.strip())
    assert ans == best

def test_answer_parity_consistency(run, x):
    # If all numbers are even and >2, turning a whole row/column prime requires making odd numbers.
    # This test is weak but may catch some gross errors.
    import math
    lines = x.strip().splitlines()
    n_m = list(map(int, lines[0].split()))
    if len(n_m) < 2:
        return
    n, m = n_m[0], n_m[1]
    mat = [list(map(int, lines[i+1].split())) for i in range(n)]
    # If all numbers are even and >2, they are not prime.
    # The minimal moves must be at least 1 per cell we change, but we don't compute.
    # Instead, just ensure the answer is an integer.
    out = run(x)
    ans = int(out.strip())
    # No specific parity constraint, but we could check that if the matrix is already prime,
    # answer is 0 (already covered). So this test just ensures answer is integer.
    # Actually we already have non‑negative test, so this is redundant; keep it trivial.
    assert isinstance(ans, int)

def test_examples_from_statement(run, x):
    # The three examples in the statement must be answered exactly.
    # Since the input list includes them, this test will run on those three inputs.
    examples = {
        "3 3\n1 2 3\n5 6 1\n4 4 1\n": "1\n",
        "2 3\n4 8 8\n9 2 9\n": "3\n",
        "2 2\n1 3\n4 2\n": "0\n",
    }
    if x in examples:
        out = run(x)
        assert out == examples[x]

