    data = list(map(int, x.split()))
    n, m = data[0], data[1]
    if n > 4 or m > 4:
        return  # skip large
    max_val = max(data[2:])
    if max_val > 10:
        return  # skip large numbers
    from itertools import product
    a = data[2:]
    mat = [a[i*m:(i+1)*m] for i in range(n)]
    zero_pos = [(i,j) for i in range(n) for j in range(m) if mat[i][j]==0]
    if not zero_pos:
        return
    best = -1
    # try values from 1 to 20 for each zero
    val_range = range(1, 21)
    for combo in product(val_range, repeat=len(zero_pos)):
        newmat = [row[:] for row in mat]
        for (idx, (i,j)) in enumerate(zero_pos):
            newmat[i][j] = combo[idx]
        ok = True
        for i in range(n):
            for j in range(m-1):
                if newmat[i][j] >= newmat[i][j+1]:
                    ok = False
        for j in range(m):
            for i in range(n-1):
                if newmat[i][j] >= newmat[i+1][j]:
                    ok = False
        if ok:
            s = sum(sum(row) for row in newmat)
            if s > best:
                best = s
    out = run(x).strip()
    if out == '-1':
        assert best == -1, f'Brute found solution sum {best} but got -1'
    else:
        assert int(out) == best, f'Brute best {best}, got {out}'

