def test_output_format(run, x):
    out = run(x)
    assert out in ('Yes\n', 'No\n'), f'Output must be exactly "Yes\\n" or "No\\n", got {repr(out)}'

def test_brute_force_small(run, x):
    # Only run brute-force when S is small enough
    s_str, p_str = x.strip().split()
    s = int(s_str); p = int(p_str)
    if s > 10**6:
        # Too large to brute-force; skip this test
        return
    out = run(x).strip()
    found = False
    for n in range(1, s):
        m = s - n
        if n * m == p:
            found = True
            break
    expected = 'Yes' if found else 'No'
    assert out == expected, f'Brute-force says {expected} but got {out}'

def test_yes_implies_factors(run, x):
    out = run(x).strip()
    if out == 'Yes':
        s_str, p_str = x.strip().split()
        s = int(s_str); p = int(p_str)
        # If Yes, there must exist positive integers N, M with N+M=S and N*M=P
        # So the quadratic equation N^2 - S*N + P = 0 must have integer roots.
        # Discriminant D = S*S - 4*P must be a perfect square.
        d = s*s - 4*p
        if d < 0:
            assert False, 'Yes but discriminant negative'
        sqrt_d = int(d**0.5)
        if sqrt_d * sqrt_d != d:
            assert False, 'Yes but discriminant not perfect square'
        n1 = (s + sqrt_d)//2
        n2 = (s - sqrt_d)//2
        if not (n1 > 0 and n2 > 0 and n1 + n2 == s and n1 * n2 == p):
            assert False, 'Yes but computed roots not valid'

def test_no_implies_no_factors(run, x):
    out = run(x).strip()
    if out == 'No':
        s_str, p_str = x.strip().split()
        s = int(s_str); p = int(p_str)
        # If No, then for all positive N, M with N+M=S, N*M != P.
        # Equivalently, the quadratic has no positive integer solution.
        d = s*s - 4*p
        if d < 0:
            return  # No is correct
        sqrt_d = int(d**0.5)
        if sqrt_d * sqrt_d != d:
            return  # No is correct
        n1 = (s + sqrt_d)//2
        n2 = (s - sqrt_d)//2
        if n1 > 0 and n2 > 0 and n1 + n2 == s and n1 * n2 == p:
            assert False, 'No but discriminant gives valid positive integers'

def test_p_not_exceed_square(run, x):
    s_str, p_str = x.strip().split()
    s = int(s_str); p = int(p_str)
    # For positive N, M with N+M=S, by AM-GM, N*M <= (S/2)^2
    max_p = (s//2) * ((s+1)//2)  # exact max product for integers
    out = run(x).strip()
    if out == 'Yes' and p > max_p:
        assert False, f'Yes but P={p} exceeds max possible product {max_p}'

def test_positive_roots(run, x):
    s_str, p_str = x.strip().split()
    s = int(s_str); p = int(p_str)
    out = run(x).strip()
    if out == 'Yes':
        # The two roots (N,M) must be positive integers.
        d = s*s - 4*p
        sqrt_d = int(d**0.5)
        n1 = (s + sqrt_d)//2
        n2 = (s - sqrt_d)//2
        if not (n1 > 0 and n2 > 0):
            assert False, 'Yes but roots not both positive'

def test_small_case_handcheck(run, x):
    s_str, p_str = x.strip().split()
    s = int(s_str); p = int(p_str)
    if s <= 1000 and p <= 10**6:
        out = run(x).strip()
        found = False
        for n in range(1, s):
            m = s - n
            if n * m == p:
                found = True
                break
        expected = 'Yes' if found else 'No'
        assert out == expected, f'Small case mismatch: expected {expected}, got {out}'

def test_discriminant_condition(run, x):
    s_str, p_str = x.strip().split()
    s = int(s_str); p = int(p_str)
    out = run(x).strip()
    d = s*s - 4*p
    if d < 0:
        # No real roots, so must be No
        if out != 'No':
            assert False, 'Discriminant negative but not No'
    else:
        sqrt_d = int(d**0.5)
        if sqrt_d * sqrt_d == d:
            # discriminant perfect square, possible Yes
            n1 = (s + sqrt_d)//2
            n2 = (s - sqrt_d)//2
            if n1 > 0 and n2 > 0 and n1 + n2 == s and n1 * n2 == p:
                # valid solution exists, must be Yes
                if out != 'Yes':
                    assert False, 'Valid solution exists but output not Yes'
            else:
                # roots not positive integers, must be No
                if out != 'No':
                    assert False, 'No valid solution but output not No'
        else:
            # discriminant not perfect square, must be No
            if out != 'No':
                assert False, 'Discriminant not perfect square but not No'

def test_output_case(run, x):
    out = run(x)
    assert out == 'Yes\n' or out == 'No\n', 'Output must be exactly Yes\\n or No\\n with capital first letter'

def test_sum_product_relation(run, x):
    s_str, p_str = x.strip().split()
    s = int(s_str); p = int(p_str)
    out = run(x).strip()
    if out == 'Yes':
        # If Yes, then (N,M) are roots of x^2 - Sx + P = 0, so they satisfy N+M=S, N*M=P.
        # Thus P must be ≤ (S/2)^2, but we already test that.
        # Additionally, for integer N,M, S^2 - 4P must be perfect square.
        d = s*s - 4*p
        if d < 0:
            assert False, 'Yes but discriminant negative'
        sqrt_d = int(d**0.5)
        if sqrt_d * sqrt_d != d:
            assert False, 'Yes but discriminant not perfect square'
        # Also N,M = (S ± sqrt_d)/2 must be integers
        if (s + sqrt_d) % 2 != 0:
            assert False, 'Yes but (S+sqrt_d) not even'
    else:
        # No output, no further checks needed
        pass

