def test_format(run, x):
    out = run(x).strip()
    if out == '-1':
        return
    parts = out.split()
    for p in parts:
        assert p.isdigit() or (p[0]=='-' and p[1:].isdigit()), f'Non-integer: {p}'
        x_val = int(p)
        assert 1 <= x_val <= 10**9, f'x out of range: {x_val}'

def test_ascending_unique(run, x):
    out = run(x).strip()
    if out == '-1':
        return
    vals = list(map(int, out.split()))
    for i in range(len(vals)-1):
        assert vals[i] < vals[i+1], f'Not ascending: {vals[i]} >= {vals[i+1]}'
    assert len(vals) == len(set(vals)), 'Duplicate values found'

def test_each_x_satisfies_conditions(run, x):
    y, k, n = map(int, x.strip().split())
    out = run(x).strip()
    if out == '-1':
        return
    for x_val in map(int, out.split()):
        assert 1 <= x_val, f'x must be >=1: {x_val}'
        assert x_val + y <= n, f'x+y={x_val+y} exceeds n={n}'
        assert (x_val + y) % k == 0, f'x+y not divisible by k: {x_val}+{y}'
        # x implicitly <= n-y from x+y <= n

def test_if_no_x_then_minus_one(run, x):
    y, k, n = map(int, x.strip().split())
    # Brute check for small n/k (since n/k <= 1e5 per constraint)
    if (n // k) <= 100000:
        possible = []
        for x_candidate in range(1, n - y + 1):
            if (x_candidate + y) % k == 0:
                possible.append(x_candidate)
        out = run(x).strip()
        if not possible:
            assert out == '-1', f'Expected -1, got {out}'
        else:
            assert out != '-1', f'Expected numbers, got -1'

def test_all_valid_x_found_for_small_inputs(run, x):
    y, k, n = map(int, x.strip().split())
    # Only run brute verification when total iterations small
    if (n // k) <= 1000:
        expected = []
        for x_candidate in range(1, n - y + 1):
            if (x_candidate + y) % k == 0:
                expected.append(x_candidate)
        out = run(x).strip()
        if expected:
            got = list(map(int, out.split()))
            assert got == expected, f'Expected {expected}, got {got}'
        else:
            assert out == '-1', f'Expected -1, got {out}'

def test_first_x_not_greater_than_k(run, x):
    y, k, n = map(int, x.strip().split())
    out = run(x).strip()
    if out == '-1':
        return
    first = int(out.split()[0])
    # The smallest x satisfying (x+y)%k==0 and x>=1 is between 1 and k
    # Actually it's (k - y%k) % k, but if that's 0 then x=k, else <k.
    # So first <= k
    assert first <= k, f'First x {first} > k {k}'

def test_gaps_are_multiple_of_k(run, x):
    y, k, n = map(int, x.strip().split())
    out = run(x).strip()
    if out == '-1' or k == 0:
        return
    vals = list(map(int, out.split()))
    for i in range(len(vals)-1):
        diff = vals[i+1] - vals[i]
        assert diff % k == 0, f'Gap {diff} not multiple of k {k}'

def test_last_x_plus_y_le_n(run, x):
    y, k, n = map(int, x.strip().split())
    out = run(x).strip()
    if out == '-1':
        return
    vals = list(map(int, out.split()))
    last = vals[-1]
    assert last + y <= n, f'last x+y={last+y} > n={n}'

def test_no_extra_gaps(run, x):
    y, k, n = map(int, x.strip().split())
    out = run(x).strip()
    if out == '-1':
        return
    vals = list(map(int, out.split()))
    if not vals:
        return
    # Check that between consecutive vals there is no missing valid x.
    # Since they are spaced by k, the only missing would be if start jumps.
    # Actually the sequence should be arithmetic progression with step k.
    step = k
    for i in range(len(vals)-1):
        assert vals[i+1] - vals[i] == step, f'Unexpected gap at {vals[i]}'

def test_output_length_bound(run, x):
    y, k, n = map(int, x.strip().split())
    out = run(x).strip()
    if out == '-1':
        return
    vals = list(map(int, out.split()))
    # At most (n-y)/k + 1 numbers, but since x>=1 and x+y divisible by k,
    # count <= floor((n-y)/k) + 1.
    max_count = (n - y) // k + 1
    assert len(vals) <= max_count, f'Too many values: {len(vals)} > {max_count}'
